{
  "name": "PocketStudio DSP",
  "description": "A professional mobile-first multi-track audio editor with real-time DSP effects, waveform editing, and offline bouncing.",
  "requestFramePermissions": [
    "microphone"
  ]
}

export interface Track {
  id: string;
  name: string;
  color: string;
  muted: boolean;
  solo: boolean;
  volume: number; // 0 to 1
}

export interface AudioClip {
  id: string;
  trackId: string;
  buffer: AudioBuffer;
  startTime: number; // Global timeline position in seconds
  duration: number; // Duration in seconds
  offset: number; // Offset into the buffer in seconds
  name: string;
}

export enum EditMode {
  MOVE = 'MOVE',
  SPLIT = 'SPLIT',
  DELETE = 'DELETE'
}

export interface ProjectData {
  id: string;
  name: string;
  tracks: Track[];
  clips: {
    id: string;
    trackId: string;
    startTime: number;
    duration: number;
    offset: number;
    name: string;
    blobKey: string; // Reference to IDB blob
  }[];
}

export interface DSPState {
  distortionAmount: number; // 0 to 100
  reverbMix: number; // 0 to 1
  cabinetEnabled: boolean;
}

export const PX_PER_SEC = 100; // Zoom level: 100 pixels per second
export const TRACK_HEIGHT = 120;
export const HEADER_HEIGHT = 60;
export const FOOTER_HEIGHT = 220; // Expanded for DSP controls
export const COLORS = [
  '#ef4444', // red-500
  '#f97316', // orange-500
  '#eab308', // yellow-500
  '#22c55e', // green-500
  '#06b6d4', // cyan-500
  '#3b82f6', // blue-500
  '#a855f7', // purple-500
  '#ec4899', // pink-500
];

export const DB_NAME = 'PocketStudioDB';
export const DB_VERSION = 1;
export const STORE_BLOBS = 'audio_blobs';
export const STORE_PROJECTS = 'projects';

import { DB_NAME, DB_VERSION, STORE_BLOBS, STORE_PROJECTS } from '../constants';

class StorageService {
  private db: IDBDatabase | null = null;

  async init(): Promise<void> {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(DB_NAME, DB_VERSION);

      request.onerror = () => reject('Error opening DB');

      request.onupgradeneeded = (event) => {
        const db = (event.target as IDBOpenDBRequest).result;
        if (!db.objectStoreNames.contains(STORE_BLOBS)) {
          db.createObjectStore(STORE_BLOBS);
        }
        if (!db.objectStoreNames.contains(STORE_PROJECTS)) {
          db.createObjectStore(STORE_PROJECTS, { keyPath: 'id' });
        }
      };

      request.onsuccess = (event) => {
        this.db = (event.target as IDBOpenDBRequest).result;
        resolve();
      };
    });
  }

  async saveBlob(key: string, blob: Blob): Promise<void> {
    return this.performTransaction(STORE_BLOBS, 'readwrite', (store) => {
      store.put(blob, key);
    });
  }

  async getBlob(key: string): Promise<Blob | undefined> {
    return this.performRequest(STORE_BLOBS, 'readonly', (store) => store.get(key));
  }

  private async performTransaction(
    storeName: string,
    mode: IDBTransactionMode,
    action: (store: IDBObjectStore) => void
  ): Promise<void> {
    if (!this.db) await this.init();
    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction([storeName], mode);
      const store = transaction.objectStore(storeName);
      action(store);
      transaction.oncomplete = () => resolve();
      transaction.onerror = () => reject(transaction.error);
    });
  }

  private async performRequest<T>(
    storeName: string,
    mode: IDBTransactionMode,
    requestFactory: (store: IDBObjectStore) => IDBRequest<T>
  ): Promise<T> {
    if (!this.db) await this.init();
    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction([storeName], mode);
      const store = transaction.objectStore(storeName);
      const request = requestFactory(store);
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
  }
}

export const storageService = new StorageService();

import { DSPState } from '../types';

export class AudioEngine {
  public ctx: AudioContext;
  private masterGain: GainNode;

  // DSP Nodes
  private inputNode: GainNode; // Mix entry point
  private distortionNode: WaveShaperNode;
  private cabinetFilterNode: BiquadFilterNode;
  private reverbNode: ConvolverNode;
  private dryNode: GainNode;
  private wetNode: GainNode;

  private activeSources: Map<string, AudioBufferSourceNode> = new Map();
  private isPlaying: boolean = false;
  private stream: MediaStream | null = null;
  private mediaRecorder: MediaRecorder | null = null;

  constructor() {
    // Initialize with a standard sample rate, fallback for safety
    const AudioContextClass = (window.AudioContext || (window as any).webkitAudioContext);
    this.ctx = new AudioContextClass({ latencyHint: 'interactive' });

    // Create Nodes
    this.masterGain = this.ctx.createGain();
    this.inputNode = this.ctx.createGain();
    this.distortionNode = this.ctx.createWaveShaper();
    this.cabinetFilterNode = this.ctx.createBiquadFilter();
    this.reverbNode = this.ctx.createConvolver();
    this.dryNode = this.ctx.createGain();
    this.wetNode = this.ctx.createGain();

    // Cabinet Setup
    this.cabinetFilterNode.type = 'highshelf';
    this.cabinetFilterNode.frequency.value = 3000;
    this.cabinetFilterNode.gain.value = -24; // Roll off high frequencies

    // Routing
    // Input -> Distortion -> Cabinet -> (Split to Dry/Wet)
    // Dry -> Master
    // Wet -> Reverb -> Master

    this.inputNode.connect(this.distortionNode);
    this.distortionNode.connect(this.cabinetFilterNode);

    // Split
    this.cabinetFilterNode.connect(this.dryNode);
    this.cabinetFilterNode.connect(this.wetNode);

    this.wetNode.connect(this.reverbNode);
    this.reverbNode.connect(this.masterGain);
    this.dryNode.connect(this.masterGain);

    this.masterGain.connect(this.ctx.destination);

    // Initial Defaults
    this.setDistortion(0);
    this.setReverbMix(0);
    this.generateSyntheticImpulse();
  }

  async resume() {
    if (this.ctx.state === 'suspended') {
      await this.ctx.resume();
    }
  }

  getCurrentTime(): number {
    return this.ctx.currentTime;
  }

  // --- DSP Control ---

  setDistortion(amount: number) {
    // 0 to 100
    // Algorithm from prompt
    const k = amount; 
    const n_samples = 44100;
    const curve = new Float32Array(n_samples);
    const deg = Math.PI / 180;

    for (let i = 0; i < n_samples; ++i) {
      const x = i * 2 / n_samples - 1;
      curve[i] = (3 + k) * x * 20 * deg / (Math.PI + k * Math.abs(x));
    }

    this.distortionNode.curve = curve;
    this.distortionNode.oversample = '4x';
  }

  setReverbMix(mix: number) {
    // mix is 0 to 1
    // Equal power crossfade
    const gainDry = Math.cos(mix * 0.5 * Math.PI);
    const gainWet = Math.sin(mix * 0.5 * Math.PI);
    this.dryNode.gain.setTargetAtTime(gainDry, this.ctx.currentTime, 0.01);
    this.wetNode.gain.setTargetAtTime(gainWet, this.ctx.currentTime, 0.01);
  }

  setCabinet(enabled: boolean) {
    if (enabled) {
        this.cabinetFilterNode.gain.setTargetAtTime(-24, this.ctx.currentTime, 0.1);
    } else {
        this.cabinetFilterNode.gain.setTargetAtTime(0, this.ctx.currentTime, 0.1);
    }
  }

  updateDSP(state: DSPState) {
    this.setDistortion(state.distortionAmount);
    this.setReverbMix(state.reverbMix);
    this.setCabinet(state.cabinetEnabled);
  }

  private generateSyntheticImpulse() {
    const rate = this.ctx.sampleRate;
    const length = rate * 2; // 2 seconds
    const decay = 2.0;
    const impulse = this.ctx.createBuffer(2, length, rate);
    const impulseL = impulse.getChannelData(0);
    const impulseR = impulse.getChannelData(1);

    for (let i = 0; i < length; i++) {
        const n = length - i;
        const noise = (Math.random() * 2 - 1) * Math.pow(n / length, decay);
        impulseL[i] = noise;
        impulseR[i] = noise;
    }
    this.reverbNode.buffer = impulse;
  }

  // --- Playback Management ---

  playClip(buffer: AudioBuffer, startTime: number, offset: number, duration: number, trackVolume: number, clipId: string) {
    const source = this.ctx.createBufferSource();
    source.buffer = buffer;

    // Track specific gain
    const trackGain = this.ctx.createGain();
    trackGain.gain.value = trackVolume;

    source.connect(trackGain);
    trackGain.connect(this.inputNode); // Route to DSP chain

    // Scheduling
    // startTime is where in the timeline it should play.
    // this.ctx.currentTime is NOW.
    // We need to calculate when to schedule the start.

    const when = Math.max(0, startTime - this.ctx.currentTime); // Delay until start
    const offsetInClip = Math.max(0, this.ctx.currentTime - startTime); // If we start late (scrubbing)

    // Calculate actual playback parameters
    const playStart = this.ctx.currentTime + (startTime > this.ctx.currentTime ? startTime - this.ctx.currentTime : 0);
    const bufferOffset = offset + (startTime < this.ctx.currentTime ? this.ctx.currentTime - startTime : 0);
    const playDuration = duration - (startTime < this.ctx.currentTime ? this.ctx.currentTime - startTime : 0);

    if (playDuration > 0) {
      source.start(playStart, bufferOffset, playDuration);
      this.activeSources.set(clipId, source);

      source.onended = () => {
        this.activeSources.delete(clipId);
      };
    }
  }

  stopAll() {
    this.activeSources.forEach(source => {
      try { source.stop(); } catch(e) {}
    });
    this.activeSources.clear();
  }

  // --- Recording ---

  async startRecording(monitor: boolean): Promise<void> {
    await this.resume();
    this.stream = await navigator.mediaDevices.getUserMedia({ 
      audio: { 
        echoCancellation: false, 
        autoGainControl: false,
        noiseSuppression: false,
        latency: 0 
      } 
    });

    const source = this.ctx.createMediaStreamSource(this.stream);

    // Monitor path
    if (monitor) {
      source.connect(this.ctx.destination);
    }

    this.mediaRecorder = new MediaRecorder(this.stream);
    this.mediaRecorder.start();
  }

  async stopRecording(): Promise<Blob> {
    return new Promise((resolve, reject) => {
      if (!this.mediaRecorder) return reject('No recorder');

      const chunks: BlobPart[] = [];
      this.mediaRecorder.ondataavailable = (e) => chunks.push(e.data);
      this.mediaRecorder.onstop = () => {
        const blob = new Blob(chunks, { type: 'audio/ogg; codecs=opus' });
        this.stream?.getTracks().forEach(track => track.stop());
        resolve(blob);
      };
      this.mediaRecorder.stop();
    });
  }

  // --- Utilities ---

  async decodeAudioData(blob: Blob): Promise<AudioBuffer> {
    const arrayBuffer = await blob.arrayBuffer();
    return await this.ctx.decodeAudioData(arrayBuffer);
  }

  splitBuffer(originalBuffer: AudioBuffer, splitTime: number): [AudioBuffer, AudioBuffer] {
    // splitTime is strictly relative to the start of the buffer (0 to duration)
    const rate = originalBuffer.sampleRate;
    // Clamp
    const splitIndex = Math.floor(Math.max(0, Math.min(originalBuffer.duration, splitTime)) * rate);

    const len1 = splitIndex;
    const len2 = originalBuffer.length - splitIndex;

    // Handle edge case where split is at very end or start
    if (len1 === 0 || len2 === 0) return [originalBuffer, originalBuffer]; // Ideally handle this upstack

    const part1 = this.ctx.createBuffer(originalBuffer.numberOfChannels, len1, rate);
    const part2 = this.ctx.createBuffer(originalBuffer.numberOfChannels, len2, rate);

    for (let i = 0; i < originalBuffer.numberOfChannels; i++) {
        const channelData = originalBuffer.getChannelData(i);
        part1.copyToChannel(channelData.subarray(0, splitIndex), i);
        part2.copyToChannel(channelData.subarray(splitIndex), i);
    }

    return [part1, part2];
  }

  async bounceMix(length: number, clips: any[], tracks: any[]): Promise<AudioBuffer> {
    const offlineCtx = new OfflineAudioContext(2, length * 44100, 44100);

    // Recreate basic mix logic for offline
    // Ideally we would duplicate the DSP chain here too for the full bounce
    // For this MVP, we will bounce the 'Dry' mix to ensure reliability or simple mix

    clips.forEach(clip => {
        const track = tracks.find((t:any) => t.id === clip.trackId);
        if (!track || track.muted) return;

        const source = offlineCtx.createBufferSource();
        source.buffer = clip.buffer;

        const gain = offlineCtx.createGain();
        gain.gain.value = track.volume;

        source.connect(gain);
        gain.connect(offlineCtx.destination);
        source.start(clip.startTime, clip.offset, clip.duration);
    });

    return await offlineCtx.startRendering();
  }
}

export const audioEngine = new AudioEngine();

import React, { useState, useRef, useEffect } from 'react';

interface KnobProps {
  value: number;
  min: number;
  max: number;
  onChange: (val: number) => void;
  label: string;
  color?: string;
}

export const Knob: React.FC<KnobProps> = ({ value, min, max, onChange, label, color = 'cyan' }) => {
  const [isDragging, setIsDragging] = useState(false);
  const startY = useRef(0);
  const startVal = useRef(0);

  const handleStart = (clientY: number) => {
    setIsDragging(true);
    startY.current = clientY;
    startVal.current = value;
  };

  const handleMove = (clientY: number) => {
    if (!isDragging) return;
    const delta = startY.current - clientY;
    const range = max - min;
    const change = (delta / 200) * range; // 200px for full range
    let newVal = startVal.current + change;
    newVal = Math.max(min, Math.min(max, newVal));
    onChange(newVal);
  };

  const handleEnd = () => {
    setIsDragging(false);
  };

  useEffect(() => {
    if (isDragging) {
      const mouseMove = (e: MouseEvent) => handleMove(e.clientY);
      const touchMove = (e: TouchEvent) => handleMove(e.touches[0].clientY);
      const end = () => handleEnd();

      window.addEventListener('mousemove', mouseMove);
      window.addEventListener('touchmove', touchMove, { passive: false });
      window.addEventListener('mouseup', end);
      window.addEventListener('touchend', end);

      return () => {
        window.removeEventListener('mousemove', mouseMove);
        window.removeEventListener('touchmove', touchMove);
        window.removeEventListener('mouseup', end);
        window.removeEventListener('touchend', end);
      };
    }
  }, [isDragging]);

  // Calculate rotation -135deg to +135deg
  const percentage = (value - min) / (max - min);
  const rotation = -135 + (percentage * 270);

  return (
    <div 
      className="flex flex-col items-center select-none touch-none"
      onMouseDown={(e) => handleStart(e.clientY)}
      onTouchStart={(e) => handleStart(e.touches[0].clientY)}
    >
      <div className="relative w-12 h-12 bg-slate-700 rounded-full border-2 border-slate-600 shadow-lg">
        <div 
          className="absolute w-full h-full rounded-full"
          style={{ transform: `rotate(${rotation}deg)` }}
        >
          <div 
            className={`absolute top-1 left-1/2 -translate-x-1/2 w-1.5 h-3 rounded-full bg-${color}-500 shadow-[0_0_8px_rgba(0,0,0,0.8)]`}
            style={{ backgroundColor: color === 'orange' ? '#f97316' : '#06b6d4'}}
          />
        </div>
      </div>
      <span className="text-[10px] uppercase font-bold text-slate-400 mt-1">{label}</span>
    </div>
  );
};

import React, { useEffect, useRef } from 'react';
import { AudioClip } from '../types';

interface WaveformProps {
  buffer: AudioBuffer;
  color: string;
  width: number;
  height: number;
}

export const Waveform: React.FC<WaveformProps> = ({ buffer, color, width, height }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Clear
    ctx.clearRect(0, 0, width, height);

    // Draw
    const data = buffer.getChannelData(0);
    const step = Math.ceil(data.length / width);
    const amp = height / 2;

    ctx.fillStyle = color;
    ctx.beginPath();

    for (let i = 0; i < width; i++) {
      let min = 1.0;
      let max = -1.0;

      // Analyze chunk
      for (let j = 0; j < step; j++) {
        const datum = data[(i * step) + j];
        if (datum < min) min = datum;
        if (datum > max) max = datum;
      }

      // Draw vertical bar
      ctx.fillRect(i, (1 + min) * amp, 1, Math.max(1, (max - min) * amp));
    }

  }, [buffer, color, width, height]);

  return (
    <canvas 
      ref={canvasRef} 
      width={width} 
      height={height} 
      className="w-full h-full opacity-80"
    />
  );
};

import React from 'react';
import { Track, AudioClip, EditMode } from '../types';
import { PX_PER_SEC, TRACK_HEIGHT } from '../constants';
import { Waveform } from './Waveform';

interface TrackLaneProps {
  track: Track;
  clips: AudioClip[];
  editMode: EditMode;
  onClipInteract: (clipId: string, action: 'start' | 'move' | 'end' | 'tap', data?: any) => void;
  currentTime: number;
  isPlaying: boolean;
}

export const TrackLane: React.FC<TrackLaneProps> = ({ 
  track, 
  clips, 
  editMode,
  onClipInteract 
}) => {
  return (
    <div 
      className="relative w-full border-b border-slate-700 bg-slate-800/50"
      style={{ height: TRACK_HEIGHT }}
      data-track-id={track.id}
    >
      {/* Track Background Grid */}
      <div className="absolute inset-0 pointer-events-none opacity-10 bg-[linear-gradient(90deg,transparent_99px,#fff_1px)] bg-[length:100px_100%]"></div>

      {clips.map(clip => {
        const left = clip.startTime * PX_PER_SEC;
        const width = clip.duration * PX_PER_SEC;

        return (
          <div
            key={clip.id}
            className={`absolute top-1 bottom-1 rounded-md overflow-hidden border border-white/20 shadow-sm touch-none
              ${editMode === EditMode.SPLIT ? 'cursor-crosshair ring-2 ring-red-500/50' : 'cursor-move'}`}
            style={{ 
              left: `${left}px`, 
              width: `${width}px`,
              backgroundColor: track.color + '40' // Hex opacity
            }}
            onTouchStart={(e) => {
              e.stopPropagation();
              onClipInteract(clip.id, 'start', { 
                x: e.touches[0].clientX, 
                y: e.touches[0].clientY,
                originalStart: clip.startTime
              });
            }}
            onClick={(e) => {
               e.stopPropagation();
               if (editMode === EditMode.SPLIT) {
                   onClipInteract(clip.id, 'tap');
               }
            }}
          >
            <Waveform 
              buffer={clip.buffer} 
              color={track.color} 
              width={width} 
              height={TRACK_HEIGHT - 8} 
            />
            <div className="absolute top-0 left-1 text-[10px] text-white/70 font-mono truncate max-w-full pointer-events-none">
              {clip.name}
            </div>
          </div>
        );
      })}
    </div>
  );
};

import React from 'react';
import { EditMode } from '../types';

interface ControlsProps {
  isPlaying: boolean;
  isRecording: boolean;
  onPlayPause: () => void;
  onRecord: () => void;
  onStop: () => void;
  onBounce: () => void;
  editMode: EditMode;
  setEditMode: (mode: EditMode) => void;
  monitor: boolean;
  setMonitor: (val: boolean) => void;
}

export const Controls: React.FC<ControlsProps> = ({
  isPlaying, isRecording, onPlayPause, onRecord, onStop, onBounce,
  editMode, setEditMode, monitor, setMonitor
}) => {
  return (
    <div className="fixed top-0 left-0 right-0 h-[60px] bg-slate-900 border-b border-slate-700 flex items-center justify-between px-4 z-50 shadow-xl">
      <div className="flex items-center space-x-2">
