import React from 'react';
import { Track, AudioClip, EditMode } from '../types';
import { TRACK_HEIGHT } from '../constants';
import { Waveform } from './Waveform';

interface TrackLaneProps {
  track: Track;
  clips: AudioClip[];
  editMode: EditMode;
  onClipInteract: (clipId: string, action: 'start' | 'move' | 'end' | 'tap', data?: any) => void;
  currentTime: number;
  isPlaying: boolean;
  zoom: number; // Pixels per second
}

export const TrackLane: React.FC<TrackLaneProps> = ({ 
  track, 
  clips, 
  editMode,
  onClipInteract,
  zoom
}) => {
  return (
    <div 
      className="relative w-full border-b border-slate-700 bg-slate-800/50"
      style={{ height: TRACK_HEIGHT }}
      data-track-id={track.id}
    >
      {/* Track Background Grid */}
      <div 
        className="absolute inset-0 pointer-events-none opacity-10 bg-[linear-gradient(90deg,transparent_99%,#fff_1%)]" 
        style={{ backgroundSize: `${zoom}px 100%` }}
      ></div>

      {clips.map(clip => {
        const left = clip.startTime * zoom;
        const width = clip.duration * zoom;

        // Windowing logic: The buffer might be longer than the clip duration due to trimming/splitting.
        // We render the full buffer waveform but mask it using the container's overflow:hidden.
        const fullBufferWidth = clip.buffer.duration * zoom;
        const offsetLeft = -(clip.offset * zoom);

        return (
          <div
            key={clip.id}
            className={`absolute top-1 bottom-1 rounded-md overflow-hidden border border-white/20 shadow-sm touch-none
              ${editMode === EditMode.SPLIT ? 'cursor-crosshair ring-2 ring-red-500/50' : 'cursor-move'}`}
            style={{ 
              left: `${left}px`, 
              width: `${width}px`,
              backgroundColor: track.color + '40' // Hex opacity
            }}
            onTouchStart={(e) => {
              e.stopPropagation();
              onClipInteract(clip.id, 'start', { 
                x: e.touches[0].clientX, 
                y: e.touches[0].clientY,
                originalStart: clip.startTime
              });
            }}
            onMouseDown={(e) => {
              e.stopPropagation();
              onClipInteract(clip.id, 'start', { 
                x: e.clientX, 
                y: e.clientY,
                originalStart: clip.startTime
              });
            }}
            onClick={(e) => {
               e.stopPropagation();
               if (editMode === EditMode.SPLIT) {
                   onClipInteract(clip.id, 'tap');
               }
            }}
          >
            {/* Inner Container for Waveform Translation */}
            <div 
                className="absolute top-0 bottom-0 pointer-events-none"
                style={{ 
                    left: `${offsetLeft}px`,
                    width: `${fullBufferWidth}px` 
                }}
            >
                <Waveform 
                  buffer={clip.buffer} 
                  color={track.color} 
                  width={fullBufferWidth} 
                  height={TRACK_HEIGHT - 8} 
                />
            </div>

            <div className="absolute top-0 left-1 text-[10px] text-white/70 font-mono truncate max-w-full pointer-events-none bg-black/30 px-1 rounded-br">
              {clip.name}
            </div>
          </div>
        );
      })}
    </div>
  );
};

