export interface Track {
  id: string;
  name: string;
  color: string;
  muted: boolean;
  solo: boolean;
  volume: number; // 0 to 1
  pan: number; // -1 (Left) to 1 (Right)
}

export interface AudioClip {
  id: string;
  trackId: string;
  buffer: AudioBuffer;
  startTime: number; // Global timeline position in seconds
  duration: number; // Duration in seconds
  offset: number; // Offset into the buffer in seconds
  name: string;
}

export enum EditMode {
  MOVE = 'MOVE',
  SPLIT = 'SPLIT',
  DELETE = 'DELETE'
}

export interface ProjectData {
  id: string;
  name: string;
  tracks: Track[];
  clips: {
    id: string;
    trackId: string;
    startTime: number;
    duration: number;
    offset: number;
    name: string;
    blobKey: string; // Reference to IDB blob
  }[];
}

export interface DSPState {
  // Master Bus
  masterVolume: number; // 0 to 1.5

  // Dynamics
  compressorThreshold: number; // -60 to 0 dB
  compressorRatio: number; // 1 to 20

  // EQ
  eqLow: number; // -12 to 12 dB
  eqMid: number; // -12 to 12 dB
  eqHigh: number; // -12 to 12 dB

  // FX
  distortionAmount: number; // 0 to 100
  reverbMix: number; // 0 to 1
  delayTime: number; // 0 to 1
  delayFeedback: number; // 0 to 0.9
}

import { DSPState } from '../types';

export class AudioEngine {
  public ctx: AudioContext;
  public analyser: AnalyserNode;

  private masterGain: GainNode;

  // Input Stage
  private inputNode: GainNode; 
  private distortionNode: WaveShaperNode;

  // EQ Stage
  private eqLowNode: BiquadFilterNode;
  private eqMidNode: BiquadFilterNode;
  private eqHighNode: BiquadFilterNode;

  // Dynamics
  private compressorNode: DynamicsCompressorNode;

  // Spatial / FX Sends
  private reverbNode: ConvolverNode;
  private delayNode: DelayNode;
  private delayFeedbackNode: GainNode;

  // Routing Gains
  private dryNode: GainNode;
  private wetReverbNode: GainNode; 
  private wetDelayNode: GainNode; 
  private delayOutNode: GainNode;

  private activeSources: Map<string, AudioBufferSourceNode> = new Map();
  private stream: MediaStream | null = null;
  private mediaRecorder: MediaRecorder | null = null;

  constructor() {
    const AudioContextClass = (window.AudioContext || (window as any).webkitAudioContext);
    this.ctx = new AudioContextClass({ latencyHint: 'interactive' });

    // --- Node Creation ---

    this.masterGain = this.ctx.createGain();
    this.analyser = this.ctx.createAnalyser();
    this.analyser.fftSize = 2048;
    this.analyser.smoothingTimeConstant = 0.85;

    this.inputNode = this.ctx.createGain();
    this.distortionNode = this.ctx.createWaveShaper();

    // EQ
    this.eqLowNode = this.ctx.createBiquadFilter();
    this.eqLowNode.type = 'lowshelf';
    this.eqLowNode.frequency.value = 200; // Hz

    this.eqMidNode = this.ctx.createBiquadFilter();
    this.eqMidNode.type = 'peaking';
    this.eqMidNode.frequency.value = 1000; // Hz
    this.eqMidNode.Q.value = 1.0;

    this.eqHighNode = this.ctx.createBiquadFilter();
    this.eqHighNode.type = 'highshelf';
    this.eqHighNode.frequency.value = 3000; // Hz

    // Compressor
    this.compressorNode = this.ctx.createDynamicsCompressor();
    this.compressorNode.attack.value = 0.003;
    this.compressorNode.release.value = 0.25;

    // FX
    this.reverbNode = this.ctx.createConvolver();
    this.delayNode = this.ctx.createDelay(4.0);
    this.delayFeedbackNode = this.ctx.createGain();

    // Mix Buses
    this.dryNode = this.ctx.createGain();
    this.wetReverbNode = this.ctx.createGain();
    this.wetDelayNode = this.ctx.createGain();
    this.delayOutNode = this.ctx.createGain();

    // --- Routing Graph ---

    // 1. Input -> Distortion
    this.inputNode.connect(this.distortionNode);

    // 2. Distortion -> EQ Chain -> Compressor
    this.distortionNode.connect(this.eqLowNode);
    this.eqLowNode.connect(this.eqMidNode);
    this.eqMidNode.connect(this.eqHighNode);
    this.eqHighNode.connect(this.compressorNode);

    // 3. Compressor -> Split (Dry, Reverb Send, Delay Send)
    // The compressor glues the mix before spatial effects (or could be after, but this is a "Master Bus" style chain)

    const postFxSignal = this.compressorNode;

    // Dry Path
    postFxSignal.connect(this.dryNode);
    this.dryNode.connect(this.masterGain);

    // Reverb Path (Parallel)
    postFxSignal.connect(this.wetReverbNode);
    this.wetReverbNode.connect(this.reverbNode);
    this.reverbNode.connect(this.masterGain);

    // Delay Path (Parallel with Feedback)
    postFxSignal.connect(this.wetDelayNode);
    this.wetDelayNode.connect(this.delayNode);
    this.delayNode.connect(this.delayFeedbackNode);
    this.delayFeedbackNode.connect(this.delayNode);

    this.delayNode.connect(this.delayOutNode);
    this.delayOutNode.connect(this.masterGain);

    // 4. Master -> Analyser -> Out
    this.masterGain.connect(this.analyser);
    this.analyser.connect(this.ctx.destination);

    // Initial Defaults
    this.generateSyntheticImpulse();
    this.updateDSP({
        masterVolume: 1.0,
        compressorThreshold: -24,
        compressorRatio: 12,
        eqLow: 0,
        eqMid: 0,
        eqHigh: 0,
        distortionAmount: 0,
        reverbMix: 0,
        delayTime: 0,
        delayFeedback: 0
    });
  }

  async resume() {
    if (this.ctx.state === 'suspended') {
      await this.ctx.resume();
    }
  }

  getCurrentTime(): number {
    return this.ctx.currentTime;
  }

  // --- DSP Control ---

  updateDSP(state: DSPState) {
    const t = this.ctx.currentTime;
    const ramptime = 0.1;

    // Master
    this.masterGain.gain.setTargetAtTime(state.masterVolume, t, ramptime);

    // Distortion
    this.setDistortion(state.distortionAmount);

    // EQ
    this.eqLowNode.gain.setTargetAtTime(state.eqLow, t, ramptime);
    this.eqMidNode.gain.setTargetAtTime(state.eqMid, t, ramptime);
    this.eqHighNode.gain.setTargetAtTime(state.eqHigh, t, ramptime);

    // Compressor
    this.compressorNode.threshold.setTargetAtTime(state.compressorThreshold, t, ramptime);
    this.compressorNode.ratio.setTargetAtTime(state.compressorRatio, t, ramptime);

    // FX Mixes
    // Dry/Wet balancing. If Reverb/Delay are 0, Dry is 1. 
    // As effects increase, we maintain Dry but add Wet (Parallel).
    // Or we can dip dry. Let's stick to Parallel processing (Dry stays at 1 unless mastered otherwise)
    // Actually for a "Mix" knob feel, let's dip dry slightly at extreme wetness to avoid clipping.
    this.dryNode.gain.setTargetAtTime(1.0, t, ramptime); 
    this.wetReverbNode.gain.setTargetAtTime(state.reverbMix, t, ramptime);

    // Delay
    // Avoid phasing at 0 time by gating output
    const delayOutGain = state.delayTime < 0.01 ? 0 : 0.8;
    this.delayNode.delayTime.setTargetAtTime(Math.max(0.01, state.delayTime), t, ramptime);
    this.delayFeedbackNode.gain.setTargetAtTime(state.delayFeedback, t, ramptime);
    this.delayOutNode.gain.setTargetAtTime(delayOutGain, t, ramptime);
    // Use reverb mix variable for delay send too for simplicity in this specific "Rack" UI, 
    // OR assuming state.delayTime implies usage. 
    // The prompt's previous state didn't have a "Delay Mix", only time/feedback. 
    // We'll assume the Delay Send is always active if Time > 0, controlled by feedback/time presence?
    // Let's set wetDelayNode to fixed 1.0 and control via Feedback/Out.
    this.wetDelayNode.gain.value = 1.0; 
  }

  private setDistortion(amount: number) {
    // 0 to 100
    if (amount <= 0) {
        this.distortionNode.curve = null;
        return;
    }
    const k = amount; 
    const n_samples = 44100;
    const curve = new Float32Array(n_samples);
    const deg = Math.PI / 180;
    for (let i = 0; i < n_samples; ++i) {
      const x = i * 2 / n_samples - 1;
      curve[i] = (3 + k) * x * 20 * deg / (Math.PI + k * Math.abs(x));
    }
    this.distortionNode.curve = curve;
    this.distortionNode.oversample = '4x';
  }

  private generateSyntheticImpulse() {
    const rate = this.ctx.sampleRate;
    const length = rate * 2; 
    const decay = 2.0;
    const impulse = this.ctx.createBuffer(2, length, rate);
    const impulseL = impulse.getChannelData(0);
    const impulseR = impulse.getChannelData(1);

    for (let i = 0; i < length; i++) {
        const n = length - i;
        const noise = (Math.random() * 2 - 1) * Math.pow(n / length, decay);
        impulseL[i] = noise;
        impulseR[i] = noise;
    }
    this.reverbNode.buffer = impulse;
  }

  // --- Playback Management ---

  playClip(clip: any, trackVolume: number, trackPan: number, projectStartOffset: number) {
    const clipStart = clip.startTime;
    const clipEnd = clip.startTime + clip.duration;

    if (clipEnd <= projectStartOffset) return;

    const source = this.ctx.createBufferSource();
    source.buffer = clip.buffer;

    // Track Chain: Source -> Gain -> Panner -> Mix Bus
    const gain = this.ctx.createGain();
    gain.gain.value = trackVolume;

    const panner = this.ctx.createStereoPanner();
    panner.pan.value = trackPan;

    source.connect(gain);
    gain.connect(panner);
    panner.connect(this.inputNode);

    let startWhen = 0;
    let startOffset = 0;
    let duration = 0;

    if (clipStart >= projectStartOffset) {
        startWhen = clipStart - projectStartOffset;
        startOffset = clip.offset;
        duration = clip.duration;
    } else {
        const timeIntoClip = projectStartOffset - clipStart;
        startWhen = 0;
        startOffset = clip.offset + timeIntoClip;
        duration = clip.duration - timeIntoClip;
    }

    if (duration > 0) {
        source.start(this.ctx.currentTime + startWhen, startOffset, duration);
        this.activeSources.set(clip.id, source);
        source.onended = () => this.activeSources.delete(clip.id);
    }
  }

  stopAll() {
    this.activeSources.forEach(source => {
      try { source.stop(); } catch(e) {}
    });
    this.activeSources.clear();
  }

  // --- Recording ---

  async startRecording(monitor: boolean): Promise<void> {
    await this.resume();
    this.stream = await navigator.mediaDevices.getUserMedia({ 
      audio: { 
        echoCancellation: false, 
        autoGainControl: false, 
        noiseSuppression: false, 
        latency: 0 
      } as any
    });

    const source = this.ctx.createMediaStreamSource(this.stream);

    if (monitor) {
      source.connect(this.ctx.destination);
    }

    this.mediaRecorder = new MediaRecorder(this.stream);
    this.mediaRecorder.start();
  }

  async stopRecording(): Promise<Blob> {
    return new Promise((resolve, reject) => {
      if (!this.mediaRecorder) return reject('No recorder');
      const chunks: BlobPart[] = [];
      this.mediaRecorder.ondataavailable = (e) => chunks.push(e.data);
      this.mediaRecorder.onstop = () => {
        const blob = new Blob(chunks, { type: 'audio/ogg; codecs=opus' });
        this.stream?.getTracks().forEach(track => track.stop());
        resolve(blob);
      };
      this.mediaRecorder.stop();
    });
  }

  // --- Utilities ---

  async decodeAudioData(blob: Blob): Promise<AudioBuffer> {
    const arrayBuffer = await blob.arrayBuffer();
    return await this.ctx.decodeAudioData(arrayBuffer);
  }

  async bounceMix(length: number, clips: any[], tracks: any[]): Promise<AudioBuffer> {
    const offlineCtx = new OfflineAudioContext(2, length * 44100, 44100);

    clips.forEach(clip => {
        const track = tracks.find((t:any) => t.id === clip.trackId);
        if (!track || track.muted) return;

        const source = offlineCtx.createBufferSource();
        source.buffer = clip.buffer;

        const gain = offlineCtx.createGain();
        gain.gain.value = track.volume;

        const panner = offlineCtx.createStereoPanner();
        panner.pan.value = track.pan || 0;

        source.connect(gain);
        gain.connect(panner);
        panner.connect(offlineCtx.destination);
        source.start(clip.startTime, clip.offset, clip.duration);
    });

    return await offlineCtx.startRendering();
  }

  splitBuffer(originalBuffer: AudioBuffer, splitTime: number): [AudioBuffer, AudioBuffer] {
    const rate = originalBuffer.sampleRate;
    const splitIndex = Math.floor(Math.max(0, Math.min(originalBuffer.duration, splitTime)) * rate);

    const len1 = splitIndex;
    const len2 = originalBuffer.length - splitIndex;

    if (len1 === 0 || len2 === 0) return [originalBuffer, originalBuffer]; 

    const part1 = this.ctx.createBuffer(originalBuffer.numberOfChannels, len1, rate);
    const part2 = this.ctx.createBuffer(originalBuffer.numberOfChannels, len2, rate);

    for (let i = 0; i < originalBuffer.numberOfChannels; i++) {
        const channelData = originalBuffer.getChannelData(i);
        part1.copyToChannel(channelData.subarray(0, splitIndex), i);
        part2.copyToChannel(channelData.subarray(splitIndex), i);
    }

    return [part1, part2];
  }
}

export const audioEngine = new AudioEngine();

import React, { useEffect, useRef } from 'react';
import { DSPState } from '../types';
import { Knob } from './Knob';
import { audioEngine } from '../services/audioEngine';

interface DSPRackProps {
  dspState: DSPState;
  onChange: (newState: DSPState) => void;
}

export const DSPRack: React.FC<DSPRackProps> = ({ dspState, onChange }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // Visualizer Loop
  useEffect(() => {
    let animationId: number;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const bufferLength = audioEngine.analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);

    const draw = () => {
      animationId = requestAnimationFrame(draw);

      audioEngine.analyser.getByteFrequencyData(dataArray);

      // Dark Tech Background
      ctx.fillStyle = '#0f172a';
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      // Grid
      ctx.strokeStyle = '#1e293b';
      ctx.lineWidth = 1;
      ctx.beginPath();
      for(let i=0; i<canvas.width; i+=20) { ctx.moveTo(i, 0); ctx.lineTo(i, canvas.height); }
      for(let i=0; i<canvas.height; i+=20) { ctx.moveTo(0, i); ctx.lineTo(canvas.width, i); }
      ctx.stroke();

      const barWidth = (canvas.width / bufferLength) * 2.5;
      let barHeight;
      let x = 0;

      for(let i = 0; i < bufferLength; i++) {
        barHeight = (dataArray[i] / 255) * canvas.height;

        // Gradient Bars
        const gradient = ctx.createLinearGradient(0, canvas.height, 0, 0);
        gradient.addColorStop(0, '#06b6d4'); // Cyan
        gradient.addColorStop(0.5, '#3b82f6'); // Blue
        gradient.addColorStop(1, '#a855f7'); // Purple

        ctx.fillStyle = gradient;
        ctx.fillRect(x, canvas.height - barHeight, barWidth, barHeight);

        x += barWidth + 1;
      }
    };

    draw();
    return () => cancelAnimationFrame(animationId);
  }, []);

  return (
    <div className="fixed bottom-0 left-0 right-0 h-[220px] bg-slate-900 border-t-2 border-slate-700 shadow-[0_-10px_40px_rgba(0,0,0,0.8)] z-50 flex flex-col">

      {/* Header / Visualizer Strip */}
      <div className="flex h-16 border-b border-slate-800 bg-black/40 relative">
        <canvas ref={canvasRef} width={600} height={64} className="w-full h-full opacity-60" />
