import React, { useState, useEffect, useRef, useCallback } from 'react';
import { audioEngine } from './services/audioEngine';
import { storageService } from './services/storageService';
import { Controls } from './components/Controls';
import { TrackLane } from './components/TrackLane';
import { DSPRack } from './components/DSPRack';
import { Track, AudioClip, EditMode, DSPState } from './types';
import { COLORS, TRACK_HEIGHT } from './constants';

const App: React.FC = () => {
  // State
  const [tracks, setTracks] = useState<Track[]>([
    { id: 't1', name: 'Vocals', color: COLORS[0], muted: false, solo: false, volume: 0.8, pan: 0 },
    { id: 't2', name: 'Guitar', color: COLORS[1], muted: false, solo: false, volume: 0.8, pan: -0.3 },
    { id: 't3', name: 'Drums', color: COLORS[2], muted: false, solo: false, volume: 0.8, pan: 0 },
    { id: 't4', name: 'Bass', color: COLORS[3], muted: false, solo: false, volume: 0.8, pan: 0 },
    { id: 't5', name: 'Keys', color: COLORS[4], muted: false, solo: false, volume: 0.7, pan: 0.4 },
  ]);
  const [clips, setClips] = useState<AudioClip[]>([]);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0); 
  const [zoom, setZoom] = useState(100); 

  const [editMode, setEditMode] = useState<EditMode>(EditMode.MOVE);
  const [dspState, setDspState] = useState<DSPState>({ 
      masterVolume: 1.0,
      compressorThreshold: -20,
      compressorRatio: 4,
      eqLow: 0,
      eqMid: 0,
      eqHigh: 0,
      distortionAmount: 0, 
      reverbMix: 0, 
      delayTime: 0,
      delayFeedback: 0
  });
  const [isRecording, setIsRecording] = useState(false);
  const [monitor, setMonitor] = useState(false);

  // Refs for loop management
  const rafRef = useRef<number>();
  const startTimeRef = useRef<number>(0); 
  const startOffsetRef = useRef<number>(0); 

  const dragRef = useRef<{ clipId: string; startX: number; originalStart: number } | null>(null);

  // --- Initialization ---
  useEffect(() => {
    storageService.init();

    // Auto-resume audio context on first touch
    const handleTouch = () => audioEngine.resume();
    document.addEventListener('touchstart', handleTouch, { once: true });
    document.addEventListener('click', handleTouch, { once: true });

    // Init Audio Engine Defaults
    audioEngine.updateDSP(dspState);

    return () => {
      cancelAnimationFrame(rafRef.current!);
    };
  }, []);

  // --- Playback Logic ---

  const updatePlayhead = useCallback(() => {
    if (audioEngine.ctx.state === 'running' && isPlaying) {
        const elapsed = audioEngine.ctx.currentTime - startTimeRef.current;
        setCurrentTime(startOffsetRef.current + elapsed);
    }
    rafRef.current = requestAnimationFrame(updatePlayhead);
  }, [isPlaying]);

  useEffect(() => {
    if (isPlaying) {
      rafRef.current = requestAnimationFrame(updatePlayhead);
    } else {
      cancelAnimationFrame(rafRef.current!);
    }
  }, [isPlaying, updatePlayhead]);

  const togglePlay = async () => {
    await audioEngine.resume();

    if (isPlaying) {
      // Pause
      audioEngine.stopAll();
      setIsPlaying(false);

      const elapsed = audioEngine.ctx.currentTime - startTimeRef.current;
      const newTime = startOffsetRef.current + elapsed;
      setCurrentTime(newTime);
      startOffsetRef.current = newTime;

    } else {
      // Play
      startTimeRef.current = audioEngine.ctx.currentTime;
      startOffsetRef.current = currentTime; 

      clips.forEach(clip => {
        const track = tracks.find(t => t.id === clip.trackId);
        if (track && !track.muted) {
           audioEngine.playClip(clip, track.volume, track.pan, currentTime);
        }
      });

      setIsPlaying(true);
    }
  };

  const stop = () => {
    audioEngine.stopAll();
    setIsPlaying(false);
    setCurrentTime(0);
    startOffsetRef.current = 0;
  };

  // --- Recording Logic ---

  const toggleRecord = async () => {
    if (isRecording) {
      const blob = await audioEngine.stopRecording();
      setIsRecording(false);

      const id = Date.now().toString();
      await storageService.saveBlob(id, blob);

      const buffer = await audioEngine.decodeAudioData(blob);
      const newClip: AudioClip = {
        id,
        trackId: tracks[0].id, 
        buffer,
        startTime: currentTime, 
        duration: buffer.duration,
        offset: 0,
        name: `Rec ${id.substr(-4)}`
      };
      setClips(prev => [...prev, newClip]);

    } else {
      await audioEngine.startRecording(monitor);
      setIsRecording(true);
      if (!isPlaying) togglePlay(); 
    }
  };

  // --- Interaction Logic ---

  const handleClipInteract = (clipId: string, action: string, data?: any) => {
    if (editMode === EditMode.SPLIT && action === 'tap') {
      splitClip(clipId);
      return;
    }

    if (editMode === EditMode.MOVE && action === 'start') {
      dragRef.current = { 
        clipId, 
        startX: data.x,
        originalStart: data.originalStart
      };

      const handleMove = (e: TouchEvent | MouseEvent) => {
        if (!dragRef.current) return;
        const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
        const deltaX = clientX - dragRef.current.startX;
        const deltaTime = deltaX / zoom; 

        const newStart = Math.max(0, dragRef.current.originalStart + deltaTime);

        setClips(prev => prev.map(c => 
          c.id === dragRef.current?.clipId ? { ...c, startTime: newStart } : c
        ));
      };

      const handleEnd = () => {
        dragRef.current = null;
        window.removeEventListener('touchmove', handleMove);
        window.removeEventListener('touchend', handleEnd);
        window.removeEventListener('mousemove', handleMove);
        window.removeEventListener('mouseup', handleEnd);
      };

      window.addEventListener('touchmove', handleMove, { passive: false });
      window.addEventListener('touchend', handleEnd);
      window.addEventListener('mousemove', handleMove);
      window.addEventListener('mouseup', handleEnd);
    }
  };

  const splitClip = (clipId: string) => {
    const clip = clips.find(c => c.id === clipId);
    if (!clip) return;

    const relativeSplitTime = currentTime - clip.startTime;
    if (relativeSplitTime <= 0 || relativeSplitTime >= clip.duration) return;

    const clip1: AudioClip = {
        ...clip,
        id: clip.id + '_1',
        duration: relativeSplitTime,
    };

    const clip2: AudioClip = {
        ...clip,
        id: clip.id + '_2',
        startTime: currentTime,
        duration: clip.duration - relativeSplitTime,
        offset: clip.offset + relativeSplitTime,
        name: clip.name + ' (Spl)'
    };

    setClips(prev => prev.filter(c => c.id !== clipId).concat([clip1, clip2]));
  };

  const handleDSPChange = (newState: DSPState) => {
    setDspState(newState);
    audioEngine.updateDSP(newState);
  };

  const handleBounce = async () => {
    if (clips.length === 0) return;
    const length = Math.max(...clips.map(c => c.startTime + c.duration));
    await audioEngine.bounceMix(length, clips, tracks);
    alert(`Bounced ${length.toFixed(2)}s.`);
  };

  const handleTimelineScrub = (e: React.TouchEvent | React.MouseEvent) => {
     const clientX = 'touches' in e ? e.touches[0].clientX : (e as React.MouseEvent).clientX;
     const scrollLeft = (e.currentTarget as HTMLElement).parentElement?.scrollLeft || 0;
     const time = Math.max(0, (clientX + scrollLeft) / zoom);

     setCurrentTime(time);
     startOffsetRef.current = time;

     if (isPlaying) {
         togglePlay().then(() => togglePlay());
     }
  };

  return (
    <div className="flex flex-col h-screen w-screen bg-slate-900 text-slate-100 overflow-hidden select-none font-sans">
      <Controls 
        isPlaying={isPlaying} 
        isRecording={isRecording}
        onPlayPause={togglePlay} 
        onRecord={toggleRecord} 
        onStop={stop}
        onBounce={handleBounce}
        editMode={editMode}
        setEditMode={setEditMode}
        monitor={monitor}
        setMonitor={setMonitor}
        zoom={zoom}
        setZoom={setZoom}
      />

      <div className="flex-1 overflow-y-auto overflow-x-auto relative mt-[60px] mb-[220px]">
        {/* Playhead */}
        <div 
            className="absolute top-0 bottom-0 z-30 pointer-events-none border-r border-red-500 shadow-[0_0_10px_rgba(239,68,68,0.8)]"
            style={{ left: `${currentTime * zoom}px`, width: '1px' }}
        >
            <div className="absolute -top-4 -translate-x-1/2 bg-red-600 text-[10px] px-2 py-0.5 rounded-full text-white font-mono shadow-md whitespace-nowrap z-40">
                {currentTime.toFixed(3)}s
            </div>
        </div>

        {/* Ruler */}
        <div 
            className="h-8 min-w-full bg-slate-800 border-b border-slate-700 relative cursor-pointer shadow-inner"
            style={{ width: `${Math.max(window.innerWidth, 300 * zoom)}px` }}
            onClick={handleTimelineScrub}
        >
             {Array.from({ length: Math.ceil(300 * zoom / 100) }).map((_, i) => (
                 <div key={i} className="absolute bottom-0 h-3 border-l border-slate-600 text-[9px] pl-1 text-slate-400 font-mono" style={{ left: i * 5 * zoom }}>
                     {i * 5}s
                 </div>
             ))}
        </div>

        {/* Tracks Area */}
        <div className="min-w-full pb-20 relative bg-[#0b101c]" style={{ width: `${Math.max(window.innerWidth, 300 * zoom)}px` }}>
          {tracks.map(track => (
            <div key={track.id} className="flex border-b border-slate-800/50">
               {/* Track Header */}
               <div className="sticky left-0 w-32 z-20 bg-slate-800 border-r border-slate-700 flex flex-col p-2 shadow-lg" style={{ height: TRACK_HEIGHT }}>
                  <div className="flex items-center justify-between mb-1">
                      <div className="font-bold text-xs truncate w-16" style={{color: track.color}}>{track.name}</div>
                      <div className="flex space-x-1">
                          <div className={`w-2 h-2 rounded-full ${track.muted ? 'bg-red-500' : 'bg-slate-600'}`} />
                          <div className={`w-2 h-2 rounded-full ${track.solo ? 'bg-yellow-500' : 'bg-slate-600'}`} />
                      </div>
                  </div>

                  {/* Volume Fader */}
                  <div className="flex items-center space-x-2 mt-1">
                      <span className="text-[8px] text-slate-500 w-3">VOL</span>
                      <input 
                        type="range" min="0" max="1" step="0.05" 
                        value={track.volume}
                        onChange={(e) => {
                            const val = parseFloat(e.target.value);
                            setTracks(ts => ts.map(t => t.id === track.id ? {...t, volume: val} : t));
                        }}
                        className="w-full h-1 bg-slate-600 rounded-lg appearance-none cursor-pointer accent-cyan-500"
                      />
                  </div>

                  {/* Pan Pot */}
                  <div className="flex items-center space-x-2 mt-2">
                      <span className="text-[8px] text-slate-500 w-3">PAN</span>
                      <input 
                        type="range" min="-1" max="1" step="0.1" 
                        value={track.pan}
                        onChange={(e) => {
                            const val = parseFloat(e.target.value);
                            setTracks(ts => ts.map(t => t.id === track.id ? {...t, pan: val} : t));
                        }}
                        className="w-full h-1 bg-slate-600 rounded-lg appearance-none cursor-pointer accent-yellow-500"
                      />
                  </div>
                  <div className="text-[8px] text-center text-slate-500 mt-1 font-mono">
                      {track.pan === 0 ? 'C' : track.pan > 0 ? `R${Math.round(track.pan*100)}` : `L${Math.round(Math.abs(track.pan)*100)}`}
                  </div>
               </div>

               <TrackLane 
                 track={track} 
                 clips={clips.filter(c => c.trackId === track.id)}
                 editMode={editMode}
                 onClipInteract={handleClipInteract}
                 currentTime={currentTime}
                 isPlaying={isPlaying}
                 zoom={zoom}
               />
            </div>
          ))}
        </div>
      </div>

      <DSPRack dspState={dspState} onChange={handleDSPChange} />
    </div>
  );
};

export default App;

