}

import React from 'react';
import { Track, AudioClip, EditMode } from '../types';
import { TRACK_HEIGHT } from '../constants';
import { Waveform } from './Waveform';

interface TrackLaneProps {
  track: Track;
  clips: AudioClip[];
  editMode: EditMode;
  selectedClipId: string | null;
  onClipInteract: (clipId: string, action: 'start' | 'move' | 'end' | 'tap', data?: any) => void;
  currentTime: number;
  isPlaying: boolean;
  zoom: number; // Pixels per second
}

export const TrackLane: React.FC<TrackLaneProps> = ({ 
  track, 
  clips, 
  editMode,
  selectedClipId,
  onClipInteract,
  zoom
}) => {
  // Dynamic Grid sizing
  const majorGrid = 1.0 * zoom; 
  const minorGrid = 0.25 * zoom;

  return (
    <div 
      className={`relative w-full border-b border-slate-700 transition-colors ${track.armed ? 'bg-red-900/10' : 'bg-slate-800/50'}`}
      style={{ height: TRACK_HEIGHT }}
      data-track-id={track.id}
    >
      {/* Track Background Grid */}
      <div 
        className="absolute inset-0 pointer-events-none opacity-20"
        style={{
             backgroundImage: `
                linear-gradient(90deg, #334155 1px, transparent 1px),
                linear-gradient(90deg, #1e293b 1px, transparent 1px)
             `,
             backgroundSize: `${majorGrid}px 100%, ${minorGrid}px 100%`
        }}
      ></div>

      {clips.map(clip => {
        const left = clip.startTime * zoom;
        const width = clip.duration * zoom;
        const isSelected = selectedClipId === clip.id;

        const fullBufferWidth = clip.buffer.duration * zoom;
        const offsetLeft = -(clip.offset * zoom);

        return (
          <div
            key={clip.id}
            className={`absolute top-2 bottom-2 rounded-md overflow-hidden touch-none transition-shadow
              ${isSelected ? 'ring-2 ring-yellow-400 z-10 shadow-[0_0_15px_rgba(250,204,21,0.3)]' : 'border border-white/10 shadow-sm'}
              ${editMode === EditMode.SPLIT ? 'cursor-crosshair' : 'cursor-move'}`}
            style={{ 
              left: `${left}px`, 
              width: `${width}px`,
              backgroundColor: isSelected ? '#334155' : (track.color + '30')
            }}
            onTouchStart={(e) => {
              e.stopPropagation();
              onClipInteract(clip.id, 'start', { 
                x: e.touches[0].clientX, 
                y: e.touches[0].clientY,
                originalStart: clip.startTime
              });
            }}
            onMouseDown={(e) => {
              e.stopPropagation();
              onClipInteract(clip.id, 'start', { 
                x: e.clientX, 
                y: e.clientY,
                originalStart: clip.startTime
              });
            }}
            onClick={(e) => {
               e.stopPropagation();
               onClipInteract(clip.id, 'tap');
            }}
          >
            {/* Waveform Container */}
            <div 
                className="absolute top-0 bottom-0 pointer-events-none opacity-90"
                style={{ 
                    left: `${offsetLeft}px`,
                    width: `${fullBufferWidth}px` 
                }}
            >
                <Waveform 
                  buffer={clip.buffer} 
                  color={isSelected ? '#facc15' : track.color} 
                  width={fullBufferWidth} 
                  height={TRACK_HEIGHT - 16} 
                />
            </div>

            {/* Clip Header */}
            <div className="absolute top-0 left-0 right-0 h-4 bg-gradient-to-b from-black/60 to-transparent px-1 flex items-center">
                <span className={`text-[9px] font-mono truncate ${isSelected ? 'text-yellow-200' : 'text-white/70'}`}>
                    {clip.name}
                </span>
            </div>

            {/* Selection Handle Indicators (Visual only for now) */}
            {isSelected && (
                <>
                    <div className="absolute left-0 top-0 bottom-0 w-1 bg-yellow-500/50"></div>
                    <div className="absolute right-0 top-0 bottom-0 w-1 bg-yellow-500/50"></div>
                </>
            )}
          </div>
        );
      })}
    </div>
  );
};

import React from 'react';
import { EditMode } from '../types';

interface ControlsProps {
  isPlaying: boolean;
  isRecording: boolean;
  onPlayPause: () => void;
  onRecord: () => void;
  onStop: () => void;
  onBounce: () => void;
  onDelete: () => void;
  editMode: EditMode;
  setEditMode: (mode: EditMode) => void;
  monitor: boolean;
  setMonitor: (val: boolean) => void;
  zoom: number;
  setZoom: (val: number) => void;
  hasSelection: boolean;
}

export const Controls: React.FC<ControlsProps> = ({
  isPlaying, isRecording, onPlayPause, onRecord, onStop, onBounce, onDelete,
  editMode, setEditMode, monitor, setMonitor, zoom, setZoom, hasSelection
}) => {
  return (
    <div className="fixed top-0 left-0 right-0 h-[60px] bg-[#0f172a] border-b border-slate-800 flex items-center justify-between px-2 md:px-4 z-50 shadow-2xl">

      {/* Transport */}
      <div className="flex items-center space-x-3 bg-slate-900/50 p-1 rounded-full border border-slate-800">
        <button
          className={`w-10 h-10 rounded-full flex items-center justify-center transition-all shadow-inner ${isRecording ? 'bg-red-600 animate-pulse shadow-red-500/50' : 'bg-slate-800 hover:bg-slate-700'}`}
          onClick={onRecord}
        >
          <div className={`w-3 h-3 rounded-full ${isRecording ? 'bg-white' : 'bg-red-500'}`}></div>
        </button>
        <button
          className="w-10 h-10 rounded-full bg-slate-200 hover:bg-white flex items-center justify-center active:scale-95 transition-transform shadow-lg shadow-white/10"
          onClick={onPlayPause}
        >
          {isPlaying ? (
            <div className="w-3 h-3 flex space-x-1 justify-center">
              <div className="w-1 h-full bg-slate-900 rounded-sm"></div>
              <div className="w-1 h-full bg-slate-900 rounded-sm"></div>
            </div>
          ) : (
             <div className="w-0 h-0 border-t-[6px] border-t-transparent border-l-[10px] border-l-slate-900 border-b-[6px] border-b-transparent ml-1"></div>
          )}
        </button>
        <button
          className="w-8 h-8 rounded-full bg-slate-800 flex items-center justify-center text-[10px] font-bold text-slate-400 hover:text-white active:scale-95 transition-transform border border-slate-700"
          onClick={onStop}
        >
          ■
        </button>
      </div>

      {/* Editing Tools */}
      <div className="flex items-center space-x-2">
         <div className="flex bg-slate-800 rounded-lg p-0.5 border border-slate-700">
             <button 
               className={`px-3 py-1.5 rounded-md text-[10px] font-bold transition-colors ${editMode === EditMode.MOVE ? 'bg-slate-600 text-white shadow-sm' : 'text-slate-400 hover:text-slate-200'}`}
               onClick={() => setEditMode(EditMode.MOVE)}
             >
               MOVE
             </button>
             <button 
               className={`px-3 py-1.5 rounded-md text-[10px] font-bold transition-colors ${editMode === EditMode.SPLIT ? 'bg-slate-600 text-white shadow-sm' : 'text-slate-400 hover:text-slate-200'}`}
               onClick={() => setEditMode(EditMode.SPLIT)}
             >
               SPLIT
             </button>
         </div>

         {/* Contextual Delete Action */}
         <button 
            disabled={!hasSelection}
            onClick={onDelete}
            className={`w-8 h-8 flex items-center justify-center rounded border transition-all
                ${hasSelection 
                    ? 'border-red-500/50 text-red-500 hover:bg-red-500 hover:text-white cursor-pointer' 
                    : 'border-slate-800 text-slate-700 cursor-not-allowed opacity-50'}`}
         >
            <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6"></polyline><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path></svg>
         </button>
      </div>

      {/* View & Utils */}
      <div className="flex items-center space-x-3">
        <div className="flex flex-col items-center group">
            <div className="flex -space-x-px">
                <button 
                    className="h-6 px-2 bg-slate-800 border border-slate-700 rounded-l text-xs text-slate-400 hover:bg-slate-700"
                    onClick={() => setZoom(Math.max(10, zoom * 0.8))}
                >-</button>
                <button 
                    className="h-6 px-2 bg-slate-800 border border-slate-700 rounded-r text-xs text-slate-400 hover:bg-slate-700"
                    onClick={() => setZoom(Math.min(500, zoom * 1.25))}
                >+</button>
            </div>
        </div>

        <button
          className={`px-2 h-6 rounded border text-[9px] font-bold tracking-wider transition-colors ${monitor ? 'bg-green-500/20 border-green-500 text-green-400' : 'border-slate-700 text-slate-500 hover:text-slate-300'}`}
          onClick={() => setMonitor(!monitor)}
        >
          MON
        </button>

        <button onClick={onBounce} className="h-6 px-3 bg-cyan-600 hover:bg-cyan-500 text-white text-[10px] font-bold rounded shadow-lg shadow-cyan-900/50">
          EXPORT
        </button>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { audioEngine } from './services/audioEngine';
import { storageService } from './services/storageService';
import { Controls } from './components/Controls';
import { TrackLane } from './components/TrackLane';
import { DSPRack } from './components/DSPRack';
import { Track, AudioClip, EditMode, DSPState } from './types';
import { COLORS, TRACK_HEIGHT } from './constants';

const App: React.FC = () => {
  // State
  const [tracks, setTracks] = useState<Track[]>([
    { id: 't1', name: 'Vocals', color: COLORS[0], muted: false, solo: false, armed: true, volume: 0.8, pan: 0 },
    { id: 't2', name: 'Guitar', color: COLORS[1], muted: false, solo: false, armed: false, volume: 0.8, pan: -0.3 },
    { id: 't3', name: 'Drums', color: COLORS[2], muted: false, solo: false, armed: false, volume: 0.8, pan: 0 },
    { id: 't4', name: 'Bass', color: COLORS[3], muted: false, solo: false, armed: false, volume: 0.8, pan: 0 },
    { id: 't5', name: 'Keys', color: COLORS[4], muted: false, solo: false, armed: false, volume: 0.7, pan: 0.4 },
  ]);
  const [clips, setClips] = useState<AudioClip[]>([]);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0); 
  const [zoom, setZoom] = useState(100); 
  const [selectedClipId, setSelectedClipId] = useState<string | null>(null);

  const [editMode, setEditMode] = useState<EditMode>(EditMode.MOVE);
  const [dspState, setDspState] = useState<DSPState>({ 
      masterVolume: 1.0,
      compressorThreshold: -20,
      compressorRatio: 4,
      eqLow: 0,
      eqMid: 0,
      eqHigh: 0,
      distortionAmount: 0, 
      reverbMix: 0, 
      delayTime: 0,
      delayFeedback: 0
  });
  const [isRecording, setIsRecording] = useState(false);
  const [monitor, setMonitor] = useState(false);

  // Refs for loop management
  const rafRef = useRef<number>();
  const startTimeRef = useRef<number>(0); 
  const startOffsetRef = useRef<number>(0); 

  const dragRef = useRef<{ clipId: string; startX: number; originalStart: number } | null>(null);

  // --- Initialization ---
  useEffect(() => {
    storageService.init();

    // Auto-resume audio context on first touch
    const handleTouch = () => audioEngine.resume();
    document.addEventListener('touchstart', handleTouch, { once: true });
    document.addEventListener('click', handleTouch, { once: true });

    // Init Audio Engine Defaults
    audioEngine.updateDSP(dspState);

    return () => {
      cancelAnimationFrame(rafRef.current!);
    };
  }, []);

  // --- Playback Logic ---

  const updatePlayhead = useCallback(() => {
    if (audioEngine.ctx.state === 'running' && isPlaying) {
        const elapsed = audioEngine.ctx.currentTime - startTimeRef.current;
        setCurrentTime(startOffsetRef.current + elapsed);
    }
    rafRef.current = requestAnimationFrame(updatePlayhead);
  }, [isPlaying]);

  useEffect(() => {
    if (isPlaying) {
      rafRef.current = requestAnimationFrame(updatePlayhead);
    } else {
      cancelAnimationFrame(rafRef.current!);
    }
  }, [isPlaying, updatePlayhead]);

  const togglePlay = async () => {
    await audioEngine.resume();

    if (isPlaying) {
      // Pause
      audioEngine.stopAll();
      setIsPlaying(false);

      const elapsed = audioEngine.ctx.currentTime - startTimeRef.current;
      const newTime = startOffsetRef.current + elapsed;
      setCurrentTime(newTime);
      startOffsetRef.current = newTime;

    } else {
      // Play
      startTimeRef.current = audioEngine.ctx.currentTime;
      startOffsetRef.current = currentTime; 

      clips.forEach(clip => {
        const track = tracks.find(t => t.id === clip.trackId);
        if (track && !track.muted && (!tracks.some(t => t.solo) || track.solo)) {
           audioEngine.playClip(clip, track.volume, track.pan, currentTime);
        }
      });

      setIsPlaying(true);
    }
  };

  const stop = () => {
    audioEngine.stopAll();
    setIsPlaying(false);
    setCurrentTime(0);
    startOffsetRef.current = 0;
  };

  // --- Recording Logic ---

  const toggleRecord = async () => {
    if (isRecording) {
      const blob = await audioEngine.stopRecording();
      setIsRecording(false);

      const id = Date.now().toString();
      await storageService.saveBlob(id, blob);
      const buffer = await audioEngine.decodeAudioData(blob);

      // Find armed track
      const armedTrack = tracks.find(t => t.armed) || tracks[0];

      const newClip: AudioClip = {
        id,
        trackId: armedTrack.id, 
        buffer,
        startTime: currentTime, 
        duration: buffer.duration,
        offset: 0,
        name: `Rec ${id.substr(-4)}`
      };
      setClips(prev => [...prev, newClip]);
      setSelectedClipId(id);

    } else {
      await audioEngine.startRecording(monitor);
      setIsRecording(true);
      if (!isPlaying) togglePlay(); 
    }
  };

  const toggleTrackArm = (trackId: string) => {
      setTracks(prev => prev.map(t => ({
          ...t,
          armed: t.id === trackId // Exclusive arming for mobile simplicity
      })));
  };

  // --- Interaction Logic ---

  const handleClipInteract = (clipId: string, action: string, data?: any) => {
    // Selection Logic
    if (action === 'tap') {
        setSelectedClipId(clipId);
        if (editMode === EditMode.SPLIT) {
            splitClip(clipId);
        }
        return;
    }

    if (editMode === EditMode.MOVE && action === 'start') {
      setSelectedClipId(clipId);
      dragRef.current = { 
        clipId, 
        startX: data.x,
        originalStart: data.originalStart
      };

      const handleMove = (e: TouchEvent | MouseEvent) => {
        if (!dragRef.current) return;
        const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
        const deltaX = clientX - dragRef.current.startX;
        const deltaTime = deltaX / zoom; 

        let newStart = Math.max(0, dragRef.current.originalStart + deltaTime);

        // Snap to Grid Logic
        const snapIncrement = 0.25; // 0.25s grid
        newStart = Math.round(newStart / snapIncrement) * snapIncrement;

        setClips(prev => prev.map(c => 
          c.id === dragRef.current?.clipId ? { ...c, startTime: newStart } : c
        ));
      };

      const handleEnd = () => {
        dragRef.current = null;
        window.removeEventListener('touchmove', handleMove);
        window.removeEventListener('touchend', handleEnd);
        window.removeEventListener('mousemove', handleMove);
        window.removeEventListener('mouseup', handleEnd);
      };

      window.addEventListener('touchmove', handleMove, { passive: false });
      window.addEventListener('touchend', handleEnd);
      window.addEventListener('mousemove', handleMove);
      window.addEventListener('mouseup', handleEnd);
    }
  };

  const splitClip = (clipId: string) => {
    const clip = clips.find(c => c.id === clipId);
    if (!clip) return;

    const relativeSplitTime = currentTime - clip.startTime;
    if (relativeSplitTime <= 0.05 || relativeSplitTime >= clip.duration - 0.05) return;

    const clip1: AudioClip = {
        ...clip,
        id: clip.id + '_1',
        duration: relativeSplitTime,
    };

    const clip2: AudioClip = {
        ...clip,
        id: clip.id + '_2',
        startTime: currentTime,
        duration: clip.duration - relativeSplitTime,
        offset: clip.offset + relativeSplitTime,
        name: clip.name
    };

    setClips(prev => prev.filter(c => c.id !== clipId).concat([clip1, clip2]));
    setSelectedClipId(clip2.id);
  };

  const deleteSelectedClip = () => {
      if (!selectedClipId) return;
      setClips(prev => prev.filter(c => c.id !== selectedClipId));
      setSelectedClipId(null);
  };

  const handleDSPChange = (newState: DSPState) => {
    setDspState(newState);
    audioEngine.updateDSP(newState);
  };

  const handleBounce = async () => {
    if (clips.length === 0) return;
    const length = Math.max(...clips.map(c => c.startTime + c.duration));
    await audioEngine.bounceMix(length, clips, tracks);
    alert(`Bounced ${length.toFixed(2)}s.`);
  };

  const handleTimelineScrub = (e: React.TouchEvent | React.MouseEvent) => {
     // Deselect on background click
     if ((e.target as HTMLElement).dataset.bg) {
         setSelectedClipId(null);
     }

     const clientX = 'touches' in e ? e.touches[0].clientX : (e as React.MouseEvent).clientX;
     const scrollLeft = (e.currentTarget as HTMLElement).parentElement?.scrollLeft || 0;

     // Only scrub if clicking ruler area or specialized background handler
     // We approximate by just using the calculation
     const time = Math.max(0, (clientX + scrollLeft) / zoom);

     // Snap playhead too? Optional, but lets keep it smooth for scrubbing
     setCurrentTime(time);
     startOffsetRef.current = time;

     if (isPlaying) {
         togglePlay().then(() => togglePlay());
     }
  };

  return (
    <div className="flex flex-col h-screen w-screen bg-[#020617] text-slate-100 overflow-hidden select-none font-sans">
      <Controls 
        isPlaying={isPlaying} 
        isRecording={isRecording}
        onPlayPause={togglePlay} 
        onRecord={toggleRecord} 
        onStop={stop}
        onBounce={handleBounce}
        onDelete={deleteSelectedClip}
        editMode={editMode}
        setEditMode={setEditMode}
        monitor={monitor}
        setMonitor={setMonitor}
        zoom={zoom}
        setZoom={setZoom}
        hasSelection={!!selectedClipId}
      />

      <div className="flex-1 overflow-y-auto overflow-x-auto relative mt-[60px] mb-[220px]" onClick={() => setSelectedClipId(null)}>
        {/* Playhead */}
        <div 
            className="absolute top-0 bottom-0 z-40 pointer-events-none border-r border-red-500 shadow-[0_0_10px_rgba(239,68,68,0.8)]"
            style={{ left: `${currentTime * zoom}px`, width: '1px' }}
        >
            <div className="absolute -top-4 -translate-x-1/2 bg-red-600 text-[9px] px-1.5 py-0.5 rounded-sm text-white font-mono shadow-md whitespace-nowrap z-50">
                {currentTime.toFixed(2)}s
            </div>
        </div>

        {/* Ruler */}
        <div 
            className="h-8 min-w-full bg-[#0f172a] border-b border-slate-700 relative cursor-pointer shadow-lg z-30"
            style={{ width: `${Math.max(window.innerWidth, 300 * zoom)}px` }}
            onClick={(e) => { e.stopPropagation(); handleTimelineScrub(e); }}
        >
             {Array.from({ length: Math.ceil(300 * zoom / 100) * 4 }).map((_, i) => {
                 const isSecond = i % 4 === 0;
                 return (
                 <div key={i} className={`absolute bottom-0 border-l ${isSecond ? 'h-3 border-slate-500' : 'h-1.5 border-slate-700'}`} style={{ left: i * 0.25 * zoom }}>
                     {isSecond && <span className="text-[9px] text-slate-500 pl-1 -mt-4 block">{i * 0.25}</span>}
                 </div>
             )})}
        </div>

        {/* Tracks Area */}
        <div className="min-w-full pb-20 relative bg-[#020617]" style={{ width: `${Math.max(window.innerWidth, 300 * zoom)}px` }}>
          {tracks.map(track => (
            <div key={track.id} className="flex border-b border-slate-800">
               {/* Channel Strip */}
               <div className="sticky left-0 w-36 z-20 bg-[#0f172a] border-r border-slate-800 flex flex-col p-2 shadow-xl" style={{ height: TRACK_HEIGHT }}>

                  {/* Row 1: Name & Arm */}
                  <div className="flex items-center justify-between mb-2">
                      <div className="font-bold text-xs truncate w-20 text-slate-200" style={{ textShadow: `0 0 10px ${track.color}40` }}>{track.name}</div>
                      <button 
                        onClick={() => toggleTrackArm(track.id)}
                        className={`w-4 h-4 rounded-full border flex items-center justify-center transition-all ${track.armed ? 'bg-red-900 border-red-500 shadow-[0_0_8px_rgba(239,68,68,0.6)]' : 'bg-slate-800 border-slate-600'}`}
                      >
                          <div className={`w-1.5 h-1.5 rounded-full ${track.armed ? 'bg-red-500' : 'bg-slate-500'}`} />
                      </button>
                  </div>

                  {/* Row 2: Mute/Solo */}
                  <div className="flex space-x-2 mb-3">
                      <button 
                        className={`flex-1 py-0.5 text-[9px] font-bold rounded border transition-colors ${track.muted ? 'bg-orange-500/20 text-orange-400 border-orange-500' : 'bg-slate-800 text-slate-500 border-slate-600'}`}
                        onClick={() => setTracks(ts => ts.map(t => t.id === track.id ? {...t, muted: !t.muted} : t))}
                      >M</button>
                      <button 
                        className={`flex-1 py-0.5 text-[9px] font-bold rounded border transition-colors ${track.solo ? 'bg-yellow-500/20 text-yellow-400 border-yellow-500' : 'bg-slate-800 text-slate-500 border-slate-600'}`}
                        onClick={() => setTracks(ts => ts.map(t => t.id === track.id ? {...t, solo: !t.solo} : t))}
                      >S</button>
                  </div>

                  {/* Row 3: Volume */}
                  <div className="flex items-center space-x-2 mb-2">
                      <span className="text-[8px] text-slate-500 font-mono w-4">VOL</span>
                      <div className="flex-1 h-1 bg-slate-700 rounded-full relative group cursor-pointer">
                          <input 
                            type="range" min="0" max="1" step="0.01" 
                            value={track.volume}
                            onChange={(e) => {
                                const val = parseFloat(e.target.value);
                                setTracks(ts => ts.map(t => t.id === track.id ? {...t, volume: val} : t));
                            }}
                            className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
                          />
                          <div className="h-full bg-cyan-500 rounded-full relative" style={{width: `${track.volume * 100}%`}}>
                              <div className="absolute right-0 top-1/2 -translate-y-1/2 w-2 h-2 bg-white rounded-full shadow-md scale-0 group-hover:scale-100 transition-transform"></div>
                          </div>
                      </div>
                  </div>

                  {/* Row 4: Pan */}
                  <div className="flex items-center space-x-2">
                      <span className="text-[8px] text-slate-500 font-mono w-4">PAN</span>
                      <div className="flex-1 h-1 bg-slate-700 rounded-full relative group cursor-pointer">
                          {/* Center Marker */}
                          <div className="absolute left-1/2 top-0 bottom-0 w-px bg-slate-500"></div>
                          <input 
                            type="range" min="-1" max="1" step="0.1" 
                            value={track.pan}
                            onChange={(e) => {
                                const val = parseFloat(e.target.value);
                                setTracks(ts => ts.map(t => t.id === track.id ? {...t, pan: val} : t));
                            }}
                            className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
                          />
                          <div 
                            className="absolute top-1/2 -translate-y-1/2 h-2 w-1 bg-yellow-500 rounded-sm shadow transition-all" 
                            style={{left: `${((track.pan + 1) / 2) * 100}%`, transform: 'translate(-50%, -50%)'}} 
                          />
                      </div>
                  </div>

                  {/* Track Color Strip */}
                  <div className="absolute top-0 bottom-0 right-0 w-1" style={{ backgroundColor: track.color }}></div>
               </div>

               <TrackLane 
                 track={track} 
                 clips={clips.filter(c => c.trackId === track.id)}
                 editMode={editMode}
                 selectedClipId={selectedClipId}
                 onClipInteract={handleClipInteract}
                 currentTime={currentTime}
                 isPlaying={isPlaying}
                 zoom={zoom}
               />
            </div>
          ))}
        </div>
      </div>

      <DSPRack dspState={dspState} onChange={handleDSPChange} />
    </div>
  );
};

