  return (
    <div className="sticky left-0 w-36 z-20 bg-[#0f172a] border-r border-slate-800 flex flex-col p-2 shadow-xl select-none" style={{ height: TRACK_HEIGHT }}>

       {/* Header: Color Swatch + Name + Arm */}
