import React, { useState, useEffect, useRef, useCallback } from 'react';
import { audioEngine } from './services/audioEngine';
import { storageService } from './services/storageService';
import { Controls } from './components/Controls';
import { TrackLane } from './components/TrackLane';
import { ChannelStrip } from './components/ChannelStrip';
import { DSPRack } from './components/DSPRack';
import { Track, AudioClip, EditMode, DSPState } from './types';
import { COLORS, TRACK_HEIGHT, CHANNEL_WIDTH } from './constants';

const App: React.FC = () => {
  // State
  const [tracks, setTracks] = useState<Track[]>([
    { id: 't1', name: 'Track 1', color: COLORS[0], muted: false, solo: false, armed: true, volume: 0.8, pan: 0 },
    { id: 't2', name: 'Track 2', color: COLORS[1], muted: false, solo: false, armed: false, volume: 0.8, pan: -0.3 },
    { id: 't3', name: 'Track 3', color: COLORS[2], muted: false, solo: false, armed: false, volume: 0.8, pan: 0 },
    { id: 't4', name: 'Track 4', color: COLORS[3], muted: false, solo: false, armed: false, volume: 0.8, pan: 0 },
    { id: 't5', name: 'Track 5', color: COLORS[4], muted: false, solo: false, armed: false, volume: 0.7, pan: 0.4 },
  ]);
  const [clips, setClips] = useState<AudioClip[]>([]);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0); 
  const [zoom, setZoom] = useState(100); 
  const [selectedClipId, setSelectedClipId] = useState<string | null>(null);

  const [editMode, setEditMode] = useState<EditMode>(EditMode.MOVE);
  const [dspState, setDspState] = useState<DSPState>({ 
      masterVolume: 1.0,
      compressorThreshold: -20,
      compressorRatio: 4,
      eqLow: 0,
      eqMid: 0,
      eqHigh: 0,
      distortionAmount: 0, 
      reverbMix: 0, 
      delayTime: 0,
      delayFeedback: 0
  });
  const [isRecording, setIsRecording] = useState(false);
  const [monitor, setMonitor] = useState(false);

  // Refs for loop management
  const rafRef = useRef<number>();
  const startTimeRef = useRef<number>(0); 
  const startOffsetRef = useRef<number>(0); 
  const recordingStartRef = useRef<number>(0); 

  const dragRef = useRef<{ clipId: string; startX: number; originalStart: number } | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // --- Initialization ---
  useEffect(() => {
    storageService.init();

    // Auto-resume audio context on first touch
    const handleTouch = () => audioEngine.resume();
    document.addEventListener('touchstart', handleTouch, { once: true });
    document.addEventListener('click', handleTouch, { once: true });

    // Init Audio Engine Defaults
    audioEngine.updateDSP(dspState);

    return () => {
      cancelAnimationFrame(rafRef.current!);
    };
  }, []);

  // --- Playback Logic ---

  const updatePlayhead = useCallback(() => {
    if (audioEngine.ctx.state === 'running' && isPlaying) {
        const elapsed = audioEngine.ctx.currentTime - startTimeRef.current;
        setCurrentTime(startOffsetRef.current + elapsed);
    }
    rafRef.current = requestAnimationFrame(updatePlayhead);
  }, [isPlaying]);

  useEffect(() => {
    if (isPlaying) {
      rafRef.current = requestAnimationFrame(updatePlayhead);
    } else {
      cancelAnimationFrame(rafRef.current!);
    }
  }, [isPlaying, updatePlayhead]);

  const togglePlay = async () => {
    await audioEngine.resume();

    if (isPlaying) {
      // Pause
      audioEngine.stopAll();
      setIsPlaying(false);

      const elapsed = audioEngine.ctx.currentTime - startTimeRef.current;
      const newTime = startOffsetRef.current + elapsed;
      setCurrentTime(newTime);
      startOffsetRef.current = newTime;

    } else {
      // Play
      startTimeRef.current = audioEngine.ctx.currentTime;
      startOffsetRef.current = currentTime; 

      clips.forEach(clip => {
        const track = tracks.find(t => t.id === clip.trackId);
        if (track && !track.muted && (!tracks.some(t => t.solo) || track.solo)) {
           audioEngine.playClip(clip, track.volume, track.pan, currentTime);
        }
      });

      setIsPlaying(true);
    }
  };

  // --- Recording Logic ---

  const stopRecordingAndSave = async () => {
      const blob = await audioEngine.stopRecording();
      setIsRecording(false);

      const id = Date.now().toString();
      await storageService.saveBlob(id, blob);
      const buffer = await audioEngine.decodeAudioData(blob);

      const armedTrack = tracks.find(t => t.armed) || tracks[0];

      const newClip: AudioClip = {
        id,
        trackId: armedTrack.id, 
        buffer,
        startTime: recordingStartRef.current,
        duration: buffer.duration,
        offset: 0,
        name: `Rec ${id.substr(-4)}`
      };
      setClips(prev => [...prev, newClip]);
      setSelectedClipId(id);
  };

  const toggleRecord = async () => {
    if (isRecording) {
      await stopRecordingAndSave();
    } else {
      recordingStartRef.current = currentTime; 
      await audioEngine.startRecording(monitor);
      setIsRecording(true);
      if (!isPlaying) {
          await togglePlay();
      }
    }
  };

  const stop = async () => {
    // Determine return point BEFORE stopping playback state
    const returnTime = isRecording ? recordingStartRef.current : startOffsetRef.current;

    if (isRecording) {
        await stopRecordingAndSave();
    }

    audioEngine.stopAll();
    setIsPlaying(false);

    // Reset playhead to Start or Recording Start
    setCurrentTime(returnTime);
    startOffsetRef.current = returnTime;
  };

  const handleTrackUpdate = (trackId: string, updates: Partial<Track>) => {
    setTracks(prev => prev.map(t => t.id === trackId ? { ...t, ...updates } : t));
  };

  const toggleTrackArm = (trackId: string) => {
      setTracks(prev => prev.map(t => ({
          ...t,
          armed: t.id === trackId 
      })));
  };

  // --- Interaction Logic ---

  const handleClipInteract = (clipId: string, action: string, data?: any) => {
    // Tap to Select or Split
    if (action === 'tap') {
        setSelectedClipId(clipId);

        // If in SPLIT mode, move playhead to tap and Split immediately
        if (editMode === EditMode.SPLIT && data?.x && containerRef.current) {
            const containerLeft = containerRef.current.getBoundingClientRect().left;
            const scrollLeft = containerRef.current.scrollLeft;

            // Calculate time from tap X (accounting for Channel Width offset)
            const clickX = data.x - containerLeft + scrollLeft - CHANNEL_WIDTH;
            const tapTime = Math.max(0, clickX / zoom);

            setCurrentTime(tapTime);
            startOffsetRef.current = tapTime; // Update sync ref

            splitClip(clipId, tapTime);
        }
        return;
    }

    // Move / Drag
    if (editMode === EditMode.MOVE && action === 'start') {
      setSelectedClipId(clipId);
      dragRef.current = { 
        clipId, 
        startX: data.x,
        originalStart: data.originalStart
      };

      const handleMove = (e: TouchEvent | MouseEvent) => {
        if (!dragRef.current || !containerRef.current) return;
        const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
        const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;

        const deltaX = clientX - dragRef.current.startX;
        const deltaTime = deltaX / zoom; 

        let newStart = Math.max(0, dragRef.current.originalStart + deltaTime);

        // Snap to Grid
        const snapIncrement = 0.25; 
        newStart = Math.round(newStart / snapIncrement) * snapIncrement;

        // Track Switching Calculation
        const containerRect = containerRef.current.getBoundingClientRect();
        // Relative Y inside the scroll container
        const relativeY = clientY - containerRect.top + containerRef.current.scrollTop;

        // Calculate track index based on Y position
        // Each track is TRACK_HEIGHT + border (1px)
        const trackIndex = Math.floor(relativeY / TRACK_HEIGHT);
        const targetTrack = tracks[trackIndex];

        setClips(prev => prev.map(c => 
          c.id === dragRef.current?.clipId ? { 
              ...c, 
              startTime: newStart,
              trackId: targetTrack ? targetTrack.id : c.trackId 
          } : c
        ));
      };

      const handleEnd = () => {
        dragRef.current = null;
        window.removeEventListener('touchmove', handleMove);
        window.removeEventListener('touchend', handleEnd);
        window.removeEventListener('mousemove', handleMove);
        window.removeEventListener('mouseup', handleEnd);
      };

      window.addEventListener('touchmove', handleMove, { passive: false });
      window.addEventListener('touchend', handleEnd);
      window.addEventListener('mousemove', handleMove);
      window.addEventListener('mouseup', handleEnd);
    }
  };

  const splitClip = (clipId: string, splitTimeOverride?: number) => {
    const clip = clips.find(c => c.id === clipId);
    if (!clip) return;

    const timeToSplitAt = splitTimeOverride !== undefined ? splitTimeOverride : currentTime;
    const relativeSplitTime = timeToSplitAt - clip.startTime;

    // Validate split point is within clip bounds
    if (relativeSplitTime <= 0.05 || relativeSplitTime >= clip.duration - 0.05) return;

    const clip1: AudioClip = {
        ...clip,
        id: clip.id + '_1',
        duration: relativeSplitTime,
    };

    const clip2: AudioClip = {
        ...clip,
        id: clip.id + '_2',
        startTime: timeToSplitAt,
        duration: clip.duration - relativeSplitTime,
        offset: clip.offset + relativeSplitTime,
        name: clip.name
    };

    setClips(prev => prev.filter(c => c.id !== clipId).concat([clip1, clip2]));
    setSelectedClipId(clip2.id);
  };

  const deleteSelectedClip = () => {
      if (!selectedClipId) return;
      setClips(prev => prev.filter(c => c.id !== selectedClipId));
      setSelectedClipId(null);
  };

  const handleDSPChange = (newState: DSPState) => {
    setDspState(newState);
    audioEngine.updateDSP(newState);
  };

  const handleBounce = async () => {
    if (clips.length === 0) return;
    const length = Math.max(...clips.map(c => c.startTime + c.duration));
    await audioEngine.bounceMix(length, clips, tracks);
    alert(`Bounced ${length.toFixed(2)}s.`);
  };

  const handleTimelineScrub = (e: React.TouchEvent | React.MouseEvent) => {
     if ((e.target as HTMLElement).dataset.bg) {
         setSelectedClipId(null);
     }

     if (!containerRef.current) return;
     const clientX = 'touches' in e ? e.touches[0].clientX : (e as React.MouseEvent).clientX;
     const containerLeft = containerRef.current.getBoundingClientRect().left;
     const scrollLeft = containerRef.current.scrollLeft;

     // Calculate Time adjusting for Channel Header Width
     // x = (time * zoom) + CHANNEL_WIDTH
     // time = (x - CHANNEL_WIDTH) / zoom

     // The clickX relative to scroll container content:
     const relativeX = clientX - containerLeft + scrollLeft;

     const time = Math.max(0, (relativeX - CHANNEL_WIDTH) / zoom);

     setCurrentTime(time);
     startOffsetRef.current = time;

     if (isPlaying) {
         togglePlay().then(() => togglePlay());
     }
  };

  return (
    <div className="flex flex-col h-screen w-screen bg-[#020617] text-slate-100 overflow-hidden select-none font-sans">
      <Controls 
        isPlaying={isPlaying} 
        isRecording={isRecording}
        onPlayPause={togglePlay} 
        onRecord={toggleRecord} 
        onStop={stop}
        onBounce={handleBounce}
        onDelete={deleteSelectedClip}
        editMode={editMode}
        setEditMode={setEditMode}
        monitor={monitor}
        setMonitor={setMonitor}
        zoom={zoom}
        setZoom={setZoom}
        hasSelection={!!selectedClipId}
      />

      <div 
        ref={containerRef}
        className="flex-1 overflow-y-auto overflow-x-auto relative mt-[60px] mb-[220px]" 
        onClick={() => setSelectedClipId(null)} 
        data-bg="true"
      >
        {/* Playhead - Offset by CHANNEL_WIDTH */}
        <div 
            className="absolute top-0 bottom-0 z-40 pointer-events-none border-r border-red-500 shadow-[0_0_10px_rgba(239,68,68,0.8)]"
            style={{ left: `${(currentTime * zoom) + CHANNEL_WIDTH}px`, width: '1px' }}
        >
            <div className="absolute -top-4 -translate-x-1/2 bg-red-600 text-[9px] px-1.5 py-0.5 rounded-sm text-white font-mono shadow-md whitespace-nowrap z-50">
                {currentTime.toFixed(2)}s
            </div>
        </div>

        {/* Ruler - Offset by CHANNEL_WIDTH */}
        <div 
            className="h-8 min-w-full bg-[#0f172a] border-b border-slate-700 relative cursor-pointer shadow-lg z-30"
            style={{ width: `${Math.max(window.innerWidth, (300 * zoom) + CHANNEL_WIDTH)}px` }}
            onClick={(e) => { e.stopPropagation(); handleTimelineScrub(e); }}
        >
             {Array.from({ length: Math.ceil(300 * zoom / 100) * 4 }).map((_, i) => {
                 const isSecond = i % 4 === 0;
                 return (
                 <div key={i} className={`absolute bottom-0 border-l ${isSecond ? 'h-3 border-slate-500' : 'h-1.5 border-slate-700'}`} 
                      style={{ left: (i * 0.25 * zoom) + CHANNEL_WIDTH }}>
                     {isSecond && <span className="text-[9px] text-slate-500 pl-1 -mt-4 block">{i * 0.25}</span>}
                 </div>
             )})}
        </div>

        {/* Tracks Area */}
        <div className="min-w-full pb-20 relative bg-[#020617]" 
             style={{ width: `${Math.max(window.innerWidth, (300 * zoom) + CHANNEL_WIDTH)}px` }} 
             data-bg="true">
          {tracks.map(track => (
            <div key={track.id} className="flex border-b border-slate-800">

               <ChannelStrip 
                  track={track}
                  onUpdate={handleTrackUpdate}
                  onToggleArm={toggleTrackArm}
               />

               <TrackLane 
                 track={track} 
                 clips={clips.filter(c => c.trackId === track.id)}
                 editMode={editMode}
                 selectedClipId={selectedClipId}
                 onClipInteract={handleClipInteract}
                 currentTime={currentTime}
                 isPlaying={isPlaying}
                 zoom={zoom}
               />
            </div>
          ))}
        </div>
      </div>

      <DSPRack dspState={dspState} onChange={handleDSPChange} />
    </div>
  );
};

export default App;

export interface Track {
  id: string;
  name: string;
  color: string;
  muted: boolean;
  solo: boolean;
  armed: boolean; // Recording target
  volume: number; // 0 to 1
  pan: number; // -1 (Left) to 1 (Right)
}

export interface AudioClip {
  id: string;
  trackId: string;
  buffer: AudioBuffer;
  startTime: number; // Global timeline position in seconds
  duration: number; // Duration in seconds
  offset: number; // Offset into the buffer in seconds
  name: string;
}

export enum EditMode {
  MOVE = 'MOVE',
  SPLIT = 'SPLIT',
  DELETE = 'DELETE' // Now used for logic, though UI might use selection
}

export interface ProjectData {
  id: string;
  name: string;
  tracks: Track[];
  clips: {
    id: string;
    trackId: string;
    startTime: number;
    duration: number;
    offset: number;
    name: string;
    blobKey: string; // Reference to IDB blob
  }[];
}

export interface DSPState {
  // Master Bus
  masterVolume: number; // 0 to 1.5

  // Filter (New)
  filterCutoff: number; // 20Hz to 20000Hz
  filterResonance: number; // 0 to 20 Q

  // Dynamics
  compressorThreshold: number; // -60 to 0 dB
  compressorRatio: number; // 1 to 20

  // EQ
  eqLow: number; // -12 to 12 dB
  eqMid: number; // -12 to 12 dB
  eqHigh: number; // -12 to 12 dB

  // FX
  distortionAmount: number; // 0 to 100

  // Modulation (New)
  chorusMix: number; // 0 to 1
  chorusRate: number; // 0.1 to 10 Hz
  chorusDepth: number; // 0 to 1 (mapped to delay time)

  reverbMix: number; // 0 to 1
  delayTime: number; // 0 to 1
  delayFeedback: number; // 0 to 0.9
}

import { DSPState } from '../types';

export class AudioEngine {
  public ctx: AudioContext;
  public analyser: AnalyserNode;

  private masterGain: GainNode;
  private limiterNode: DynamicsCompressorNode;

  // Input Stage
  private inputNode: GainNode; 

  // FX Nodes
  private filterNode: BiquadFilterNode;
  private distortionNode: WaveShaperNode;

  // EQ Stage
  private eqLowNode: BiquadFilterNode;
  private eqMidNode: BiquadFilterNode;
  private eqHighNode: BiquadFilterNode;

  // Modulation (Chorus)
  private chorusSplitter: GainNode; // To wet
  private chorusDelay: DelayNode;
  private chorusLFO: OscillatorNode;
  private chorusLFOGain: GainNode;
  private chorusWetGain: GainNode;
  private chorusDryGain: GainNode;
  private chorusMerge: GainNode; // Recombines

  // Dynamics
  private compressorNode: DynamicsCompressorNode;

  // Spatial / FX Sends
  private reverbNode: ConvolverNode;
  private delayNode: DelayNode;
  private delayFeedbackNode: GainNode;

  // Routing Gains for Spatial
  private drySpatialNode: GainNode;
  private wetReverbNode: GainNode; 
  private wetDelayNode: GainNode; 
  private delayOutNode: GainNode;

  private activeSources: Map<string, AudioBufferSourceNode> = new Map();
  private stream: MediaStream | null = null;
  private mediaRecorder: MediaRecorder | null = null;

  constructor() {
    const AudioContextClass = (window.AudioContext || (window as any).webkitAudioContext);
    this.ctx = new AudioContextClass({ latencyHint: 'interactive' });

    // --- Node Creation ---

    this.masterGain = this.ctx.createGain();

    // Limiter (Brickwall-ish) at the very end
    this.limiterNode = this.ctx.createDynamicsCompressor();
    this.limiterNode.threshold.value = -0.5;
    this.limiterNode.knee.value = 0;
    this.limiterNode.ratio.value = 20;
    this.limiterNode.attack.value = 0.001;
    this.limiterNode.release.value = 0.1;

    this.analyser = this.ctx.createAnalyser();
    this.analyser.fftSize = 2048;
    this.analyser.smoothingTimeConstant = 0.85;

    this.inputNode = this.ctx.createGain();

    // Filter
    this.filterNode = this.ctx.createBiquadFilter();
    this.filterNode.type = 'lowpass';
    this.filterNode.frequency.value = 20000;
    this.filterNode.Q.value = 1;

    this.distortionNode = this.ctx.createWaveShaper();

    // EQ
    this.eqLowNode = this.ctx.createBiquadFilter();
    this.eqLowNode.type = 'lowshelf';
    this.eqLowNode.frequency.value = 200; // Hz

    this.eqMidNode = this.ctx.createBiquadFilter();
    this.eqMidNode.type = 'peaking';
    this.eqMidNode.frequency.value = 1000; // Hz
    this.eqMidNode.Q.value = 1.0;

    this.eqHighNode = this.ctx.createBiquadFilter();
    this.eqHighNode.type = 'highshelf';
    this.eqHighNode.frequency.value = 3000; // Hz

    // Chorus
    this.chorusSplitter = this.ctx.createGain();
    this.chorusDelay = this.ctx.createDelay(0.1);
    this.chorusLFO = this.ctx.createOscillator();
    this.chorusLFOGain = this.ctx.createGain();
    this.chorusWetGain = this.ctx.createGain();
    this.chorusDryGain = this.ctx.createGain();
    this.chorusMerge = this.ctx.createGain();

    this.chorusLFO.type = 'sine';
    this.chorusLFO.frequency.value = 1.5; // Hz
    this.chorusLFO.start();
    this.chorusLFO.connect(this.chorusLFOGain);
    this.chorusLFOGain.connect(this.chorusDelay.delayTime);

    // Compressor
    this.compressorNode = this.ctx.createDynamicsCompressor();
    this.compressorNode.attack.value = 0.003;
    this.compressorNode.release.value = 0.25;

    // Spatial
    this.reverbNode = this.ctx.createConvolver();
    this.delayNode = this.ctx.createDelay(4.0);
    this.delayFeedbackNode = this.ctx.createGain();

    // Spatial Mix Buses
    this.drySpatialNode = this.ctx.createGain();
    this.wetReverbNode = this.ctx.createGain();
    this.wetDelayNode = this.ctx.createGain();
    this.delayOutNode = this.ctx.createGain();

    // --- Routing Graph ---

    // 1. Input -> Filter -> Distortion
    this.inputNode.connect(this.filterNode);
    this.filterNode.connect(this.distortionNode);

    // 2. Distortion -> EQ Chain
    this.distortionNode.connect(this.eqLowNode);
    this.eqLowNode.connect(this.eqMidNode);
    this.eqMidNode.connect(this.eqHighNode);

    // 3. EQ -> Chorus Block
    // Logic: Split signal. Dry passes. Wet goes through modulated delay. Merge.
    const eqOut = this.eqHighNode;

    eqOut.connect(this.chorusDryGain);
    eqOut.connect(this.chorusDelay); // Feed Delay directly

    // Chorus Internal
    this.chorusDelay.connect(this.chorusWetGain);

    this.chorusDryGain.connect(this.chorusMerge);
    this.chorusWetGain.connect(this.chorusMerge);

    // 4. Chorus Out -> Compressor
    this.chorusMerge.connect(this.compressorNode);

    // 5. Compressor -> Spatial Split (Dry, Reverb Send, Delay Send)
    const postDynSignal = this.compressorNode;

    // Dry Path
    postDynSignal.connect(this.drySpatialNode);
    this.drySpatialNode.connect(this.masterGain);

    // Reverb Path (Parallel)
    postDynSignal.connect(this.wetReverbNode);
    this.wetReverbNode.connect(this.reverbNode);
    this.reverbNode.connect(this.masterGain);

    // Delay Path (Parallel with Feedback)
    postDynSignal.connect(this.wetDelayNode);
    this.wetDelayNode.connect(this.delayNode);
    this.delayNode.connect(this.delayFeedbackNode);
    this.delayFeedbackNode.connect(this.delayNode);

    this.delayNode.connect(this.delayOutNode);
    this.delayOutNode.connect(this.masterGain);

    // 6. Master -> Limiter -> Analyser -> Out
    this.masterGain.connect(this.limiterNode);
    this.limiterNode.connect(this.analyser);
    this.analyser.connect(this.ctx.destination);

    // Initial Defaults
    this.generateSyntheticImpulse();
    this.updateDSP({
        masterVolume: 1.0,
        filterCutoff: 20000,
        filterResonance: 0,
        compressorThreshold: -24,
        compressorRatio: 4,
        eqLow: 0,
        eqMid: 0,
        eqHigh: 0,
        distortionAmount: 0,
        chorusMix: 0,
        chorusRate: 1.5,
        chorusDepth: 0,
        reverbMix: 0,
        delayTime: 0,
        delayFeedback: 0
    });
  }

  async resume() {
    if (this.ctx.state === 'suspended') {
      await this.ctx.resume();
    }
  }

  // --- DSP Control ---

  updateDSP(state: DSPState) {
    const t = this.ctx.currentTime;
    const ramptime = 0.05; // Fast response

    // Master
    this.masterGain.gain.setTargetAtTime(state.masterVolume, t, ramptime);

    // Filter
    // Smooth transition for cutoff to prevent zipper noise
    this.filterNode.frequency.setTargetAtTime(Math.max(20, Math.min(20000, state.filterCutoff)), t, ramptime);
    this.filterNode.Q.setTargetAtTime(state.filterResonance, t, ramptime);

    // Distortion
    this.setDistortion(state.distortionAmount);

    // EQ
    this.eqLowNode.gain.setTargetAtTime(state.eqLow, t, ramptime);
    this.eqMidNode.gain.setTargetAtTime(state.eqMid, t, ramptime);
    this.eqHighNode.gain.setTargetAtTime(state.eqHigh, t, ramptime);

    // Chorus
    // Crossfade Dry/Wet
    // If mix is 0, Dry=1, Wet=0. If mix is 1, Dry=0.7, Wet=0.7 (Equal power-ish) or just linear
    // Let's do a simple linear blend keeping level somewhat constant
    const cmix = state.chorusMix;
    this.chorusDryGain.gain.setTargetAtTime(1.0 - (cmix * 0.5), t, ramptime); // Don't kill dry completely, standard chorus mixes with dry
    this.chorusWetGain.gain.setTargetAtTime(cmix, t, ramptime);

    this.chorusLFO.frequency.setTargetAtTime(state.chorusRate, t, ramptime);
    // Depth maps to gain of LFO going into DelayTime.
    // 0 to 1 map to 0s to 0.005s (5ms modulation is standard deep chorus)
    this.chorusLFOGain.gain.setTargetAtTime(state.chorusDepth * 0.005, t, ramptime);
    // Base delay time for chorus is usually 15-20ms
    this.chorusDelay.delayTime.setTargetAtTime(0.015, t, ramptime);

    // Compressor
    this.compressorNode.threshold.setTargetAtTime(state.compressorThreshold, t, ramptime);
    this.compressorNode.ratio.setTargetAtTime(state.compressorRatio, t, ramptime);

    // Spatial Mixes
    // Dry signal level dips slightly as FX increase to maintain headroom?
    // Let's keep Dry at 1.0 to behave like a standard "Send".
    this.drySpatialNode.gain.setTargetAtTime(1.0, t, ramptime); 
    this.wetReverbNode.gain.setTargetAtTime(state.reverbMix, t, ramptime);

    // Delay
    const delayOutGain = state.delayTime < 0.01 ? 0 : 0.8;
    this.delayNode.delayTime.setTargetAtTime(Math.max(0.01, state.delayTime), t, ramptime);
    this.delayFeedbackNode.gain.setTargetAtTime(state.delayFeedback, t, ramptime);
    this.delayOutNode.gain.setTargetAtTime(delayOutGain, t, ramptime);
    this.wetDelayNode.gain.value = 1.0; 
  }

  private setDistortion(amount: number) {
    // 0 to 100
    if (amount <= 0.1) {
        this.distortionNode.curve = null;
        return;
    }

    // High-end Soft Clipping Curve (Magic Sigmoid)
    const n_samples = 44100;
    const curve = new Float32Array(n_samples);
    const deg = Math.PI / 180;

    // Convert 0-100 to a drive factor
    // 0 -> 0
    // 100 -> ~100+
    const k = amount * 2; 

    for (let i = 0; i < n_samples; ++i) {
      const x = (i * 2) / n_samples - 1;
      // Classic sigmoid soft clipper
      // curve[i] = (3 + k) * x * 20 * deg / (Math.PI + k * Math.abs(x));

      // "Tube-like" Asymmetric Soft Clip? 
      // Let's stick to a very symmetrical but aggressive soft clip for "Pro" sound
      // Arctan is smoother than the standard algorithms often used
      curve[i] = (2 / Math.PI) * Math.atan(k * x); 
      // This is purely normalized to -1..1.
    }
    this.distortionNode.curve = curve;
    this.distortionNode.oversample = '4x';
  }

  private generateSyntheticImpulse() {
    const rate = this.ctx.sampleRate;
    const length = rate * 2.5; 
    const decay = 3.0;
    const impulse = this.ctx.createBuffer(2, length, rate);
    const impulseL = impulse.getChannelData(0);
    const impulseR = impulse.getChannelData(1);

    for (let i = 0; i < length; i++) {
        const n = length - i;
        const env = Math.pow(n / length, decay);
        // Stereo spread noise
        impulseL[i] = (Math.random() * 2 - 1) * env;
        impulseR[i] = (Math.random() * 2 - 1) * env;
    }
    this.reverbNode.buffer = impulse;
  }

  // --- Playback Management ---

  playClip(clip: any, trackVolume: number, trackPan: number, projectStartOffset: number) {
    const clipStart = clip.startTime;
    const clipEnd = clip.startTime + clip.duration;

    if (clipEnd <= projectStartOffset) return;

    const source = this.ctx.createBufferSource();
    source.buffer = clip.buffer;

    // Track Chain: Source -> Gain -> Panner -> Mix Bus
    const gain = this.ctx.createGain();
    gain.gain.value = trackVolume;

    const panner = this.ctx.createStereoPanner();
    panner.pan.value = trackPan;

    source.connect(gain);
    gain.connect(panner);
    panner.connect(this.inputNode);

    let startWhen = 0;
    let startOffset = 0;
    let duration = 0;

    if (clipStart >= projectStartOffset) {
        startWhen = clipStart - projectStartOffset;
        startOffset = clip.offset;
        duration = clip.duration;
    } else {
        const timeIntoClip = projectStartOffset - clipStart;
        startWhen = 0;
        startOffset = clip.offset + timeIntoClip;
        duration = clip.duration - timeIntoClip;
    }

    if (duration > 0) {
        source.start(this.ctx.currentTime + startWhen, startOffset, duration);
        this.activeSources.set(clip.id, source);
        source.onended = () => this.activeSources.delete(clip.id);
    }
  }

  stopAll() {
    this.activeSources.forEach(source => {
      try { source.stop(); } catch(e) {}
    });
    this.activeSources.clear();
  }

  // --- Recording ---

  async startRecording(monitor: boolean): Promise<void> {
    await this.resume();
    this.stream = await navigator.mediaDevices.getUserMedia({ 
      audio: { 
        echoCancellation: false, 
        autoGainControl: false, 
        noiseSuppression: false, 
        latency: 0 
      } as any
    });

    const source = this.ctx.createMediaStreamSource(this.stream);

    if (monitor) {
      source.connect(this.ctx.destination);
    }

    this.mediaRecorder = new MediaRecorder(this.stream);
    this.mediaRecorder.start();
  }

  async stopRecording(): Promise<Blob> {
    return new Promise((resolve, reject) => {
      if (!this.mediaRecorder) return reject('No recorder');
      const chunks: BlobPart[] = [];
      this.mediaRecorder.ondataavailable = (e) => chunks.push(e.data);
      this.mediaRecorder.onstop = () => {
        const blob = new Blob(chunks, { type: 'audio/ogg; codecs=opus' });
        this.stream?.getTracks().forEach(track => track.stop());
        resolve(blob);
      };
      this.mediaRecorder.stop();
    });
  }

  // --- Utilities ---

  async decodeAudioData(blob: Blob): Promise<AudioBuffer> {
    const arrayBuffer = await blob.arrayBuffer();
    return await this.ctx.decodeAudioData(arrayBuffer);
  }

  async bounceMix(length: number, clips: any[], tracks: any[]): Promise<AudioBuffer> {
    const offlineCtx = new OfflineAudioContext(2, length * 44100, 44100);

    clips.forEach(clip => {
        const track = tracks.find((t:any) => t.id === clip.trackId);
        if (!track || track.muted) return;

        const source = offlineCtx.createBufferSource();
        source.buffer = clip.buffer;

        const gain = offlineCtx.createGain();
        gain.gain.value = track.volume;

        const panner = offlineCtx.createStereoPanner();
        panner.pan.value = track.pan || 0;

        source.connect(gain);
        gain.connect(panner);
        panner.connect(offlineCtx.destination);
        source.start(clip.startTime, clip.offset, clip.duration);
    });

    return await offlineCtx.startRendering();
  }
}

export const audioEngine = new AudioEngine();

import React, { useEffect, useRef } from 'react';
import { DSPState } from '../types';
import { Knob } from './Knob';
import { audioEngine } from '../services/audioEngine';

interface DSPRackProps {
  dspState: DSPState;
  onChange: (newState: DSPState) => void;
}

export const DSPRack: React.FC<DSPRackProps> = ({ dspState, onChange }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // Visualizer Loop
  useEffect(() => {
    let animationId: number;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const bufferLength = audioEngine.analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);

    const draw = () => {
      animationId = requestAnimationFrame(draw);

      audioEngine.analyser.getByteFrequencyData(dataArray);

      // Dark Tech Background
      ctx.fillStyle = '#0f172a';
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      // Grid
      ctx.strokeStyle = '#1e293b';
      ctx.lineWidth = 1;
      ctx.beginPath();
      for(let i=0; i<canvas.width; i+=20) { ctx.moveTo(i, 0); ctx.lineTo(i, canvas.height); }
      for(let i=0; i<canvas.height; i+=20) { ctx.moveTo(0, i); ctx.lineTo(canvas.width, i); }
      ctx.stroke();

      const barWidth = (canvas.width / bufferLength) * 2.5;
      let barHeight;
      let x = 0;

      for(let i = 0; i < bufferLength; i++) {
        barHeight = (dataArray[i] / 255) * canvas.height;

        // Gradient Bars
        const gradient = ctx.createLinearGradient(0, canvas.height, 0, 0);
        gradient.addColorStop(0, '#06b6d4'); // Cyan
        gradient.addColorStop(0.5, '#3b82f6'); // Blue
        gradient.addColorStop(1, '#a855f7'); // Purple

        ctx.fillStyle = gradient;
        ctx.fillRect(x, canvas.height - barHeight, barWidth, barHeight);

        x += barWidth + 1;
      }
    };

    draw();
    return () => cancelAnimationFrame(animationId);
  }, []);

  return (
    <div className="fixed bottom-0 left-0 right-0 h-[220px] bg-slate-900 border-t-2 border-slate-700 shadow-[0_-10px_40px_rgba(0,0,0,0.8)] z-50 flex flex-col">

      {/* Header / Visualizer Strip */}
      <div className="flex h-16 border-b border-slate-800 bg-black/40 relative">
        <canvas ref={canvasRef} width={600} height={64} className="w-full h-full opacity-60" />
        <div className="absolute top-2 left-2 text-[10px] text-cyan-500 font-mono tracking-widest border border-cyan-500/30 px-2 py-0.5 rounded bg-black/50">
          MASTER BUS ANALYZER
        </div>
      </div>

      {/* Main Rack Controls */}
      <div className="flex-1 overflow-x-auto overflow-y-hidden">
        <div className="flex h-full items-center px-4 space-x-6 min-w-max">

          {/* Section: FILTER (New) */}
          <div className="rack-section border-r border-slate-700 pr-6 flex space-x-3 items-center">
             <div className="text-[9px] text-slate-500 font-bold -rotate-90 w-4 whitespace-nowrap">VCF</div>
             <Knob value={dspState.filterCutoff} min={20} max={20000} label="Cutoff" color="pink" onChange={(v) => onChange({...dspState, filterCutoff: v})} />
             <Knob value={dspState.filterResonance} min={0} max={20} label="Res" color="pink" onChange={(v) => onChange({...dspState, filterResonance: v})} />
          </div>

          {/* Section: SATURATION */}
          <div className="rack-section border-r border-slate-700 pr-6 flex space-x-3 items-center">
             <div className="text-[9px] text-slate-500 font-bold -rotate-90 w-4 whitespace-nowrap">DRIVE</div>
             <Knob value={dspState.distortionAmount} min={0} max={100} label="Inferno" color="orange" onChange={(v) => onChange({...dspState, distortionAmount: v})} />
          </div>

          {/* Section: EQ */}
          <div className="rack-section border-r border-slate-700 pr-6 flex space-x-3 items-center">
             <div className="text-[9px] text-slate-500 font-bold -rotate-90 w-4 whitespace-nowrap">EQ-3</div>
             <Knob value={dspState.eqLow} min={-12} max={12} label="Low" color="blue" onChange={(v) => onChange({...dspState, eqLow: v})} />
             <Knob value={dspState.eqMid} min={-12} max={12} label="Mid" color="blue" onChange={(v) => onChange({...dspState, eqMid: v})} />
             <Knob value={dspState.eqHigh} min={-12} max={12} label="High" color="blue" onChange={(v) => onChange({...dspState, eqHigh: v})} />
          </div>

          {/* Section: MODULATION (New - Chorus) */}
          <div className="rack-section border-r border-slate-700 pr-6 flex space-x-3 items-center">
             <div className="text-[9px] text-slate-500 font-bold -rotate-90 w-4 whitespace-nowrap">CHORUS</div>
             <Knob value={dspState.chorusMix} min={0} max={1} label="Mix" color="green" onChange={(v) => onChange({...dspState, chorusMix: v})} />
             <Knob value={dspState.chorusRate} min={0.1} max={10} label="Rate" color="green" onChange={(v) => onChange({...dspState, chorusRate: v})} />
             <Knob value={dspState.chorusDepth} min={0} max={1} label="Depth" color="green" onChange={(v) => onChange({...dspState, chorusDepth: v})} />
          </div>

          {/* Section: DYNAMICS */}
          <div className="rack-section border-r border-slate-700 pr-6 flex space-x-3 items-center">
             <div className="text-[9px] text-slate-500 font-bold -rotate-90 w-4 whitespace-nowrap">COMP</div>
             <Knob value={dspState.compressorThreshold} min={-60} max={0} label="Thresh" color="yellow" onChange={(v) => onChange({...dspState, compressorThreshold: v})} />
             <Knob value={dspState.compressorRatio} min={1} max={20} label="Ratio" color="yellow" onChange={(v) => onChange({...dspState, compressorRatio: v})} />
          </div>

          {/* Section: SPATIAL */}
          <div className="rack-section border-r border-slate-700 pr-6 flex space-x-3 items-center">
             <div className="text-[9px] text-slate-500 font-bold -rotate-90 w-4 whitespace-nowrap">SPACE</div>
             <Knob value={dspState.delayTime} min={0} max={1.0} label="Dly Time" color="purple" onChange={(v) => onChange({...dspState, delayTime: v})} />
             <Knob value={dspState.delayFeedback} min={0} max={0.9} label="Dly Fdbk" color="purple" onChange={(v) => onChange({...dspState, delayFeedback: v})} />
             <Knob value={dspState.reverbMix} min={0} max={1} label="Verb Mix" color="cyan" onChange={(v) => onChange({...dspState, reverbMix: v})} />
          </div>

           {/* Section: MASTER */}
           <div className="rack-section pl-2 flex space-x-3 items-center bg-black/20 p-2 rounded-lg border border-slate-700/50">
             <Knob value={dspState.masterVolume} min={0} max={1.5} label="MASTER" color="red" onChange={(v) => onChange({...dspState, masterVolume: v})} />
          </div>

        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { audioEngine } from './services/audioEngine';
import { storageService } from './services/storageService';
import { Controls } from './components/Controls';
import { TrackLane } from './components/TrackLane';
import { ChannelStrip } from './components/ChannelStrip';
import { DSPRack } from './components/DSPRack';
import { Track, AudioClip, EditMode, DSPState } from './types';
import { COLORS, TRACK_HEIGHT, CHANNEL_WIDTH } from './constants';

const App: React.FC = () => {
  // State
  const [tracks, setTracks] = useState<Track[]>([
    { id: 't1', name: 'Track 1', color: COLORS[0], muted: false, solo: false, armed: true, volume: 0.8, pan: 0 },
    { id: 't2', name: 'Track 2', color: COLORS[1], muted: false, solo: false, armed: false, volume: 0.8, pan: -0.3 },
    { id: 't3', name: 'Track 3', color: COLORS[2], muted: false, solo: false, armed: false, volume: 0.8, pan: 0 },
    { id: 't4', name: 'Track 4', color: COLORS[3], muted: false, solo: false, armed: false, volume: 0.8, pan: 0 },
    { id: 't5', name: 'Track 5', color: COLORS[4], muted: false, solo: false, armed: false, volume: 0.7, pan: 0.4 },
  ]);
  const [clips, setClips] = useState<AudioClip[]>([]);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0); 
  const [zoom, setZoom] = useState(100); 
  const [selectedClipId, setSelectedClipId] = useState<string | null>(null);

  const [editMode, setEditMode] = useState<EditMode>(EditMode.MOVE);
  const [dspState, setDspState] = useState<DSPState>({ 
      masterVolume: 1.0,

      filterCutoff: 20000,
      filterResonance: 0,

      distortionAmount: 0, 

      eqLow: 0,
      eqMid: 0,
      eqHigh: 0,

      chorusMix: 0,
      chorusRate: 1.5,
      chorusDepth: 0.0,

      compressorThreshold: -20,
      compressorRatio: 4,

      reverbMix: 0, 
      delayTime: 0,
      delayFeedback: 0
  });
  const [isRecording, setIsRecording] = useState(false);
  const [monitor, setMonitor] = useState(false);

  // Refs for loop management
  const rafRef = useRef<number>();
  const startTimeRef = useRef<number>(0); 
  const startOffsetRef = useRef<number>(0); 
  const recordingStartRef = useRef<number>(0); 

  const dragRef = useRef<{ clipId: string; startX: number; originalStart: number } | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // --- Initialization ---
  useEffect(() => {
    storageService.init();

    // Auto-resume audio context on first touch
    const handleTouch = () => audioEngine.resume();
    document.addEventListener('touchstart', handleTouch, { once: true });
    document.addEventListener('click', handleTouch, { once: true });

    // Init Audio Engine Defaults
    audioEngine.updateDSP(dspState);

    return () => {
      cancelAnimationFrame(rafRef.current!);
    };
  }, []);

  // --- Playback Logic ---

  const updatePlayhead = useCallback(() => {
    if (audioEngine.ctx.state === 'running' && isPlaying) {
        const elapsed = audioEngine.ctx.currentTime - startTimeRef.current;
        setCurrentTime(startOffsetRef.current + elapsed);
    }
    rafRef.current = requestAnimationFrame(updatePlayhead);
  }, [isPlaying]);

  useEffect(() => {
    if (isPlaying) {
      rafRef.current = requestAnimationFrame(updatePlayhead);
    } else {
      cancelAnimationFrame(rafRef.current!);
    }
  }, [isPlaying, updatePlayhead]);

  const togglePlay = async () => {
    await audioEngine.resume();

    if (isPlaying) {
      // Pause
      audioEngine.stopAll();
      setIsPlaying(false);

      const elapsed = audioEngine.ctx.currentTime - startTimeRef.current;
      const newTime = startOffsetRef.current + elapsed;
      setCurrentTime(newTime);
      startOffsetRef.current = newTime;

    } else {
      // Play
      startTimeRef.current = audioEngine.ctx.currentTime;
      startOffsetRef.current = currentTime; 

      clips.forEach(clip => {
        const track = tracks.find(t => t.id === clip.trackId);
        if (track && !track.muted && (!tracks.some(t => t.solo) || track.solo)) {
           audioEngine.playClip(clip, track.volume, track.pan, currentTime);
        }
      });

      setIsPlaying(true);
    }
  };

  // --- Recording Logic ---

  const stopRecordingAndSave = async () => {
      const blob = await audioEngine.stopRecording();
      setIsRecording(false);

      const id = Date.now().toString();
      await storageService.saveBlob(id, blob);
      const buffer = await audioEngine.decodeAudioData(blob);

      const armedTrack = tracks.find(t => t.armed) || tracks[0];

      const newClip: AudioClip = {
        id,
        trackId: armedTrack.id, 
        buffer,
        startTime: recordingStartRef.current,
        duration: buffer.duration,
        offset: 0,
        name: `Rec ${id.substr(-4)}`
      };
      setClips(prev => [...prev, newClip]);
      setSelectedClipId(id);
  };

  const toggleRecord = async () => {
    if (isRecording) {
      await stopRecordingAndSave();
    } else {
      recordingStartRef.current = currentTime; 
      await audioEngine.startRecording(monitor);
      setIsRecording(true);
      if (!isPlaying) {
          await togglePlay();
      }
    }
  };

  const stop = async () => {
    // Determine return point BEFORE stopping playback state
    const returnTime = isRecording ? recordingStartRef.current : startOffsetRef.current;

    if (isRecording) {
        await stopRecordingAndSave();
    }

    audioEngine.stopAll();
    setIsPlaying(false);

    // Reset playhead to Start or Recording Start
    setCurrentTime(returnTime);
    startOffsetRef.current = returnTime;
  };

  const handleTrackUpdate = (trackId: string, updates: Partial<Track>) => {
    setTracks(prev => prev.map(t => t.id === trackId ? { ...t, ...updates } : t));
  };

  const toggleTrackArm = (trackId: string) => {
      setTracks(prev => prev.map(t => ({
          ...t,
          armed: t.id === trackId 
      })));
  };

  // --- Interaction Logic ---

  const handleClipInteract = (clipId: string, action: string, data?: any) => {
    // Tap to Select or Split
    if (action === 'tap') {
        setSelectedClipId(clipId);

        // If in SPLIT mode, move playhead to tap and Split immediately
        if (editMode === EditMode.SPLIT && data?.x && containerRef.current) {
            const containerLeft = containerRef.current.getBoundingClientRect().left;
            const scrollLeft = containerRef.current.scrollLeft;

            // Calculate time from tap X (accounting for Channel Width offset)
            const clickX = data.x - containerLeft + scrollLeft - CHANNEL_WIDTH;
            const tapTime = Math.max(0, clickX / zoom);

            setCurrentTime(tapTime);
            startOffsetRef.current = tapTime; // Update sync ref

            splitClip(clipId, tapTime);
        }
        return;
    }

    // Move / Drag
    if (editMode === EditMode.MOVE && action === 'start') {
      setSelectedClipId(clipId);
      dragRef.current = { 
        clipId, 
        startX: data.x,
        originalStart: data.originalStart
      };

      const handleMove = (e: TouchEvent | MouseEvent) => {
        if (!dragRef.current || !containerRef.current) return;
        const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
        const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;

        const deltaX = clientX - dragRef.current.startX;
        const deltaTime = deltaX / zoom; 

        let newStart = Math.max(0, dragRef.current.originalStart + deltaTime);

        // Snap to Grid
        const snapIncrement = 0.25; 
        newStart = Math.round(newStart / snapIncrement) * snapIncrement;

        // Track Switching Calculation
        const containerRect = containerRef.current.getBoundingClientRect();
        // Relative Y inside the scroll container
        const relativeY = clientY - containerRect.top + containerRef.current.scrollTop;

        // Calculate track index based on Y position
        // Each track is TRACK_HEIGHT + border (1px)
        const trackIndex = Math.floor(relativeY / TRACK_HEIGHT);
        const targetTrack = tracks[trackIndex];

        setClips(prev => prev.map(c => 
          c.id === dragRef.current?.clipId ? { 
              ...c, 
              startTime: newStart,
              trackId: targetTrack ? targetTrack.id : c.trackId 
          } : c
        ));
      };

      const handleEnd = () => {
        dragRef.current = null;
        window.removeEventListener('touchmove', handleMove);
        window.removeEventListener('touchend', handleEnd);
        window.removeEventListener('mousemove', handleMove);
        window.removeEventListener('mouseup', handleEnd);
      };

      window.addEventListener('touchmove', handleMove, { passive: false });
      window.addEventListener('touchend', handleEnd);
      window.addEventListener('mousemove', handleMove);
      window.addEventListener('mouseup', handleEnd);
    }
  };

  const splitClip = (clipId: string, splitTimeOverride?: number) => {
    const clip = clips.find(c => c.id === clipId);
    if (!clip) return;

    const timeToSplitAt = splitTimeOverride !== undefined ? splitTimeOverride : currentTime;
    const relativeSplitTime = timeToSplitAt - clip.startTime;

    // Validate split point is within clip bounds
    if (relativeSplitTime <= 0.05 || relativeSplitTime >= clip.duration - 0.05) return;

    const clip1: AudioClip = {
        ...clip,
        id: clip.id + '_1',
        duration: relativeSplitTime,
    };

    const clip2: AudioClip = {
        ...clip,
        id: clip.id + '_2',
        startTime: timeToSplitAt,
        duration: clip.duration - relativeSplitTime,
        offset: clip.offset + relativeSplitTime,
        name: clip.name
    };

    setClips(prev => prev.filter(c => c.id !== clipId).concat([clip1, clip2]));
    setSelectedClipId(clip2.id);
  };

  const deleteSelectedClip = () => {
      if (!selectedClipId) return;
      setClips(prev => prev.filter(c => c.id !== selectedClipId));
      setSelectedClipId(null);
  };

  const handleDSPChange = (newState: DSPState) => {
    setDspState(newState);
    audioEngine.updateDSP(newState);
  };

  const handleBounce = async () => {
    if (clips.length === 0) return;
    const length = Math.max(...clips.map(c => c.startTime + c.duration));
    await audioEngine.bounceMix(length, clips, tracks);
    alert(`Bounced ${length.toFixed(2)}s.`);
  };

  const handleTimelineScrub = (e: React.TouchEvent | React.MouseEvent) => {
     if ((e.target as HTMLElement).dataset.bg) {
         setSelectedClipId(null);
     }

     if (!containerRef.current) return;
     const clientX = 'touches' in e ? e.touches[0].clientX : (e as React.MouseEvent).clientX;
     const containerLeft = containerRef.current.getBoundingClientRect().left;
     const scrollLeft = containerRef.current.scrollLeft;

     // Calculate Time adjusting for Channel Header Width
     // x = (time * zoom) + CHANNEL_WIDTH
     // time = (x - CHANNEL_WIDTH) / zoom

     // The clickX relative to scroll container content:
     const relativeX = clientX - containerLeft + scrollLeft;

     const time = Math.max(0, (relativeX - CHANNEL_WIDTH) / zoom);

     setCurrentTime(time);
     startOffsetRef.current = time;

     if (isPlaying) {
         togglePlay().then(() => togglePlay());
     }
  };

  return (
    <div className="flex flex-col h-screen w-screen bg-[#020617] text-slate-100 overflow-hidden select-none font-sans">
      <Controls 
        isPlaying={isPlaying} 
        isRecording={isRecording}
        onPlayPause={togglePlay} 
        onRecord={toggleRecord} 
        onStop={stop}
        onBounce={handleBounce}
        onDelete={deleteSelectedClip}
        editMode={editMode}
        setEditMode={setEditMode}
        monitor={monitor}
        setMonitor={setMonitor}
        zoom={zoom}
        setZoom={setZoom}
        hasSelection={!!selectedClipId}
      />

      <div 
        ref={containerRef}
        className="flex-1 overflow-y-auto overflow-x-auto relative mt-[60px] mb-[220px]" 
        onClick={() => setSelectedClipId(null)} 
        data-bg="true"
      >
        {/* Playhead - Offset by CHANNEL_WIDTH */}
        <div 
            className="absolute top-0 bottom-0 z-40 pointer-events-none border-r border-red-500 shadow-[0_0_10px_rgba(239,68,68,0.8)]"
            style={{ left: `${(currentTime * zoom) + CHANNEL_WIDTH}px`, width: '1px' }}
        >
            <div className="absolute -top-4 -translate-x-1/2 bg-red-600 text-[9px] px-1.5 py-0.5 rounded-sm text-white font-mono shadow-md whitespace-nowrap z-50">
                {currentTime.toFixed(2)}s
            </div>
        </div>

        {/* Ruler - Offset by CHANNEL_WIDTH */}
        <div 
            className="h-8 min-w-full bg-[#0f172a] border-b border-slate-700 relative cursor-pointer shadow-lg z-30"
            style={{ width: `${Math.max(window.innerWidth, (300 * zoom) + CHANNEL_WIDTH)}px` }}
            onClick={(e) => { e.stopPropagation(); handleTimelineScrub(e); }}
        >
             {Array.from({ length: Math.ceil(300 * zoom / 100) * 4 }).map((_, i) => {
                 const isSecond = i % 4 === 0;
                 return (
                 <div key={i} className={`absolute bottom-0 border-l ${isSecond ? 'h-3 border-slate-500' : 'h-1.5 border-slate-700'}`} 
                      style={{ left: (i * 0.25 * zoom) + CHANNEL_WIDTH }}>
                     {isSecond && <span className="text-[9px] text-slate-500 pl-1 -mt-4 block">{i * 0.25}</span>}
                 </div>
             )})}
        </div>

        {/* Tracks Area */}
        <div className="min-w-full pb-20 relative bg-[#020617]" 
             style={{ width: `${Math.max(window.innerWidth, (300 * zoom) + CHANNEL_WIDTH)}px` }} 
             data-bg="true">
          {tracks.map(track => (
            <div key={track.id} className="flex border-b border-slate-800">

               <ChannelStrip 
                  track={track}
                  onUpdate={handleTrackUpdate}
                  onToggleArm={toggleTrackArm}
               />

               <TrackLane 
                 track={track} 
                 clips={clips.filter(c => c.trackId === track.id)}
                 editMode={editMode}
                 selectedClipId={selectedClipId}
                 onClipInteract={handleClipInteract}
                 currentTime={currentTime}
                 isPlaying={isPlaying}
                 zoom={zoom}
               />
            </div>
          ))}
        </div>
      </div>

      <DSPRack dspState={dspState} onChange={handleDSPChange} />
    </div>
  );
};

export default App;

export interface TrackFX {
  eqLow: number; // dB
  eqMid: number; // dB
  eqHigh: number; // dB
  compressorThreshold: number; // dB
  compressorRatio: number; // Ratio
  saturation: number; // 0-100
  sendReverb: number; // 0-1
  sendDelay: number; // 0-1
  highPassFreq: number; // Hz
}

export interface ClipFX {
  gain: number; // 0-2 (1 is unity)
  pitch: number; // Playback rate: 0.5 to 2.0
  pan: number; // -1 to 1
  isReversed: boolean;
}

export interface Track {
  id: string;
  name: string;
  color: string;
  muted: boolean;
  solo: boolean;
  armed: boolean;
  volume: number;
  pan: number;
  fx: TrackFX; // Nested FX state
  isExpanded: boolean; // UI State
}

export interface AudioClip {
  id: string;
  trackId: string;
  buffer: AudioBuffer;
  startTime: number;
  duration: number;
  offset: number;
  name: string;
  fx: ClipFX; // Nested Clip FX
}

export enum EditMode {
  MOVE = 'MOVE',
  SPLIT = 'SPLIT',
  DELETE = 'DELETE'
}

export interface DSPState {
  // Master Bus Global FX
  masterVolume: number;
  limiterThreshold: number;

  // Return Bus Settings (Global FX)
  reverbDecay: number; 
  delayTime: number;
  delayFeedback: number;

  // Global Filter (Master)
  masterFilterCutoff: number;
  masterFilterRes: number;
}

import { DSPState, Track, AudioClip, TrackFX } from '../types';

interface TrackChannel {
  input: GainNode;
  hpf: BiquadFilterNode;
  eqLow: BiquadFilterNode;
  eqMid: BiquadFilterNode;
  eqHigh: BiquadFilterNode;
  drive: WaveShaperNode;
  compressor: DynamicsCompressorNode;
  sendReverb: GainNode;
  sendDelay: GainNode;
  panner: StereoPannerNode;
  output: GainNode; // Post-fader, connects to Master
}

export class AudioEngine {
  public ctx: AudioContext;
  public analyser: AnalyserNode;

  // Master Bus
  private masterGain: GainNode;
  private limiterNode: DynamicsCompressorNode;
  private masterFilter: BiquadFilterNode;

  // Aux Returns (Global)
  private reverbNode: ConvolverNode;
  private delayNode: DelayNode;
  private delayFeedback: GainNode;
  private returnReverbGain: GainNode;
  private returnDelayGain: GainNode;

  // Track Management
  private trackChannels: Map<string, TrackChannel> = new Map();
  private activeSources: Map<string, AudioBufferSourceNode> = new Map();

  private stream: MediaStream | null = null;
  private mediaRecorder: MediaRecorder | null = null;

  constructor() {
    const AudioContextClass = (window.AudioContext || (window as any).webkitAudioContext);
    this.ctx = new AudioContextClass({ latencyHint: 'interactive' });

    // --- Master Chain ---
    this.masterGain = this.ctx.createGain();
    this.limiterNode = this.ctx.createDynamicsCompressor();
    this.masterFilter = this.ctx.createBiquadFilter();
    this.analyser = this.ctx.createAnalyser();

    // Limiter settings (Brickwall-ish)
    this.limiterNode.threshold.value = -1.0;
    this.limiterNode.knee.value = 0;
    this.limiterNode.ratio.value = 20;
    this.limiterNode.attack.value = 0.002;
    this.limiterNode.release.value = 0.1;

    // Master Routing
    this.masterFilter.connect(this.masterGain);
    this.masterGain.connect(this.limiterNode);
    this.limiterNode.connect(this.analyser);
    this.analyser.connect(this.ctx.destination);

    // --- Aux Sends Setup ---
    this.reverbNode = this.ctx.createConvolver();
    this.delayNode = this.ctx.createDelay(4.0);
    this.delayFeedback = this.ctx.createGain();
    this.returnReverbGain = this.ctx.createGain();
    this.returnDelayGain = this.ctx.createGain();

    // Reverb Wiring
    this.reverbNode.connect(this.returnReverbGain);
    this.returnReverbGain.connect(this.masterFilter); // Return to Master

    // Delay Wiring
    this.delayNode.connect(this.delayFeedback);
    this.delayFeedback.connect(this.delayNode); // Feedback loop
    this.delayNode.connect(this.returnDelayGain);
    this.returnDelayGain.connect(this.masterFilter); // Return to Master

    this.generateImpulseResponse();
  }

  async resume() {
    if (this.ctx.state === 'suspended') {
      await this.ctx.resume();
    }
  }

  // --- Track Graph Management ---

  // Ensures a track exists in the graph. Called when tracks are added or during init.
  ensureTrackChannel(track: Track) {
    if (this.trackChannels.has(track.id)) return;

    // Create Nodes
    const input = this.ctx.createGain();
    const hpf = this.ctx.createBiquadFilter();
    const eqLow = this.ctx.createBiquadFilter();
    const eqMid = this.ctx.createBiquadFilter();
    const eqHigh = this.ctx.createBiquadFilter();
    const drive = this.ctx.createWaveShaper();
    const compressor = this.ctx.createDynamicsCompressor();
    const sendReverb = this.ctx.createGain();
    const sendDelay = this.ctx.createGain();
    const panner = this.ctx.createStereoPanner();
    const output = this.ctx.createGain();

    // Config Nodes
    hpf.type = 'highpass';
    hpf.frequency.value = 20;
    eqLow.type = 'lowshelf';
    eqLow.frequency.value = 200;
    eqMid.type = 'peaking';
    eqMid.frequency.value = 1000;
    eqHigh.type = 'highshelf';
    eqHigh.frequency.value = 4000;

    // Saturation Curve
    this.updateDriveCurve(drive, 0);

    // Graph Connection (Series)
    input.connect(hpf);
    hpf.connect(eqLow);
    eqLow.connect(eqMid);
    eqMid.connect(eqHigh);
    eqHigh.connect(drive);
    drive.connect(compressor);
    compressor.connect(output); // Signal path to fader

    // Aux Sends (Parallel split from Compressor output)
    compressor.connect(sendReverb);
    sendReverb.connect(this.reverbNode);

    compressor.connect(sendDelay);
    sendDelay.connect(this.delayNode);

    // Fader & Pan
    output.connect(panner);
    panner.connect(this.masterFilter);

    // Store
    this.trackChannels.set(track.id, {
        input, hpf, eqLow, eqMid, eqHigh, drive, compressor, sendReverb, sendDelay, panner, output
    });

    // Apply Initial State
    this.updateTrackState(track);
  }

  updateTrackState(track: Track) {
    const ch = this.trackChannels.get(track.id);
    if (!ch) return;

    const t = this.ctx.currentTime;
    const ramp = 0.05;

    // Fader / Pan
    const vol = track.muted ? 0 : track.volume;
    ch.output.gain.setTargetAtTime(vol, t, ramp);
    ch.panner.pan.setTargetAtTime(track.pan, t, ramp);

    // FX
    const fx = track.fx;
    ch.hpf.frequency.setTargetAtTime(fx.highPassFreq, t, ramp);

    ch.eqLow.gain.setTargetAtTime(fx.eqLow, t, ramp);
    ch.eqMid.gain.setTargetAtTime(fx.eqMid, t, ramp);
    ch.eqHigh.gain.setTargetAtTime(fx.eqHigh, t, ramp);

    ch.compressor.threshold.setTargetAtTime(fx.compressorThreshold, t, ramp);
    ch.compressor.ratio.setTargetAtTime(fx.compressorRatio, t, ramp);

    this.updateDriveCurve(ch.drive, fx.saturation);

    ch.sendReverb.gain.setTargetAtTime(fx.sendReverb, t, ramp);
    ch.sendDelay.gain.setTargetAtTime(fx.sendDelay, t, ramp);
  }

  private updateDriveCurve(node: WaveShaperNode, amount: number) {
     if (amount < 1) {
         node.curve = null;
         return;
     }
     const k = amount;
     const n_samples = 44100;
     const curve = new Float32Array(n_samples);
     for (let i = 0; i < n_samples; ++i) {
       const x = (i * 2) / n_samples - 1;
       curve[i] = (Math.PI + 50) * x / (Math.PI + 50 * Math.abs(x));
     }
     node.curve = curve;
     node.oversample = '4x';
  }

  // --- Master DSP ---

  updateMasterDSP(state: DSPState) {
      const t = this.ctx.currentTime;
      const ramp = 0.05;

      this.masterGain.gain.setTargetAtTime(state.masterVolume, t, ramp);
      this.masterFilter.frequency.setTargetAtTime(state.masterFilterCutoff, t, ramp);
      this.masterFilter.Q.setTargetAtTime(state.masterFilterRes, t, ramp);

      this.delayNode.delayTime.setTargetAtTime(state.delayTime, t, ramp);
      this.delayFeedback.gain.setTargetAtTime(state.delayFeedback, t, ramp);
  }

  // --- Playback ---

  playClip(clip: AudioClip, projectTime: number) {
    const ch = this.trackChannels.get(clip.trackId);
    if (!ch) return; // Track must exist

    const clipStart = clip.startTime;
    const clipEnd = clip.startTime + (clip.duration / clip.fx.pitch); // Adjust duration for pitch

    if (clipEnd <= projectTime) return;

    // Create Source
    const source = this.ctx.createBufferSource();

    // Reverse Logic
    if (clip.fx.isReversed) {
        // Expensive: Reversing buffer on the fly. 
        // Optimization: In a real app, cache the reversed buffer.
        // Here we do it live for simplicity of code.
        const original = clip.buffer;
        const reversed = this.ctx.createBuffer(original.numberOfChannels, original.length, original.sampleRate);
        for(let c=0; c<original.numberOfChannels; c++) {
            const dest = reversed.getChannelData(c);
            const src = original.getChannelData(c);
            for(let i=0; i<original.length; i++) dest[i] = src[original.length - 1 - i];
        }
        source.buffer = reversed;
    } else {
        source.buffer = clip.buffer;
    }

    // Clip FX Chain
    // Source -> Pitch -> ClipGain -> ClipPan -> TrackInput
    source.playbackRate.value = clip.fx.pitch;

    const clipGain = this.ctx.createGain();
    clipGain.gain.value = clip.fx.gain;

    const clipPan = this.ctx.createStereoPanner();
    clipPan.pan.value = clip.fx.pan;

    source.connect(clipGain);
    clipGain.connect(clipPan);
    clipPan.connect(ch.input); // Connect to Track Channel Strip

    // Calculate timing
    let startWhen = 0;
    let startOffset = 0;
    let duration = 0;

    // Playback rate affects how much buffer we consume
    const rate = clip.fx.pitch;

    if (clipStart >= projectTime) {
        startWhen = clipStart - projectTime;
        startOffset = clip.offset;
        duration = clip.duration;
    } else {
        const timeIntoClip = (projectTime - clipStart) * rate; 
        startWhen = 0;
        startOffset = clip.offset + timeIntoClip;
        duration = clip.duration - (timeIntoClip / rate);
    }

    // Safety check
    if (duration > 0 && startOffset < source.buffer.duration) {
        source.start(this.ctx.currentTime + startWhen, startOffset, duration);
        this.activeSources.set(clip.id, source);
        source.onended = () => this.activeSources.delete(clip.id);
    }
  }

  stopAll() {
    this.activeSources.forEach(s => { try { s.stop(); } catch(e){} });
    this.activeSources.clear();
  }

  // --- Recording ---

  async startRecording(monitor: boolean): Promise<void> {
    await this.resume();
    this.stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: false, latency: 0 } });
    this.mediaRecorder = new MediaRecorder(this.stream);
    this.mediaRecorder.start();
  }

  async stopRecording(): Promise<Blob> {
    return new Promise((resolve, reject) => {
      if (!this.mediaRecorder) return reject('No recorder');
      const chunks: BlobPart[] = [];
      this.mediaRecorder.ondataavailable = (e) => chunks.push(e.data);
      this.mediaRecorder.onstop = () => {
        const blob = new Blob(chunks, { type: 'audio/ogg; codecs=opus' });
        this.stream?.getTracks().forEach(track => track.stop());
        resolve(blob);
      };
      this.mediaRecorder.stop();
    });
  }

  async decodeAudioData(blob: Blob): Promise<AudioBuffer> {
    const buf = await blob.arrayBuffer();
    return await this.ctx.decodeAudioData(buf);
  }

  // Helper for init
  private generateImpulseResponse() {
    const rate = this.ctx.sampleRate;
    const length = rate * 2.0;
    const impulse = this.ctx.createBuffer(2, length, rate);
    const L = impulse.getChannelData(0);
    const R = impulse.getChannelData(1);
    for (let i = 0; i < length; i++) {
        const decay = Math.pow(1 - i / length, 4);
        L[i] = (Math.random() * 2 - 1) * decay;
        R[i] = (Math.random() * 2 - 1) * decay;
    }
    this.reverbNode.buffer = impulse;
  }

  // Bounce (Offline Render)
  async bounceMix(length: number, clips: AudioClip[], tracks: Track[]): Promise<AudioBuffer> {
      // Simplistic bounce. Real bounce needs to recreate the entire graph in OfflineContext.
      // For brevity, we render dry+vol+pan. A full offline graph mirror is complex.
      const offline = new OfflineAudioContext(2, length * 44100, 44100);

      clips.forEach(clip => {
          const track = tracks.find(t => t.id === clip.trackId);
          if (!track || track.muted) return;

          const src = offline.createBufferSource();
          src.buffer = clip.buffer;
          src.playbackRate.value = clip.fx.pitch;

          const gain = offline.createGain();
          gain.gain.value = track.volume * clip.fx.gain;

          const pan = offline.createStereoPanner();
          pan.pan.value = track.pan;

          src.connect(gain);
          gain.connect(pan);
          pan.connect(offline.destination);

          src.start(clip.startTime, clip.offset, clip.duration);
      });
      return await offline.startRendering();
  }
}

