                    onChange={(e) => onUpdate(track.id, { pan: parseFloat(e.target.value) })}
                    className="flex-1 h-1 bg-slate-700 rounded-full appearance-none [&::-webkit-slider-thumb]:w-2 [&::-webkit-slider-thumb]:h-2 [&::-webkit-slider-thumb]:rounded-full [&::-webkit-slider-thumb]:bg-yellow-500" />
            </div>
       </div>

       {/* Expanded FX Panel */}
       {track.isExpanded && (
           <div className="flex-1 bg-black/40 border-t border-slate-800 overflow-y-auto p-2 scrollbar-hide">
               <div className="text-[9px] text-slate-400 font-bold mb-2 text-center border-b border-slate-700 pb-1">INSERTS CHAIN</div>

               <div className="grid grid-cols-2 gap-y-4 gap-x-1">
                   {/* Row 1: EQ */}
                   <Knob value={track.fx.eqLow} min={-12} max={12} label="Low" color="blue" onChange={(v) => updateFX('eqLow', v)} />
                   <Knob value={track.fx.highPassFreq} min={20} max={500} label="HPF" color="blue" onChange={(v) => updateFX('highPassFreq', v)} />

                   <Knob value={track.fx.eqMid} min={-12} max={12} label="Mid" color="blue" onChange={(v) => updateFX('eqMid', v)} />
                   <Knob value={track.fx.eqHigh} min={-12} max={12} label="High" color="blue" onChange={(v) => updateFX('eqHigh', v)} />

                   {/* Row 2: Dynamics */}
                   <div className="col-span-2 h-px bg-slate-800 my-1"></div>
                   <Knob value={track.fx.compressorThreshold} min={-60} max={0} label="Thresh" color="yellow" onChange={(v) => updateFX('compressorThreshold', v)} />
                   <Knob value={track.fx.saturation} min={0} max={50} label="Drive" color="orange" onChange={(v) => updateFX('saturation', v)} />

                   {/* Row 3: Sends */}
                   <div className="col-span-2 h-px bg-slate-800 my-1"></div>
                   <Knob value={track.fx.sendReverb} min={0} max={1} label="Verb" color="purple" onChange={(v) => updateFX('sendReverb', v)} />
                   <Knob value={track.fx.sendDelay} min={0} max={1} label="Delay" color="purple" onChange={(v) => updateFX('sendDelay', v)} />
               </div>
           </div>
       )}

       <div className="absolute top-0 bottom-0 right-0 w-1" style={{ backgroundColor: track.color }}></div>
    </div>
  );
};

