import React, { useState, useRef, useEffect } from 'react';

interface KnobProps {
  value: number;
  min: number;
  max: number;
  onChange: (val: number) => void;
  label: string;
  color?: string;
  size?: number;
}

export const Knob: React.FC<KnobProps> = ({ value, min, max, onChange, label, color = 'cyan', size = 40 }) => {
  const [isDragging, setIsDragging] = useState(false);
  const startY = useRef(0);
  const startVal = useRef(0);

  const handleStart = (clientY: number) => {
    setIsDragging(true);
    startY.current = clientY;
    startVal.current = value;
  };

  const handleMove = (clientY: number) => {
    if (!isDragging) return;
    const delta = startY.current - clientY;
    const range = max - min;
    const change = (delta / 150) * range; // Sensitivity
    let newVal = startVal.current + change;
    newVal = Math.max(min, Math.min(max, newVal));
    onChange(newVal);
  };

  const handleEnd = () => {
    setIsDragging(false);
  };

  useEffect(() => {
    if (isDragging) {
      const mouseMove = (e: MouseEvent) => { e.preventDefault(); handleMove(e.clientY); };
      const touchMove = (e: TouchEvent) => { e.preventDefault(); handleMove(e.touches[0].clientY); };
      const end = () => handleEnd();

      document.addEventListener('mousemove', mouseMove, { passive: false });
      document.addEventListener('touchmove', touchMove, { passive: false });
      document.addEventListener('mouseup', end);
      document.addEventListener('touchend', end);

      return () => {
        document.removeEventListener('mousemove', mouseMove);
        document.removeEventListener('touchmove', touchMove);
        document.removeEventListener('mouseup', end);
        document.removeEventListener('touchend', end);
      };
    }
  }, [isDragging]);

  // Calculate rotation -135deg to +135deg
  const percentage = (value - min) / (max - min);
  const rotation = -135 + (percentage * 270);

  // Color mapping
  const colorMap: Record<string, string> = {
    cyan: '#06b6d4',
    blue: '#3b82f6',
    purple: '#a855f7',
    green: '#22c55e',
    yellow: '#eab308',
    orange: '#f97316',
    red: '#ef4444',
    pink: '#ec4899',
  };

  const accentColor = colorMap[color] || colorMap['cyan'];

  return (
    <div 
      className="flex flex-col items-center justify-center select-none touch-none"
      onMouseDown={(e) => handleStart(e.clientY)}
      onTouchStart={(e) => handleStart(e.touches[0].clientY)}
      style={{ width: size + 16 }}
    >
      <div 
        className="relative rounded-full shadow-[0_4px_6px_rgba(0,0,0,0.5),inset_0_-2px_4px_rgba(0,0,0,0.6)] bg-gradient-to-b from-slate-700 to-slate-900 border border-slate-600"
        style={{ width: size, height: size }}
      >
        {/* Tick Marks Ring */}
        <div className="absolute -inset-1 rounded-full border border-slate-700 opacity-30 pointer-events-none"></div>

        {/* Rotating Body */}
        <div 
          className="absolute inset-0 rounded-full"
          style={{ transform: `rotate(${rotation}deg)` }}
        >
          {/* Indicator Line */}
          <div 
            className="absolute top-1 left-1/2 -translate-x-1/2 w-1 rounded-full shadow-[0_0_5px_currentColor]"
            style={{ height: size * 0.35, backgroundColor: accentColor }}
          />
        </div>

        {/* Metallic Center Cap */}
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-1/2 h-1/2 rounded-full bg-gradient-to-tr from-slate-800 to-slate-600 shadow-inner"></div>
      </div>

      <span className="text-[9px] uppercase font-bold text-slate-400 mt-1.5 tracking-tighter shadow-black drop-shadow-sm">
        {label}
      </span>
    </div>
  );
};

