interface ChannelStripProps {
  track: Track;
  onUpdate: (id: string, updates: Partial<Track>) => void;
  onToggleArm: (id: string) => void;
  onToggleExpand: (id: string) => void;
}

export const ChannelStrip: React.FC<ChannelStripProps> = ({ track, onUpdate, onToggleArm, onToggleExpand }) => {
  const [showColors, setShowColors] = useState(false);
  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setShowColors(false);
      }
    };
    if (showColors) document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [showColors]);

  const updateFX = (key: keyof typeof track.fx, value: number) => {
      onUpdate(track.id, {
          fx: { ...track.fx, [key]: value }
      });
  };

  return (
    <div 
        className="sticky left-0 w-36 z-20 flex flex-col shadow-[4px_0_15px_rgba(0,0,0,0.5)] select-none transition-all duration-300 group" 
        style={{ 
            height: track.isExpanded ? EXPANDED_TRACK_HEIGHT : TRACK_HEIGHT,
            backgroundColor: '#111827', // Slate 900 base
            backgroundImage: `linear-gradient(to bottom, #1f2937 0%, #111827 10%, #030712 100%)`
        }}
    >
       {/* --- HEADER SECTION --- */}
       <div className="p-2 flex-shrink-0 flex flex-col justify-between border-b border-black/50" style={{ height: TRACK_HEIGHT }}>

            {/* Top Row: Color, Name, Arm */}
            <div className="flex items-center justify-between mb-1 gap-1.5 relative z-30">
                <div className="relative" ref={menuRef}>
                    <button
                        className="w-3 h-3 rounded-full border border-white/20 shadow-[0_0_8px_inset_rgba(0,0,0,0.5)] active:scale-95"
                        style={{ backgroundColor: track.color, boxShadow: `0 0 5px ${track.color}40` }}
                        onClick={() => setShowColors(!showColors)}
                    />
                    {showColors && (
                    <div className="absolute top-full left-0 mt-2 bg-slate-950 border border-slate-700 p-2 rounded-lg grid grid-cols-4 gap-2 shadow-2xl z-50 w-32 animate-in zoom-in-95 duration-100">
                        {COLORS.map(c => (
                            <button key={c} className="w-5 h-5 rounded-full border border-white/10" style={{ backgroundColor: c }}
                            onClick={(e) => { e.stopPropagation(); onUpdate(track.id, { color: c }); setShowColors(false); }} />
                        ))}
                    </div>
                    )}
                </div>

                <input
                    className="bg-transparent text-[11px] font-bold text-slate-200 w-full outline-none px-0.5 truncate tracking-wide focus:text-cyan-400 focus:bg-white/5 rounded-sm transition-colors"
                    value={track.name}
                    onChange={(e) => onUpdate(track.id, { name: e.target.value })}
                />

                <button 
                    onClick={() => onToggleArm(track.id)} 
                    className={`w-4 h-4 rounded-full border flex items-center justify-center transition-all ${track.armed ? 'bg-red-900 border-red-500 shadow-[0_0_8px_rgba(220,38,38,0.5)]' : 'bg-slate-800 border-slate-600 hover:border-slate-500'}`}
                >
                    <div className={`w-1.5 h-1.5 rounded-full ${track.armed ? 'bg-red-500 animate-pulse' : 'bg-slate-500'}`} />
                </button>
            </div>

            {/* Buttons: Mute/Solo/FX */}
            <div className="flex space-x-1 mb-2">
                <button className={`flex-1 py-1 text-[9px] font-black rounded shadow-sm border border-b-2 active:border-b active:translate-y-[1px] transition-all
                    ${track.muted 
                        ? 'bg-orange-500/20 text-orange-500 border-orange-600/50 border-b-orange-600' 
                        : 'bg-slate-800 text-slate-500 border-slate-700 border-b-slate-900 hover:text-slate-300'}`}
                    onClick={() => onUpdate(track.id, { muted: !track.muted })}>M</button>

                <button className={`flex-1 py-1 text-[9px] font-black rounded shadow-sm border border-b-2 active:border-b active:translate-y-[1px] transition-all
                    ${track.solo 
                        ? 'bg-yellow-500/20 text-yellow-500 border-yellow-600/50 border-b-yellow-600' 
                        : 'bg-slate-800 text-slate-500 border-slate-700 border-b-slate-900 hover:text-slate-300'}`}
                    onClick={() => onUpdate(track.id, { solo: !track.solo })}>S</button>

                <button className={`flex-1 py-1 text-[9px] font-black rounded shadow-sm border border-b-2 active:border-b active:translate-y-[1px] transition-all
                    ${track.isExpanded 
                        ? 'bg-cyan-600 text-white border-cyan-800 border-b-cyan-900 shadow-[0_0_10px_rgba(8,145,178,0.3)]' 
                        : 'bg-slate-800 text-cyan-600 border-slate-700 border-b-slate-900 hover:text-cyan-400'}`}
                    onClick={() => onToggleExpand(track.id)}>FX</button>
            </div>

            {/* Volume Slider */}
            <div className="flex items-center space-x-2 mb-1 group/vol">
                <span className="text-[8px] text-slate-600 font-black w-4 group-hover/vol:text-cyan-500 transition-colors">VOL</span>
                <div className="flex-1 h-5 relative flex items-center">
                    {/* Track */}
                    <div className="absolute left-0 right-0 h-1 bg-slate-950 rounded-full shadow-inner border border-white/5 overflow-hidden">
                        <div className="h-full bg-cyan-700" style={{ width: `${track.volume * 100}%` }}></div>
