                    />
                    {/* Visual Thumb */}
                    <div 
                        className="absolute h-3 w-3 bg-slate-200 rounded-full shadow-md border border-slate-400 pointer-events-none transition-transform active:scale-110"
                        style={{ left: `calc(${track.volume * 100}% - 6px)` }}
