// --- Visualization Logic ---

const drawFilterCurve = (ctx: CanvasRenderingContext2D, width: number, height: number, freq: number, res: number, dataArray: Uint8Array) => {
  ctx.clearRect(0, 0, width, height);

  // 1. Draw Audio Spectrum Background (RTA)
  ctx.fillStyle = 'rgba(236, 72, 153, 0.1)'; // Pink tint
  const barWidth = width / 32;
  for(let i=0; i<32; i++) {
    const val = dataArray[i * 2] || 0;
    const h = (val / 255) * height;
    ctx.fillRect(i * barWidth, height - h, barWidth - 1, h);
  }

  // 2. Calculate Biquad Lowpass Magnitude Response
  // |H(w)| = 1 / sqrt( (1 - (w/w0)^2)^2 + (1/Q * w/w0)^2 )
  const w0 = 2 * Math.PI * freq;
  const Q = Math.max(0.1, res); // Prevent divide by zero, Q maps roughly 0-20
  // Note: Web Audio Q for lowpass is in dB or linear? usually linear. 
  // Standard biquad Q: 0.707 is flat. High Q is resonant. 
  // UI Res range is 0-20. Let's assume linear Q.
  const plotQ = 0.707 + (res * 1.5); 

  const minF = 20;
  const maxF = 20000;
  const logMin = Math.log(minF);
  const logMax = Math.log(maxF);
  const logRange = logMax - logMin;

  ctx.beginPath();
  ctx.moveTo(0, height); // Start bottom left

  // Iterate pixels for surgical precision
  for (let x = 0; x < width; x++) {
      // Map x -> frequency (Log Scale)
      const t = x / width;
      const f = Math.exp(logMin + t * logRange);
      const w = 2 * Math.PI * f;
      const ratio = w / w0;

      // Magnitude Calculation
      // denom = sqrt( (1 - r^2)^2 + (r/Q)^2 )
      const r2 = ratio * ratio;
      const term1 = (1 - r2);
      const term2 = ratio / plotQ;
      const denom = Math.sqrt(term1 * term1 + term2 * term2);
      const mag = 1 / (denom || 0.0001);

      // Convert Magnitude to Decibels then to Y
      // 20log10(mag). Let's clamp visual range +20dB to -100dB
      const db = 20 * Math.log10(mag);

      // Map dB to height. 0dB = middle (approx), but let's put 0dB at 30% from top to allow resonance headroom
      // range: +20dB (top) to -60dB (bottom) => 80dB range
      const rangeDB = 80;
      const topDB = 20;

      let normY = (topDB - db) / rangeDB;
      // Clamp
      normY = Math.max(0, Math.min(1, normY));

      const y = normY * height;

      if (x === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
  }

  // 3. Fill Area Under Curve
  // Complete the path to corners to create a shape
  ctx.lineTo(width, height);
  ctx.lineTo(0, height);
  ctx.closePath();

  // Create Gradient
  const grad = ctx.createLinearGradient(0, 0, 0, height);
  grad.addColorStop(0, 'rgba(236, 72, 153, 0.5)'); // Pink
  grad.addColorStop(1, 'rgba(236, 72, 153, 0.05)');

  ctx.fillStyle = grad;
  ctx.fill();

  // 4. Stroke the Line
  ctx.strokeStyle = '#ec4899';
  ctx.lineWidth = 2;
  ctx.stroke();
};

const drawSaturationCurve = (ctx: CanvasRenderingContext2D, width: number, height: number, drive: number) => {
  ctx.clearRect(0, 0, width, height);

  // Center Axis
  const midY = height / 2;
  const midX = width / 2;

  // Grid
  ctx.strokeStyle = '#333';
  ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(midX, 0); ctx.lineTo(midX, height); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(0, midY); ctx.lineTo(width, midY); ctx.stroke();

  // Path Calculation
  ctx.beginPath();

  const k = drive; // 0 to 100

  // We want to fill between the curve and the X-axis (y=0)
  // Since fill() works on a closed shape, we'll draw the curve, then trace back along the x-axis?
  // Actually, we can just draw the curve top, line to bottom right, line to bottom left? 
  // No, standard fill is fine if we close it properly.

  // Start from left edge on axis? No, let's just plot points.

  const points: [number, number][] = [];

  for (let i = 0; i <= width; i+=2) {
     const x = (i / width) * 2 - 1; // -1 to 1

     // WaveShaper Algo
     let y = x;
     if (k > 0) {
        y = ((Math.PI + k) * x) / (Math.PI + k * Math.abs(x));
     }

     // map y (-1 to 1) to canvas Y
     // -1 => height, 1 => 0
     const plotY = midY - (y * midY * 0.9); // 0.9 padding
     points.push([i, plotY]);
  }

  // Draw Curve Path
  if (points.length > 0) ctx.moveTo(points[0][0], points[0][1]);
  for(const p of points) ctx.lineTo(p[0], p[1]);

  // Stroke First
  ctx.strokeStyle = '#f97316'; // Orange
  ctx.lineWidth = 2;
  ctx.stroke();

  // Fill Area between Curve and Axis
  // We need two shapes: Positive lobe and Negative lobe or just fill the whole polygon?
  // Let's create a polygon that goes: Start -> Curve -> End -> AxisRight -> AxisLeft -> Start?
  // Actually, simpler to fill to the bottom or fill relative to axis.
  // To fill "under" the line relative to X-axis:
  ctx.beginPath();
  ctx.moveTo(0, midY);
  for(const p of points) ctx.lineTo(p[0], p[1]);
  ctx.lineTo(width, midY);
  ctx.closePath();

  const grad = ctx.createLinearGradient(0, 0, 0, height);
  grad.addColorStop(0, 'rgba(249, 115, 22, 0.4)'); // Top (Orange)
  grad.addColorStop(0.5, 'rgba(249, 115, 22, 0.1)'); // Middle
  grad.addColorStop(1, 'rgba(249, 115, 22, 0.4)'); // Bottom

  ctx.fillStyle = grad;
  ctx.fill();
};

const drawEQBars = (ctx: CanvasRenderingContext2D, width: number, height: number, low: number, mid: number, high: number, dataArray: Uint8Array) => {
  ctx.clearRect(0, 0, width, height);
  const bandW = width / 3;
  const bands = [low, mid, high];
  const colors = ['#3b82f6', '#06b6d4', '#a855f7']; // Blue range

  // Sample Audio Data for reactivity
  const lowEnergy = dataArray[2] / 255;
  const midEnergy = dataArray[16] / 255;
  const highEnergy = dataArray[40] / 255;
  const energies = [lowEnergy, midEnergy, highEnergy];

  // Draw Filled Curve connecting the peaks (Area Chart style)
  ctx.beginPath();
  ctx.moveTo(0, height);
  bands.forEach((gain, i) => {
     const energyH = energies[i] * height * 0.8;
     const x = i * bandW + bandW/2;
     const y = height - energyH;
     // simple curve or line
     ctx.lineTo(x, y);
  });
  ctx.lineTo(width, height);
  ctx.closePath();

  const areaGrad = ctx.createLinearGradient(0, height, 0, 0);
  areaGrad.addColorStop(0, 'rgba(59, 130, 246, 0.05)');
  areaGrad.addColorStop(1, 'rgba(168, 85, 247, 0.2)');
  ctx.fillStyle = areaGrad;
  ctx.fill();

  // Draw Specific Band Indicators
  bands.forEach((gain, i) => {
    // Gain line
    const zeroY = height / 2;
    const gainY = zeroY - (gain / 12) * (height / 2.5); // Map +/- 12dB

    // Background slot
    ctx.fillStyle = 'rgba(255,255,255,0.05)';
    ctx.fillRect(i * bandW + 2, 0, bandW - 4, height);

    // Active Level Bar (Filled)
    const energyHeight = energies[i] * height;

    const barGrad = ctx.createLinearGradient(0, height, 0, height - energyHeight);
    barGrad.addColorStop(0, colors[i] + '10');
    barGrad.addColorStop(1, colors[i] + '60');

    ctx.fillStyle = barGrad;
    ctx.fillRect(i * bandW + 2, height - energyHeight, bandW - 4, energyHeight);

    // Gain Puck with connecting line
    ctx.beginPath();
    ctx.strokeStyle = colors[i];
    ctx.lineWidth = 2;
    ctx.moveTo(i*bandW, gainY);
    ctx.lineTo((i+1)*bandW, gainY);
    ctx.stroke();

    ctx.fillStyle = colors[i];
    ctx.beginPath();
    ctx.arc(i * bandW + bandW/2, gainY, 3, 0, Math.PI*2);
    ctx.fill();

    // Fill to center
    ctx.fillStyle = colors[i] + '33';
    ctx.fillRect(i * bandW + bandW/2 - 1, Math.min(zeroY, gainY), 2, Math.abs(zeroY - gainY));
  });
};

const drawDynamicsCurve = (ctx: CanvasRenderingContext2D, width: number, height: number, thresh: number, ratio: number, dataArray: Uint8Array) => {
  ctx.clearRect(0, 0, width, height);

  // Avg volume for ball
  let sum = 0;
  for(let i=0; i<dataArray.length; i++) sum += dataArray[i];
  const vol = (sum / dataArray.length) / 255; // 0 to 1
  const dbEst = 20 * Math.log10(vol + 0.0001); // approx dB
  const inputX = Math.max(0, Math.min(width, ((dbEst + 60) / 60) * width)); // Map -60dB...0dB to width

  const threshX = ((thresh + 60) / 60) * width; // Threshold X position

  // Construct Path
  ctx.beginPath();
  ctx.moveTo(0, height);

  // Point 1: Threshold Knee
  const kneeY = height - threshX;
  ctx.lineTo(threshX, kneeY); // Linear part (1:1)

  // Point 2: Compressed End
  const remainingW = width - threshX;
  const compressedH = remainingW * (1/ratio);
  const endY = height - threshX - compressedH;
  ctx.lineTo(width, endY);

  // Close Path for Fill
  ctx.lineTo(width, height);
  ctx.lineTo(0, height);
  ctx.closePath();

  // Fill
  const grad = ctx.createLinearGradient(0, height, 0, 0);
  grad.addColorStop(0, 'rgba(234, 179, 8, 0.1)'); 
  grad.addColorStop(1, 'rgba(234, 179, 8, 0.4)');
  ctx.fillStyle = grad;
  ctx.fill();

  // Stroke Top
  ctx.beginPath();
  ctx.strokeStyle = '#eab308'; // Yellow
  ctx.lineWidth = 2;
  ctx.moveTo(0, height);
  ctx.lineTo(threshX, kneeY);
  ctx.lineTo(width, endY);
  ctx.stroke();

  // Draw Bouncing Ball (Current Level)
  ctx.fillStyle = '#fff';
  ctx.beginPath();
  let ballY = height - inputX; // Linear default
  if (inputX > threshX) {
      const over = inputX - threshX;
      ballY = height - threshX - (over * (1/ratio));
  }
  ctx.arc(inputX, ballY, 4, 0, Math.PI*2);
  ctx.fill();

  // Drop line for ball
  ctx.strokeStyle = 'rgba(255,255,255,0.3)';
  ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(inputX, ballY); ctx.lineTo(inputX, height); ctx.stroke();
};

const drawSpatialScope = (ctx: CanvasRenderingContext2D, width: number, height: number, time: number, mix: number) => {
  ctx.clearRect(0, 0, width, height);

  const cx = width / 2;
  const cy = height / 2;
  const maxR = Math.min(width, height) / 2 - 4;

  // Base Circle Area Fill
  ctx.beginPath();
  ctx.arc(cx, cy, maxR * mix, 0, Math.PI * 2);
  ctx.fillStyle = 'rgba(168, 85, 247, 0.2)';
  ctx.fill();
  ctx.strokeStyle = '#a855f7'; // Purple
  ctx.lineWidth = 1.5;
  ctx.stroke();

  // Orbiting Dots (Simulate delay taps)
  const count = 4;
  const now = Date.now() / 1000;
  ctx.fillStyle = '#06b6d4'; // Cyan

  for(let i=0; i<count; i++) {
     const offset = (i / count) * Math.PI * 2;
     const speed = (1.1 - time) * 3; 
     const angle = now * speed + offset;
     const r = maxR * (0.3 + (mix * 0.7));

     const x = cx + Math.cos(angle) * r;
     const y = cy + Math.sin(angle) * r;

     // Trail
     ctx.beginPath();
     ctx.arc(x, y, 4, 0, Math.PI * 2);
     ctx.shadowColor = '#06b6d4';
     ctx.shadowBlur = 10;
     ctx.fill();
     ctx.shadowBlur = 0;
  }
};

const drawOutputMeter = (ctx: CanvasRenderingContext2D, width: number, height: number, vol: number, dataArray: Uint8Array) => {
    ctx.clearRect(0, 0, width, height);

    // Calculate RMS approx
    let sum = 0;
    for(let i=0; i<dataArray.length; i++) sum += dataArray[i] * dataArray[i];
    const rms = Math.sqrt(sum / dataArray.length) / 255;

    // Apply Master Gain
    const outputLevel = Math.min(1, rms * vol);

    const w = width * 0.8;
    const x = (width - w) / 2;
    const h = height * outputLevel;

    // Background Track
    ctx.fillStyle = '#1e293b';
    ctx.fillRect(x, 0, w, height);

    // Meter Fill with Gradient
    const gradient = ctx.createLinearGradient(0, height, 0, 0);
    gradient.addColorStop(0, '#22c55e');
    gradient.addColorStop(0.6, '#eab308');
    gradient.addColorStop(1, '#ef4444');

    ctx.fillStyle = gradient;
    ctx.fillRect(x, height - h, w, h);

    // Grid lines
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    for(let i=0; i<height; i+=4) {
        ctx.fillRect(x, i, w, 1);
    }
};

// --- Rack Module Component ---

const RackModule: React.FC<{
  title: string;
  type: keyof typeof ICONS;
  color: string;
  dspState: DSPState;
  children: React.ReactNode;
}> = ({ title, type, color, dspState, children }) => {

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const glowMap: Record<string, string> = {
    pink: 'text-pink-500 border-pink-900',
    orange: 'text-orange-500 border-orange-900',
    blue: 'text-blue-500 border-blue-900',
    yellow: 'text-yellow-500 border-yellow-900',
    purple: 'text-purple-500 border-purple-900',
    cyan: 'text-cyan-500 border-cyan-900',
    red: 'text-red-500 border-red-900',
  };
  const themeClass = glowMap[color];
  const Icon = ICONS[type];

  useEffect(() => {
     const canvas = canvasRef.current;
     if(!canvas) return;
     const ctx = canvas.getContext('2d');
     if(!ctx) return;

     let frameId: number;
     const dataArray = new Uint8Array(audioEngine.analyser.frequencyBinCount);

     const render = () => {
         frameId = requestAnimationFrame(render);
         audioEngine.analyser.getByteFrequencyData(dataArray);

         const w = canvas.width;
         const h = canvas.height;

         if (type === 'filter') {
            drawFilterCurve(ctx, w, h, dspState.masterFilterFreq, dspState.masterFilterRes, dataArray);
         } else if (type === 'saturator') {
            drawSaturationCurve(ctx, w, h, dspState.masterSaturation);
         } else if (type === 'eq') {
            drawEQBars(ctx, w, h, dspState.masterEqLow, dspState.masterEqMid, dspState.masterEqHigh, dataArray);
         } else if (type === 'dynamics') {
            drawDynamicsCurve(ctx, w, h, dspState.masterCompressorThreshold, dspState.masterCompressorRatio, dataArray);
         } else if (type === 'spatial') {
            drawSpatialScope(ctx, w, h, dspState.delayTime, dspState.reverbMix);
         } else if (type === 'output') {
            drawOutputMeter(ctx, w, h, dspState.masterVolume, dataArray);
         }
     };
     render();
     return () => cancelAnimationFrame(frameId);
  }, [type, dspState]);

  return (
    <div className="flex flex-col h-full bg-[#111827] border-r border-slate-800 relative group min-w-[160px]">

      {/* Header with Calligraphic Symbol & Visualizer */}
      <div className="h-20 bg-black border-b border-slate-800 relative overflow-hidden group-hover:bg-[#161e2e] transition-colors">

        {/* The Dynamic Visualizer Layer */}
        <canvas ref={canvasRef} width={160} height={80} className="absolute inset-0 z-0 opacity-40" />

        {/* The Scanline Overlay */}
        <div className="absolute inset-0 bg-[linear-gradient(rgba(0,0,0,0)_50%,rgba(0,0,0,0.5)_50%)] bg-[length:100%_4px] pointer-events-none z-10 opacity-30"></div>

        {/* The Symbol & Title Layer */}
        <div className="absolute inset-0 flex flex-col items-center justify-center z-20 pointer-events-none">
             <div className="mb-1">{Icon(themeClass.split(' ')[0].replace('text-', '#').split('-')[0])}</div>
             <div className={`text-[9px] font-black tracking-[0.2em] uppercase ${themeClass} drop-shadow-md`}>{title}</div>
        </div>

      </div>

      {/* Controls Area */}
      <div className="flex-1 flex items-center justify-center space-x-3 px-3 py-2 bg-gradient-to-b from-[#1f2937] to-[#111827] relative">
         {/* Subtle ornate corners */}
         <div className="absolute top-0 left-0 w-2 h-2 border-t border-l border-slate-600 opacity-50"></div>
         <div className="absolute top-0 right-0 w-2 h-2 border-t border-r border-slate-600 opacity-50"></div>

         {children}
      </div>

      {/* Bolts */}
      <div className="absolute bottom-1 right-1 w-1.5 h-1.5 rounded-full bg-slate-700 shadow-[inset_1px_1px_1px_rgba(0,0,0,1)] flex items-center justify-center">
        <div className="w-1 h-px bg-slate-900 rotate-45"></div>
      </div>
      <div className="absolute bottom-1 left-1 w-1.5 h-1.5 rounded-full bg-slate-700 shadow-[inset_1px_1px_1px_rgba(0,0,0,1)] flex items-center justify-center">
        <div className="w-1 h-px bg-slate-900 rotate-45"></div>
      </div>
    </div>
  );
};

