// --- Visualization Logic with Wave Interference Calculus ---

const calculateInterference = (x: number, time: number, frequency: number) => {
    // Constructive/Destructive interference of two waves
    const wave1 = Math.sin(x * frequency + time);
    const wave2 = Math.sin(x * (frequency * 1.5) - time * 0.5);
    // Normalize to 0-1 range approx
    return (wave1 + wave2 + 2) / 4;
};

const drawFilterCurve = (ctx: CanvasRenderingContext2D, width: number, height: number, freq: number, res: number, dataArray: Uint8Array, time: number) => {
  ctx.clearRect(0, 0, width, height);

  // RTA Background
  const barWidth = width / 32;
  ctx.fillStyle = 'rgba(236, 72, 153, 0.05)';
  for(let i=0; i<32; i++) {
    const val = dataArray[i * 2] || 0;
    const h = (val / 255) * height;
    ctx.fillRect(i * barWidth, height - h, barWidth - 1, h);
  }

  // Biquad Lowpass Calculation
  const w0 = 2 * Math.PI * freq;
  const Q = 0.707 + (res * 1.5); 
  const minF = 20;
  const maxF = 20000;
  const logMin = Math.log(minF);
  const logRange = Math.log(maxF) - logMin;

  // Render scanlines with interference pattern for fill
  for (let x = 0; x < width; x+=2) {
      const t = x / width;
      const f = Math.exp(logMin + t * logRange);
      const w = 2 * Math.PI * f;
      const ratio = w / w0;

      const r2 = ratio * ratio;
      const denom = Math.sqrt(Math.pow(1 - r2, 2) + Math.pow(ratio / Q, 2));
      const mag = 1 / (denom || 0.0001);
      const db = 20 * Math.log10(mag);

      let normY = (20 - db) / 80; // +20dB to -60dB range
      normY = Math.max(0, Math.min(1, normY));
      const y = normY * height;

      // Interference Fill
      const intensity = calculateInterference(x, time, 0.1);
      ctx.fillStyle = `rgba(236, 72, 153, ${intensity * 0.3})`;
      ctx.fillRect(x, y, 2, height - y);

      // Top Line pixel
      ctx.fillStyle = '#ec4899';
      ctx.fillRect(x, y, 2, 2);
  }
};

const drawSaturationCurve = (ctx: CanvasRenderingContext2D, width: number, height: number, drive: number, time: number) => {
  ctx.clearRect(0, 0, width, height);
  const midY = height / 2;

  // Grid
  ctx.strokeStyle = 'rgba(255,255,255,0.1)';
  ctx.beginPath(); ctx.moveTo(0, midY); ctx.lineTo(width, midY); ctx.stroke();

  const k = drive; 

  for (let i = 0; i < width; i+=2) {
     const xInput = (i / width) * 2 - 1; 
     let yOutput = xInput;
     if (k > 0) {
        yOutput = ((Math.PI + k) * xInput) / (Math.PI + k * Math.abs(xInput));
     }
     const plotY = midY - (yOutput * midY * 0.9);

     // Interference Fill relative to X-axis
     const intensity = calculateInterference(i, time, 0.08);
     const fillColor = `rgba(249, 115, 22, ${intensity * 0.25})`;
     ctx.fillStyle = fillColor;

     // Draw rect from axis to point
     if (plotY < midY) {
         ctx.fillRect(i, plotY, 2, midY - plotY);
     } else {
         ctx.fillRect(i, midY, 2, plotY - midY);
     }

     // Line
     ctx.fillStyle = '#f97316';
     ctx.fillRect(i, plotY, 2, 2);
  }
};

const drawEQBars = (ctx: CanvasRenderingContext2D, width: number, height: number, low: number, mid: number, high: number, dataArray: Uint8Array, time: number) => {
  ctx.clearRect(0, 0, width, height);
  const bandW = width / 3;
  const bands = [low, mid, high];
  const colors = ['#3b82f6', '#06b6d4', '#a855f7'];

  // Interference Background
  for(let x=0; x<width; x+=4) {
      const intensity = calculateInterference(x, time, 0.05);
      ctx.fillStyle = `rgba(59, 130, 246, ${intensity * 0.05})`;
      ctx.fillRect(x, 0, 2, height);
  }

  // Draw Bars
  const energies = [dataArray[2]/255, dataArray[16]/255, dataArray[40]/255];

  bands.forEach((gain, i) => {
    const gainY = (height / 2) - (gain / 12) * (height / 2.5);
    const energyHeight = energies[i] * height;

    // Fill
    const barGrad = ctx.createLinearGradient(0, height, 0, height - energyHeight);
    barGrad.addColorStop(0, colors[i] + '10');
    barGrad.addColorStop(1, colors[i] + '60');
    ctx.fillStyle = barGrad;
    ctx.fillRect(i * bandW + 2, height - energyHeight, bandW - 4, energyHeight);

    // Gain Line with interference modulation on width
    ctx.strokeStyle = colors[i];
    ctx.lineWidth = 2 + Math.sin(time * 5 + i) * 1; 
    ctx.beginPath();
    ctx.moveTo(i*bandW + 5, gainY);
    ctx.lineTo((i+1)*bandW - 5, gainY);
    ctx.stroke();

    // Center dot
    ctx.fillStyle = colors[i];
    ctx.beginPath();
    ctx.arc(i * bandW + bandW/2, gainY, 3, 0, Math.PI*2);
    ctx.fill();
  });
};

const drawDynamicsCurve = (ctx: CanvasRenderingContext2D, width: number, height: number, thresh: number, ratio: number, dataArray: Uint8Array, time: number) => {
  ctx.clearRect(0, 0, width, height);

  // Input Level Ball
  let sum = 0; for(let i=0; i<dataArray.length; i++) sum += dataArray[i];
  const vol = (sum / dataArray.length) / 255;
  const dbEst = 20 * Math.log10(vol + 0.0001);
  const inputX = Math.max(0, Math.min(width, ((dbEst + 60) / 60) * width));
  const threshX = ((thresh + 60) / 60) * width;

  // Interference Fill under curve
  const kneeY = height - threshX;
  const remainingW = width - threshX;
  const compressedH = remainingW * (1/ratio);
  const endY = height - threshX - compressedH;

  // Define line segments for calc
  const getCurveY = (x: number) => {
      if (x <= threshX) return height - x;
      return height - threshX - (x - threshX) * (1/ratio);
  };

  for (let x = 0; x < width; x+=2) {
      const y = getCurveY(x);
      const intensity = calculateInterference(x, time, 0.1);
      ctx.fillStyle = `rgba(234, 179, 8, ${intensity * 0.2 + 0.1})`;
      ctx.fillRect(x, y, 2, height - y);

      // Line
      ctx.fillStyle = '#eab308';
      ctx.fillRect(x, y, 2, 2);
  }

  // Ball
  let ballY = getCurveY(inputX);
  ctx.fillStyle = '#fff';
  ctx.beginPath(); ctx.arc(inputX, ballY, 4, 0, Math.PI*2); ctx.fill();
};

const drawSpatialScope = (ctx: CanvasRenderingContext2D, width: number, height: number, delayTime: number, mix: number, time: number) => {
  ctx.clearRect(0, 0, width, height);
  const cx = width / 2;
  const cy = height / 2;
  const maxR = Math.min(width, height) / 2 - 4;

  // Interference Pattern Background (Lissajous-like)
  ctx.beginPath();
  for (let t = 0; t < Math.PI * 2; t += 0.1) {
      const r = maxR * mix * (0.8 + 0.2 * Math.sin(t * 10 + time)); // Modulated Radius
      const x = cx + Math.cos(t) * r;
      const y = cy + Math.sin(t) * r;
      if (t===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
  }
  ctx.closePath();
  ctx.strokeStyle = `rgba(168, 85, 247, 0.5)`;
  ctx.stroke();
  ctx.fillStyle = `rgba(168, 85, 247, 0.1)`;
  ctx.fill();

  // Orbiting Dots
  const count = 4;
  ctx.fillStyle = '#06b6d4';
  for(let i=0; i<count; i++) {
     const offset = (i / count) * Math.PI * 2;
     const speed = (1.1 - delayTime) * 3; 
     const angle = time * speed + offset;

     // Interference movement
     const wobble = Math.sin(time * 10 + i) * 5;
     const r = maxR * (0.3 + (mix * 0.7)) + wobble;

     const x = cx + Math.cos(angle) * r;
     const y = cy + Math.sin(angle) * r;

     ctx.beginPath(); ctx.arc(x, y, 3, 0, Math.PI * 2); ctx.fill();
  }
};

const drawOutputMeter = (ctx: CanvasRenderingContext2D, width: number, height: number, vol: number, dataArray: Uint8Array, time: number) => {
    ctx.clearRect(0, 0, width, height);
    let sum = 0; for(let i=0; i<dataArray.length; i++) sum += dataArray[i] * dataArray[i];
    const rms = Math.sqrt(sum / dataArray.length) / 255;
    const outputLevel = Math.min(1, rms * vol);

    const w = width * 0.7;
    const x = (width - w) / 2;
    const h = height * outputLevel;

    // Background interference
    for (let i = 0; i < height; i+=4) {
        const intensity = calculateInterference(i, time, 0.2);
        ctx.fillStyle = `rgba(30, 41, 59, ${0.5 + intensity * 0.5})`;
        ctx.fillRect(x, i, w, 2);
    }

    // Meter Fill
    const gradient = ctx.createLinearGradient(0, height, 0, 0);
    gradient.addColorStop(0, '#22c55e');
    gradient.addColorStop(0.6, '#eab308');
    gradient.addColorStop(1, '#ef4444');
    ctx.fillStyle = gradient;
    ctx.fillRect(x, height - h, w, h);
};

// --- Rack Module Component ---

const RackModule: React.FC<{
  title: string;
  type: keyof typeof ICONS;
  color: string;
  dspState: DSPState;
  children: React.ReactNode;
}> = ({ title, type, color, dspState, children }) => {

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const glowMap: Record<string, string> = {
    pink: 'text-pink-500 border-pink-900',
    orange: 'text-orange-500 border-orange-900',
    blue: 'text-blue-500 border-blue-900',
    yellow: 'text-yellow-500 border-yellow-900',
    purple: 'text-purple-500 border-purple-900',
    cyan: 'text-cyan-500 border-cyan-900',
    red: 'text-red-500 border-red-900',
  };
  const themeClass = glowMap[color];
  const Icon = ICONS[type];

  useEffect(() => {
     const canvas = canvasRef.current;
     if(!canvas) return;
     const ctx = canvas.getContext('2d');
     if(!ctx) return;

     let frameId: number;
     const dataArray = new Uint8Array(audioEngine.analyser.frequencyBinCount);

     const render = () => {
         frameId = requestAnimationFrame(render);
         const time = performance.now() / 1000;
         audioEngine.analyser.getByteFrequencyData(dataArray);

         const w = canvas.width;
         const h = canvas.height;

         if (type === 'filter') {
            drawFilterCurve(ctx, w, h, dspState.masterFilterFreq, dspState.masterFilterRes, dataArray, time);
         } else if (type === 'saturator') {
            drawSaturationCurve(ctx, w, h, dspState.masterSaturation, time);
         } else if (type === 'eq') {
            drawEQBars(ctx, w, h, dspState.masterEqLow, dspState.masterEqMid, dspState.masterEqHigh, dataArray, time);
         } else if (type === 'dynamics') {
            drawDynamicsCurve(ctx, w, h, dspState.masterCompressorThreshold, dspState.masterCompressorRatio, dataArray, time);
         } else if (type === 'spatial') {
            drawSpatialScope(ctx, w, h, dspState.delayTime, dspState.reverbMix, time);
         } else if (type === 'output') {
            drawOutputMeter(ctx, w, h, dspState.masterVolume, dataArray, time);
         }
     };
     render();
     return () => cancelAnimationFrame(frameId);
  }, [type, dspState]);

  return (
    <div className="flex flex-col h-full bg-[#111827] border-r border-slate-800 relative group min-w-[160px]">

      {/* Header with Calligraphic Symbol & Visualizer */}
      <div className="h-20 bg-black border-b border-slate-800 relative overflow-hidden group-hover:bg-[#161e2e] transition-colors">

        {/* The Dynamic Visualizer Layer */}
        <canvas ref={canvasRef} width={160} height={80} className="absolute inset-0 z-0 opacity-60" />

        {/* The Scanline Overlay */}
        <div className="absolute inset-0 bg-[linear-gradient(rgba(0,0,0,0)_50%,rgba(0,0,0,0.5)_50%)] bg-[length:100%_4px] pointer-events-none z-10 opacity-30"></div>

        {/* The Symbol & Title Layer (Aligned Right) */}
        <div className="absolute inset-0 flex flex-col items-end justify-center z-20 pointer-events-none pr-3">
             <div className="mb-1">{Icon(themeClass.split(' ')[0].replace('text-', '#').split('-')[0])}</div>
             <div className={`text-[9px] font-black tracking-[0.2em] uppercase ${themeClass} drop-shadow-md text-right`}>{title}</div>
        </div>

      </div>

      {/* Controls Area */}
      <div className="flex-1 flex items-center justify-center space-x-3 px-3 py-2 bg-gradient-to-b from-[#1f2937] to-[#111827] relative">
         {/* Subtle ornate corners */}
         <div className="absolute top-0 left-0 w-2 h-2 border-t border-l border-slate-600 opacity-50"></div>
         <div className="absolute top-0 right-0 w-2 h-2 border-t border-r border-slate-600 opacity-50"></div>

         {children}
      </div>

      {/* Bolts */}
      <div className="absolute bottom-1 right-1 w-1.5 h-1.5 rounded-full bg-slate-700 shadow-[inset_1px_1px_1px_rgba(0,0,0,1)] flex items-center justify-center">
        <div className="w-1 h-px bg-slate-900 rotate-45"></div>
      </div>
      <div className="absolute bottom-1 left-1 w-1.5 h-1.5 rounded-full bg-slate-700 shadow-[inset_1px_1px_1px_rgba(0,0,0,1)] flex items-center justify-center">
        <div className="w-1 h-px bg-slate-900 rotate-45"></div>
      </div>
    </div>
  );
};

