// --- Color Parsing & Wave Calculus ---

const hexToRgb = (hex: string): [number, number, number] => {
  const map: Record<string, [number, number, number]> = {
    'pink': [236, 72, 153],
    'orange': [249, 115, 22],
    'blue': [59, 130, 246],
    'yellow': [234, 179, 8],
    'purple': [168, 85, 247],
    'cyan': [6, 182, 212],
    'red': [239, 68, 68]
  };
  if (map[hex]) return map[hex];

  // Fallback for hex strings if passed directly
  const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
  return result ? 
    [parseInt(result[1], 16), parseInt(result[2], 16), parseInt(result[3], 16)] : 
    [100, 100, 100];
};

const calculateMultiSpectralInterference = (x: number, width: number, time: number, baseColorName: string): string => {
    // We simulate interference for R, G, B separately
    // Wavelength ratios: R(long) ~ 1.0, G(mid) ~ 0.8, B(short) ~ 0.7

    // Normalized position 0 to 1
    const n = x / width;

    // Base frequency scaling (The "2*pi*canvas width" logic applied to phase cycles)
    // To get tight waves, we scale by a factor of 2PI * Cycles.
    // Let's use 12 cycles across the canvas width for "intricate" detail.
    const baseFreq = Math.PI * 2 * 12; 

    // Time scaling
    const t = time * 2;

    // Calculate intensity for each channel
    // Sin(kx - wt)
    const rInt = Math.sin(n * baseFreq * 1.0 + t * 0.5) * 0.5 + 0.5;
    const gInt = Math.sin(n * baseFreq * 1.2 + t * 0.7) * 0.5 + 0.5;
    const bInt = Math.sin(n * baseFreq * 1.4 + t * 0.9) * 0.5 + 0.5;

    // Get Base Color
    const [bR, bG, bB] = hexToRgb(baseColorName);

    // Mix Base Color with Interference Pattern
    // We want the base color to be dominant but shifted by interference
    const finalR = Math.min(255, bR * 0.4 + rInt * 150);
    const finalG = Math.min(255, bG * 0.4 + gInt * 150);
    const finalB = Math.min(255, bB * 0.4 + bInt * 150);

    // Alpha Modulation: darker in troughs
    const alpha = 0.1 + ((rInt + gInt + bInt) / 3) * 0.2;

    return `rgba(${Math.floor(finalR)}, ${Math.floor(finalG)}, ${Math.floor(finalB)}, ${alpha})`;
};

// --- Draw Functions ---

const drawFilterCurve = (ctx: CanvasRenderingContext2D, width: number, height: number, freq: number, res: number, dataArray: Uint8Array, time: number) => {
  ctx.clearRect(0, 0, width, height);

  // RTA
  const barWidth = width / 32;
  ctx.fillStyle = 'rgba(236, 72, 153, 0.05)';
  for(let i=0; i<32; i++) {
    const val = dataArray[i * 2] || 0;
    const h = (val / 255) * height;
    ctx.fillRect(i * barWidth, height - h, barWidth - 1, h);
  }

  const w0 = 2 * Math.PI * freq;
  const Q = 0.707 + (res * 1.5); 
  const minF = 20;
  const maxF = 20000;
  const logMin = Math.log(minF);
  const logRange = Math.log(maxF) - logMin;

  for (let x = 0; x < width; x+=1) { // 1px precision for wave smoothness
      const t = x / width;
      const f = Math.exp(logMin + t * logRange);
      const w = 2 * Math.PI * f;
      const ratio = w / w0;
      const r2 = ratio * ratio;
      const denom = Math.sqrt(Math.pow(1 - r2, 2) + Math.pow(ratio / Q, 2));
      const mag = 1 / (denom || 0.0001);
      const db = 20 * Math.log10(mag);

      let normY = (20 - db) / 80;
      normY = Math.max(0, Math.min(1, normY));
      const y = normY * height;

      // Multi-spectral fill
      ctx.fillStyle = calculateMultiSpectralInterference(x, width, time, 'pink');
      ctx.fillRect(x, y, 1, height - y);

      ctx.fillStyle = '#ec4899';
      ctx.fillRect(x, y, 1, 2);
  }
};

const drawSaturationCurve = (ctx: CanvasRenderingContext2D, width: number, height: number, drive: number, time: number) => {
  ctx.clearRect(0, 0, width, height);
  const midY = height / 2;

  ctx.strokeStyle = 'rgba(255,255,255,0.1)';
  ctx.beginPath(); ctx.moveTo(0, midY); ctx.lineTo(width, midY); ctx.stroke();

  const k = drive; 
  for (let i = 0; i < width; i+=1) {
     const xInput = (i / width) * 2 - 1; 
     let yOutput = xInput;
     if (k > 0) yOutput = ((Math.PI + k) * xInput) / (Math.PI + k * Math.abs(xInput));
     const plotY = midY - (yOutput * midY * 0.9);

     ctx.fillStyle = calculateMultiSpectralInterference(i, width, time, 'orange');

     if (plotY < midY) ctx.fillRect(i, plotY, 1, midY - plotY);
     else ctx.fillRect(i, midY, 1, plotY - midY);

     ctx.fillStyle = '#f97316';
     ctx.fillRect(i, plotY, 1, 2);
  }
};

const drawEQBars = (ctx: CanvasRenderingContext2D, width: number, height: number, low: number, mid: number, high: number, dataArray: Uint8Array, time: number) => {
  ctx.clearRect(0, 0, width, height);
  const bandW = width / 3;
  const bands = [low, mid, high];
  const colors = ['blue', 'cyan', 'purple'];
  const energies = [dataArray[2]/255, dataArray[16]/255, dataArray[40]/255];

  // Background Interference Field
  for(let x=0; x<width; x+=2) {
      // Very faint background
      const n = x / width;
      const baseFreq = Math.PI * 2 * 8;
      const t = time;
      const alpha = (Math.sin(n * baseFreq + t) * 0.5 + 0.5) * 0.05;
      ctx.fillStyle = `rgba(59, 130, 246, ${alpha})`;
      ctx.fillRect(x, 0, 1, height);
  }

  bands.forEach((gain, i) => {
    const gainY = (height / 2) - (gain / 12) * (height / 2.5);
    const energyHeight = energies[i] * height;
    const startX = i * bandW + 2;
    const barWidth = bandW - 4;

    // Draw Bar with detailed interference
    for (let bx = 0; bx < barWidth; bx+=2) {
        const absX = startX + bx;
        ctx.fillStyle = calculateMultiSpectralInterference(absX, width, time, colors[i]);
        // Modify alpha for bar solidity
        const color = ctx.fillStyle as string;
        // Hacky string manipulation to boost alpha for the bar
        // Ideally we'd separate color calc, but this works for visual flair
        ctx.fillRect(absX, height - energyHeight, 2, energyHeight);
    }

    // Gain Line
    const lineColor = hexToRgb(colors[i]);
    ctx.strokeStyle = `rgb(${lineColor[0]},${lineColor[1]},${lineColor[2]})`;
    ctx.lineWidth = 2 + Math.sin(time * 5 + i) * 1; 
    ctx.beginPath(); ctx.moveTo(i*bandW + 5, gainY); ctx.lineTo((i+1)*bandW - 5, gainY); ctx.stroke();

    // Puck
    ctx.fillStyle = `rgb(${lineColor[0]},${lineColor[1]},${lineColor[2]})`;
    ctx.beginPath(); ctx.arc(i * bandW + bandW/2, gainY, 3, 0, Math.PI*2); ctx.fill();
  });
};

const drawDynamicsCurve = (ctx: CanvasRenderingContext2D, width: number, height: number, thresh: number, ratio: number, dataArray: Uint8Array, time: number) => {
  ctx.clearRect(0, 0, width, height);
  let sum = 0; for(let i=0; i<dataArray.length; i++) sum += dataArray[i];
  const vol = (sum / dataArray.length) / 255;
  const dbEst = 20 * Math.log10(vol + 0.0001);
  const inputX = Math.max(0, Math.min(width, ((dbEst + 60) / 60) * width));
  const threshX = ((thresh + 60) / 60) * width;

  const getCurveY = (x: number) => {
      if (x <= threshX) return height - x;
      return height - threshX - (x - threshX) * (1/ratio);
  };

  for (let x = 0; x < width; x+=1) {
      const y = getCurveY(x);
      ctx.fillStyle = calculateMultiSpectralInterference(x, width, time, 'yellow');
      ctx.fillRect(x, y, 1, height - y);

      ctx.fillStyle = '#eab308';
      ctx.fillRect(x, y, 1, 2);
  }

  let ballY = getCurveY(inputX);
  ctx.fillStyle = '#fff';
  ctx.beginPath(); ctx.arc(inputX, ballY, 4, 0, Math.PI*2); ctx.fill();
};

const drawSpatialScope = (ctx: CanvasRenderingContext2D, width: number, height: number, delayTime: number, mix: number, time: number) => {
  ctx.clearRect(0, 0, width, height);
  const cx = width / 2;
  const cy = height / 2;
  const maxR = Math.min(width, height) / 2 - 4;

  // Interference Pattern Background
  ctx.beginPath();
  for (let t = 0; t < Math.PI * 2; t += 0.05) {
      const r = maxR * mix * (0.8 + 0.2 * Math.sin(t * 12 + time * 2)); 
      const x = cx + Math.cos(t) * r;
      const y = cy + Math.sin(t) * r;
      if (t===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
  }
  ctx.closePath();

  // Fill with a gradient to simulate the interference style since we can't easily iterate pixels in a poly fill efficiently here
  const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, maxR);
  grad.addColorStop(0, 'rgba(168, 85, 247, 0)');
  grad.addColorStop(1, 'rgba(168, 85, 247, 0.2)');
  ctx.fillStyle = grad;
  ctx.fill();

  ctx.strokeStyle = `rgba(168, 85, 247, 0.6)`;
  ctx.stroke();

  // Orbiting Dots
  const count = 4;
  ctx.fillStyle = '#06b6d4';
  for(let i=0; i<count; i++) {
     const offset = (i / count) * Math.PI * 2;
     const speed = (1.1 - delayTime) * 3; 
     const angle = time * speed + offset;
     const wobble = Math.sin(time * 15 + i) * 3;
     const r = maxR * (0.3 + (mix * 0.7)) + wobble;
     const x = cx + Math.cos(angle) * r;
     const y = cy + Math.sin(angle) * r;
     ctx.beginPath(); ctx.arc(x, y, 3, 0, Math.PI * 2); ctx.fill();
  }
};

const drawOutputMeter = (ctx: CanvasRenderingContext2D, width: number, height: number, vol: number, dataArray: Uint8Array, time: number) => {
    ctx.clearRect(0, 0, width, height);
    let sum = 0; for(let i=0; i<dataArray.length; i++) sum += dataArray[i] * dataArray[i];
    const rms = Math.sqrt(sum / dataArray.length) / 255;
    const outputLevel = Math.min(1, rms * vol);

    const w = width * 0.7;
    const x = (width - w) / 2;
    const h = height * outputLevel;

    // Background interference
    for (let i = 0; i < height; i+=2) {
        // Vertical interference
        const n = i / height;
        const freq = Math.PI * 2 * 20; 
        const intensity = Math.sin(n * freq - time * 3) * 0.5 + 0.5;
        ctx.fillStyle = `rgba(30, 41, 59, ${0.3 + intensity * 0.3})`;
        ctx.fillRect(x, i, w, 1);
    }

    // Meter Fill
    const gradient = ctx.createLinearGradient(0, height, 0, 0);
    gradient.addColorStop(0, '#22c55e');
    gradient.addColorStop(0.6, '#eab308');
    gradient.addColorStop(1, '#ef4444');
    ctx.fillStyle = gradient;
    ctx.fillRect(x, height - h, w, h);
};

