// --- Color Utils ---

const hexToRgb = (colorName: string): [number, number, number] => {
  const map: Record<string, [number, number, number]> = {
    'pink': [236, 72, 153],
    'orange': [249, 115, 22],
    'blue': [59, 130, 246],
    'yellow': [234, 179, 8],
    'purple': [168, 85, 247],
    'cyan': [6, 182, 212],
    'red': [239, 68, 68]
  };
  return map[colorName] || [150, 150, 150];
};

// --- Interference Field Renderer ---

/**
 * Draws a complex, shimmering interference pattern into the current clipping region.
 * Uses "surgical" calculus to generate multi-spectral iridescence.
 */
const drawInterferenceField = (
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  time: number,
  baseColorName: string,
  type: 'filter' | 'saturator' | 'eq' | 'dynamics' | 'spatial' | 'output'
) => {
  const [bR, bG, bB] = hexToRgb(baseColorName);

  // Intelligent Tuning for each Effect Type
  // density: cycles per screen width (wave tightness)
  // speed: animation speed
  // chaos: complexity of the secondary interference wave
  // shimmer: intensity of the color shifting
  let density = 20; 
  let speed = 1.0;
  let chaos = 1.0;
  let shimmer = 30; // Amount of RGB shift

  switch (type) {
      case 'filter': // Resonance: Liquid, smooth, rolling
          density = 10;
          speed = 0.5;
          chaos = 0.5;
          shimmer = 20;
          break;
      case 'saturator': // Combustion: Fast, hot, dense, flickering
          density = 40;
          speed = 3.0;
          chaos = 1.8;
          shimmer = 50;
          break;
      case 'eq': // Spectrum: Digital, structured, harmonic
          density = 25;
          speed = 0.8;
          chaos = 0.2; // Regular
          shimmer = 30;
          break;
      case 'dynamics': // Pressure: Tight, pulsing
          density = 15;
          speed = 1.2;
          chaos = 1.0;
          shimmer = 25;
          break;
      case 'spatial': // Dimension: Ethereal, slow, deep
          density = 5;
          speed = 0.2;
          chaos = 1.5;
          shimmer = 15;
          break;
      case 'output': // Magnitude: Energetic
          density = 30;
          speed = 2.0;
          chaos = 1.0;
          shimmer = 40;
          break;
  }

  // Pre-calculate angular frequency
  // "2 * pi * canvas width" interpretation:
  // We want the wave phase to complete 'density' times over 'width'.
  // k * width = 2 * PI * density
  const k = (Math.PI * 2 * density) / width;

  // We draw 2px wide strips for performance while maintaining high resolution gradient feel
  for (let x = 0; x <= width; x += 2) {
      // Primary Wave
      const theta1 = x * k + time * speed;
      const w1 = Math.sin(theta1);

      // Secondary Wave (Interference)
      // Slight detuning of frequency and opposing direction creates interference beats
      const theta2 = x * (k * (1 + chaos * 0.1)) - time * (speed * 0.8);
      const w2 = Math.sin(theta2);

      // Combined Amplitude (-1 to 1)
      const interference = (w1 + w2) / 2;

      // Calculate Shimmer Colors
      // We shift each channel's phase slightly differently to create iridescence

      // Red Channel
      let r = bR + (interference * shimmer);
      // Green Channel (Offset phase)
      let g = bG + (Math.sin(theta1 + 2) * shimmer);
      // Blue Channel (Different frequency component)
      let b = bB + (Math.cos(theta2) * shimmer);

      // Clamp
      r = Math.min(255, Math.max(0, r));
      g = Math.min(255, Math.max(0, g));
      b = Math.min(255, Math.max(0, b));

      // Alpha Modulation
      // Darker in troughs (destructive interference), lighter in peaks
      // Base alpha 0.15, max 0.4
      const alpha = 0.15 + ((interference + 1) / 2) * 0.25;

      ctx.fillStyle = `rgba(${Math.floor(r)}, ${Math.floor(g)}, ${Math.floor(b)}, ${alpha})`;
      ctx.fillRect(x, 0, 2, height);
  }
};

// --- Draw Functions ---

const drawFilterCurve = (ctx: CanvasRenderingContext2D, width: number, height: number, freq: number, res: number, dataArray: Uint8Array, time: number) => {
  ctx.clearRect(0, 0, width, height);

  // 1. RTA Background (Behind everything)
  const barWidth = width / 32;
  ctx.fillStyle = 'rgba(236, 72, 153, 0.05)';
  for(let i=0; i<32; i++) {
    const val = dataArray[i * 2] || 0;
    const h = (val / 255) * height;
    ctx.fillRect(i * barWidth, height - h, barWidth - 1, h);
  }

  // 2. Define Filter Response Path
  ctx.beginPath();
  ctx.moveTo(0, height);

  const w0 = 2 * Math.PI * freq;
  const Q = 0.707 + (res * 1.5); 
  const minF = 20;
  const maxF = 20000;
  const logMin = Math.log(minF);
  const logRange = Math.log(maxF) - logMin;

  for (let x = 0; x <= width; x+=2) {
      const t = x / width;
      const f = Math.exp(logMin + t * logRange);
      const w = 2 * Math.PI * f;
      const ratio = w / w0;
      const r2 = ratio * ratio;
      const denom = Math.sqrt(Math.pow(1 - r2, 2) + Math.pow(ratio / Q, 2));
      const mag = 1 / (denom || 0.0001);
      const db = 20 * Math.log10(mag);

      let normY = (20 - db) / 80;
      normY = Math.max(0, Math.min(1, normY));
      const y = normY * height;

      ctx.lineTo(x, y);
  }
  ctx.lineTo(width, height);
  ctx.closePath();

  // 3. Clip Area & Draw Interference Field
  ctx.save();
  ctx.clip();
  drawInterferenceField(ctx, width, height, time, 'pink', 'filter');
  ctx.restore();

  // 4. Stroke Line
  ctx.strokeStyle = '#ec4899';
  ctx.lineWidth = 2;
  ctx.stroke();
};

const drawSaturationCurve = (ctx: CanvasRenderingContext2D, width: number, height: number, drive: number, time: number) => {
  ctx.clearRect(0, 0, width, height);
  const midY = height / 2;

  // Grid
  ctx.strokeStyle = 'rgba(255,255,255,0.1)';
  ctx.beginPath(); ctx.moveTo(0, midY); ctx.lineTo(width, midY); ctx.stroke();

  // 1. Define Area Path (Positive Lobe)
  ctx.beginPath();
  ctx.moveTo(0, midY);

  const k = drive; 
  for (let i = 0; i <= width; i+=2) {
     const xInput = (i / width) * 2 - 1; 
     let yOutput = xInput;
     if (k > 0) yOutput = ((Math.PI + k) * xInput) / (Math.PI + k * Math.abs(xInput));
     const plotY = midY - (yOutput * midY * 0.9);
     ctx.lineTo(i, plotY);
  }
  ctx.lineTo(width, midY);
  ctx.closePath();

  // 2. Clip & Fill
  ctx.save();
  ctx.clip();
  drawInterferenceField(ctx, width, height, time, 'orange', 'saturator');
  ctx.restore();

  // 3. Stroke
  ctx.strokeStyle = '#f97316';
  ctx.lineWidth = 2;
  ctx.stroke();
};

const drawEQBars = (ctx: CanvasRenderingContext2D, width: number, height: number, low: number, mid: number, high: number, dataArray: Uint8Array, time: number) => {
  ctx.clearRect(0, 0, width, height);
  const bandW = width / 3;
  const bands = [low, mid, high];
  const colors = ['blue', 'cyan', 'purple'];
  const energies = [dataArray[2]/255, dataArray[16]/255, dataArray[40]/255];

  // Background Field (Static)
  ctx.fillStyle = 'rgba(15, 23, 42, 0.5)';
  ctx.fillRect(0,0,width,height);

  bands.forEach((gain, i) => {
    const gainY = (height / 2) - (gain / 12) * (height / 2.5);
    const energyHeight = energies[i] * height;
    const startX = i * bandW + 4;
    const barWidth = bandW - 8;

    // Draw Bar Area
    ctx.save();
    ctx.beginPath();
    ctx.rect(startX, height - energyHeight, barWidth, energyHeight);
    ctx.clip();

    // Fill Bar with EQ Interference
    drawInterferenceField(ctx, width, height, time, colors[i], 'eq');
    ctx.restore();

    // Gain Puck & Line
    const lineColor = hexToRgb(colors[i]);
    const rgbStr = `rgb(${lineColor[0]},${lineColor[1]},${lineColor[2]})`;

    ctx.strokeStyle = rgbStr;
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(i*bandW + 5, gainY); ctx.lineTo((i+1)*bandW - 5, gainY); ctx.stroke();

    ctx.fillStyle = rgbStr;
    ctx.beginPath(); ctx.arc(i * bandW + bandW/2, gainY, 3, 0, Math.PI*2); ctx.fill();
  });
};

const drawDynamicsCurve = (ctx: CanvasRenderingContext2D, width: number, height: number, thresh: number, ratio: number, dataArray: Uint8Array, time: number) => {
  ctx.clearRect(0, 0, width, height);
  let sum = 0; for(let i=0; i<dataArray.length; i++) sum += dataArray[i];
  const vol = (sum / dataArray.length) / 255;
  const dbEst = 20 * Math.log10(vol + 0.0001);
  const inputX = Math.max(0, Math.min(width, ((dbEst + 60) / 60) * width));
  const threshX = ((thresh + 60) / 60) * width;

  // 1. Define Path
  ctx.beginPath();
  ctx.moveTo(0, height);

  const getCurveY = (x: number) => {
      if (x <= threshX) return height - x;
      return height - threshX - (x - threshX) * (1/ratio);
  };

  // Knee point
  const kneeY = height - threshX;
  ctx.lineTo(threshX, kneeY);

  // End point
  const endY = getCurveY(width);
  ctx.lineTo(width, endY);

  // Close shape
  ctx.lineTo(width, height);
  ctx.lineTo(0, height);
  ctx.closePath();

  // 2. Clip & Fill
  ctx.save();
  ctx.clip();
  drawInterferenceField(ctx, width, height, time, 'yellow', 'dynamics');
  ctx.restore();

  // 3. Stroke
  ctx.strokeStyle = '#eab308';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(0, height);
  ctx.lineTo(threshX, kneeY);
  ctx.lineTo(width, endY);
  ctx.stroke();

  // Ball
  let ballY = getCurveY(inputX);
  ctx.fillStyle = '#fff';
  ctx.beginPath(); ctx.arc(inputX, ballY, 4, 0, Math.PI*2); ctx.fill();
};

const drawSpatialScope = (ctx: CanvasRenderingContext2D, width: number, height: number, delayTime: number, mix: number, time: number) => {
  ctx.clearRect(0, 0, width, height);
  const cx = width / 2;
  const cy = height / 2;
  const maxR = Math.min(width, height) / 2 - 4;

  // 1. Define Circular Path
  ctx.beginPath();
  ctx.arc(cx, cy, maxR, 0, Math.PI*2);
  ctx.closePath();

  // 2. Clip & Fill Background
  ctx.save();
  ctx.clip();
  drawInterferenceField(ctx, width, height, time, 'purple', 'spatial');
  ctx.restore();

  // Inner ring representing mix
  ctx.strokeStyle = `rgba(168, 85, 247, 0.6)`;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(cx, cy, maxR * mix, 0, Math.PI*2);
  ctx.stroke();

  // Orbiting Dots
  const count = 4;
  ctx.fillStyle = '#06b6d4';
  for(let i=0; i<count; i++) {
     const offset = (i / count) * Math.PI * 2;
     const speed = (1.1 - delayTime) * 3; 
     const angle = time * speed + offset;
     const r = maxR * (0.3 + (mix * 0.7));
     const x = cx + Math.cos(angle) * r;
     const y = cy + Math.sin(angle) * r;
     ctx.beginPath(); ctx.arc(x, y, 3, 0, Math.PI * 2); ctx.fill();
  }
};

const drawOutputMeter = (ctx: CanvasRenderingContext2D, width: number, height: number, vol: number, dataArray: Uint8Array, time: number) => {
    ctx.clearRect(0, 0, width, height);
    let sum = 0; for(let i=0; i<dataArray.length; i++) sum += dataArray[i] * dataArray[i];
    const rms = Math.sqrt(sum / dataArray.length) / 255;
    const outputLevel = Math.min(1, rms * vol);

    const w = width * 0.7;
    const x = (width - w) / 2;
    const h = height * outputLevel;

    // Background Grid
    ctx.fillStyle = '#1e293b';
    ctx.fillRect(x, 0, w, height);

    // Meter Fill
    ctx.save();
    ctx.beginPath();
    ctx.rect(x, height - h, w, h);
    ctx.clip();
    drawInterferenceField(ctx, width, height, time, 'red', 'output');
    ctx.restore();

    // Grid Lines
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    for(let i=0; i<height; i+=4) {
        ctx.fillRect(x, i, w, 1);
    }
};

