interface DSPRackProps {
  dspState: DSPState;
  onChange: (newState: DSPState) => void;
}

// --- Calculus for Effect Shapes (12 Panels) ---

const calculateFilterShape = (freq: number, res: number) => {
    // 12 bars log scale from 20Hz to 20kHz
    const bars = [];
    const minLog = Math.log(20);
    const maxLog = Math.log(20000);
    const range = maxLog - minLog;

    const w0 = 2 * Math.PI * freq;
    const Q = 0.707 + (res * 1.5);

    for(let i=0; i<12; i++) {
        const f = Math.exp(minLog + (i/11) * range);
        // Biquad LP Magnitude
        const w = 2 * Math.PI * f;
        // Analog approx magnitude response
        const ratio = w / w0;
        const denom = Math.sqrt(Math.pow(1 - ratio*ratio, 2) + Math.pow(ratio/Q, 2));
        const mag = 1 / (denom || 0.001);

        // Normalize for visual (0 to 1) - assume max gain with Res can be high
        let h = Math.min(1, mag * 0.8);
        bars.push(h);
    }
    return bars;
};

const calculateSaturatorShape = (drive: number) => {
    // Transfer function shape: Input x (-1 to 1) mapped to 12 bars
    const bars = [];
    const k = drive;
    for(let i=0; i<12; i++) {
        const x = (i / 11) * 2 - 1; // -1 to 1
        let y = x;
        if (k > 0) {
            y = ((Math.PI + k) * x) / (Math.PI + k * Math.abs(x));
        }
        // Map output y (-1 to 1) to height (0 to 1). 
        bars.push((y + 1) / 2);
    }
    return bars;
};

const calculateEQShape = (low: number, mid: number, high: number) => {
    // 3 Band EQ curve approximation
    const bars = [];
    for(let i=0; i<12; i++) {
        // Simple interpolation of gains
        let gain = 0;
        if (i < 4) gain = low;
        else if (i < 8) gain = mid;
        else gain = high;

        // Smooth transitions roughly
        if (i===3 || i===4) gain = (low + mid)/2;
        if (i===7 || i===8) gain = (mid + high)/2;

        // Map +/- 12dB to 0..1
        bars.push((gain + 12) / 24);
    }
    return bars;
};

const calculateDynamicsShape = (thresh: number, ratio: number) => {
    // Compression curve
    const bars = [];
    for(let i=0; i<12; i++) {
        const inDB = -60 + (i/11) * 60; // -60 to 0
        let outDB = inDB;
        if (inDB > thresh) {
            outDB = thresh + (inDB - thresh) / ratio;
        }
        bars.push((outDB + 60) / 60);
    }
    return bars;
};

const calculateSpatialShape = (time: number, feedback: number, mix: number) => {
    // Visualizing delay taps / echoes
    const bars = new Array(12).fill(0);
    // Initial signal
    bars[0] = 1.0; 

    // Tap spacing based on time
    const delayStep = Math.max(1, Math.round(time * 5)); // 1 to 5 bars apart

    for (let i = 0; i < 12; i+=delayStep) {
       const decay = Math.pow(feedback, i/delayStep);
       if(i < 12) bars[i] = decay;
    }

    // Mix scales the whole thing
    return bars.map(b => b * (0.3 + mix * 0.7));
};

const calculateOutputShape = (vol: number, dataArray: Uint8Array) => {
    // VU Meter style - 12 bars peak
    if (!dataArray) return new Array(12).fill(0);

    let sum = 0;
    for(let i=0; i<dataArray.length; i++) sum += dataArray[i] * dataArray[i];
    const rms = Math.sqrt(sum / dataArray.length) / 255;

    const level = Math.min(1, rms * vol * 2); // *2 for visual boost

    const bars = [];
    for(let i=0; i<12; i++) {
        const threshold = (i+1)/12;
        bars.push(level >= threshold ? 1 : 0);
    }
    return bars;
};

// --- LED Panel Renderer ---

const drawLedPanels = (
    ctx: CanvasRenderingContext2D, 
    width: number, 
    height: number, 
    bars: number[], 
    time: number
) => {
    ctx.clearRect(0, 0, width, height);

    const gap = 2;
    const barW = (width - (11 * gap)) / 12;
    const baseColor = '#3b82f6'; // Blue-500
    const glowColor = '#60a5fa'; // Blue-400

    bars.forEach((val, i) => {
        const h = Math.max(2, val * height);
        const x = i * (barW + gap);
        const y = height - h;

        // Shimmer effect
        const shimmer = Math.sin(time * 5 + i) * 0.2 + 0.8; 

        ctx.fillStyle = baseColor;
        ctx.shadowColor = glowColor;
        ctx.shadowBlur = 8 * shimmer;

        // Fill Rect
        ctx.globalAlpha = 0.8 * shimmer;
        ctx.fillRect(x, y, barW, h);

        // "LED" core (brighter center)
        ctx.fillStyle = '#fff';
        ctx.globalAlpha = 0.3 * shimmer;
        ctx.fillRect(x + 2, y, barW - 4, h);

        ctx.globalAlpha = 1.0;
        ctx.shadowBlur = 0;
    });
};

// --- Rack Module Component ---

const RackModule: React.FC<{
  title: string;
  type: 'filter' | 'saturator' | 'eq' | 'dynamics' | 'spatial' | 'output';
  color: string;
  dspState: DSPState;
  children: React.ReactNode;
}> = ({ title, type, color, dspState, children }) => {

  const canvasRef = useRef<HTMLCanvasElement>(null);

  // Color map just for the title text highlight
  const glowMap: Record<string, string> = {
    pink: 'text-pink-500',
    orange: 'text-orange-500',
    blue: 'text-blue-500',
    yellow: 'text-yellow-500',
    purple: 'text-purple-500',
    cyan: 'text-cyan-500',
    red: 'text-red-500',
  };
  const titleColor = glowMap[color];

  useEffect(() => {
     const canvas = canvasRef.current;
     if(!canvas) return;
     const ctx = canvas.getContext('2d');
     if(!ctx) return;

     let frameId: number;
     const dataArray = new Uint8Array(audioEngine.analyser.frequencyBinCount);

     const render = () => {
         frameId = requestAnimationFrame(render);
         const time = performance.now() / 1000;
         audioEngine.analyser.getByteFrequencyData(dataArray);

         const w = canvas.width;
         const h = canvas.height;
         let bars: number[] = [];

         if (type === 'filter') {
            bars = calculateFilterShape(dspState.masterFilterFreq, dspState.masterFilterRes);
            // Modulate with RTA for fun
            const rta = dataArray[10] / 255;
            bars = bars.map(b => b * (0.8 + rta * 0.2)); 
         } else if (type === 'saturator') {
            bars = calculateSaturatorShape(dspState.masterSaturation);
         } else if (type === 'eq') {
            bars = calculateEQShape(dspState.masterEqLow, dspState.masterEqMid, dspState.masterEqHigh);
         } else if (type === 'dynamics') {
            bars = calculateDynamicsShape(dspState.masterCompressorThreshold, dspState.masterCompressorRatio);
            // Gain reduction meter effect
            if (audioEngine.ctx.currentTime % 0.5 < 0.1) bars[11] = 0; // Fake GR blip
         } else if (type === 'spatial') {
            bars = calculateSpatialShape(dspState.delayTime, dspState.delayFeedback, dspState.reverbMix);
         } else if (type === 'output') {
            bars = calculateOutputShape(dspState.masterVolume, dataArray);
         }

         drawLedPanels(ctx, w, h, bars, time);
     };
     render();
     return () => cancelAnimationFrame(frameId);
  }, [type, dspState]);

  return (
    <div className="flex flex-col h-full bg-[#0b1120] border-r border-slate-800 relative group min-w-[160px]">

      {/* Header with LED Visualizer */}
      <div className="h-24 bg-black relative border-b border-slate-800 p-2 flex flex-col items-center justify-end">
        {/* LED Screen Container */}
        <div className="w-full h-full bg-[#050a15] rounded border border-slate-800 relative overflow-hidden shadow-[inset_0_0_10px_#000]">
             {/* Grid Overlay */}
             <div className="absolute inset-0 z-10 opacity-20 pointer-events-none" 
                  style={{ backgroundImage: 'linear-gradient(rgba(255,255,255,0.1) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,0.1) 1px, transparent 1px)', backgroundSize: '10px 10px' }}></div>

             <canvas ref={canvasRef} width={140} height={60} className="w-full h-full" />
        </div>

        {/* Title */}
        <div className={`absolute top-2 left-2 text-[8px] font-black tracking-widest uppercase ${titleColor} bg-black/80 px-1 rounded`}>{title}</div>
      </div>

      {/* Controls Area */}
      <div className="flex-1 flex items-center justify-center space-x-3 px-3 py-2 bg-gradient-to-b from-[#111827] to-[#020617] relative">
         {children}
      </div>

      {/* Industrial Screws */}
      <div className="absolute top-1 right-1 w-1 h-1 rounded-full bg-slate-700"></div>
      <div className="absolute top-1 left-1 w-1 h-1 rounded-full bg-slate-700"></div>
      <div className="absolute bottom-1 right-1 w-1 h-1 rounded-full bg-slate-700"></div>
      <div className="absolute bottom-1 left-1 w-1 h-1 rounded-full bg-slate-700"></div>
    </div>
  );
};

