import React, { useEffect, useRef } from 'react';

export const BackgroundInterference: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let w = canvas.width = window.innerWidth;
    let h = canvas.height = window.innerHeight;
    let time = 0;

    const resize = () => {
      w = canvas.width = window.innerWidth;
      h = canvas.height = window.innerHeight;
    };
    window.addEventListener('resize', resize);

    const draw = () => {
      time += 0.005;

      // Clear with very slight transparency for trails? No, strict redraw for interference.
      ctx.fillStyle = '#020617'; // Base Slate-950
      ctx.fillRect(0, 0, w, h);

      // Create Gradient
      const grad = ctx.createLinearGradient(0, 0, w, h);
      grad.addColorStop(0, 'rgba(15, 23, 42, 0)');
      grad.addColorStop(0.5, 'rgba(56, 189, 248, 0.05)'); // Cyan hint
      grad.addColorStop(1, 'rgba(168, 85, 247, 0.05)'); // Purple hint
      ctx.fillStyle = grad;
      ctx.fillRect(0,0,w,h);

      ctx.lineWidth = 2;

      // Interference Pattern: Two overlapping sine wave fields
      // Optimization: Draw lines with varying opacity based on sine calculation

      const waveCount = 40;
      const spacing = h / waveCount;

      for (let i = 0; i < waveCount + 5; i++) {
        const yBase = i * spacing;

        ctx.beginPath();
        for (let x = 0; x <= w; x += 20) {
            // Wave 1: Slow, broad
            const y1 = Math.sin(x * 0.01 + time + i * 0.2) * 20;
            // Wave 2: Fast, interference
            const y2 = Math.cos(x * 0.03 - time * 1.5 + i * 0.1) * 15;

            const y = yBase + y1 + y2;
            if (x === 0) ctx.moveTo(x, y);
            else ctx.lineTo(x, y);
        }

        // Dynamic color based on index
        const alpha = 0.03 + (Math.sin(time * 2 + i * 0.5) + 1) * 0.02;
        const blue = 200 + Math.sin(i)*50;
        ctx.strokeStyle = `rgba(100, ${blue}, 255, ${alpha})`;
        ctx.stroke();
      }

      // Secondary Interference Grid (Moiré)
      ctx.beginPath();
      const cx = w/2;
      const cy = h/2;
      for(let r=0; r<Math.max(w,h); r+=40) {
          const distortion = Math.sin(r * 0.05 - time) * 10;
          ctx.moveTo(cx + r + distortion, cy);
          ctx.arc(cx, cy, r + distortion, 0, Math.PI * 2);
      }
      ctx.strokeStyle = `rgba(255, 255, 255, 0.02)`;
      ctx.stroke();

      requestAnimationFrame(draw);
    };

    const animId = requestAnimationFrame(draw);
    return () => {
      window.removeEventListener('resize', resize);
      cancelAnimationFrame(animId);
    };
  }, []);

  return (
    <canvas 
      ref={canvasRef} 
      className="fixed inset-0 pointer-events-none z-0"
    />
  );
};

