import React, { useEffect, useRef } from 'react';

export const BackgroundInterference: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let w = canvas.width = window.innerWidth;
    let h = canvas.height = window.innerHeight;
    let time = 0;

    const resize = () => {
      w = canvas.width = window.innerWidth;
      h = canvas.height = window.innerHeight;
    };
    window.addEventListener('resize', resize);

    const draw = () => {
      time += 0.005;

      // Strict Black Background
      ctx.fillStyle = '#000000';
      ctx.fillRect(0, 0, w, h);

      ctx.lineWidth = 1;

      // Interference Pattern: White and Blue lines on Black
      const waveCount = 45;
      const spacing = h / waveCount;

      for (let i = 0; i < waveCount + 5; i++) {
        const yBase = i * spacing;

        ctx.beginPath();
        for (let x = 0; x <= w; x += 30) {
            // Wave 1: Broad movement
            const y1 = Math.sin(x * 0.005 + time + i * 0.1) * 30;
            // Wave 2: High frequency jitter (interference)
            const y2 = Math.cos(x * 0.05 - time * 2.0 + i * 0.2) * 5;

            const y = yBase + y1 + y2;
            if (x === 0) ctx.moveTo(x, y);
            else ctx.lineTo(x, y);
        }

        // Color Palette: White and Blue-500 (#3b82f6)
        const isBlue = i % 3 === 0;
        const alpha = 0.05 + (Math.sin(time * 3 + i) + 1) * 0.03;

        if (isBlue) {
            ctx.strokeStyle = `rgba(59, 130, 246, ${alpha * 1.5})`; // Blue
        } else {
            ctx.strokeStyle = `rgba(255, 255, 255, ${alpha})`; // White
        }
        ctx.stroke();
      }

      // Moiré overlay - Radial
      ctx.beginPath();
      const cx = w/2;
      const cy = h/2;
      const maxR = Math.sqrt(w*w + h*h)/2;

      for(let r=0; r<maxR; r+=50) {
          const distort = Math.sin(r * 0.02 - time) * 20;
          ctx.moveTo(cx + r + distort, cy);
          ctx.arc(cx, cy, r + distort, 0, Math.PI * 2);
      }
      ctx.strokeStyle = `rgba(255, 255, 255, 0.03)`;
      ctx.stroke();

      // Scanlines effect
      ctx.fillStyle = 'rgba(0, 0, 0, 0.3)';
      for(let y=0; y<h; y+=4) {
          ctx.fillRect(0, y, w, 1);
      }

      requestAnimationFrame(draw);
    };

    const animId = requestAnimationFrame(draw);
    return () => {
      window.removeEventListener('resize', resize);
      cancelAnimationFrame(animId);
    };
  }, []);

  return (
    <canvas 
      ref={canvasRef} 
      className="fixed inset-0 pointer-events-none z-0"
    />
  );
};

import React, { useState, useRef, useEffect } from 'react';

interface KnobProps {
  value: number;
  min: number;
  max: number;
  onChange: (val: number) => void;
  label: string;
  color?: string;
  size?: number;
}

export const Knob: React.FC<KnobProps> = ({ value, min, max, onChange, label, color = 'cyan', size = 40 }) => {
  const [isDragging, setIsDragging] = useState(false);
  const startY = useRef(0);
  const startVal = useRef(0);

  const handleStart = (clientY: number) => {
    setIsDragging(true);
    startY.current = clientY;
    startVal.current = value;
  };

  const handleMove = (clientY: number) => {
    if (!isDragging) return;
    const delta = startY.current - clientY;
    const range = max - min;
    const change = (delta / 150) * range; // Sensitivity
    let newVal = startVal.current + change;
    newVal = Math.max(min, Math.min(max, newVal));
    onChange(newVal);
  };

  const handleEnd = () => {
    setIsDragging(false);
  };

  useEffect(() => {
    if (isDragging) {
      const mouseMove = (e: MouseEvent) => { e.preventDefault(); handleMove(e.clientY); };
      const touchMove = (e: TouchEvent) => { e.preventDefault(); handleMove(e.touches[0].clientY); };
      const end = () => handleEnd();

      document.addEventListener('mousemove', mouseMove, { passive: false });
      document.addEventListener('touchmove', touchMove, { passive: false });
      document.addEventListener('mouseup', end);
      document.addEventListener('touchend', end);

      return () => {
        document.removeEventListener('mousemove', mouseMove);
        document.removeEventListener('touchmove', touchMove);
        document.removeEventListener('mouseup', end);
        document.removeEventListener('touchend', end);
      };
    }
  }, [isDragging]);

  const percentage = (value - min) / (max - min);
  // -135 to +135 degrees
  const startAngle = -135;
  const endAngle = -135 + (percentage * 270);

  // SVG Calculation
  const radius = size / 2;
  const center = size / 2 + 5; // padding
  const strokeWidth = 3;
  const r = radius - strokeWidth;

  // Helper to get coordinates
  const getCoords = (angleInDegrees: number) => {
    const angleInRadians = (angleInDegrees - 90) * Math.PI / 180.0;
    return {
      x: center + (r * Math.cos(angleInRadians)),
      y: center + (r * Math.sin(angleInRadians))
    };
  };

  const start = getCoords(-135);
  const end = getCoords(135);
  const current = getCoords(endAngle);
  const largeArcFlag = endAngle - startAngle <= 180 ? "0" : "1";

  // Color mapping (Updated to match Blue/White theme preference)
  const colorMap: Record<string, string> = {
    cyan: '#06b6d4',
    blue: '#3b82f6',
    purple: '#a855f7',
    green: '#22c55e',
    yellow: '#eab308',
    orange: '#f97316',
    red: '#ef4444',
    pink: '#ec4899',
    white: '#ffffff'
  };
  const accentColor = colorMap[color] || colorMap['cyan'];

  return (
    <div 
      className="flex flex-col items-center justify-center select-none touch-none group relative overflow-hidden rounded-full p-1"
      onMouseDown={(e) => handleStart(e.clientY)}
      onTouchStart={(e) => handleStart(e.touches[0].clientY)}
      style={{ width: size + 10 }}
    >
      {/* Light Interference Overlay */}
      <div className="absolute inset-0 pointer-events-none opacity-20 z-0" 
           style={{ backgroundImage: 'repeating-linear-gradient(45deg, transparent, transparent 2px, rgba(255,255,255,0.1) 3px)' }}></div>

      <div className="relative z-10">
          <svg width={size + 10} height={size + 10}>
             {/* Background Track */}
             <path 
                d={`M ${start.x} ${start.y} A ${r} ${r} 0 1 1 ${end.x} ${end.y}`}
                fill="none"
                stroke="#1e293b"
                strokeWidth={strokeWidth}
                strokeLinecap="round"
             />

             {/* Glowing Value Arc */}
             <path 
                d={`M ${start.x} ${start.y} A ${r} ${r} 0 ${largeArcFlag} 1 ${current.x} ${current.y}`}
                fill="none"
                stroke={accentColor}
                strokeWidth={strokeWidth + 1}
                strokeLinecap="round"
                filter={`drop-shadow(0 0 3px ${accentColor})`}
                style={{ opacity: 0.8 + (percentage * 0.2) }}
             />
          </svg>

          {/* Center Knob Cap (Dark Glass) */}
          <div 
            className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 rounded-full bg-black border border-slate-700 shadow-inner flex items-center justify-center transition-all group-active:scale-95"
            style={{ width: size * 0.7, height: size * 0.7 }}
          >
             <div className="w-1 h-1 rounded-full bg-white opacity-50"></div>
          </div>
      </div>

      <span 
        className="relative z-10 text-[9px] uppercase font-bold text-slate-500 mt-1 tracking-tighter"
        style={{ textShadow: isDragging ? `0 0 5px ${accentColor}` : 'none', color: isDragging ? accentColor : undefined }}
      >
        {label}
      </span>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';

interface SliderProps {
  value: number;
  min: number;
  max: number;
  onChange: (val: number) => void;
  label: string;
  color?: string;
  height?: number;
}

export const Slider: React.FC<SliderProps> = ({ value, min, max, onChange, label, color = 'cyan', height = 100 }) => {
  const [isDragging, setIsDragging] = useState(false);
  const startY = useRef(0);
  const startVal = useRef(0);
  const sliderRef = useRef<HTMLDivElement>(null);

  const handleStart = (clientY: number) => {
    setIsDragging(true);
    startY.current = clientY;
    startVal.current = value;
  };

  const handleMove = (clientY: number) => {
    if (!isDragging) return;
    const delta = startY.current - clientY; // Up is positive
    const range = max - min;
    const pxRange = height * 0.8; 
    const change = (delta / pxRange) * range; 
    let newVal = startVal.current + change;
    newVal = Math.max(min, Math.min(max, newVal));
    onChange(newVal);
  };

  const handleEnd = () => {
    setIsDragging(false);
  };

  useEffect(() => {
    if (isDragging) {
      const mouseMove = (e: MouseEvent) => { e.preventDefault(); handleMove(e.clientY); };
      const touchMove = (e: TouchEvent) => { e.preventDefault(); handleMove(e.touches[0].clientY); };
      const end = () => handleEnd();

      document.addEventListener('mousemove', mouseMove, { passive: false });
      document.addEventListener('touchmove', touchMove, { passive: false });
      document.addEventListener('mouseup', end);
      document.addEventListener('touchend', end);

      return () => {
        document.removeEventListener('mousemove', mouseMove);
        document.removeEventListener('touchmove', touchMove);
        document.removeEventListener('mouseup', end);
        document.removeEventListener('touchend', end);
      };
    }
  }, [isDragging]);

  const percentage = Math.max(0, Math.min(1, (value - min) / (max - min)));

  const colorMap: Record<string, string> = {
    cyan: '#06b6d4',
    blue: '#3b82f6',
    purple: '#a855f7',
    green: '#22c55e',
    yellow: '#eab308',
    orange: '#f97316',
    red: '#ef4444',
    pink: '#ec4899',
    white: '#ffffff'
  };
  const accentColor = colorMap[color] || colorMap['cyan'];

  return (
    <div className="flex flex-col items-center justify-center space-y-2 select-none touch-none group">
      <div 
        ref={sliderRef}
        className="relative w-8 rounded-full bg-black border border-slate-700 shadow-inner flex justify-center overflow-hidden"
        style={{ height: height }}
        onMouseDown={(e) => handleStart(e.clientY)}
        onTouchStart={(e) => handleStart(e.touches[0].clientY)}
      >
        {/* Light Interference Overlay */}
        <div className="absolute inset-0 pointer-events-none opacity-20 z-0" 
             style={{ backgroundImage: 'repeating-linear-gradient(0deg, transparent, transparent 2px, rgba(255,255,255,0.1) 3px)' }}></div>

        {/* LED Background Track (dim) */}
        <div className="absolute bottom-0 w-1.5 bg-slate-800 h-full rounded-full opacity-50 z-0"></div>

        {/* Active LED Bar (Glowing) */}
        <div 
            className="absolute bottom-0 w-2 rounded-full transition-all duration-75 z-10"
            style={{ 
                height: `${percentage * 100}%`, 
                backgroundColor: accentColor,
                boxShadow: `0 0 10px ${accentColor}, 0 0 20px ${accentColor}`
            }}
        ></div>

        {/* Thumb Handle (Glassy LED) */}
        <div 
            className="absolute w-6 h-4 bg-black rounded border border-slate-500 shadow-md flex items-center justify-center transition-all duration-75 group-hover:border-white/50 z-20"
            style={{ bottom: `calc(${percentage * 100}% - 8px)` }}
        >
             <div className="w-full h-[1px] bg-white/50"></div>
        </div>

      </div>

      <span 
        className="text-[9px] uppercase font-bold text-slate-500 tracking-tighter"
        style={{ textShadow: isDragging ? `0 0 5px ${accentColor}` : 'none', color: isDragging ? accentColor : undefined }}
      >
        {label}
      </span>
    </div>
  );
};

