               {/* Screw Heads (Visual) */}
               <div className="absolute top-1 left-1 w-1.5 h-1.5 rounded-full bg-slate-800 shadow-[inset_1px_1px_2px_rgba(0,0,0,0.8)] border border-slate-700"></div>
               <div className="absolute top-1 right-1 w-1.5 h-1.5 rounded-full bg-slate-800 shadow-[inset_1px_1px_2px_rgba(0,0,0,0.8)] border border-slate-700"></div>

               <div className="py-3 px-2 flex flex-col items-center space-y-3 relative z-10">

                   {/* MODULE: DEEP DISTORTION (SPLIT CONTROLS) */}
                   <div className="w-full bg-black/60 rounded border border-white/10 p-2 shadow-inner">
                        <div className="text-[8px] font-black text-slate-500 tracking-widest text-center mb-2 border-b border-white/10 pb-1">DEEP DISTORTION</div>
                        <div className="flex justify-between items-center px-1">
                             <Knob value={track.fx.saturation} min={0} max={100} label="COARSE" color="orange" size={36} onChange={(v) => updateFX('saturation', v)} />
                             <Knob value={track.fx.saturationFine || 0} min={0} max={10} label="FINE" color="yellow" size={28} onChange={(v) => updateFX('saturationFine', v)} />
                             <Knob value={track.fx.distortionTone || 20000} min={1000} max={20000} label="TONE" color="blue" size={28} onChange={(v) => updateFX('distortionTone', v)} />
                        </div>
                   </div>

                   {/* MODULE: CABINET EMULATOR */}
                   <div className="w-full bg-black/60 rounded border border-white/10 p-2 shadow-inner">
                        <div className="text-[8px] font-black text-slate-500 tracking-widest text-center mb-2 border-b border-white/10 pb-1">CABINET</div>
                        <div className="flex justify-between items-center px-2">
                             <button 
                                onClick={() => updateFX('cabinetOn', !track.fx.cabinetOn)}
                                className={`w-10 h-10 rounded border-2 flex items-center justify-center transition-all ${track.fx.cabinetOn ? 'border-green-500 bg-green-500/20 text-green-400 shadow-[0_0_10px_rgba(34,197,94,0.3)]' : 'border-slate-800 text-slate-600'}`}
                             >
                                <span className="text-[9px] font-black">{track.fx.cabinetOn ? 'ON' : 'OFF'}</span>
                             </button>
                             <Knob value={track.fx.cabinetTone} min={0} max={1} label="AIR" color="cyan" size={36} onChange={(v) => updateFX('cabinetTone', v)} />
