                        <div className="flex justify-between px-1 space-x-1">
                            <Slider value={track.fx.eqHigh} min={-12} max={12} label="HI" color="cyan" height={60} onChange={(v) => updateFX('eqHigh', v)} />
                            <Slider value={track.fx.eqMid} min={-12} max={12} label="MID" color="cyan" height={60} onChange={(v) => updateFX('eqMid', v)} />
                            <Slider value={track.fx.eqLow} min={-12} max={12} label="LO" color="cyan" height={60} onChange={(v) => updateFX('eqLow', v)} />
