                                 <span className="text-[7px] text-slate-500 font-bold mt-1">REVERB</span>
                             </div>
                             <div className="flex flex-col items-center">
                                 <Knob value={track.fx.sendDelay} min={0} max={1} label="SEND" color="blue" size={32} onChange={(v) => updateFX('sendDelay', v)} />
