export const Slider: React.FC<SliderProps> = ({ value, min, max, onChange, label, color = 'cyan', height = 100 }) => {
  const [isDragging, setIsDragging] = useState(false);
  const startY = useRef(0);
  const startVal = useRef(0);
  const sliderRef = useRef<HTMLDivElement>(null);

  const handleStart = (clientY: number) => {
    setIsDragging(true);
    startY.current = clientY;
    startVal.current = value;
  };

  const handleMove = (clientY: number) => {
    if (!isDragging) return;
    const delta = startY.current - clientY;
    const range = max - min;
    const pxRange = height * 0.8; 
    const change = (delta / pxRange) * range; 
    let newVal = startVal.current + change;
    newVal = Math.max(min, Math.min(max, newVal));
    onChange(newVal);
  };

  const handleEnd = () => {
    setIsDragging(false);
  };

  useEffect(() => {
    if (isDragging) {
      const mouseMove = (e: MouseEvent) => { e.preventDefault(); handleMove(e.clientY); };
      const touchMove = (e: TouchEvent) => { e.preventDefault(); handleMove(e.touches[0].clientY); };
      const end = () => handleEnd();

      document.addEventListener('mousemove', mouseMove, { passive: false });
      document.addEventListener('touchmove', touchMove, { passive: false });
      document.addEventListener('mouseup', end);
      document.addEventListener('touchend', end);

      return () => {
        document.removeEventListener('mousemove', mouseMove);
        document.removeEventListener('touchmove', touchMove);
        document.removeEventListener('mouseup', end);
        document.removeEventListener('touchend', end);
      };
    }
  }, [isDragging]);

  const percentage = Math.max(0, Math.min(1, (value - min) / (max - min)));

  const colorMap: Record<string, string> = {
    cyan: '#06b6d4',
    blue: '#3b82f6',
    purple: '#a855f7',
    green: '#22c55e',
    yellow: '#eab308',
    orange: '#f97316',
    red: '#ef4444',
    pink: '#ec4899',
    white: '#ffffff'
  };
  const accentColor = colorMap[color] || colorMap['cyan'];

  return (
    <div className="flex flex-col items-center justify-center space-y-2 select-none touch-none group">
      <div 
        ref={sliderRef}
        className="relative w-8 rounded-full bg-black border border-slate-700 shadow-inner flex justify-center overflow-hidden"
        style={{ height: height }}
        onMouseDown={(e) => handleStart(e.clientY)}
        onTouchStart={(e) => handleStart(e.touches[0].clientY)}
      >
        {/* Background Track with Diffraction Grating Pattern */}
        <div className="absolute inset-0 z-0 opacity-30" 
             style={{ 
                 backgroundImage: 'repeating-linear-gradient(90deg, transparent, transparent 2px, rgba(255,255,255,0.05) 3px, transparent 4px)',
                 backgroundSize: '100% 100%' 
             }}>
        </div>

        {/* Guide Line */}
        <div className="absolute bottom-0 w-[1px] bg-slate-800 h-full opacity-50 z-0"></div>

        {/* Active Fill (Light Column) */}
        <div 
            className="absolute bottom-0 w-full z-10 transition-all duration-75 mix-blend-screen"
            style={{ 
                height: `${percentage * 100}%`, 
                backgroundColor: accentColor,
                opacity: 0.3,
                boxShadow: `0 0 15px ${accentColor}`
            }}
        ></div>

        {/* Thumb Handle (Prism) */}
        <div 
            className="absolute w-6 h-3 bg-black rounded-sm border border-slate-600 shadow-md flex items-center justify-center transition-all duration-75 z-20 overflow-hidden"
            style={{ bottom: `calc(${percentage * 100}% - 6px)` }}
        >
             {/* Thumb Texture: Horizontal Micro-gratings */}
             <div className="absolute inset-0 opacity-50"
                  style={{
                      backgroundImage: `repeating-linear-gradient(0deg, transparent, transparent 1px, rgba(255,255,255,0.3) 2px)`
                  }}
             ></div>
             <div className="w-4 h-[1px] bg-white shadow-[0_0_2px_white] relative z-10"></div>
        </div>

      </div>

      <span 
        className="text-[9px] uppercase font-bold text-slate-500 tracking-tighter"
        style={{ textShadow: isDragging ? `0 0 5px ${accentColor}` : 'none', color: isDragging ? accentColor : undefined }}
      >
        {label}
      </span>
    </div>
  );
};

