// --- Numerical Analysis for Visualizers ---

const calculateFilterMagnitude = (freq: number, res: number) => {
    // Exact Biquad Lowpass Magnitude Calculation (Digital)
    const fs = 44100;
    const phi = Math.pow(Math.sin(Math.PI * freq / (2 * fs)), 2);
    const bars = [];
    const steps = 12;
    // Approximating the analog response curve for visuals
    const w_c = 2 * Math.PI * freq / fs;
    const alpha = Math.sin(w_c) / (2 * (0.707 + res));

    // Simplification for visual representation of a Bode Plot
    for(let i=0; i<steps; i++) {
        // Logarithmic scale 20Hz to 20kHz
        const f = 20 * Math.pow(1000, i / (steps-1));
        const w = 2 * Math.PI * f / fs;
        // Simple 2nd order LPF transfer function mag
        const ratio = f / freq;
        const mag = 1 / Math.sqrt(Math.pow(1 - ratio*ratio, 2) + Math.pow(ratio/(0.707 + res), 2));
        bars.push(Math.min(1.2, mag)); 
    }
    return bars;
};

const calculateSaturatorShape = (drive: number) => {
    const bars = [];
    const k = drive;
    for(let i=0; i<12; i++) {
        const x = (i / 11) * 2 - 1; 
        let y = x;
        if (k > 0) y = ((Math.PI + k) * x) / (Math.PI + k * Math.abs(x));
        bars.push((y + 1) / 2);
    }
    return bars;
};

const calculateHarmonicsShape = (drive: number) => {
    // Exciter visual: Shows addition of higher harmonics
    const bars = new Array(12).fill(0);
    // Fundamental is solid
    bars[0] = 0.8;
    // Harmonics depend on drive
    for(let i=1; i<12; i++) {
       if (i % 2 !== 0) { // Odd harmonics often stronger in simple saturation
           bars[i] = (drive / 100) * (1 / i) * 2; 
       } else {
           bars[i] = (drive / 100) * (1 / (i*2));
       }
    }
    return bars;
};

const calculateEQShape = (low: number, mid: number, high: number) => {
    const bars = [];
    for(let i=0; i<12; i++) {
        let gain = 0;
        if (i < 4) gain = low;
        else if (i < 8) gain = mid;
        else gain = high;
        // Smooth transitions roughly
        if (i===3 || i===4) gain = (low + mid)/2;
        if (i===7 || i===8) gain = (mid + high)/2;
        bars.push((gain + 12) / 24);
    }
    return bars;
};

const calculateDynamicsShape = (thresh: number, ratio: number) => {
    const bars = [];
    for(let i=0; i<12; i++) {
        const inDB = -60 + (i/11) * 60; 
        let outDB = inDB;
        if (inDB > thresh) outDB = thresh + (inDB - thresh) / ratio;
        bars.push((outDB + 60) / 60);
    }
    return bars;
};

const calculateSpatialShape = (time: number, feedback: number, mix: number) => {
    const bars = new Array(12).fill(0);
    bars[0] = 1.0; 
    const delayStep = Math.max(1, Math.round(time * 5)); 
    for (let i = 0; i < 12; i+=delayStep) {
       const decay = Math.pow(feedback, i/delayStep);
       if(i < 12) bars[i] = decay;
    }
    return bars.map(b => b * (0.3 + mix * 0.7));
};

const calculateOutputShape = (vol: number, dataArray: Uint8Array) => {
    if (!dataArray) return new Array(12).fill(0);
    let sum = 0;
    for(let i=0; i<dataArray.length; i++) sum += dataArray[i] * dataArray[i];
    const rms = Math.sqrt(sum / dataArray.length) / 255;
    const level = Math.min(1, rms * vol * 2.5);
    // Fill all bars up to level
    return Array(12).fill(0).map((_, i) => (level > i/12 ? 1 : 0));
};

// --- Discrete Pixel Renderer (VFD Style) ---

const drawPixelLeds = (
    ctx: CanvasRenderingContext2D, 
    width: number, 
    height: number, 
    bars: number[], 
    colorHex: string
) => {
    ctx.clearRect(0, 0, width, height);

    // Config
    const numCols = 12;
    const numRows = 8; // Vertical resolution

    const gap = 2;
    const colWidth = (width - ((numCols - 1) * gap)) / numCols;
    const rowHeight = (height - ((numRows - 1) * gap)) / numRows;

    // Convert hex to rgb for opacity handling
    // Simple lookup or parsing (assuming standard tailwind colors passed)
    // We will assume bright accent color

    for (let c = 0; c < numCols; c++) {
        const value = bars[c] || 0; // Normalized 0-1

        // Determine how many rows are active in this column
        // We can treat value as the "height" of the column
        const activeHeight = value * numRows; // Float, e.g. 4.5 rows active

        for (let r = 0; r < numRows; r++) {
             // Invert Y (draw from bottom up)
             const rowIndex = (numRows - 1) - r;
             const y = rowIndex * (rowHeight + gap);
             const x = c * (colWidth + gap);

             // Check if this pixel is active
             let intensity = 0;
             if (r < Math.floor(activeHeight)) {
                 intensity = 1.0; // Fully on
             } else if (r < activeHeight) {
                 intensity = activeHeight - r; // Fractional (anti-aliased edge)
             } else {
                 intensity = 0.05; // Ghosted / Off state
             }

             // Draw Pixel
             ctx.fillStyle = colorHex;
             ctx.globalAlpha = intensity;

             // Core
             ctx.fillRect(x, y, colWidth, rowHeight);

             // Inner bright spot for "LED" look
             if (intensity > 0.5) {
                ctx.fillStyle = '#ffffff';
                ctx.globalAlpha = 0.4;
                ctx.fillRect(x + 2, y + 2, colWidth - 4, rowHeight - 4);
             }
        }
    }
    // Reset
    ctx.globalAlpha = 1.0;
};

