         } else if (type === 'output') {
            bars = calculateOutputShape(dspState.masterVolume, dataArray);
         }

         drawPixelLeds(ctx, w, h, bars, hexColor);
     };
     render();
     return () => cancelAnimationFrame(frameId);
  }, [type, dspState, hexColor]);

  return (
