        </div>

        {/* Title Tag */}
        <div className="absolute top-2 left-2 px-1.5 py-0.5 bg-black/90 rounded border border-white/10 z-10">
            <span className="text-[8px] font-black tracking-widest uppercase" style={{ color: hexColor }}>{title}</span>
        </div>
      </div>

      {/* Controls Area */}
      <div className="flex-1 flex items-center justify-center space-x-3 px-3 py-2 bg-gradient-to-b from-[#111827] to-[#020617] relative">
         {children}
      </div>

      {/* Industrial Screws */}
      <div className="absolute top-1 right-1 w-1 h-1 rounded-full bg-slate-700 shadow-[inset_0_1px_1px_rgba(0,0,0,1)]"></div>
      <div className="absolute top-1 left-1 w-1 h-1 rounded-full bg-slate-700 shadow-[inset_0_1px_1px_rgba(0,0,0,1)]"></div>
      <div className="absolute bottom-1 right-1 w-1 h-1 rounded-full bg-slate-700 shadow-[inset_0_1px_1px_rgba(0,0,0,1)]"></div>
