import React, { useEffect, useRef } from 'react';
import { ClipViewConfig } from '../types';

interface WaveformProps {
  buffer: AudioBuffer;
  color: string;
  width: number;
  height: number;
  viewConfig: ClipViewConfig;
}

// --- Numerical Analysis Engine ---

// Blackman-Harris Window: Minimizes spectral leakage for high-precision FFT visual
const blackmanHarris = (n: number, N: number) => {
    const a0 = 0.35875;
    const a1 = 0.48829;
    const a2 = 0.14128;
    const a3 = 0.01168;
    const term = (2 * Math.PI * n) / (N - 1);
    return a0 - a1 * Math.cos(term) + a2 * Math.cos(2 * term) - a3 * Math.cos(3 * term);
};

// Complex Number Struct
class Complex {
    constructor(public re: number, public im: number) {}
    add(other: Complex) { return new Complex(this.re + other.re, this.im + other.im); }
    sub(other: Complex) { return new Complex(this.re - other.re, this.im - other.im); }
    mult(other: Complex) { return new Complex(this.re * other.re - this.im * other.im, this.re * other.im + this.im * other.re); }
    mag() { return Math.sqrt(this.re * this.re + this.im * this.im); }
    phase() { return Math.atan2(this.im, this.re); }
}

// Recursive Cooley-Tukey FFT (Decimation in Time)
// Optimized for visual usage (Power of 2 inputs required)
const fft = (input: Complex[]): Complex[] => {
    const N = input.length;
    if (N <= 1) return input;

    const even = fft(input.filter((_, i) => i % 2 === 0));
    const odd = fft(input.filter((_, i) => i % 2 !== 0));

    const T = new Array(N / 2);
    for (let k = 0; k < N / 2; k++) {
        const angle = -2 * Math.PI * k / N;
        const w = new Complex(Math.cos(angle), Math.sin(angle));
        T[k] = w.mult(odd[k]);
    }

    const output = new Array(N);
    for (let k = 0; k < N / 2; k++) {
        output[k] = even[k].add(T[k]);
        output[k + N / 2] = even[k].sub(T[k]);
    }
    return output;
};

export const Waveform: React.FC<WaveformProps> = ({ buffer, color, width, height, viewConfig }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Clear
    ctx.clearRect(0, 0, width, height);

    // Parse Config
    const { mode, resolution, scale } = viewConfig;
    const data = buffer.getChannelData(0);

    // --- RENDER MODES ---

    if (mode === 'PCM') {
        // Standard high-performance time-domain rendering
        const step = Math.ceil(data.length / width);
        const amp = (height / 2) * scale;

        ctx.fillStyle = color;
        ctx.beginPath();
        for (let i = 0; i < width; i++) {
          let min = 1.0;
          let max = -1.0;
          const idx = i * step;
          for (let j = 0; j < step; j++) {
            if (idx + j >= data.length) break;
            const datum = data[idx + j];
            if (datum < min) min = datum;
            if (datum > max) max = datum;
          }
          if (min <= max) {
             ctx.fillRect(i, (height / 2) + (min * amp), 1, Math.max(1, (max - min) * amp));
          }
        }
        return;
    }

    // --- SPECTRAL PREPARATION ---
    // For 3D/4D/Sine modes, we perform STFT (Short-Time Fourier Transform) chunks

    // Config parameters based on "Resolution" knob (1-5)
    // Higher resolution = larger FFT size, more detailed frequency bins
    const fftSize = Math.pow(2, 5 + Math.floor(resolution)); // 64 to 1024
    const stride = Math.floor(data.length / (width / (resolution >= 3 ? 2 : 4))); // Density of slices

    // Limit stride to prevent infinite loops on tiny clips
    const safeStride = Math.max(fftSize, Math.min(stride, data.length));
    const numSlices = Math.floor((data.length - fftSize) / safeStride);

    // Color Helpers
    const hexToRgb = (hex: string) => {
        const bigint = parseInt(hex.replace('#', ''), 16);
        return [(bigint >> 16) & 255, (bigint >> 8) & 255, bigint & 255];
    };
    const [r, g, b] = hexToRgb(color);

    if (mode === 'SEPARATED_SINES') {
        // Decompose signal into dominant sine waves and render them
        ctx.lineWidth = 1;
        ctx.globalCompositeOperation = 'screen'; // Additive blending

        for (let i = 0; i < numSlices; i++) {
            const startIdx = i * safeStride;
            const windowData = new Array(fftSize);

            // Windowing
            for (let n = 0; n < fftSize; n++) {
                windowData[n] = new Complex(data[startIdx + n] * blackmanHarris(n, fftSize), 0);
            }

            const spectrum = fft(windowData);

            // Draw dominant frequencies for this slice
            // We only look at first half (Nyquist)
            const x = (startIdx / data.length) * width;

            for (let k = 1; k < fftSize / 4; k++) { // Limit to lower freq bands for visual clarity
                const mag = spectrum[k].mag();
                // Threshold to remove noise
                if (mag > 0.5) {
                    const normMag = Math.min(1, mag * 0.1 * scale);
                    const freqY = (k / (fftSize/4)) * height; // Map freq to height roughly

                    // Sine wave approximation drawing
                    // We draw a small sine segment or dot representing the harmonic presence
                    ctx.strokeStyle = `rgba(${r}, ${g}, ${b}, ${normMag})`;
                    ctx.beginPath();
                    // Draw a vertical line representing harmonic strength at this time
                    // Or actually, "Separated Sines" implies drawing the wave. 
                    // Let's draw the constituent sine wave amplitude as a stream
                    ctx.moveTo(x, height/2 - (freqY/2) - (mag*scale));
                    ctx.lineTo(x + (width/numSlices) + 1, height/2 - (freqY/2) - (mag*scale));
                    ctx.stroke();

                    // Mirror for stereo-ish look or just aesthetics
                    ctx.beginPath();
                    ctx.moveTo(x, height/2 + (freqY/2) + (mag*scale));
                    ctx.lineTo(x + (width/numSlices) + 1, height/2 + (freqY/2) + (mag*scale));
                    ctx.stroke();
                }
            }
        }
    } 
    else if (mode === 'SPECTRAL_FLUX_3D') {
        // Deep 3D Frequency View (Waterfall Plot)
        // X = Time, Y = Frequency (Isometric), Z = Magnitude (Height)

        ctx.lineWidth = 1;

        for (let i = 0; i < numSlices; i++) {
            const startIdx = i * safeStride;
            const windowData = new Array(fftSize);
            for (let n = 0; n < fftSize; n++) windowData[n] = new Complex(data[startIdx + n] * blackmanHarris(n, fftSize), 0);
            const spectrum = fft(windowData);

            // Isometric Projection Helper
            const isoX = (valX: number, valY: number) => valX + valY;
            const isoY = (valX: number, valY: number, valZ: number) => (valY - valX) * 0.5 - valZ;

            const sliceX = (startIdx / data.length) * width;

            ctx.beginPath();
            let started = false;

            // Iterate through frequency bins
            // We limit bins to keep performance high and visuals clean
            const maxBin = Math.min(fftSize / 2, 64); 

            for (let k = 0; k < maxBin; k++) {
                const mag = spectrum[k].mag();
                const logMag = Math.log10(1 + mag) * 20 * scale; // Decibel-ish scale

                // 3D Projection
                // x pos is time
                // y pos is frequency (depth)
                // z pos is magnitude (height)

                // Map to screen
                const screenX = sliceX + (k * 2); // Freq slants right
                const screenY = height - (k * (height/maxBin) * 0.5) - logMag; 

                // Add depth shading
                const alpha = Math.min(1, logMag / 20);
                ctx.strokeStyle = `rgba(${r}, ${g}, ${b}, ${alpha})`;

                if (k === 0) ctx.moveTo(screenX, screenY);
                else ctx.lineTo(screenX, screenY);
            }
            ctx.stroke();
        }
    }
    else if (mode === 'HYPER_DIMENSIONAL_4D') {
        // 4D View: Time (X), Frequency (Y), Magnitude (Size/Z), Phase (Color Hue)
        // Renders as a point cloud / mesh

        const maxBin = Math.min(fftSize / 2, 48);

        for (let i = 0; i < numSlices; i++) {
            const startIdx = i * safeStride;
            const windowData = new Array(fftSize);
            for (let n = 0; n < fftSize; n++) windowData[n] = new Complex(data[startIdx + n] * blackmanHarris(n, fftSize), 0);
            const spectrum = fft(windowData);

            const sliceX = (startIdx / data.length) * width;

            for (let k = 0; k < maxBin; k++) {
                const comp = spectrum[k];
                const mag = comp.mag();

                if (mag > 1.0) {
                    const phase = comp.phase(); // -PI to PI

                    // Map Phase to Hue (4th Dimension)
                    // We mix the base color with the phase color
                    const phaseDeg = ((phase + Math.PI) / (2 * Math.PI)) * 360;

                    const y = height - (k / maxBin) * height;
                    const size = Math.min(10, Math.log10(mag) * scale * 2);

                    // Draw Hyper-Point
                    ctx.fillStyle = `hsla(${phaseDeg}, 70%, 60%, 0.8)`;
                    ctx.beginPath();
                    ctx.arc(sliceX, y, size, 0, Math.PI * 2);
                    ctx.fill();

                    // Connecting thread (String Theory aesthetic)
                    if (k > 0) {
                        ctx.strokeStyle = `rgba(255,255,255,0.1)`;
                        ctx.beginPath();
                        ctx.moveTo(sliceX, y);
                        ctx.lineTo(sliceX, height - ((k-1)/maxBin) * height);
                        ctx.stroke();
                    }
                }
            }
        }
    }

  }, [buffer, color, width, height, viewConfig]);

  return (
    <canvas 
      ref={canvasRef} 
      width={width} 
      height={height} 
      className="w-full h-full opacity-90"
    />
  );
};

