import React, { useEffect, useRef } from 'react';

export const BackgroundInterference: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) return;

    let w = 0, h = 0;
    let t = 0;
    const source1 = { x: 0, y: 0 };
    const source2 = { x: 0, y: 0 };
    const wavelength = 24; 

    const resize = () => {
      w = canvas.width = window.innerWidth;
      h = canvas.height = window.innerHeight;
    };
    window.addEventListener('resize', resize);
    resize();

    const draw = () => {
      t += 0.2; // Slow, majestic movement

      // Lissajous Orbits
      source1.x = w/2 + Math.cos(t * 0.001) * (w * 0.4);
      source1.y = h/2 + Math.sin(t * 0.002) * (h * 0.3);
      source2.x = w/2 + Math.sin(t * 0.0015) * (w * 0.4);
      source2.y = h/2 + Math.cos(t * 0.001) * (h * 0.3);

      // Deep Void Base
      ctx.fillStyle = '#030305';
      ctx.fillRect(0, 0, w, h);

      // Additive Blending for Light
      ctx.globalCompositeOperation = 'lighter';

      const maxRadius = Math.max(w, h) * 1.5;
      const numRings = Math.ceil(maxRadius / wavelength);

      // Source 1: Cyan/Aurora
      ctx.strokeStyle = 'rgba(0, 240, 255, 0.08)'; 
      ctx.lineWidth = 2;
      ctx.beginPath();
      for (let i = 0; i < numRings; i+=2) { // Skip rings for transparency
          const r = i * wavelength + (-(t * 0.5) % wavelength);
          if (r > 0) {
            ctx.moveTo(source1.x + r, source1.y);
            ctx.arc(source1.x, source1.y, r, 0, Math.PI * 2);
          }
      }
      ctx.stroke();

      // Source 2: Purple/Nebula
      ctx.strokeStyle = 'rgba(180, 0, 255, 0.06)';
      ctx.lineWidth = 3;
      ctx.beginPath();
      for (let i = 0; i < numRings; i+=3) {
          const r = i * wavelength + (-(t * 0.4) % wavelength);
          if (r > 0) {
            ctx.moveTo(source2.x + r, source2.y);
            ctx.arc(source2.x, source2.y, r, 0, Math.PI * 2);
          }
      }
      ctx.stroke();

      // Subtle Vignette
      ctx.globalCompositeOperation = 'source-over';
      const gradient = ctx.createRadialGradient(w/2, h/2, w/4, w/2, h/2, w);
      gradient.addColorStop(0, 'transparent');
      gradient.addColorStop(1, 'rgba(0,0,0,0.8)');
      ctx.fillStyle = gradient;
      ctx.fillRect(0, 0, w, h);

      requestAnimationFrame(draw);
    };

    const animId = requestAnimationFrame(draw);
    return () => {
      window.removeEventListener('resize', resize);
      cancelAnimationFrame(animId);
    };
  }, []);

  return (
    <canvas 
      ref={canvasRef} 
      className="fixed inset-0 pointer-events-none z-0"
    />
  );
};

export interface TrackFX {
  eqLow: number; // dB
  eqMid: number; // dB
  eqHigh: number; // dB
