                    : 'border-transparent text-slate-800 cursor-not-allowed'}`}
            title="Delete Selected"
         >
            <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6"></polyline><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path></svg>
         </button>
      </div>

      {/* Group 4: Config & Utils */}
      <div className="flex items-center space-x-2 flex-shrink-0 ml-auto pl-4 border-l border-white/10">

        <button
            onClick={onShowCredits}
            className="text-[10px] font-bold text-slate-500 hover:text-white uppercase tracking-widest mr-2"
        >
            Credits
        </button>

        <button
            onClick={onOpenInfo}
            className="w-8 h-8 rounded-full bg-black border border-blue-900/50 text-blue-500 hover:text-white hover:bg-blue-900 flex items-center justify-center transition-colors"
            title="Project Info & Export"
        >
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"></circle><line x1="12" y1="16" x2="12" y2="12"></line><line x1="12" y1="8" x2="12.01" y2="8"></line></svg>
        </button>

        <div className="flex flex-col items-center group">
            <div className="flex -space-x-px">
                <button 
                    className="h-6 px-1.5 bg-black border border-slate-700 rounded-l text-[10px] text-slate-400 hover:bg-slate-800 font-mono"
                    onClick={() => setZoom(Math.max(10, zoom * 0.8))}
                >-</button>
                <button 
                    className="h-6 px-1.5 bg-black border border-slate-700 rounded-r text-[10px] text-slate-400 hover:bg-slate-800 font-mono"
                    onClick={() => setZoom(Math.min(500, zoom * 1.25))}
                >+</button>
            </div>
        </div>

        <button
          className={`w-8 h-6 rounded border text-[9px] font-bold tracking-wider transition-colors flex items-center justify-center ${monitor ? 'bg-green-500/20 border-green-500 text-green-400' : 'bg-black border-slate-700 text-slate-500 hover:text-slate-300'}`}
          onClick={() => setMonitor(!monitor)}
          title="Input Monitor"
        >
          MON
        </button>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { audioEngine } from './services/audioEngine';
import { storageService } from './services/storageService';
import { Controls } from './components/Controls';
import { TrackLane } from './components/TrackLane';
import { ChannelStrip } from './components/ChannelStrip';
import { DSPRack } from './components/DSPRack';
import { ClipInspector } from './components/ClipInspector';
import { BackgroundInterference } from './components/BackgroundInterference';
import { ProjectInfoPanel } from './components/ProjectInfoPanel';
import { CreditsModal } from './components/CreditsModal';
import { Track, AudioClip, EditMode, DSPState, TrackFX, ProjectMetadata, ClipViewConfig, ViewSettings } from './types';
import { COLORS, TRACK_HEIGHT, EXPANDED_TRACK_HEIGHT, CHANNEL_WIDTH_DEFAULT, CHANNEL_WIDTH_EXPANDED, CHANNEL_WIDTH_COLLAPSED } from './constants';

const DEFAULT_TRACK_FX: TrackFX = {
    eqLow: 0, eqMid: 0, eqHigh: 0,
    compressorThreshold: 0, compressorRatio: 1,

    saturation: 0,
    saturationFine: 0,
    distortionTone: 20000,

    cabinetOn: false,
    cabinetTone: 0.5,

    sendReverb: 0, 
    reverbTone: 0.5,
    sendDelay: 0,
    highPassFreq: 20
};

const DEFAULT_CLIP_FX = {
    gain: 1.0,
    pitch: 1.0,
    pan: 0,
    isReversed: false,

    filterFreq: 20000,
    filterRes: 0,
    saturation: 0
};

const DEFAULT_VIEW_CONFIG: ClipViewConfig = {
    mode: 'PCM',
    resolution: 2,
    scale: 1.0
};

const App: React.FC = () => {
  // State
  const [tracks, setTracks] = useState<Track[]>([
    { id: 't1', name: 'Vocals', color: COLORS[0], muted: false, solo: false, armed: true, volume: 0.8, pan: 0, fx: {...DEFAULT_TRACK_FX}, isExpanded: false },
    { id: 't2', name: 'Guitars', color: COLORS[1], muted: false, solo: false, armed: false, volume: 0.8, pan: -0.3, fx: {...DEFAULT_TRACK_FX}, isExpanded: false },
    { id: 't3', name: 'Bass', color: COLORS[2], muted: false, solo: false, armed: false, volume: 0.8, pan: 0, fx: {...DEFAULT_TRACK_FX}, isExpanded: false },
    { id: 't4', name: 'Drums', color: COLORS[3], muted: false, solo: false, armed: false, volume: 0.8, pan: 0, fx: {...DEFAULT_TRACK_FX}, isExpanded: false },
  ]);
  const [clips, setClips] = useState<AudioClip[]>([]);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0); 
  const [zoom, setZoom] = useState(100); 
  const [selectedClipId, setSelectedClipId] = useState<string | null>(null);

  // UI View Settings
  const [viewSettings, setViewSettings] = useState<ViewSettings>({
      showTransport: true,
      showMix: true,
      showRack: true,
      isCollapsed: false
  });

  // Clipboard
  const [clipClipboard, setClipClipboard] = useState<AudioClip | null>(null);

  // Loop State
  const [loopRange, setLoopRange] = useState<{ start: number, end: number } | null>(null);
  const [isLooping, setIsLooping] = useState(false);

  const [editMode, setEditMode] = useState<EditMode>(EditMode.MOVE);

  // Project Metadata
  const [metadata, setMetadata] = useState<ProjectMetadata>({ title: 'New Project', artist: 'Artist', album: '', year: new Date().getFullYear().toString() });
  const [showInfoPanel, setShowInfoPanel] = useState(false);
  const [showCredits, setShowCredits] = useState(true); // Show on load
  const [isExporting, setIsExporting] = useState(false);

  // Updated DSP State with all master controls
  const [dspState, setDspState] = useState<DSPState>({ 
      masterVolume: 1.0,

      masterFilterFreq: 20000,
      masterFilterRes: 0,

      masterEqLow: 0,
      masterEqMid: 0,
      masterEqHigh: 0,

      masterSaturation: 0,

      masterExciterDrive: 0, // NEW INITIALIZATION
      masterStereoWidth: 1,  // NEW INITIALIZATION

      masterCompressorThreshold: 0,
      masterCompressorRatio: 1,

      delayTime: 0.3,
      delayFeedback: 0.3,
      reverbMix: 0.2, 

      limiterThreshold: -1.0,
      reverbDecay: 2.0
  });

  const [isRecording, setIsRecording] = useState(false);
  const [monitor, setMonitor] = useState(false);

  // Refs
  const rafRef = useRef<number>();
  const startTimeRef = useRef<number>(0); 
  const startOffsetRef = useRef<number>(0); 
  const recordingStartRef = useRef<number>(0); 
  const dragRef = useRef<{ clipId: string; startX: number; originalStart: number } | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // --- Layout Calculation ---
  // Calculate dynamic channel width based on selection and collapse state
  const currentChannelWidth = viewSettings.isCollapsed 
      ? CHANNEL_WIDTH_COLLAPSED 
      : (selectedClipId ? CHANNEL_WIDTH_EXPANDED : CHANNEL_WIDTH_DEFAULT);

  // --- Initialization ---
  useEffect(() => {
    storageService.init();
    const handleTouch = () => audioEngine.resume();
    document.addEventListener('touchstart', handleTouch, { once: true });
    document.addEventListener('click', handleTouch, { once: true });

    // Initialize Tracks in Audio Engine
    tracks.forEach(t => audioEngine.ensureTrackChannel(t));

    return () => cancelAnimationFrame(rafRef.current!);
  }, []);

  // Update engine when tracks change
  useEffect(() => {
      tracks.forEach(t => audioEngine.updateTrackState(t));
  }, [tracks]);

  useEffect(() => {
      audioEngine.updateMasterDSP(dspState);
  }, [dspState]);

  // --- Playback Logic ---

  const restartPlayback = async (startAt: number) => {
    audioEngine.stopAll();
    setCurrentTime(startAt);
    startTimeRef.current = audioEngine.ctx.currentTime;
    startOffsetRef.current = startAt;

    clips.forEach(clip => {
      const track = tracks.find(t => t.id === clip.trackId);
      if (track && !track.muted && (!tracks.some(t => t.solo) || track.solo)) {
         audioEngine.playClip(clip, startAt);
      }
    });
  };

  const updatePlayhead = useCallback(() => {
    if (audioEngine.ctx.state === 'running' && isPlaying) {
        const elapsed = audioEngine.ctx.currentTime - startTimeRef.current;
        const newTime = startOffsetRef.current + elapsed;

        // Loop Logic
        if (isLooping && loopRange && newTime >= loopRange.end) {
            restartPlayback(loopRange.start);
        } else if (isExporting) {
            // Check export end
            const maxDuration = Math.max(...clips.map(c => c.startTime + c.duration)) + 2.0;
            if (newTime >= maxDuration) {
                finishExport();
            } else {
                setCurrentTime(newTime);
            }
        } else {
            setCurrentTime(newTime);
        }
    }
    rafRef.current = requestAnimationFrame(updatePlayhead);
  }, [isPlaying, isLooping, loopRange, isExporting, clips]);

  useEffect(() => {
    if (isPlaying) {
      rafRef.current = requestAnimationFrame(updatePlayhead);
    } else {
      cancelAnimationFrame(rafRef.current!);
    }
  }, [isPlaying, updatePlayhead]);

  const togglePlay = async () => {
    await audioEngine.resume();
    if (isPlaying) {
      audioEngine.stopAll();
      setIsPlaying(false);
      const elapsed = audioEngine.ctx.currentTime - startTimeRef.current;
      const newTime = startOffsetRef.current + elapsed;
      setCurrentTime(newTime);
      startOffsetRef.current = newTime;
    } else {
      startTimeRef.current = audioEngine.ctx.currentTime;
      startOffsetRef.current = currentTime; 

      clips.forEach(clip => {
        const track = tracks.find(t => t.id === clip.trackId);
        if (track && !track.muted && (!tracks.some(t => t.solo) || track.solo)) {
           audioEngine.playClip(clip, currentTime);
        }
      });
      setIsPlaying(true);
    }
  };

  // --- Loop Controls ---
  const handleSetLoopIn = () => {
      setLoopRange(prev => ({ start: currentTime, end: prev ? Math.max(prev.end, currentTime + 1) : currentTime + 4.0 }));
      if (!isLooping) setIsLooping(true);
  };

  const handleSetLoopOut = () => {
      setLoopRange(prev => ({ start: prev ? Math.min(prev.start, currentTime - 1) : Math.max(0, currentTime - 4.0), end: currentTime }));
      if (!isLooping) setIsLooping(true);
  };

  const handleToggleLoop = () => {
      if (!isLooping && !loopRange) {
          // Default loop 4 bars-ish (assuming 4 seconds for now)
          setLoopRange({ start: currentTime, end: currentTime + 4.0 });
      }
      setIsLooping(!isLooping);
  };

  // --- Copy / Paste Logic ---

  const handleCopy = () => {
      if (!selectedClipId) return;
      const clip = clips.find(c => c.id === selectedClipId);
      if (clip) {
          setClipClipboard(clip);
      }
  };

  const handlePaste = () => {
      if (!clipClipboard) return;

      // Determine target track: If a clip is selected, use that track, else use first track
      let targetTrackId = tracks[0].id;
      if (selectedClipId) {
          const selected = clips.find(c => c.id === selectedClipId);
          if (selected) targetTrackId = selected.trackId;
      }

      const newClip: AudioClip = {
          ...clipClipboard,
          id: Date.now().toString() + Math.random().toString().slice(2,5),
          startTime: currentTime,
          trackId: targetTrackId
      };

      setClips(prev => [...prev, newClip]);
      setSelectedClipId(newClip.id);
  };

  // --- Track Operations ---

  const handleTrackUpdate = (trackId: string, updates: Partial<Track>) => {
    setTracks(prev => prev.map(t => t.id === trackId ? { ...t, ...updates } : t));
  };

  const toggleTrackArm = (trackId: string) => {
      setTracks(prev => prev.map(t => ({ ...t, armed: t.id === trackId })));
  };

  const toggleTrackExpand = (trackId: string) => {
      setTracks(prev => prev.map(t => ({ ...t, isExpanded: t.id === trackId ? !t.isExpanded : t.isExpanded })));
  };

  const handleDuplicateTrack = (trackId: string) => {
      const originalTrack = tracks.find(t => t.id === trackId);
      if (!originalTrack) return;

      const newTrackId = Date.now().toString();
      const newTrack: Track = {
          ...originalTrack,
          id: newTrackId,
          name: originalTrack.name + ' (Copy)',
          isExpanded: false
      };

      // Duplicate clips belonging to this track
      const originalClips = clips.filter(c => c.trackId === trackId);
      const newClips = originalClips.map(c => ({
          ...c,
          id: c.id + '_copy_' + Math.random().toString().slice(2,5),
          trackId: newTrackId
      }));

      // Insert after original
      const index = tracks.findIndex(t => t.id === trackId);
      const newTracks = [...tracks];
      newTracks.splice(index + 1, 0, newTrack);

      setTracks(newTracks);
      setClips(prev => [...prev, ...newClips]);

      // Init engine for new track
      audioEngine.ensureTrackChannel(newTrack);
  };

  // --- Export Logic ---
  const handleExport = async (format: 'mp4') => {
      if (isPlaying) await togglePlay();

      setIsExporting(true);

      // Start real-time bounce
      audioEngine.startBounceRecorder();

      // Start Playback from 0
      startTimeRef.current = audioEngine.ctx.currentTime;
      startOffsetRef.current = 0;
      setCurrentTime(0);

      clips.forEach(clip => {
        const track = tracks.find(t => t.id === clip.trackId);
        if (track && !track.muted && (!tracks.some(t => t.solo) || track.solo)) {
           audioEngine.playClip(clip, 0);
        }
      });
      setIsPlaying(true);
      // Playhead loop will handle the "Stop" condition when time > maxDuration
  };

  const finishExport = async () => {
      setIsPlaying(false);
      audioEngine.stopAll();
      const blob = await audioEngine.stopBounceRecorder();
      setIsExporting(false);
      setShowInfoPanel(false);

      // Download
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.style.display = 'none';
      a.href = url;
      // Use filename from metadata
      const cleanTitle = metadata.title.replace(/[^a-z0-9]/gi, '_').toLowerCase();
      a.download = `${cleanTitle}_bounce.mp4`;
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
  };

  // --- Recording ---
  const stopRecordingAndSave = async () => {
      const blob = await audioEngine.stopRecording();
      setIsRecording(false);
      const id = Date.now().toString();
      await storageService.saveBlob(id, blob);
      const buffer = await audioEngine.decodeAudioData(blob);
      const armedTrack = tracks.find(t => t.armed) || tracks[0];
      const newClip: AudioClip = {
        id, trackId: armedTrack.id, buffer, startTime: recordingStartRef.current,
        duration: buffer.duration, offset: 0, name: `Rec ${id.substr(-4)}`,
        fx: {...DEFAULT_CLIP_FX},
        viewConfig: {...DEFAULT_VIEW_CONFIG}
      };
      setClips(prev => [...prev, newClip]);
      setSelectedClipId(id);
  };

  const toggleRecord = async () => {
    if (isRecording) {
      await stopRecordingAndSave();
    } else {
      recordingStartRef.current = currentTime; 
      try {
        await audioEngine.startRecording(monitor);
        setIsRecording(true);
        if (!isPlaying) await togglePlay();
      } catch (err) {
        console.error("Failed to start recording:", err);
      }
    }
  };

  const stop = async () => {
    // 1. Immediate Audio Stop
    audioEngine.stopAll();
    setIsPlaying(false);

    // 2. Handle Export Cancel
    if (isExporting) {
        audioEngine.stopBounceRecorder();
        setIsExporting(false);
        return;
    }

    // 3. Determine Return Time
    const returnTime = isRecording ? recordingStartRef.current : (isLooping && loopRange ? loopRange.start : 0);

    // 4. Handle Recording asynchronously
    if (isRecording) {
        try {
            await stopRecordingAndSave();
        } catch(e) {
            console.error("Error saving recording on stop:", e);
            setIsRecording(false);
        }
    }

    // 5. Reset Playhead
    setCurrentTime(returnTime);
    startOffsetRef.current = returnTime;
  };

  // --- Clip Interaction ---
  const handleClipInteract = (clipId: string, action: string, data?: any) => {
    if (action === 'tap') {
        setSelectedClipId(clipId);
        if (editMode === EditMode.SPLIT && data?.x && containerRef.current) {
            const containerLeft = containerRef.current.getBoundingClientRect().left;
            const scrollLeft = containerRef.current.scrollLeft;
            const clickX = data.x - containerLeft + scrollLeft - currentChannelWidth;
            const tapTime = Math.max(0, clickX / zoom);
            setCurrentTime(tapTime);
            startOffsetRef.current = tapTime;
            splitClip(clipId, tapTime);
        }
        return;
    }
    if (editMode === EditMode.MOVE && action === 'start') {
      setSelectedClipId(clipId);
      dragRef.current = { clipId, startX: data.x, originalStart: data.originalStart };
      const handleMove = (e: any) => {
        if (!dragRef.current || !containerRef.current) return;
        const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
        const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
        const deltaX = clientX - dragRef.current.startX;
        const deltaTime = deltaX / zoom; 
        let newStart = Math.max(0, dragRef.current.originalStart + deltaTime);
        newStart = Math.round(newStart / 0.1) * 0.1; // Snap to 100ms

        // Calc Track Index by absolute Y against container
        const containerRect = containerRef.current.getBoundingClientRect();
        const scrollY = containerRef.current.scrollTop;
        const relativeY = clientY - containerRect.top + scrollY;

        // Complex height calculation because tracks can be expanded
        let accumulatedHeight = 0;
        let targetTrackId = null;
        for (const track of tracks) {
            const h = track.isExpanded ? EXPANDED_TRACK_HEIGHT : TRACK_HEIGHT; // Match ChannelStrip heights
            if (relativeY >= accumulatedHeight && relativeY < accumulatedHeight + h) {
                targetTrackId = track.id;
                break;
            }
            accumulatedHeight += h;
        }

        setClips(prev => prev.map(c => 
          c.id === dragRef.current?.clipId ? { 
              ...c, startTime: newStart, 
              trackId: targetTrackId || c.trackId 
          } : c
        ));
      };
      const handleEnd = () => {
        dragRef.current = null;
        window.removeEventListener('touchmove', handleMove); window.removeEventListener('touchend', handleEnd);
        window.removeEventListener('mousemove', handleMove); window.addEventListener('mouseup', handleEnd);
      };
      window.addEventListener('touchmove', handleMove, { passive: false }); window.addEventListener('touchend', handleEnd);
      window.addEventListener('mousemove', handleMove); window.addEventListener('mouseup', handleEnd);
    }
  };

  const handleClipFXUpdate = (clipId: string, updates: Partial<AudioClip['fx']> | { viewConfig: any }) => {
      setClips(prev => prev.map(c => 
        c.id === clipId 
            ? { 
                ...c, 
                ...('viewConfig' in updates ? { viewConfig: updates.viewConfig } : { fx: { ...c.fx, ...updates } }) 
              } 
            : c
      ));
      if (!('viewConfig' in updates)) {
          audioEngine.updateClipParams(clipId, updates as Partial<typeof DEFAULT_CLIP_FX>);
      }
  };

  const splitClip = (clipId: string, splitTimeOverride?: number) => {
    const clip = clips.find(c => c.id === clipId);
    if (!clip) return;
    const timeToSplitAt = splitTimeOverride !== undefined ? splitTimeOverride : currentTime;
    const relativeSplitTime = (timeToSplitAt - clip.startTime); 

    // Allow smaller splits, but prevent glitching
    if (relativeSplitTime <= 0.01 || relativeSplitTime >= clip.duration - 0.01) return;

    const clip1: AudioClip = { ...clip, id: clip.id + '_1', duration: relativeSplitTime };
    const clip2: AudioClip = { ...clip, id: clip.id + '_2', startTime: timeToSplitAt, duration: clip.duration - relativeSplitTime, offset: clip.offset + relativeSplitTime };
    setClips(prev => prev.filter(c => c.id !== clipId).concat([clip1, clip2]));
    setSelectedClipId(clip2.id);
  };

  const handleSplitButton = () => {
      if (selectedClipId) splitClip(selectedClipId, currentTime);
  };

  const deleteSelectedClip = () => {
      if (!selectedClipId) return;
      setClips(prev => prev.filter(c => c.id !== selectedClipId));
      setSelectedClipId(null);
  };

  const handleTimelineScrub = (e: any) => {
     if (e.target.dataset.bg) setSelectedClipId(null);
     if (!containerRef.current) return;
     const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
     const containerLeft = containerRef.current.getBoundingClientRect().left;
     const scrollLeft = containerRef.current.scrollLeft;
     const relativeX = clientX - containerLeft + scrollLeft;
     const time = Math.max(0, (relativeX - currentChannelWidth) / zoom);
     setCurrentTime(time);
     startOffsetRef.current = time;
  };

  const selectedClip = clips.find(c => c.id === selectedClipId);

  return (
    <div className="flex flex-col h-screen w-screen bg-transparent text-slate-100 overflow-hidden select-none font-sans relative">

      {/* Background Mood */}
      <BackgroundInterference />

      {/* Main Content (with subtle translucency to let interference show) */}
      <div className="flex flex-col h-full w-full z-10 relative bg-black/10 backdrop-blur-[1px]">
        <Controls 
            isPlaying={isPlaying} isRecording={isRecording} 
            isLooping={isLooping} loopRange={loopRange}
            onPlayPause={togglePlay} 
            onRecord={toggleRecord} onStop={stop} onBounce={() => setShowInfoPanel(true)} 
            onDelete={deleteSelectedClip} onSplit={handleSplitButton}
            onCopy={handleCopy} onPaste={handlePaste}
            onToggleLoop={handleToggleLoop} onSetLoopIn={handleSetLoopIn} onSetLoopOut={handleSetLoopOut}
            onOpenInfo={() => setShowInfoPanel(true)}
            onShowCredits={() => setShowCredits(true)}
            editMode={editMode} setEditMode={setEditMode} monitor={monitor} setMonitor={setMonitor}
            zoom={zoom} setZoom={setZoom} hasSelection={!!selectedClipId}
            hasClipboard={!!clipClipboard}
            viewSettings={viewSettings} setViewSettings={setViewSettings}
        />

        <div ref={containerRef} className="flex-1 overflow-y-auto overflow-x-auto relative mt-[60px] mb-[220px]" 
            onClick={() => setSelectedClipId(null)} data-bg="true">

            {/* Playhead */}
            <div className="absolute top-0 bottom-0 z-40 pointer-events-none border-r border-blue-500 shadow-[0_0_10px_rgba(59,130,246,0.8)]"
                style={{ left: `${(currentTime * zoom) + currentChannelWidth}px`, width: '1px' }}>
                <div className="absolute -top-4 -translate-x-1/2 bg-blue-600 text-[9px] px-1.5 py-0.5 rounded-sm text-white font-mono shadow-md whitespace-nowrap z-50">
                    {currentTime.toFixed(2)}s
                </div>
                {/* Playhead Line Extension */}
                <div className="absolute top-0 bottom-0 w-px bg-blue-500/50"></div>
            </div>

            {/* Ruler */}
            <div className="h-8 min-w-full bg-[#000000] border-b border-white/10 relative cursor-pointer shadow-lg z-30 transition-all duration-300"
                style={{ width: `${Math.max(window.innerWidth, (300 * zoom) + currentChannelWidth)}px` }}
                onClick={(e) => { e.stopPropagation(); handleTimelineScrub(e); }}>

                {/* Loop Region Overlay */}
                {loopRange && (
                    <div className="absolute top-0 bottom-0 bg-blue-500/10 border-x border-blue-500/50 z-0"
                        style={{ 
                            left: `${loopRange.start * zoom + currentChannelWidth}px`, 
                            width: `${(loopRange.end - loopRange.start) * zoom}px` 
                        }}>
                        {/* Triangle Indicators */}
                        <div className="absolute top-0 left-0 -translate-x-1/2 w-0 h-0 border-l-[4px] border-l-transparent border-r-[4px] border-r-transparent border-t-[6px] border-t-blue-500"></div>
                        <div className="absolute top-0 right-0 translate-x-1/2 w-0 h-0 border-l-[4px] border-l-transparent border-r-[4px] border-r-transparent border-t-[6px] border-t-blue-500"></div>
                    </div>
                )}

                {/* Ticks */}
                {Array.from({ length: Math.ceil(300 * zoom / 100) * 4 }).map((_, i) => {
                    const sec = i * 0.25;
                    const isMajor = i % 4 === 0;
                    return (
                    <div key={i} className={`absolute bottom-0 border-l z-10 pointer-events-none ${isMajor ? 'h-4 border-slate-400' : 'h-2 border-slate-700'}`} 
                        style={{ left: (sec * zoom) + currentChannelWidth }}>
                        {isMajor && <span className="text-[9px] font-medium text-slate-400 pl-1.5 -mt-4 block">{sec}</span>}
                    </div>
                )})}
            </div>

            {/* Tracks Container */}
            <div className="min-w-full pb-20 relative bg-transparent transition-all duration-300" style={{ width: `${Math.max(window.innerWidth, (300 * zoom) + currentChannelWidth)}px` }} data-bg="true">

            {/* Loop Region Highlight in Tracks */}
            {loopRange && (
                <div className="absolute top-0 bottom-0 bg-blue-900/5 pointer-events-none z-0 border-x border-blue-900/20"
                    style={{ 
                        left: `${loopRange.start * zoom + currentChannelWidth}px`, 
                        width: `${(loopRange.end - loopRange.start) * zoom}px` 
                    }}
                />
            )}

            {tracks.map(track => (
                <div key={track.id} className="flex border-b border-white/5 bg-black/40" style={{ height: track.isExpanded ? EXPANDED_TRACK_HEIGHT : TRACK_HEIGHT }}>
                <ChannelStrip 
                    track={track} 
                    onUpdate={handleTrackUpdate} 
                    onToggleArm={toggleTrackArm} 
                    onToggleExpand={toggleTrackExpand} 
                    onDuplicate={handleDuplicateTrack}
                    width={currentChannelWidth}
                    viewSettings={viewSettings}
                    isCollapsed={viewSettings.isCollapsed}
                />
                <div className="relative w-full z-10">
                    <TrackLane track={track} clips={clips.filter(c => c.trackId === track.id)}
                        editMode={editMode} selectedClipId={selectedClipId} onClipInteract={handleClipInteract}
                        currentTime={currentTime} isPlaying={isPlaying} zoom={zoom} />
                </div>
                </div>
            ))}
            </div>
        </div>

        {selectedClip ? (
            <ClipInspector clip={selectedClip} onUpdate={handleClipFXUpdate} onClose={() => setSelectedClipId(null)} />
        ) : (
            <DSPRack dspState={dspState} onChange={(s) => { setDspState(s); audioEngine.updateMasterDSP(s); }} />
        )}

        {/* Info / Config Panel */}
        {showInfoPanel && (
            <ProjectInfoPanel 
                metadata={metadata} 
                onChange={setMetadata} 
                onClose={() => !isExporting && setShowInfoPanel(false)}
                onExport={handleExport}
                isExporting={isExporting}
            />
        )}

        {/* Credits Modal */}
        {showCredits && (
            <CreditsModal onClose={() => setShowCredits(false)} />
        )}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { Track, ViewSettings } from '../types';
import { COLORS, TRACK_HEIGHT, EXPANDED_TRACK_HEIGHT } from '../constants';
import { Knob } from './Knob';
import { Slider } from './Slider';

interface ChannelStripProps {
  track: Track;
  onUpdate: (id: string, updates: Partial<Track>) => void;
  onToggleArm: (id: string) => void;
  onToggleExpand: (id: string) => void;
  onDuplicate: (id: string) => void;
  width: number;
  viewSettings: ViewSettings;
  isCollapsed: boolean;
}

export const ChannelStrip: React.FC<ChannelStripProps> = ({ 
    track, onUpdate, onToggleArm, onToggleExpand, onDuplicate, 
    width, viewSettings, isCollapsed 
}) => {
  const [showColors, setShowColors] = useState(false);
  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setShowColors(false);
      }
    };
    if (showColors) document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [showColors]);

  const updateFX = (key: keyof typeof track.fx, value: any) => {
      onUpdate(track.id, {
          fx: { ...track.fx, [key]: value }
      });
  };

  const isWide = width > 200;

  return (
    <div 
        className="sticky left-0 z-20 flex flex-col transition-all duration-300 ease-out group shadow-[4px_0_20px_rgba(0,0,0,0.8)] overflow-hidden" 
        style={{ 
            width: width,
            height: track.isExpanded ? EXPANDED_TRACK_HEIGHT : TRACK_HEIGHT,
            background: '#0a0a0c',
            borderRight: `1px solid ${track.color}20`
        }}
    >
       {/* --- HEADER SECTION --- */}
       <div className="p-3 flex-shrink-0 flex flex-col relative" style={{ height: TRACK_HEIGHT }}>

            {/* Identity Row (Color, Name, Arm) */}
            <div className={`flex items-center gap-2 relative z-30 transition-all ${isCollapsed ? 'justify-center flex-col h-full space-y-4' : 'justify-between mb-2'}`}>

                {/* Color Dot */}
                <div className="relative flex-shrink-0" ref={menuRef}>
                    <button
                        className="w-3 h-3 rounded-full transition-all duration-300 hover:scale-125"
                        style={{ backgroundColor: track.color, boxShadow: `0 0 8px ${track.color}` }}
                        onClick={() => setShowColors(!showColors)}
                    />
                    {showColors && (
                    <div className="absolute top-full left-0 mt-2 bg-black/90 backdrop-blur-xl border border-white/10 p-2 rounded-lg grid grid-cols-4 gap-2 shadow-2xl z-50 w-32 animate-in zoom-in-95 duration-100">
                        {COLORS.map(c => (
                            <button key={c} className="w-5 h-5 rounded-full border border-white/10 hover:scale-110 transition-transform" style={{ backgroundColor: c, boxShadow: `0 0 10px ${c}` }}
                            onClick={(e) => { e.stopPropagation(); onUpdate(track.id, { color: c }); setShowColors(false); }} />
                        ))}
                    </div>
                    )}
                </div>

                {/* Name */}
                {!isCollapsed && (
                    <input
                        className="bg-transparent text-[13px] font-bold text-slate-200 w-full outline-none px-0.5 truncate tracking-wide focus:text-white placeholder-slate-600 font-mono transition-all"
                        value={track.name}
                        onChange={(e) => onUpdate(track.id, { name: e.target.value })}
                        style={{ opacity: width < 60 ? 0 : 1 }}
                    />
                )}

                {/* Arm Button */}
                <button 
                    onClick={() => onToggleArm(track.id)} 
                    className={`w-6 h-6 rounded-full flex-shrink-0 flex items-center justify-center transition-all ${track.armed ? 'bg-red-500/10 shadow-[0_0_15px_rgba(220,38,38,0.4)]' : 'bg-transparent hover:bg-white/5'}`}
                    title="Arm Track"
                >
                    <div className={`w-2.5 h-2.5 rounded-full transition-all ${track.armed ? 'bg-red-500 animate-pulse' : 'bg-slate-700'}`} />
                </button>
            </div>

            {/* --- TRANSPORT SECTION (Mute/Solo) --- */}
            {!isCollapsed && (
                <div className={`flex space-x-1 mb-3 transition-all duration-300 overflow-hidden ${viewSettings.showTransport ? 'opacity-100 max-h-10' : 'opacity-0 max-h-0'}`}>
                    <button className={`flex-1 py-1 text-[10px] font-bold rounded transition-all tracking-wider
                        ${track.muted 
                            ? 'bg-orange-500 text-black shadow-[0_0_10px_rgba(249,115,22,0.5)]' 
                            : 'bg-[#1a1a1e] text-slate-500 hover:bg-[#222]'}`}
                        onClick={() => onUpdate(track.id, { muted: !track.muted })}>M</button>

                    <button className={`flex-1 py-1 text-[10px] font-bold rounded transition-all tracking-wider
                        ${track.solo 
                            ? 'bg-yellow-400 text-black shadow-[0_0_10px_rgba(250,204,21,0.5)]' 
                            : 'bg-[#1a1a1e] text-slate-500 hover:bg-[#222]'}`}
                        onClick={() => onUpdate(track.id, { solo: !track.solo })}>S</button>

                    {/* FX Expander Toggle */}
                    {viewSettings.showRack && (
                        <button className={`flex-1 py-1 text-[10px] font-bold rounded transition-all tracking-wider
                            ${track.isExpanded 
                                ? 'bg-blue-600 text-white shadow-[0_0_15px_rgba(37,99,235,0.4)]' 
                                : 'bg-[#1a1a1e] text-blue-500 hover:bg-[#222]'}`}
                            onClick={() => onToggleExpand(track.id)}>FX</button>
                    )}
                </div>
            )}

            {/* Duplicate Logic */}
             {!isCollapsed && width > 100 && (
                <button 
                    className="absolute right-2 top-10 text-[8px] text-slate-700 hover:text-white uppercase tracking-wider opacity-0 group-hover:opacity-100 transition-opacity"
                    onClick={() => onDuplicate(track.id)}
                >
                    Dup
                </button>
             )}

            {/* --- MIX SECTION (Volume/Pan) --- */}
            {!isCollapsed && (
                <div className={`flex flex-col space-y-2 transition-all duration-500 overflow-hidden ${viewSettings.showMix ? 'opacity-100 max-h-20' : 'opacity-0 max-h-0'}`}>
                    {/* Volume Laser */}
                    <div className="flex items-center space-x-2 group/vol">
                         {isWide && <span className="text-[8px] font-bold text-slate-600 w-6">VOL</span>}
                        <div className="flex-1 h-1.5 relative flex items-center bg-[#111] rounded-full overflow-hidden">
                            {/* Laser Beam */}
                            <div className="h-full shadow-[0_0_10px_currentColor] transition-all duration-75 ease-out" 
                                style={{ width: `${track.volume * 100}%`, backgroundColor: track.color, color: track.color }}></div>
                            <input 
                                type="range" min="0" max="1" step="0.01" 
                                value={track.volume} 
                                onChange={(e) => onUpdate(track.id, { volume: parseFloat(e.target.value) })}
                                className="absolute w-full h-full opacity-0 cursor-pointer" 
                            />
                        </div>
                        {isWide && <span className="text-[8px] font-mono text-slate-400 w-8 text-right">{(track.volume * 100).toFixed(0)}%</span>}
                    </div>

                    {/* Pan Laser */}
                    <div className="flex items-center space-x-2 group/pan">
                         {isWide && <span className="text-[8px] font-bold text-slate-600 w-6">PAN</span>}
                        <div className="flex-1 h-1 relative flex items-center bg-[#111] rounded-full">
                            {/* Center Marker */}
                            <div className="absolute left-1/2 w-px h-full bg-slate-600"></div>
                            {/* Pan Thumb */}
                            <div 
                                className="absolute h-2 w-2 rounded-full shadow-[0_0_8px_white] bg-white pointer-events-none transition-transform"
                                style={{ left: `calc(${((track.pan + 1) / 2) * 100}% - 4px)` }}
                            />
                            <input 
                                type="range" min="-1" max="1" step="0.1" 
                                value={track.pan} 
                                onChange={(e) => onUpdate(track.id, { pan: parseFloat(e.target.value) })}
                                className="absolute w-full h-full opacity-0 cursor-pointer" 
                            />
                        </div>
                        {isWide && <span className="text-[8px] font-mono text-slate-400 w-8 text-right">{track.pan.toFixed(1)}</span>}
                    </div>
                </div>
            )}
       </div>

       {/* --- EXPANDED FX RACK (HOLOGRAPHIC) --- */}
       {track.isExpanded && !isCollapsed && (
           <div className="flex-1 overflow-y-auto overflow-x-hidden relative bg-black/40 backdrop-blur-md animate-in slide-in-from-left duration-300">
               <div className="py-4 px-2 flex flex-col items-center space-y-4 relative z-10">

                   {/* Modules styled as glass panes */}
                   {[
                       { title: "DEEP DRIVE", color: "orange", children: (
                           <div className="flex justify-between items-center px-1">
                                <Knob value={track.fx.saturation} min={0} max={100} label="DRIVE" color="orange" size={36} onChange={(v) => updateFX('saturation', v)} />
                                <Knob value={track.fx.distortionTone || 20000} min={1000} max={20000} label="TONE" color="orange" size={28} onChange={(v) => updateFX('distortionTone', v)} />
                           </div>
                       )},
                       { title: "EQ MATRIX", color: "cyan", children: (
                           <div className="flex justify-between px-1 space-x-1">
                               <Slider value={track.fx.eqHigh} min={-12} max={12} label="HI" color="cyan" height={50} onChange={(v) => updateFX('eqHigh', v)} />
                               <Slider value={track.fx.eqMid} min={-12} max={12} label="MID" color="cyan" height={50} onChange={(v) => updateFX('eqMid', v)} />
                               <Slider value={track.fx.eqLow} min={-12} max={12} label="LO" color="cyan" height={50} onChange={(v) => updateFX('eqLow', v)} />
                           </div>
                       )},
                       { title: "COMPRESSOR", color: "yellow", children: (
                            <div className="flex justify-between px-2">
                                <Knob value={track.fx.compressorThreshold} min={-60} max={0} label="THR" color="yellow" size={36} onChange={(v) => updateFX('compressorThreshold', v)} />
                                <Knob value={track.fx.compressorRatio} min={1} max={20} label="RAT" color="yellow" size={36} onChange={(v) => updateFX('compressorRatio', v)} />
                            </div>
                       )},
                       { title: "SPATIAL SENDS", color: "purple", children: (
                           <div className="flex justify-between px-1">
                                <Knob value={track.fx.sendReverb} min={0} max={1} label="VERB" color="purple" size={32} onChange={(v) => updateFX('sendReverb', v)} />
                                <Knob value={track.fx.sendDelay} min={0} max={1} label="ECHO" color="blue" size={32} onChange={(v) => updateFX('sendDelay', v)} />
                           </div>
                       )}
                   ].map((mod, i) => (
                       <div key={i} className="w-full bg-white/5 rounded-lg border border-white/5 p-3 shadow-[0_4px_20px_rgba(0,0,0,0.5)]">
                            <div className="text-[9px] font-black tracking-[0.2em] text-center mb-3 text-white/50">{mod.title}</div>
                            {mod.children}
                       </div>
                   ))}

               </div>
           </div>
       )}
    </div>
  );
};

export interface TrackFX {
  eqLow: number; // dB
  eqMid: number; // dB
  eqHigh: number; // dB
  compressorThreshold: number; // dB
  compressorRatio: number; // Ratio

  // Distortion
  saturation: number; // Coarse (0-100)
  saturationFine: number; // Fine (0-10)
  distortionTone: number; // Hz (LPF)

  // Cabinet
  cabinetOn: boolean;
  cabinetTone: number; // 0-1 (Brightness)

  // Sends
  sendReverb: number; // 0-1
  reverbTone: number; // 0-1 (Tone on send)
  sendDelay: number; // 0-1

  highPassFreq: number; // Hz
}

export interface ClipFX {
  gain: number; // 0-2 (1 is unity)
  pitch: number; // Playback rate: 0.5 to 2.0
  pan: number; // -1 to 1
  isReversed: boolean;

  // New DSP
  filterFreq: number; // 20 to 20000 Hz
  filterRes: number; // 0 to 20
  saturation: number; // 0 to 100
}

export type WaveformMode = 'PCM' | 'SEPARATED_SINES' | 'SPECTRAL_FLUX_3D' | 'HYPER_DIMENSIONAL_4D';

export interface ClipViewConfig {
    mode: WaveformMode;
    resolution: number; // 1 to 5 (FFT Size Multiplier)
    scale: number; // 0.5 to 3.0 (Vertical/Depth scale)
}

export interface Track {
  id: string;
  name: string;
  color: string;
  muted: boolean;
  solo: boolean;
  armed: boolean;
  volume: number;
  pan: number;
  fx: TrackFX; // Nested FX state
  isExpanded: boolean; // UI State
}

export interface AudioClip {
  id: string;
  trackId: string;
  buffer: AudioBuffer;
  startTime: number;
  duration: number;
  offset: number;
  name: string;
  fx: ClipFX; // Nested Clip FX
  viewConfig: ClipViewConfig; // Visualization Settings
}

export interface ProjectMetadata {
  title: string;
  artist: string;
  album: string;
  year: string;
}

export enum EditMode {
  MOVE = 'MOVE',
  SPLIT = 'SPLIT',
  DELETE = 'DELETE'
}

export interface ViewSettings {
    showTransport: boolean; // Mute, Solo, Arm
    showMix: boolean;       // Volume, Pan
    showRack: boolean;      // The "FX" button
    isCollapsed: boolean;   // Master toggle for the whole strip
}

export interface DSPState {
  // Master Output
  masterVolume: number; // 0 to 1.5

  // Master Filter
  masterFilterFreq: number; // 20 to 20000 Hz
  masterFilterRes: number; // 0 to 20
  masterFilterBypass: boolean; 

  // Master EQ
  masterEqLow: number; // -12 to 12 dB
  masterEqMid: number; // -12 to 12 dB
  masterEqHigh: number; // -12 to 12 dB
  masterEqBypass: boolean;

  // Master Saturation
  masterSaturation: number; // 0 to 100
  masterSaturationBypass: boolean;

  // Master Exciter
  masterExciterDrive: number; // 0 to 1
  masterExciterBypass: boolean;

  // Master Stereo Width
  masterStereoWidth: number; // 0 to 2 (1 = normal, 0 = mono, 2 = wide)
  masterStereoBypass: boolean;

  // Master Dynamics
  masterCompressorThreshold: number; // -60 to 0 dB
  masterCompressorRatio: number; // 1 to 20
  masterCompressorBypass: boolean;

  // Master Spatial (Returns)
  delayTime: number; // 0 to 1.0 s
  delayFeedback: number; // 0 to 0.9
  reverbMix: number; // 0 to 1 (Return Gain)
  masterSpatialBypass: boolean;

  // Legacy
  limiterThreshold: number;
  reverbDecay: number; 
}

import { DSPState, Track, AudioClip, TrackFX, ClipFX } from '../types';

interface TrackChannel {
  input: GainNode;
  hpf: BiquadFilterNode;
  eqLow: BiquadFilterNode;
  eqMid: BiquadFilterNode;
  eqHigh: BiquadFilterNode;

  // Distortion Chain
  drive: WaveShaperNode;
  distTone: BiquadFilterNode; // Post-drive tone

  // Cabinet Chain
  cabHpf: BiquadFilterNode;
  cabLpf: BiquadFilterNode;

  compressor: DynamicsCompressorNode;

  // Sends
  reverbTone: BiquadFilterNode; // Tone before send
  sendReverb: GainNode;
  sendDelay: GainNode;

  panner: StereoPannerNode;
  output: GainNode; // Post-fader, connects to Master
}

interface ActiveClipResource {
    source: AudioBufferSourceNode;
    drive: WaveShaperNode;
    filter: BiquadFilterNode;
    gain: GainNode;
    pan: StereoPannerNode;
}

export class AudioEngine {
  public ctx: AudioContext;
  public analyser: AnalyserNode;

  // Master Bus Nodes
  private masterInput: GainNode; // Summing point

  // 1. Dynamics & Color
  private masterFilter: BiquadFilterNode;
  private masterEqLow: BiquadFilterNode;
  private masterEqMid: BiquadFilterNode;
  private masterEqHigh: BiquadFilterNode;
  private masterDrive: WaveShaperNode;

  // 2. Exciter (Parallel)
  private exciterSplit: GainNode;
  private exciterHpf: BiquadFilterNode;
  private exciterDrive: WaveShaperNode;
  private exciterGain: GainNode;
  private exciterMerge: GainNode;

  // 3. Dynamics
  private masterCompressor: DynamicsCompressorNode;

  // 4. Stereo Imaging (M/S Matrix)
  private msSplitter: ChannelSplitterNode;
  private msMerger: ChannelMergerNode;
  private midGain: GainNode;
  private sideGain: GainNode;

  // 5. Output
  private masterGain: GainNode;
  private limiterNode: DynamicsCompressorNode;

  // Aux Returns (Global)
  private reverbNode: ConvolverNode;
  private delayNode: DelayNode;
  private delayFeedback: GainNode;
  private returnReverbGain: GainNode;
  private returnDelayGain: GainNode;

  // Track Management
  private trackChannels: Map<string, TrackChannel> = new Map();
  private activeClipResources: Map<string, ActiveClipResource> = new Map();

  private stream: MediaStream | null = null;
  private mediaRecorder: MediaRecorder | null = null;

  // Export
  private exportDest: MediaStreamAudioDestinationNode;

  constructor() {
    const AudioContextClass = (window.AudioContext || (window as any).webkitAudioContext);
    // Explicitly request high sample rate if possible, though browser handles this
    this.ctx = new AudioContextClass({ latencyHint: 'interactive', sampleRate: 48000 });

    // --- Master Chain Initialization ---
    this.masterInput = this.ctx.createGain();

    this.masterFilter = this.ctx.createBiquadFilter();
    this.masterEqLow = this.ctx.createBiquadFilter();
    this.masterEqMid = this.ctx.createBiquadFilter();
    this.masterEqHigh = this.ctx.createBiquadFilter();
    this.masterDrive = this.ctx.createWaveShaper();

    // Exciter
    this.exciterSplit = this.ctx.createGain();
    this.exciterHpf = this.ctx.createBiquadFilter();
    this.exciterDrive = this.ctx.createWaveShaper();
    this.exciterGain = this.ctx.createGain();
    this.exciterMerge = this.ctx.createGain();

    this.masterCompressor = this.ctx.createDynamicsCompressor();

    // Stereo Width (M/S)
    this.msSplitter = this.ctx.createChannelSplitter(2);
    this.msMerger = this.ctx.createChannelMerger(2);
    this.midGain = this.ctx.createGain();
    this.sideGain = this.ctx.createGain();

    this.masterGain = this.ctx.createGain();
    this.limiterNode = this.ctx.createDynamicsCompressor();
    this.analyser = this.ctx.createAnalyser();

    // Export Destination (for bouncing)
    this.exportDest = this.ctx.createMediaStreamDestination();

    // Node Configuration
    this.masterFilter.type = 'lowpass'; 
    this.masterFilter.Q.value = 0;

    this.masterEqLow.type = 'lowshelf';
    this.masterEqLow.frequency.value = 200;

    this.masterEqMid.type = 'peaking';
    this.masterEqMid.frequency.value = 1000;

    this.masterEqHigh.type = 'highshelf';
    this.masterEqHigh.frequency.value = 4000;

    // Exciter Config
    this.exciterHpf.type = 'highpass';
    this.exciterHpf.frequency.value = 3000;
    this.updateDriveCurve(this.exciterDrive, 50); // Fixed high drive for harmonics

    // Curve for saturation
    this.updateDriveCurve(this.masterDrive, 0);

    // Brickwall Limiter settings
    this.limiterNode.threshold.value = -0.5;
    this.limiterNode.knee.value = 0;
    this.limiterNode.ratio.value = 20;
    this.limiterNode.attack.value = 0.002;
    this.limiterNode.release.value = 0.1;

    // --- Master Routing ---
    // 1. Input -> Filter -> EQ -> Saturation
    this.masterInput.connect(this.masterFilter);
    this.masterFilter.connect(this.masterEqLow);
    this.masterEqLow.connect(this.masterEqMid);
    this.masterEqMid.connect(this.masterEqHigh);
    this.masterEqHigh.connect(this.masterDrive);

    // 2. Exciter Path (Parallel)
    this.masterDrive.connect(this.exciterSplit); // Dry path continues...

    // ...Wet Path
    this.exciterSplit.connect(this.exciterHpf);
    this.exciterHpf.connect(this.exciterDrive);
    this.exciterDrive.connect(this.exciterGain);
    this.exciterGain.connect(this.exciterMerge);

    // ...Merge Dry + Wet
    this.masterDrive.connect(this.exciterMerge);

    // 3. Compressor
    this.exciterMerge.connect(this.masterCompressor);

    // 4. Stereo Width (M/S Processing)
    this.masterCompressor.connect(this.msSplitter);
    this.msSplitter.connect(this.midGain, 0); // L+R
    this.msSplitter.connect(this.sideGain, 1); // L-R

    this.midGain.connect(this.msMerger, 0, 0);
    this.sideGain.connect(this.msMerger, 0, 1);

    this.msMerger.connect(this.masterGain);

    // 5. Output
    this.masterGain.connect(this.limiterNode);
    this.limiterNode.connect(this.analyser);
    this.analyser.connect(this.ctx.destination);
    this.limiterNode.connect(this.exportDest); 

    // --- Aux Sends Setup ---
    this.reverbNode = this.ctx.createConvolver();
    this.delayNode = this.ctx.createDelay(4.0);
    this.delayFeedback = this.ctx.createGain();
    this.returnReverbGain = this.ctx.createGain();
    this.returnDelayGain = this.ctx.createGain();

    this.reverbNode.connect(this.returnReverbGain);
    this.returnReverbGain.connect(this.masterInput);

    this.delayNode.connect(this.delayFeedback);
    this.delayFeedback.connect(this.delayNode); 
    this.delayNode.connect(this.returnDelayGain);
    this.returnDelayGain.connect(this.masterInput);

    this.generateImpulseResponse();
  }

  async resume() {
    if (this.ctx.state === 'suspended') {
      await this.ctx.resume();
    }
  }

  // Helper for safe parameter updates
  private safeSet(param: AudioParam, value: number, time: number, ramp: number = 0.05) {
      if (typeof value === 'number' && Number.isFinite(value)) {
          // Use setTargetAtTime for smooth exponential approach, avoiding clicks
          param.setTargetAtTime(value, time, ramp);
      }
  }

  // --- Track Graph Management ---

  ensureTrackChannel(track: Track) {
    if (this.trackChannels.has(track.id)) return;

    // Create Nodes
    const input = this.ctx.createGain();
    const hpf = this.ctx.createBiquadFilter();
    const eqLow = this.ctx.createBiquadFilter();
    const eqMid = this.ctx.createBiquadFilter();
    const eqHigh = this.ctx.createBiquadFilter();
    const drive = this.ctx.createWaveShaper();
    const distTone = this.ctx.createBiquadFilter();

    const cabHpf = this.ctx.createBiquadFilter();
    const cabLpf = this.ctx.createBiquadFilter();

    const compressor = this.ctx.createDynamicsCompressor();

    const reverbTone = this.ctx.createBiquadFilter();
    const sendReverb = this.ctx.createGain();
    const sendDelay = this.ctx.createGain();
    const panner = this.ctx.createStereoPanner();
    const output = this.ctx.createGain();

    // Config Nodes
    hpf.type = 'highpass';
    hpf.frequency.value = 20;

    eqLow.type = 'lowshelf';
    eqLow.frequency.value = 200;
    eqMid.type = 'peaking';
    eqMid.frequency.value = 1000;
    eqHigh.type = 'highshelf';
    eqHigh.frequency.value = 4000;

    distTone.type = 'lowpass';
    distTone.frequency.value = 20000;

    cabHpf.type = 'highpass';
    cabHpf.frequency.value = 80; 
    cabLpf.type = 'lowpass';
    cabLpf.frequency.value = 5000; 

    reverbTone.type = 'highpass'; 
    reverbTone.frequency.value = 100;

    this.updateDriveCurve(drive, 0);

    // Graph Connection:
    input.connect(hpf);
    hpf.connect(eqLow);
    eqLow.connect(eqMid);
    eqMid.connect(eqHigh);
    eqHigh.connect(drive);
    drive.connect(distTone);
    distTone.connect(cabHpf);
    cabHpf.connect(cabLpf);
    cabLpf.connect(compressor);
    compressor.connect(output); 

    // Aux Sends
    compressor.connect(reverbTone);
    reverbTone.connect(sendReverb);
    sendReverb.connect(this.reverbNode);

    compressor.connect(sendDelay);
    sendDelay.connect(this.delayNode);

    // Fader & Pan
    output.connect(panner);
    panner.connect(this.masterInput);

    // Store
    this.trackChannels.set(track.id, {
        input, hpf, eqLow, eqMid, eqHigh, drive, distTone, 
        cabHpf, cabLpf, compressor, 
        reverbTone, sendReverb, sendDelay, panner, output
    });

    // Apply Initial State
    this.updateTrackState(track);
  }

  updateTrackState(track: Track) {
    const ch = this.trackChannels.get(track.id);
    if (!ch) return;

    const t = this.ctx.currentTime;
    const ramp = 0.05;

    // Fader / Pan
    const vol = track.muted ? 0 : track.volume;
    this.safeSet(ch.output.gain, vol, t, ramp);
    this.safeSet(ch.panner.pan, track.pan, t, ramp);

    // FX
    const fx = track.fx;
    this.safeSet(ch.hpf.frequency, fx.highPassFreq, t, ramp);

    this.safeSet(ch.eqLow.gain, fx.eqLow, t, ramp);
    this.safeSet(ch.eqMid.gain, fx.eqMid, t, ramp);
    this.safeSet(ch.eqHigh.gain, fx.eqHigh, t, ramp);

    this.safeSet(ch.compressor.threshold, fx.compressorThreshold, t, ramp);
    this.safeSet(ch.compressor.ratio, fx.compressorRatio, t, ramp);

    const totalSat = (fx.saturation || 0) + (fx.saturationFine || 0);
    this.updateDriveCurve(ch.drive, totalSat);

    const distToneFreq = fx.distortionTone || 20000;
    this.safeSet(ch.distTone.frequency, Math.max(100, distToneFreq), t, ramp);

    // Cabinet Logic
    if (fx.cabinetOn) {
        this.safeSet(ch.cabHpf.frequency, 80, t, ramp);
        const lpfFreq = 2000 + (fx.cabinetTone * 6000); 
        this.safeSet(ch.cabLpf.frequency, lpfFreq, t, ramp);
    } else {
        this.safeSet(ch.cabHpf.frequency, 0, t, ramp);
        this.safeSet(ch.cabLpf.frequency, 22000, t, ramp);
    }

    // Sends
    this.safeSet(ch.sendReverb.gain, fx.sendReverb, t, ramp);

    const revToneFreq = 20 + (fx.reverbTone * 1000);
    this.safeSet(ch.reverbTone.frequency, revToneFreq, t, ramp);

    this.safeSet(ch.sendDelay.gain, fx.sendDelay, t, ramp);
  }

  private updateDriveCurve(node: WaveShaperNode, amount: number) {
     if (!Number.isFinite(amount) || amount < 1) {
         node.curve = null;
         return;
     }
     const k = amount;
     const n_samples = 8192; // Optimized size
     const curve = new Float32Array(n_samples);
     for (let i = 0; i < n_samples; ++i) {
       const x = (i * 2) / n_samples - 1;
       curve[i] = (Math.PI + 50) * x / (Math.PI + 50 * Math.abs(x));
     }
     node.curve = curve;
     node.oversample = '4x'; // Ensure high quality
  }

  // --- Master DSP ---

  updateMasterDSP(state: DSPState) {
      const t = this.ctx.currentTime;
      const ramp = 0.05;

      // Master Fader
      this.safeSet(this.masterGain.gain, state.masterVolume, t, ramp);

      // 1. FILTER
      if (state.masterFilterBypass) {
          this.safeSet(this.masterFilter.frequency, 22000, t, ramp);
          this.safeSet(this.masterFilter.Q, 0, t, ramp);
      } else {
          const safeFreq = Math.max(20, Math.min(22000, state.masterFilterFreq || 20000));
          this.safeSet(this.masterFilter.frequency, safeFreq, t, ramp);
          this.safeSet(this.masterFilter.Q, state.masterFilterRes || 0, t, ramp);
      }

      // 2. EQ
      if (state.masterEqBypass) {
          this.safeSet(this.masterEqLow.gain, 0, t, ramp);
          this.safeSet(this.masterEqMid.gain, 0, t, ramp);
          this.safeSet(this.masterEqHigh.gain, 0, t, ramp);
      } else {
          this.safeSet(this.masterEqLow.gain, state.masterEqLow, t, ramp);
          this.safeSet(this.masterEqMid.gain, state.masterEqMid, t, ramp);
          this.safeSet(this.masterEqHigh.gain, state.masterEqHigh, t, ramp);
      }

      // 3. SATURATION
      if (state.masterSaturationBypass) {
          this.updateDriveCurve(this.masterDrive, 0);
      } else {
          this.updateDriveCurve(this.masterDrive, state.masterSaturation || 0);
      }

      // 4. EXCITER (Parallel)
      const exciterDrive = state.masterExciterDrive !== undefined ? state.masterExciterDrive : 0;
      if (state.masterExciterBypass) {
          this.safeSet(this.exciterGain.gain, 0, t, ramp);
      } else {
          this.safeSet(this.exciterGain.gain, exciterDrive * 0.5, t, ramp); 
      }

      // 5. DYNAMICS
      if (state.masterCompressorBypass) {
          this.safeSet(this.masterCompressor.threshold, 0, t, ramp);
          this.safeSet(this.masterCompressor.ratio, 1, t, ramp);
      } else {
          this.safeSet(this.masterCompressor.threshold, state.masterCompressorThreshold, t, ramp);
          this.safeSet(this.masterCompressor.ratio, state.masterCompressorRatio, t, ramp);
      }

      // 6. STEREO WIDTH
      if (state.masterStereoBypass) {
          // Mid = 1, Side = 0 (Mono) -- Wait, bypass means unity which is usually stereo preserved?
          // No, stereo width param: 1=Normal. Bypass implies default state (1).
          this.safeSet(this.midGain.gain, 1, t, ramp);
          this.safeSet(this.sideGain.gain, 1, t, ramp);
      } else {
          // MS matrix: Width > 1 boosts side, Width < 1 attenuates side
          const width = state.masterStereoWidth ?? 1;
          // Simplified width control:
          // Width = 0 -> Mid=1, Side=0
          // Width = 1 -> Mid=1, Side=1
          // Width = 2 -> Mid=0.5, Side=1.5 (Exaggerated)
          // Adjust logic for better feeling:
          if (width <= 1) {
              this.safeSet(this.midGain.gain, 1, t, ramp);
              this.safeSet(this.sideGain.gain, width, t, ramp);
          } else {
              this.safeSet(this.midGain.gain, 2 - width, t, ramp);
              this.safeSet(this.sideGain.gain, 1 + (width-1)*0.5, t, ramp);
          }
      }

      // 7. SPATIAL (Returns)
      if (state.masterSpatialBypass) {
          this.safeSet(this.returnDelayGain.gain, 0, t, ramp); 
          this.safeSet(this.returnReverbGain.gain, 0, t, ramp);
      } else {
          this.safeSet(this.delayNode.delayTime, state.delayTime, t, ramp);
          this.safeSet(this.delayFeedback.gain, state.delayFeedback, t, ramp);
          this.safeSet(this.returnDelayGain.gain, 0.7, t, ramp); 
          this.safeSet(this.returnReverbGain.gain, state.reverbMix, t, ramp);
      }
  }

  // --- Playback ---

  playClip(clip: AudioClip, projectTime: number) {
    const ch = this.trackChannels.get(clip.trackId);
    if (!ch) return; 

    const clipStart = clip.startTime;
    const clipEnd = clip.startTime + (clip.duration / clip.fx.pitch); 

    if (clipEnd <= projectTime) return;

    const source = this.ctx.createBufferSource();

    // Reverse Logic
    if (clip.fx.isReversed) {
        const original = clip.buffer;
        const reversed = this.ctx.createBuffer(original.numberOfChannels, original.length, original.sampleRate);
        for(let c=0; c<original.numberOfChannels; c++) {
            const dest = reversed.getChannelData(c);
            const src = original.getChannelData(c);
            for(let i=0; i<original.length; i++) dest[i] = src[original.length - 1 - i];
        }
        source.buffer = reversed;
    } else {
        source.buffer = clip.buffer;
    }

    source.playbackRate.value = clip.fx.pitch;

    // --- Per-Clip FX Chain ---
    // Source -> Drive -> Filter -> Gain -> Pan -> Track Input
    const clipDrive = this.ctx.createWaveShaper();
    const clipFilter = this.ctx.createBiquadFilter();
    const clipGain = this.ctx.createGain();
    const clipPan = this.ctx.createStereoPanner();

    // Init FX Params
    this.updateDriveCurve(clipDrive, clip.fx.saturation || 0);

    clipFilter.type = 'lowpass';
    const freq = clip.fx.filterFreq ?? 20000;
    const res = clip.fx.filterRes ?? 0;
    clipFilter.frequency.value = freq;
    clipFilter.Q.value = res;

    clipGain.gain.value = clip.fx.gain;
    clipPan.pan.value = clip.fx.pan;

    // Connect Chain
    source.connect(clipDrive);
    clipDrive.connect(clipFilter);
    clipFilter.connect(clipGain);
    clipGain.connect(clipPan);
    clipPan.connect(ch.input);

    // Schedule
    let startWhen = 0;
    let startOffset = 0;
    let duration = 0;
    const rate = clip.fx.pitch;

    if (clipStart >= projectTime) {
        startWhen = clipStart - projectTime;
        startOffset = clip.offset;
        duration = clip.duration;
    } else {
        const timeIntoClip = (projectTime - clipStart) * rate; 
        startWhen = 0;
        startOffset = clip.offset + timeIntoClip;
        duration = clip.duration - (timeIntoClip / rate);
    }

    if (duration > 0 && startOffset < source.buffer.duration) {
        source.start(this.ctx.currentTime + startWhen, startOffset, duration);

        const resource: ActiveClipResource = {
            source,
            drive: clipDrive,
            filter: clipFilter,
            gain: clipGain,
            pan: clipPan
        };
        this.activeClipResources.set(clip.id, resource);

        source.onended = () => {
             this.activeClipResources.delete(clip.id);
        };
    }
  }

  updateClipParams(clipId: string, fx: Partial<ClipFX>) {
      const res = this.activeClipResources.get(clipId);
      if (!res) return; 

      const t = this.ctx.currentTime;
      const ramp = 0.05;

      // Validate inputs strictly to prevent NaN propagation
      if (typeof fx.gain === 'number' && Number.isFinite(fx.gain)) {
          this.safeSet(res.gain.gain, fx.gain, t, ramp);
      }
      if (typeof fx.pan === 'number' && Number.isFinite(fx.pan)) {
          // Clamp pan -1 to 1
          this.safeSet(res.pan.pan, Math.max(-1, Math.min(1, fx.pan)), t, ramp);
      }
      if (typeof fx.pitch === 'number' && Number.isFinite(fx.pitch)) {
          // Prevent rate 0 or negative which can crash some implementations
          this.safeSet(res.source.playbackRate, Math.max(0.1, fx.pitch), t, ramp);
      }

      if (typeof fx.filterFreq === 'number' && Number.isFinite(fx.filterFreq)) {
          this.safeSet(res.filter.frequency, Math.max(10, Math.min(22000, fx.filterFreq)), t, ramp);
      }
      if (typeof fx.filterRes === 'number' && Number.isFinite(fx.filterRes)) {
          this.safeSet(res.filter.Q, fx.filterRes, t, ramp);
      }

      if (typeof fx.saturation === 'number' && Number.isFinite(fx.saturation)) {
          this.updateDriveCurve(res.drive, fx.saturation);
      }
  }

  stopAll() {
    this.activeClipResources.forEach(r => { try { r.source.stop(); } catch(e){} });
    this.activeClipResources.clear();
  }

  // --- Recording ---

  async startRecording(monitor: boolean): Promise<void> {
    await this.resume();
    this.stream = await navigator.mediaDevices.getUserMedia({ 
        audio: { 
            echoCancellation: false, 
            latency: 0 
        } as any 
    });
    this.mediaRecorder = new MediaRecorder(this.stream);
    this.mediaRecorder.start();
  }

  async stopRecording(): Promise<Blob> {
    return new Promise((resolve, reject) => {
      // Safety check for recorder state
      if (!this.mediaRecorder || this.mediaRecorder.state === 'inactive') {
          return reject('Recorder inactive or not initialized');
      }

      const chunks: BlobPart[] = [];
      this.mediaRecorder.ondataavailable = (e) => chunks.push(e.data);
      this.mediaRecorder.onstop = () => {
        const blob = new Blob(chunks, { type: 'audio/ogg; codecs=opus' });
        this.stream?.getTracks().forEach(track => track.stop());
        resolve(blob);
      };
      this.mediaRecorder.stop();
    });
  }

  async decodeAudioData(blob: Blob): Promise<AudioBuffer> {
    const buf = await blob.arrayBuffer();
    return await this.ctx.decodeAudioData(buf);
  }

  // --- Bounce / Export ---

  startBounceRecorder(): void {
      const stream = this.exportDest.stream;
      let options = { mimeType: 'audio/webm;codecs=opus' };
      if (MediaRecorder.isTypeSupported('audio/mp4')) {
          options = { mimeType: 'audio/mp4' };
      }

      try {
        this.mediaRecorder = new MediaRecorder(stream, options);
      } catch (e) {
          this.mediaRecorder = new MediaRecorder(stream);
      }

      this.mediaRecorder.start();
  }

  async stopBounceRecorder(): Promise<Blob> {
      return new Promise((resolve, reject) => {
          if (!this.mediaRecorder || this.mediaRecorder.state === 'inactive') return reject('No active export');

          const chunks: BlobPart[] = [];
          this.mediaRecorder.ondataavailable = (e) => {
              if (e.data.size > 0) chunks.push(e.data);
          };
          this.mediaRecorder.onstop = () => {
              const type = this.mediaRecorder?.mimeType || 'audio/mp4';
              const blob = new Blob(chunks, { type });
              resolve(blob);
          };
          this.mediaRecorder.stop();
      });
  }

  private generateImpulseResponse() {
    const rate = this.ctx.sampleRate;
    const length = rate * 2.0;
    const impulse = this.ctx.createBuffer(2, length, rate);
    const L = impulse.getChannelData(0);
    const R = impulse.getChannelData(1);
    for (let i = 0; i < length; i++) {
        const decay = Math.pow(1 - i / length, 4);
        L[i] = (Math.random() * 2 - 1) * decay;
        R[i] = (Math.random() * 2 - 1) * decay;
    }
    this.reverbNode.buffer = impulse;
  }
}

export const audioEngine = new AudioEngine();

import React, { useEffect, useRef } from 'react';
import { DSPState } from '../types';
import { Knob } from './Knob';
import { Slider } from './Slider';
import { audioEngine } from '../services/audioEngine';

interface DSPRackProps {
  dspState: DSPState;
  onChange: (newState: DSPState) => void;
}

// ... (Numerical Analysis functions kept same) ...
const calculateFilterMagnitude = (freq: number, res: number) => {
    const steps = 12;
    const bars = [];
    for(let i=0; i<steps; i++) {
        const f = 20 * Math.pow(1000, i / (steps-1));
        const ratio = f / freq;
        const mag = 1 / Math.sqrt(Math.pow(1 - ratio*ratio, 2) + Math.pow(ratio/(0.707 + res), 2));
        bars.push(Math.min(1.2, mag)); 
    }
    return bars;
};
const calculateSaturatorShape = (drive: number) => {
    const bars = [];
    const k = drive;
    for(let i=0; i<12; i++) {
        const x = (i / 11) * 2 - 1; 
        let y = x;
        if (k > 0) y = ((Math.PI + k) * x) / (Math.PI + k * Math.abs(x));
        bars.push((y + 1) / 2);
    }
    return bars;
};
const calculateHarmonicsShape = (drive: number) => {
    const bars = new Array(12).fill(0);
    bars[0] = 0.8;
    for(let i=1; i<12; i++) {
       if (i % 2 !== 0) bars[i] = (drive / 100) * (1 / i) * 2; 
       else bars[i] = (drive / 100) * (1 / (i*2));
    }
    return bars;
};
const calculateEQShape = (low: number, mid: number, high: number) => {
    const bars = [];
    for(let i=0; i<12; i++) {
        let gain = 0;
        if (i < 4) gain = low; else if (i < 8) gain = mid; else gain = high;
        if (i===3 || i===4) gain = (low + mid)/2;
        if (i===7 || i===8) gain = (mid + high)/2;
        bars.push((gain + 12) / 24);
    }
    return bars;
};
const calculateDynamicsShape = (thresh: number, ratio: number) => {
    const bars = [];
    for(let i=0; i<12; i++) {
        const inDB = -60 + (i/11) * 60; 
        let outDB = inDB;
        if (inDB > thresh) outDB = thresh + (inDB - thresh) / ratio;
        bars.push((outDB + 60) / 60);
    }
    return bars;
};
const calculateSpatialShape = (time: number, feedback: number, mix: number) => {
    const bars = new Array(12).fill(0);
    bars[0] = 1.0; 
    const delayStep = Math.max(1, Math.round(time * 5)); 
    for (let i = 0; i < 12; i+=delayStep) {
       const decay = Math.pow(feedback, i/delayStep);
       if(i < 12) bars[i] = decay;
    }
    return bars.map(b => b * (0.3 + mix * 0.7));
};
const calculateOutputShape = (vol: number, dataArray: Uint8Array) => {
    if (!dataArray) return new Array(12).fill(0);
    let sum = 0;
    for(let i=0; i<dataArray.length; i++) sum += dataArray[i] * dataArray[i];
    const rms = Math.sqrt(sum / dataArray.length) / 255;
    const level = Math.min(1, rms * vol * 2.5);
    return Array(12).fill(0).map((_, i) => (level > i/12 ? 1 : 0));
};

const drawPixelLeds = (ctx: CanvasRenderingContext2D, width: number, height: number, bars: number[], colorHex: string, bypassed: boolean) => {
    ctx.clearRect(0, 0, width, height);

    // Dim visualizations if bypassed
    const dimFactor = bypassed ? 0.2 : 1.0;

    const numCols = 12; const numRows = 8;
    const gap = 2;
    const colWidth = (width - ((numCols - 1) * gap)) / numCols;
    const rowHeight = (height - ((numRows - 1) * gap)) / numRows;

    // Draw Phantom Grid (Off Pixels)
    ctx.fillStyle = '#111';
    for (let c = 0; c < numCols; c++) {
        for (let r = 0; r < numRows; r++) {
             const rowIndex = (numRows - 1) - r;
             ctx.fillRect(c * (colWidth + gap), rowIndex * (rowHeight + gap), colWidth, rowHeight);
        }
    }

    for (let c = 0; c < numCols; c++) {
        const value = bars[c] || 0; 
        const activeHeight = value * numRows;

        for (let r = 0; r < numRows; r++) {
             const rowIndex = (numRows - 1) - r;
             const y = rowIndex * (rowHeight + gap);
             const x = c * (colWidth + gap);

             let intensity = 0;
             if (r < Math.floor(activeHeight)) intensity = 1.0;
             else if (r < activeHeight) intensity = activeHeight - r;

             if (intensity > 0) {
                 ctx.fillStyle = colorHex;
                 ctx.globalAlpha = intensity * dimFactor;
                 ctx.shadowBlur = bypassed ? 0 : 4;
                 ctx.shadowColor = colorHex;
                 ctx.fillRect(x, y, colWidth, rowHeight);

                 // Inner LED Core
                 if (intensity > 0.6) {
                    ctx.fillStyle = '#ffffff';
                    ctx.globalAlpha = 0.5 * dimFactor;
                    ctx.shadowBlur = 0;
                    ctx.fillRect(x + 2, y + 2, colWidth - 4, rowHeight - 4);
                 }
                 ctx.shadowBlur = 0;
             }
        }
    }
    ctx.globalAlpha = 1.0;
};

const RackModule: React.FC<{
  title: string;
  type: 'filter' | 'saturator' | 'exciter' | 'eq' | 'dynamics' | 'spatial' | 'width' | 'output';
  color: string;
  dspState: DSPState;
  children: React.ReactNode;
  isBypassed?: boolean;
  onToggleBypass?: () => void;
}> = ({ title, type, color, dspState, children, isBypassed = false, onToggleBypass }) => {

  const canvasRef = useRef<HTMLCanvasElement>(null);

  const colorMap: Record<string, string> = {
    pink: '#ff00d4', orange: '#ff6600', blue: '#2f80ed',
    yellow: '#ffcc00', purple: '#b721ff', cyan: '#00f0ff',
    red: '#ff003c', green: '#0aff60',
  };
  const hexColor = colorMap[color] || '#3b82f6';

  useEffect(() => {
     const canvas = canvasRef.current;
     if(!canvas) return;
     const ctx = canvas.getContext('2d');
     if(!ctx) return;

     let frameId: number;
     const dataArray = new Uint8Array(audioEngine.analyser.frequencyBinCount);

     const render = () => {
         frameId = requestAnimationFrame(render);
         audioEngine.analyser.getByteFrequencyData(dataArray);
         const w = canvas.width;
         const h = canvas.height;
         let bars: number[] = [];

         if (type === 'filter') bars = calculateFilterMagnitude(dspState.masterFilterFreq, dspState.masterFilterRes);
         else if (type === 'saturator') bars = calculateSaturatorShape(dspState.masterSaturation);
         else if (type === 'exciter') bars = calculateHarmonicsShape(dspState.masterExciterDrive * 100);
         else if (type === 'eq') bars = calculateEQShape(dspState.masterEqLow, dspState.masterEqMid, dspState.masterEqHigh);
         else if (type === 'dynamics') bars = calculateDynamicsShape(dspState.masterCompressorThreshold, dspState.masterCompressorRatio);
         else if (type === 'spatial') bars = calculateSpatialShape(dspState.delayTime, dspState.delayFeedback, dspState.reverbMix);
         else if (type === 'width') { const w = dspState.masterStereoWidth; bars = [w/2, w/2, w/2, w/2, 0.1, 0.1, 0.1, 0.1, w/2, w/2, w/2, w/2]; }
         else if (type === 'output') bars = calculateOutputShape(dspState.masterVolume, dataArray);

         drawPixelLeds(ctx, w, h, bars, hexColor, !!isBypassed);
     };
     render();
     return () => cancelAnimationFrame(frameId);
  }, [type, dspState, hexColor, isBypassed]);

  return (
    <div className={`flex flex-col h-full backdrop-blur-md border-r border-white/5 relative group min-w-[170px] overflow-hidden transition-colors ${isBypassed ? 'bg-black/40' : 'bg-white/5'}`}>

