import React, { useState, useRef, useEffect } from 'react';

interface KnobProps {
  value: number;
  min: number;
  max: number;
  onChange: (val: number) => void;
  label: string;
  color?: string;
  size?: number;
}

export const Knob: React.FC<KnobProps> = ({ value, min, max, onChange, label, color = 'cyan', size = 46 }) => {
  const [isDragging, setIsDragging] = useState(false);
  const startY = useRef(0);
  const startVal = useRef(0);

  // Sanitize input value immediately
  const safeValue = Math.min(max, Math.max(min, Number.isFinite(value) ? value : min));

  const handleStart = (clientY: number) => {
    setIsDragging(true);
    startY.current = clientY;
    startVal.current = safeValue;
  };

  const handleMove = (clientY: number) => {
    if (!isDragging) return;
    const delta = startY.current - clientY;
    const range = max - min;

    // Sensitivity: 200px drag = full range
    const sensitivity = 200; 
    const change = (delta / sensitivity) * range;

    let newVal = startVal.current + change;

    // Hard Clamp
    newVal = Math.max(min, Math.min(max, newVal));

    // Quantize slightly to avoid floating point noise if needed, but smooth is better for DSP
    onChange(newVal);
  };

  const handleEnd = () => {
    setIsDragging(false);
  };

  useEffect(() => {
    if (isDragging) {
      const mouseMove = (e: MouseEvent) => { e.preventDefault(); handleMove(e.clientY); };
      const touchMove = (e: TouchEvent) => { e.preventDefault(); handleMove(e.touches[0].clientY); };
      const end = () => handleEnd();

      window.addEventListener('mousemove', mouseMove, { passive: false });
      window.addEventListener('touchmove', touchMove, { passive: false });
      window.addEventListener('mouseup', end);
      window.addEventListener('touchend', end);

      return () => {
        window.removeEventListener('mousemove', mouseMove);
        window.removeEventListener('touchmove', touchMove);
        window.removeEventListener('mouseup', end);
        window.removeEventListener('touchend', end);
      };
    }
  }, [isDragging]);

  const percentage = (safeValue - min) / (max - min);
  const angle = -135 + (percentage * 270);

  const colorMap: Record<string, string> = {
    cyan: '#00f0ff',
    blue: '#2f80ed',
    purple: '#b721ff',
    green: '#0aff60',
    yellow: '#ffcc00',
    orange: '#ff6600',
    red: '#ff003c',
    pink: '#ff00d4',
    white: '#ffffff'
  };
  const accentColor = colorMap[color] || colorMap['cyan'];

  return (
    <div 
      className="flex flex-col items-center justify-center select-none touch-none group relative py-2" // Increased padding
      onMouseDown={(e) => handleStart(e.clientY)}
      onTouchStart={(e) => handleStart(e.touches[0].clientY)}
      style={{ width: size + 24, cursor: isDragging ? 'ns-resize' : 'pointer' }} // Wider hitbox
    >
      <div className="relative flex items-center justify-center" style={{ width: size, height: size }}>

          {/* 1. Outer Tick Ring (Rotates) */}
          <div 
            className="absolute inset-0 rounded-full transition-transform duration-75 ease-out"
            style={{ 
                transform: `rotate(${angle}deg)`,
                opacity: 0.4
            }}
          >
             <div className="absolute top-0 left-1/2 -translate-x-1/2 w-0.5 h-1.5 bg-white shadow-[0_0_5px_white]"></div>
          </div>

          {/* 2. Static Backplate */}
          <div className="absolute inset-0 rounded-full bg-black shadow-[inset_0_1px_5px_rgba(255,255,255,0.1)] border border-white/5"></div>

          {/* 3. The Arc (SVG) */}
          <svg className="absolute top-0 left-0 w-full h-full rotate-90" style={{ transform: 'rotate(135deg)' }}>
             <circle 
                cx="50%" cy="50%" r="44%" 
                fill="none" 
                stroke="#111" 
                strokeWidth="3" 
             />
             <circle 
                cx="50%" cy="50%" r="44%" 
                fill="none" 
                stroke={accentColor} 
                strokeWidth="3"
                strokeDasharray={`${percentage * 206} 300`} 
                strokeLinecap="round"
                style={{ filter: `drop-shadow(0 0 4px ${accentColor})` }}
             />
          </svg>

          {/* 4. The Void Core (Inner Cap) */}
          <div 
            className="absolute rounded-full flex items-center justify-center overflow-hidden transition-all duration-200"
            style={{ 
                width: '70%', 
                height: '70%',
                background: `radial-gradient(circle at 30% 30%, #222, #000)`,
                boxShadow: isDragging 
                    ? `0 0 15px ${accentColor}40, inset 0 0 10px #000` 
                    : `0 5px 10px rgba(0,0,0,0.5), inset 0 0 2px rgba(255,255,255,0.2)`
            }}
          >
             {/* Core Glow */}
             <div 
                className="absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity duration-500"
                style={{
                    background: `radial-gradient(circle, ${accentColor}20 0%, transparent 70%)`
                }}
             ></div>

             {/* Numeric Value (Only on Drag/Hover) */}
             <span className={`text-[9px] font-mono font-bold text-white transition-opacity duration-200 ${isDragging ? 'opacity-100' : 'opacity-0'}`}>
                {safeValue.toFixed(Math.abs(max - min) < 10 ? 2 : 1)}
             </span>
          </div>

      </div>

      {/* Label */}
      <span 
        className="mt-2 text-[8px] font-bold tracking-widest uppercase transition-all duration-300"
        style={{ 
            color: isDragging ? accentColor : '#52525b',
            textShadow: isDragging ? `0 0 8px ${accentColor}` : 'none',
            letterSpacing: '0.1em'
        }}
      >
        {label}
      </span>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';

interface SliderProps {
  value: number;
  min: number;
  max: number;
  onChange: (val: number) => void;
  label: string;
  color?: string;
  height?: number;
}

export const Slider: React.FC<SliderProps> = ({ value, min, max, onChange, label, color = 'cyan', height = 110 }) => {
  const [isDragging, setIsDragging] = useState(false);
  const sliderRef = useRef<HTMLDivElement>(null);

  // Sanitize
  const safeValue = Math.min(max, Math.max(min, Number.isFinite(value) ? value : min));

  const updateValueFromPointer = (clientY: number) => {
    if (!sliderRef.current) return;
    const rect = sliderRef.current.getBoundingClientRect();
    const relativeY = rect.bottom - clientY;
    let percentage = relativeY / rect.height;

    // Clamp
    percentage = Math.max(0, Math.min(1, percentage));

    const newValue = min + (percentage * (max - min));
    onChange(newValue);
  };

  const handleStart = (clientY: number) => {
    setIsDragging(true);
    updateValueFromPointer(clientY);
  };

  const handleMove = (clientY: number) => {
    if (!isDragging) return;
    updateValueFromPointer(clientY);
  };

  const handleEnd = () => {
    setIsDragging(false);
  };

  useEffect(() => {
    if (isDragging) {
      const mouseMove = (e: MouseEvent) => { e.preventDefault(); handleMove(e.clientY); };
      const touchMove = (e: TouchEvent) => { e.preventDefault(); handleMove(e.touches[0].clientY); };
      const end = () => handleEnd();
      window.addEventListener('mousemove', mouseMove, { passive: false });
      window.addEventListener('touchmove', touchMove, { passive: false });
      window.addEventListener('mouseup', end);
      window.addEventListener('touchend', end);
      return () => {
        window.removeEventListener('mousemove', mouseMove);
        window.removeEventListener('touchmove', touchMove);
        window.removeEventListener('mouseup', end);
        window.removeEventListener('touchend', end);
      };
    }
  }, [isDragging]);

  const percentage = Math.max(0, Math.min(1, (safeValue - min) / (max - min)));

  const colorMap: Record<string, string> = {
    cyan: '#00f0ff',
    blue: '#2f80ed',
    purple: '#b721ff',
    green: '#0aff60',
    yellow: '#ffcc00',
    orange: '#ff6600',
    red: '#ff003c',
    pink: '#ff00d4',
    white: '#ffffff'
  };
  const accentColor = colorMap[color] || colorMap['cyan'];

  return (
    <div className="flex flex-col items-center justify-center space-y-2 select-none touch-none group">

      {/* Invisible Expanded Hitbox Container */}
      <div 
        ref={sliderRef}
        className="relative w-16 flex justify-center cursor-pointer py-2" // WIDER HITBOX
        style={{ height: height }}
        onMouseDown={(e) => handleStart(e.clientY)}
        onTouchStart={(e) => handleStart(e.touches[0].clientY)}
      >
        {/* The Physical Track (Glass Tube) */}
        <div className="absolute w-2 h-full bg-[#111] rounded-full overflow-hidden shadow-[inset_0_0_4px_rgba(0,0,0,0.8)] border border-white/5 pointer-events-none">
             {/* Background Grid inside tube */}
             <div className="absolute inset-0 opacity-30" 
                  style={{ 
                      backgroundImage: `linear-gradient(0deg, transparent 20%, ${accentColor} 21%, transparent 22%)`,
                      backgroundSize: '100% 10px' 
                  }}>
             </div>
        </div>

        {/* The Photon Beam (Fill) */}
        <div 
            className="absolute bottom-2 w-1 rounded-full transition-all duration-75 pointer-events-none"
            style={{ 
                height: `calc(${percentage * 100}% - 4px)`, 
                backgroundColor: accentColor,
                boxShadow: `0 0 10px ${accentColor}, 0 0 20px ${accentColor}`
            }}
        ></div>

        {/* The Prism (Thumb) */}
        <div 
            className="absolute w-10 h-6 flex items-center justify-center transition-all duration-75 z-20 pointer-events-none"
            style={{ bottom: `calc(${percentage * 100}% - 12px)` }}
        >
             {/* Light Flare */}
             <div 
                className="absolute w-full h-1 bg-white rounded-full blur-[2px] mix-blend-overlay"
                style={{ opacity: isDragging ? 1 : 0.5 }}
             ></div>

             {/* Physical Handle */}
             <div 
                className="w-full h-[3px] bg-white shadow-[0_0_5px_white,0_0_15px_currentColor]" 
                style={{ color: accentColor }}
             ></div>
        </div>

      </div>

      <span 
        className="text-[8px] font-bold tracking-widest uppercase transition-all duration-200"
        style={{ 
            color: isDragging ? accentColor : '#52525b',
            textShadow: isDragging ? `0 0 5px ${accentColor}` : 'none'
        }}
      >
        {label}
      </span>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Track, ViewSettings } from '../types';
import { COLORS, TRACK_HEIGHT, EXPANDED_TRACK_HEIGHT } from '../constants';
import { Knob } from './Knob';
import { Slider } from './Slider';

interface ChannelStripProps {
  track: Track;
  onUpdate: (id: string, updates: Partial<Track>) => void;
  onToggleArm: (id: string) => void;
  onToggleExpand: (id: string) => void;
  onDuplicate: (id: string) => void;
  width: number;
  viewSettings: ViewSettings;
  isCollapsed: boolean;
}

export const ChannelStrip: React.FC<ChannelStripProps> = ({ 
    track, onUpdate, onToggleArm, onToggleExpand, onDuplicate, 
    width, viewSettings, isCollapsed 
}) => {
  const [showColors, setShowColors] = useState(false);
  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setShowColors(false);
      }
    };
    if (showColors) document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [showColors]);

  const updateFX = (key: keyof typeof track.fx, value: any) => {
      onUpdate(track.id, {
          fx: { ...track.fx, [key]: value }
      });
  };

  const isWide = width > 200;

  return (
    <div 
        className="sticky left-0 z-20 flex flex-col transition-all duration-300 ease-out group shadow-[4px_0_20px_rgba(0,0,0,0.8)] overflow-hidden" 
        style={{ 
            width: width,
            height: track.isExpanded ? EXPANDED_TRACK_HEIGHT : TRACK_HEIGHT,
            background: '#0a0a0c',
            borderRight: `1px solid ${track.color}20`
        }}
    >
       {/* --- HEADER SECTION --- */}
       <div className="p-3 flex-shrink-0 flex flex-col relative" style={{ height: TRACK_HEIGHT }}>

            {/* Identity Row (Color, Name, Arm) */}
            <div className={`flex items-center gap-2 relative z-30 transition-all ${isCollapsed ? 'justify-center flex-col h-full space-y-4' : 'justify-between mb-2'}`}>

                {/* Color Dot */}
                <div className="relative flex-shrink-0" ref={menuRef}>
                    <button
                        className="w-3 h-3 rounded-full transition-all duration-300 hover:scale-125"
                        style={{ backgroundColor: track.color, boxShadow: `0 0 8px ${track.color}` }}
                        onClick={() => setShowColors(!showColors)}
                    />
                    {showColors && (
                    <div className="absolute top-full left-0 mt-2 bg-black/90 backdrop-blur-xl border border-white/10 p-2 rounded-lg grid grid-cols-4 gap-2 shadow-2xl z-50 w-32 animate-in zoom-in-95 duration-100">
                        {COLORS.map(c => (
                            <button key={c} className="w-5 h-5 rounded-full border border-white/10 hover:scale-110 transition-transform" style={{ backgroundColor: c, boxShadow: `0 0 10px ${c}` }}
                            onClick={(e) => { e.stopPropagation(); onUpdate(track.id, { color: c }); setShowColors(false); }} />
                        ))}
                    </div>
                    )}
                </div>

                {/* Name */}
                {!isCollapsed && (
                    <input
                        className="bg-transparent text-[13px] font-bold text-slate-200 w-full outline-none px-0.5 truncate tracking-wide focus:text-white placeholder-slate-600 font-mono transition-all"
                        value={track.name}
                        onChange={(e) => onUpdate(track.id, { name: e.target.value })}
                        style={{ opacity: width < 60 ? 0 : 1 }}
                    />
                )}

                {/* Arm Button */}
                <button 
                    onClick={() => onToggleArm(track.id)} 
                    className={`w-6 h-6 rounded-full flex-shrink-0 flex items-center justify-center transition-all ${track.armed ? 'bg-red-500/10 shadow-[0_0_15px_rgba(220,38,38,0.4)]' : 'bg-transparent hover:bg-white/5'}`}
                    title="Arm Track"
                >
                    <div className={`w-2.5 h-2.5 rounded-full transition-all ${track.armed ? 'bg-red-500 animate-pulse' : 'bg-slate-700'}`} />
                </button>
            </div>

            {/* --- TRANSPORT SECTION (Mute/Solo) --- */}
            {!isCollapsed && (
                <div className={`flex space-x-1 mb-3 transition-all duration-300 overflow-hidden ${viewSettings.showTransport ? 'opacity-100 max-h-10' : 'opacity-0 max-h-0'}`}>
                    <button className={`flex-1 py-1.5 text-[10px] font-bold rounded transition-all tracking-wider
                        ${track.muted 
                            ? 'bg-orange-500 text-black shadow-[0_0_10px_rgba(249,115,22,0.5)]' 
                            : 'bg-[#1a1a1e] text-slate-500 hover:bg-[#222]'}`}
                        onClick={() => onUpdate(track.id, { muted: !track.muted })}>MUTE</button>

                    <button className={`flex-1 py-1.5 text-[10px] font-bold rounded transition-all tracking-wider
                        ${track.solo 
                            ? 'bg-yellow-400 text-black shadow-[0_0_10px_rgba(250,204,21,0.5)]' 
                            : 'bg-[#1a1a1e] text-slate-500 hover:bg-[#222]'}`}
                        onClick={() => onUpdate(track.id, { solo: !track.solo })}>SOLO</button>

                    {/* FX Expander Toggle */}
                    {viewSettings.showRack && (
                        <button className={`flex-1 py-1.5 text-[10px] font-bold rounded transition-all tracking-wider
                            ${track.isExpanded 
                                ? 'bg-blue-600 text-white shadow-[0_0_15px_rgba(37,99,235,0.4)]' 
                                : 'bg-[#1a1a1e] text-blue-500 hover:bg-[#222]'}`}
                            onClick={() => onToggleExpand(track.id)}>FX</button>
                    )}
                </div>
            )}

            {/* Duplicate Logic */}
             {!isCollapsed && width > 100 && (
                <button 
                    className="absolute right-2 top-10 text-[8px] text-slate-700 hover:text-white uppercase tracking-wider opacity-0 group-hover:opacity-100 transition-opacity"
                    onClick={() => onDuplicate(track.id)}
                >
                    Dup
                </button>
             )}

            {/* --- MIX SECTION (Volume/Pan) --- */}
            {!isCollapsed && (
                <div className={`flex flex-col space-y-3 transition-all duration-500 overflow-hidden ${viewSettings.showMix ? 'opacity-100 max-h-24' : 'opacity-0 max-h-0'}`}>
                    {/* Volume Laser */}
                    <div className="flex items-center space-x-2 group/vol">
                         {isWide && <span className="text-[8px] font-bold text-slate-600 w-8 text-right">VOL</span>}
                        <div className="flex-1 h-2 relative flex items-center bg-[#111] rounded-full overflow-hidden border border-white/5">
                            {/* Laser Beam */}
                            <div className="h-full shadow-[0_0_10px_currentColor] transition-all duration-75 ease-out" 
                                style={{ width: `${track.volume * 100}%`, backgroundColor: track.color, color: track.color }}></div>
                            <input 
                                type="range" min="0" max="1" step="0.01" 
                                value={track.volume} 
                                onChange={(e) => onUpdate(track.id, { volume: parseFloat(e.target.value) })}
                                className="absolute w-full h-full opacity-0 cursor-pointer" 
                            />
                        </div>
                        {isWide && <span className="text-[9px] font-mono text-white w-8 text-right">{(track.volume * 100).toFixed(0)}</span>}
                    </div>

                    {/* Pan Laser */}
                    <div className="flex items-center space-x-2 group/pan">
                         {isWide && <span className="text-[8px] font-bold text-slate-600 w-8 text-right">PAN</span>}
                        <div className="flex-1 h-1.5 relative flex items-center bg-[#111] rounded-full border border-white/5">
                            {/* Center Marker */}
                            <div className="absolute left-1/2 w-px h-full bg-slate-600"></div>
                            {/* Pan Thumb */}
                            <div 
                                className="absolute h-2.5 w-2.5 rounded-full shadow-[0_0_8px_white] bg-white pointer-events-none transition-transform top-1/2 -translate-y-1/2"
                                style={{ left: `calc(${((track.pan + 1) / 2) * 100}% - 5px)` }}
                            />
                            <input 
                                type="range" min="-1" max="1" step="0.1" 
                                value={track.pan} 
                                onChange={(e) => onUpdate(track.id, { pan: parseFloat(e.target.value) })}
                                className="absolute w-full h-full opacity-0 cursor-pointer" 
                            />
                        </div>
                        {isWide && <span className="text-[9px] font-mono text-slate-400 w-8 text-right">{track.pan.toFixed(1)}</span>}
                    </div>
                </div>
            )}
       </div>

       {/* --- EXPANDED FX RACK (GRID LAYOUT) --- */}
       {track.isExpanded && !isCollapsed && (
           <div className="flex-1 overflow-y-auto overflow-x-hidden relative bg-black/40 backdrop-blur-md animate-in slide-in-from-left duration-300">
               <div className="p-2 grid grid-cols-2 gap-2 relative z-10 w-full h-full content-start">

                   {/* 1. Drive */}
                   <div className="col-span-1 bg-white/5 rounded border border-white/5 p-2 flex flex-col items-center justify-between">
                        <div className="text-[8px] font-black text-orange-500 mb-1">DRIVE</div>
                        <Knob value={track.fx.saturation} min={0} max={100} label="SAT" color="orange" size={32} onChange={(v) => updateFX('saturation', v)} />
                        <Knob value={track.fx.distortionTone || 20000} min={1000} max={20000} label="TONE" color="orange" size={24} onChange={(v) => updateFX('distortionTone', v)} />
                   </div>

                   {/* 2. Compressor */}
                   <div className="col-span-1 bg-white/5 rounded border border-white/5 p-2 flex flex-col items-center justify-between">
                        <div className="text-[8px] font-black text-yellow-500 mb-1">DYN</div>
                        <Knob value={track.fx.compressorThreshold} min={-60} max={0} label="THR" color="yellow" size={32} onChange={(v) => updateFX('compressorThreshold', v)} />
                        <Knob value={track.fx.compressorRatio} min={1} max={20} label="RAT" color="yellow" size={32} onChange={(v) => updateFX('compressorRatio', v)} />
                   </div>

                   {/* 3. EQ Matrix (Full Width) */}
                   <div className="col-span-2 bg-white/5 rounded border border-white/5 p-2">
                        <div className="text-[8px] font-black text-cyan-500 mb-2 text-center tracking-[0.2em]">EQUALIZER</div>
                        <div className="flex justify-around items-end h-32">
                            <Slider value={track.fx.eqLow} min={-12} max={12} label="LO" color="cyan" height={80} onChange={(v) => updateFX('eqLow', v)} />
                            <Slider value={track.fx.eqMid} min={-12} max={12} label="MID" color="cyan" height={80} onChange={(v) => updateFX('eqMid', v)} />
                            <Slider value={track.fx.eqHigh} min={-12} max={12} label="HI" color="cyan" height={80} onChange={(v) => updateFX('eqHigh', v)} />
                        </div>
                   </div>

                   {/* 4. Sends */}
                   <div className="col-span-2 bg-white/5 rounded border border-white/5 p-2 flex justify-around items-center">
                       <div className="flex flex-col items-center">
                           <div className="text-[8px] font-black text-purple-500 mb-1">VERB</div>
                           <Knob value={track.fx.sendReverb} min={0} max={1} label="SEND" color="purple" size={36} onChange={(v) => updateFX('sendReverb', v)} />
                       </div>
                       <div className="h-full w-px bg-white/10 mx-2"></div>
                       <div className="flex flex-col items-center">
                           <div className="text-[8px] font-black text-blue-500 mb-1">ECHO</div>
                           <Knob value={track.fx.sendDelay} min={0} max={1} label="SEND" color="blue" size={36} onChange={(v) => updateFX('sendDelay', v)} />
                       </div>
                   </div>

               </div>
           </div>
       )}
    </div>
  );
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { audioEngine } from './services/audioEngine';
import { storageService } from './services/storageService';
import { Controls } from './components/Controls';
import { TrackLane } from './components/TrackLane';
import { ChannelStrip } from './components/ChannelStrip';
import { DSPRack } from './components/DSPRack';
import { ClipInspector } from './components/ClipInspector';
import { BackgroundInterference } from './components/BackgroundInterference';
import { ProjectInfoPanel } from './components/ProjectInfoPanel';
import { CreditsModal } from './components/CreditsModal';
import { Track, AudioClip, EditMode, DSPState, TrackFX, ProjectMetadata, ClipViewConfig, ViewSettings } from './types';
import { COLORS, TRACK_HEIGHT, EXPANDED_TRACK_HEIGHT, CHANNEL_WIDTH_DEFAULT, CHANNEL_WIDTH_EXPANDED, CHANNEL_WIDTH_COLLAPSED } from './constants';

const DEFAULT_TRACK_FX: TrackFX = {
    eqLow: 0, eqMid: 0, eqHigh: 0,
    compressorThreshold: 0, compressorRatio: 1,

    saturation: 0,
    saturationFine: 0,
    distortionTone: 20000,

    cabinetOn: false,
    cabinetTone: 0.5,

    sendReverb: 0, 
    reverbTone: 0.5,
    sendDelay: 0,
    highPassFreq: 20
};

const DEFAULT_CLIP_FX = {
    gain: 1.0,
    pitch: 1.0,
    pan: 0,
    isReversed: false,

    filterFreq: 20000,
    filterRes: 0,
    saturation: 0
};

const DEFAULT_VIEW_CONFIG: ClipViewConfig = {
    mode: 'PCM',
    resolution: 2,
    scale: 1.0
};

const App: React.FC = () => {
  // State
  const [tracks, setTracks] = useState<Track[]>([
    { id: 't1', name: 'Vocals', color: COLORS[0], muted: false, solo: false, armed: true, volume: 0.8, pan: 0, fx: {...DEFAULT_TRACK_FX}, isExpanded: false },
    { id: 't2', name: 'Guitars', color: COLORS[1], muted: false, solo: false, armed: false, volume: 0.8, pan: -0.3, fx: {...DEFAULT_TRACK_FX}, isExpanded: false },
    { id: 't3', name: 'Bass', color: COLORS[2], muted: false, solo: false, armed: false, volume: 0.8, pan: 0, fx: {...DEFAULT_TRACK_FX}, isExpanded: false },
    { id: 't4', name: 'Drums', color: COLORS[3], muted: false, solo: false, armed: false, volume: 0.8, pan: 0, fx: {...DEFAULT_TRACK_FX}, isExpanded: false },
  ]);
  const [clips, setClips] = useState<AudioClip[]>([]);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0); 
  const [zoom, setZoom] = useState(100); 
  const [selectedClipId, setSelectedClipId] = useState<string | null>(null);
  const [snapTime, setSnapTime] = useState<number | null>(null); // For visual feedback

  // UI View Settings
  const [viewSettings, setViewSettings] = useState<ViewSettings>({
      showTransport: true,
      showMix: true,
      showRack: true,
      isCollapsed: false
  });

  // Clipboard
  const [clipClipboard, setClipClipboard] = useState<AudioClip | null>(null);

  // Loop State
  const [loopRange, setLoopRange] = useState<{ start: number, end: number } | null>(null);
  const [isLooping, setIsLooping] = useState(false);

  const [editMode, setEditMode] = useState<EditMode>(EditMode.MOVE);

  // Project Metadata
  const [metadata, setMetadata] = useState<ProjectMetadata>({ title: 'New Project', artist: 'Artist', album: '', year: new Date().getFullYear().toString() });
  const [showInfoPanel, setShowInfoPanel] = useState(false);
  const [showCredits, setShowCredits] = useState(true); // Show on load
  const [isExporting, setIsExporting] = useState(false);

  // DSP State
  const [dspState, setDspState] = useState<DSPState>({ 
      masterVolume: 1.0,
      masterFilterFreq: 20000, masterFilterRes: 0, masterFilterBypass: false,
      masterEqLow: 0, masterEqMid: 0, masterEqHigh: 0, masterEqBypass: false,
      masterSaturation: 0, masterSaturationBypass: false,
      masterExciterDrive: 0, masterExciterBypass: false,
      masterStereoWidth: 1, masterStereoBypass: false,
      masterCompressorThreshold: 0, masterCompressorRatio: 1, masterCompressorBypass: false,
      delayTime: 0.3, delayFeedback: 0.3, reverbMix: 0.2, masterSpatialBypass: false,
      limiterThreshold: -1.0, reverbDecay: 2.0
  });

  const [isRecording, setIsRecording] = useState(false);
  const [monitor, setMonitor] = useState(false);

  // Refs
  const rafRef = useRef<number>();
  const startTimeRef = useRef<number>(0); 
  const startOffsetRef = useRef<number>(0); 
  const recordingStartRef = useRef<number>(0); 
  const dragRef = useRef<{ clipId: string; startX: number; originalStart: number } | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // --- Layout Calculation ---
  // If ANY track is expanded, the side column must be wide.
  const isAnyExpanded = tracks.some(t => t.isExpanded);

  const currentChannelWidth = viewSettings.isCollapsed 
      ? CHANNEL_WIDTH_COLLAPSED 
      : (isAnyExpanded ? CHANNEL_WIDTH_EXPANDED : CHANNEL_WIDTH_DEFAULT);

  // --- Initialization ---
  useEffect(() => {
    storageService.init();
    const handleTouch = () => audioEngine.resume();
    document.addEventListener('touchstart', handleTouch, { once: true });
    document.addEventListener('click', handleTouch, { once: true });

    // Initialize Tracks in Audio Engine
    tracks.forEach(t => audioEngine.ensureTrackChannel(t));

    return () => cancelAnimationFrame(rafRef.current!);
  }, []);

  // Update engine when tracks change
  useEffect(() => {
      tracks.forEach(t => audioEngine.updateTrackState(t));
  }, [tracks]);

  useEffect(() => {
      audioEngine.updateMasterDSP(dspState);
  }, [dspState]);

  // --- Snapping Logic ---
  const calculateSnap = (time: number, zoomLevel: number): number => {
      // Determine grid size based on zoom
      // Zoom 100 (100px/s) -> 1.0s or 0.25s
      let gridSize = 1.0;
      if (zoomLevel > 150) gridSize = 0.25;
      if (zoomLevel > 300) gridSize = 0.1;

      const snapped = Math.round(time / gridSize) * gridSize;
      const pixelDiff = Math.abs(snapped - time) * zoomLevel;

      // Snap threshold: 15 pixels
      if (pixelDiff < 15) return snapped;
      return time;
  };

  // --- Playback Logic ---

  const restartPlayback = async (startAt: number) => {
    audioEngine.stopAll();
    setCurrentTime(startAt);
    startTimeRef.current = audioEngine.ctx.currentTime;
    startOffsetRef.current = startAt;

    clips.forEach(clip => {
      const track = tracks.find(t => t.id === clip.trackId);
      if (track && !track.muted && (!tracks.some(t => t.solo) || track.solo)) {
         audioEngine.playClip(clip, startAt);
      }
    });
  };

  const updatePlayhead = useCallback(() => {
    if (audioEngine.ctx.state === 'running' && isPlaying) {
        const elapsed = audioEngine.ctx.currentTime - startTimeRef.current;
        const newTime = startOffsetRef.current + elapsed;

        // Loop Logic
        if (isLooping && loopRange && newTime >= loopRange.end) {
            restartPlayback(loopRange.start);
        } else if (isExporting) {
            const maxDuration = Math.max(...clips.map(c => c.startTime + c.duration)) + 2.0;
            if (newTime >= maxDuration) {
                finishExport();
            } else {
                setCurrentTime(newTime);
            }
        } else {
            setCurrentTime(newTime);
        }
    }
    rafRef.current = requestAnimationFrame(updatePlayhead);
  }, [isPlaying, isLooping, loopRange, isExporting, clips]);

  useEffect(() => {
    if (isPlaying) {
      rafRef.current = requestAnimationFrame(updatePlayhead);
    } else {
      cancelAnimationFrame(rafRef.current!);
    }
  }, [isPlaying, updatePlayhead]);

  const togglePlay = async () => {
    await audioEngine.resume();
    if (isPlaying) {
      audioEngine.stopAll();
      setIsPlaying(false);
      const elapsed = audioEngine.ctx.currentTime - startTimeRef.current;
      const newTime = startOffsetRef.current + elapsed;
      setCurrentTime(newTime);
      startOffsetRef.current = newTime;
    } else {
      startTimeRef.current = audioEngine.ctx.currentTime;
      startOffsetRef.current = currentTime; 

      clips.forEach(clip => {
        const track = tracks.find(t => t.id === clip.trackId);
        if (track && !track.muted && (!tracks.some(t => t.solo) || track.solo)) {
           audioEngine.playClip(clip, currentTime);
        }
      });
      setIsPlaying(true);
    }
  };

  // ... (Loop Controls omitted for brevity, logic identical to previous) ...
  // --- Loop Controls ---
  const handleSetLoopIn = () => {
      setLoopRange(prev => ({ start: currentTime, end: prev ? Math.max(prev.end, currentTime + 1) : currentTime + 4.0 }));
      if (!isLooping) setIsLooping(true);
  };
  const handleSetLoopOut = () => {
      setLoopRange(prev => ({ start: prev ? Math.min(prev.start, currentTime - 1) : Math.max(0, currentTime - 4.0), end: currentTime }));
      if (!isLooping) setIsLooping(true);
  };
  const handleToggleLoop = () => {
      if (!isLooping && !loopRange) {
          setLoopRange({ start: currentTime, end: currentTime + 4.0 });
      }
      setIsLooping(!isLooping);
  };

  const handleCopy = () => {
      if (!selectedClipId) return;
      const clip = clips.find(c => c.id === selectedClipId);
      if (clip) setClipClipboard(clip);
  };

  const handlePaste = () => {
      if (!clipClipboard) return;
      let targetTrackId = tracks[0].id;
      if (selectedClipId) {
          const selected = clips.find(c => c.id === selectedClipId);
          if (selected) targetTrackId = selected.trackId;
      }
      const newClip: AudioClip = {
          ...clipClipboard,
          id: Date.now().toString() + Math.random().toString().slice(2,5),
          startTime: currentTime,
          trackId: targetTrackId
      };
      setClips(prev => [...prev, newClip]);
      setSelectedClipId(newClip.id);
  };

  const handleTrackUpdate = (trackId: string, updates: Partial<Track>) => {
    setTracks(prev => prev.map(t => t.id === trackId ? { ...t, ...updates } : t));
  };

  const toggleTrackArm = (trackId: string) => {
      setTracks(prev => prev.map(t => ({ ...t, armed: t.id === trackId })));
  };

  const toggleTrackExpand = (trackId: string) => {
      // Exclusive expansion for simplicity/space
      setTracks(prev => prev.map(t => ({ ...t, isExpanded: t.id === trackId ? !t.isExpanded : false })));
  };

  const handleDuplicateTrack = (trackId: string) => {
      const originalTrack = tracks.find(t => t.id === trackId);
      if (!originalTrack) return;
      const newTrackId = Date.now().toString();
      const newTrack: Track = { ...originalTrack, id: newTrackId, name: originalTrack.name + ' (Copy)', isExpanded: false };
      const originalClips = clips.filter(c => c.trackId === trackId);
      const newClips = originalClips.map(c => ({ ...c, id: c.id + '_copy_' + Math.random().toString().slice(2,5), trackId: newTrackId }));
      const index = tracks.findIndex(t => t.id === trackId);
      const newTracks = [...tracks];
      newTracks.splice(index + 1, 0, newTrack);
      setTracks(newTracks);
      setClips(prev => [...prev, ...newClips]);
      audioEngine.ensureTrackChannel(newTrack);
  };

  const handleExport = async (format: 'mp4') => {
      if (isPlaying) await togglePlay();
      setIsExporting(true);
      audioEngine.startBounceRecorder();
      startTimeRef.current = audioEngine.ctx.currentTime;
      startOffsetRef.current = 0;
      setCurrentTime(0);
      clips.forEach(clip => {
        const track = tracks.find(t => t.id === clip.trackId);
        if (track && !track.muted && (!tracks.some(t => t.solo) || track.solo)) audioEngine.playClip(clip, 0);
      });
      setIsPlaying(true);
  };

  const finishExport = async () => {
      setIsPlaying(false);
      audioEngine.stopAll();
      const blob = await audioEngine.stopBounceRecorder();
      setIsExporting(false);
      setShowInfoPanel(false);
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.style.display = 'none';
      a.href = url;
      const cleanTitle = metadata.title.replace(/[^a-z0-9]/gi, '_').toLowerCase();
      a.download = `${cleanTitle}_bounce.mp4`;
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
  };

  const stopRecordingAndSave = async () => {
      const blob = await audioEngine.stopRecording();
      setIsRecording(false);
      const id = Date.now().toString();
      await storageService.saveBlob(id, blob);
      const buffer = await audioEngine.decodeAudioData(blob);
      const armedTrack = tracks.find(t => t.armed) || tracks[0];
      const newClip: AudioClip = {
        id, trackId: armedTrack.id, buffer, startTime: recordingStartRef.current,
        duration: buffer.duration, offset: 0, name: `Rec ${id.substr(-4)}`,
        fx: {...DEFAULT_CLIP_FX}, viewConfig: {...DEFAULT_VIEW_CONFIG}
      };
      setClips(prev => [...prev, newClip]);
      setSelectedClipId(id);
  };

  const toggleRecord = async () => {
    if (isRecording) {
      await stopRecordingAndSave();
    } else {
      recordingStartRef.current = currentTime; 
      try {
        await audioEngine.startRecording(monitor);
        setIsRecording(true);
        if (!isPlaying) await togglePlay();
      } catch (err) {
        console.error("Failed to start recording:", err);
      }
    }
  };

  const stop = async () => {
    audioEngine.stopAll();
    setIsPlaying(false);
    if (isExporting) {
        audioEngine.stopBounceRecorder();
        setIsExporting(false);
        return;
    }
    const returnTime = isRecording ? recordingStartRef.current : (isLooping && loopRange ? loopRange.start : 0);
    if (isRecording) {
        try { await stopRecordingAndSave(); } catch(e) { console.error("Error saving:", e); setIsRecording(false); }
    }
    setCurrentTime(returnTime);
    startOffsetRef.current = returnTime;
  };

  // --- Clip Interaction (Move/Split) ---
  const handleClipInteract = (clipId: string, action: string, data?: any) => {
    if (action === 'tap') {
        setSelectedClipId(clipId);
        // Only trigger split logic if specifically in split mode and tapping inside grid
        return;
    }
    if (editMode === EditMode.MOVE && action === 'start') {
      setSelectedClipId(clipId);
      dragRef.current = { clipId, startX: data.x, originalStart: data.originalStart };

      const handleMove = (e: any) => {
        if (!dragRef.current || !containerRef.current) return;
        const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
        const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
        const deltaX = clientX - dragRef.current.startX;
        const deltaTime = deltaX / zoom; 

        let newStart = Math.max(0, dragRef.current.originalStart + deltaTime);

        // Apply Snapping
        const snappedStart = calculateSnap(newStart, zoom);
        if (Math.abs(snappedStart - newStart) * zoom < 15) {
            setSnapTime(snappedStart);
            newStart = snappedStart;
        } else {
            setSnapTime(null);
        }

        const containerRect = containerRef.current.getBoundingClientRect();
        const scrollY = containerRef.current.scrollTop;
        const relativeY = clientY - containerRect.top + scrollY;

        let accumulatedHeight = 0;
        let targetTrackId = null;
        for (const track of tracks) {
            const h = track.isExpanded ? EXPANDED_TRACK_HEIGHT : TRACK_HEIGHT;
            if (relativeY >= accumulatedHeight && relativeY < accumulatedHeight + h) {
                targetTrackId = track.id;
                break;
            }
            accumulatedHeight += h;
        }

        setClips(prev => prev.map(c => 
          c.id === dragRef.current?.clipId ? { 
              ...c, startTime: newStart, 
              trackId: targetTrackId || c.trackId 
          } : c
        ));
      };

      const handleEnd = () => {
        dragRef.current = null;
        setSnapTime(null);
        window.removeEventListener('touchmove', handleMove); window.removeEventListener('touchend', handleEnd);
        window.removeEventListener('mousemove', handleMove); window.addEventListener('mouseup', handleEnd);
      };
      window.addEventListener('touchmove', handleMove, { passive: false }); window.addEventListener('touchend', handleEnd);
      window.addEventListener('mousemove', handleMove); window.addEventListener('mouseup', handleEnd);
    }
  };

  const handleClipFXUpdate = (clipId: string, updates: Partial<AudioClip['fx']> | { viewConfig: any }) => {
      setClips(prev => prev.map(c => c.id === clipId ? { ...c, ...('viewConfig' in updates ? { viewConfig: updates.viewConfig } : { fx: { ...c.fx, ...updates } }) } : c));
      if (!('viewConfig' in updates)) audioEngine.updateClipParams(clipId, updates as Partial<typeof DEFAULT_CLIP_FX>);
  };

  const splitClip = (clipId: string, splitTimeOverride?: number) => {
    const clip = clips.find(c => c.id === clipId);
    if (!clip) return;
    const timeToSplitAt = splitTimeOverride !== undefined ? splitTimeOverride : currentTime;

    // Snap Split
    const snappedSplit = calculateSnap(timeToSplitAt, zoom);

    const relativeSplitTime = (snappedSplit - clip.startTime); 
    if (relativeSplitTime <= 0.01 || relativeSplitTime >= clip.duration - 0.01) return;

    const clip1: AudioClip = { ...clip, id: clip.id + '_1', duration: relativeSplitTime };
    const clip2: AudioClip = { ...clip, id: clip.id + '_2', startTime: snappedSplit, duration: clip.duration - relativeSplitTime, offset: clip.offset + relativeSplitTime };
    setClips(prev => prev.filter(c => c.id !== clipId).concat([clip1, clip2]));
    setSelectedClipId(clip2.id);
  };

  const handleSplitButton = () => { if (selectedClipId) splitClip(selectedClipId, currentTime); };
  const deleteSelectedClip = () => { if (selectedClipId) setClips(prev => prev.filter(c => c.id !== selectedClipId)); setSelectedClipId(null); };

  const handleTimelineScrub = (e: any) => {
     if (e.target.dataset.bg) setSelectedClipId(null);
     if (!containerRef.current) return;
     const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
     const containerLeft = containerRef.current.getBoundingClientRect().left;
     const scrollLeft = containerRef.current.scrollLeft;
     const relativeX = clientX - containerLeft + scrollLeft;
     const rawTime = Math.max(0, (relativeX - currentChannelWidth) / zoom);

     // Snap Playhead
     const snappedTime = calculateSnap(rawTime, zoom);
     setCurrentTime(snappedTime);
     startOffsetRef.current = snappedTime;
  };

  const selectedClip = clips.find(c => c.id === selectedClipId);

  return (
    <div className="flex flex-col h-screen w-screen bg-transparent text-slate-100 overflow-hidden select-none font-sans relative">
      <BackgroundInterference />
      <div className="flex flex-col h-full w-full z-10 relative bg-black/10 backdrop-blur-[1px]">
        <Controls 
            isPlaying={isPlaying} isRecording={isRecording} isLooping={isLooping} loopRange={loopRange}
            onPlayPause={togglePlay} onRecord={toggleRecord} onStop={stop} onBounce={() => setShowInfoPanel(true)} 
            onDelete={deleteSelectedClip} onSplit={handleSplitButton} onCopy={handleCopy} onPaste={handlePaste}
            onToggleLoop={handleToggleLoop} onSetLoopIn={handleSetLoopIn} onSetLoopOut={handleSetLoopOut}
            onOpenInfo={() => setShowInfoPanel(true)} onShowCredits={() => setShowCredits(true)}
            editMode={editMode} setEditMode={setEditMode} monitor={monitor} setMonitor={setMonitor}
            zoom={zoom} setZoom={setZoom} hasSelection={!!selectedClipId} hasClipboard={!!clipClipboard}
            viewSettings={viewSettings} setViewSettings={setViewSettings}
        />

        <div ref={containerRef} className="flex-1 overflow-y-auto overflow-x-auto relative mt-[60px] mb-[260px]" 
            onClick={() => setSelectedClipId(null)} data-bg="true">

            {/* Snap Guide Line */}
            {snapTime !== null && (
                <div className="absolute top-0 bottom-0 border-l border-yellow-400 z-50 pointer-events-none opacity-80"
                     style={{ left: `${(snapTime * zoom) + currentChannelWidth}px` }}></div>
            )}

            {/* Playhead */}
            <div className="absolute top-0 bottom-0 z-40 pointer-events-none border-r border-blue-500 shadow-[0_0_10px_rgba(59,130,246,0.8)]"
                style={{ left: `${(currentTime * zoom) + currentChannelWidth}px`, width: '1px' }}>
                <div className="absolute -top-4 -translate-x-1/2 bg-blue-600 text-[9px] px-1.5 py-0.5 rounded-sm text-white font-mono shadow-md whitespace-nowrap z-50">
                    {currentTime.toFixed(2)}s
                </div>
                <div className="absolute top-0 bottom-0 w-px bg-blue-500/50"></div>
            </div>

            {/* Ruler */}
            <div className="h-8 min-w-full bg-[#000000] border-b border-white/10 relative cursor-pointer shadow-lg z-30 transition-all duration-300"
                style={{ width: `${Math.max(window.innerWidth, (300 * zoom) + currentChannelWidth)}px` }}
                onClick={(e) => { e.stopPropagation(); handleTimelineScrub(e); }}>
                {loopRange && (
                    <div className="absolute top-0 bottom-0 bg-blue-500/10 border-x border-blue-500/50 z-0"
                        style={{ left: `${loopRange.start * zoom + currentChannelWidth}px`, width: `${(loopRange.end - loopRange.start) * zoom}px` }}>
                        <div className="absolute top-0 left-0 -translate-x-1/2 w-0 h-0 border-l-[4px] border-l-transparent border-r-[4px] border-r-transparent border-t-[6px] border-t-blue-500"></div>
                        <div className="absolute top-0 right-0 translate-x-1/2 w-0 h-0 border-l-[4px] border-l-transparent border-r-[4px] border-r-transparent border-t-[6px] border-t-blue-500"></div>
                    </div>
                )}
                {/* Adaptive Ticks */}
                {Array.from({ length: Math.ceil(300 * zoom / 100) * (zoom > 150 ? 8 : 4) }).map((_, i) => {
                    const step = zoom > 150 ? 0.125 : 0.25;
                    const sec = i * step;
                    const isMajor = Math.abs(sec % 1) < 0.001;
                    const isMedium = Math.abs(sec % 0.5) < 0.001;
                    let h = 'h-2 border-slate-700';
                    if (isMajor) h = 'h-5 border-slate-300';
                    else if (isMedium) h = 'h-3 border-slate-500';
                    return (
                    <div key={i} className={`absolute bottom-0 border-l z-10 pointer-events-none ${h}`} 
                        style={{ left: (sec * zoom) + currentChannelWidth }}>
                        {isMajor && <span className="text-[9px] font-medium text-slate-400 pl-1.5 -mt-5 block">{sec}</span>}
                    </div>
                )})}
            </div>

            {/* Tracks Container */}
            <div className="min-w-full pb-20 relative bg-transparent transition-all duration-300" style={{ width: `${Math.max(window.innerWidth, (300 * zoom) + currentChannelWidth)}px` }} data-bg="true">
            {loopRange && (
                <div className="absolute top-0 bottom-0 bg-blue-900/5 pointer-events-none z-0 border-x border-blue-900/20"
                    style={{ left: `${loopRange.start * zoom + currentChannelWidth}px`, width: `${(loopRange.end - loopRange.start) * zoom}px` }} />
            )}
            {tracks.map(track => (
                <div key={track.id} className="flex border-b border-white/5 bg-black/40" style={{ height: track.isExpanded ? EXPANDED_TRACK_HEIGHT : TRACK_HEIGHT }}>
                <ChannelStrip 
                    track={track} onUpdate={handleTrackUpdate} onToggleArm={toggleTrackArm} onToggleExpand={toggleTrackExpand} onDuplicate={handleDuplicateTrack}
                    width={currentChannelWidth} viewSettings={viewSettings} isCollapsed={viewSettings.isCollapsed}
                />
                <div className="relative w-full z-10 flex-1 min-w-0">
                    <TrackLane track={track} clips={clips.filter(c => c.trackId === track.id)} editMode={editMode} selectedClipId={selectedClipId} onClipInteract={handleClipInteract} currentTime={currentTime} isPlaying={isPlaying} zoom={zoom} />
                </div>
                </div>
            ))}
            </div>
        </div>

        {selectedClip ? (
            <ClipInspector clip={selectedClip} onUpdate={handleClipFXUpdate} onClose={() => setSelectedClipId(null)} />
        ) : (
            <DSPRack dspState={dspState} onChange={(s) => { setDspState(s); audioEngine.updateMasterDSP(s); }} />
        )}

        {showInfoPanel && (
            <ProjectInfoPanel metadata={metadata} onChange={setMetadata} onClose={() => !isExporting && setShowInfoPanel(false)} onExport={handleExport} isExporting={isExporting} />
        )}
        {showCredits && (
            <CreditsModal onClose={() => setShowCredits(false)} />
        )}
      </div>
    </div>
  );
};

