import React, { useRef, useState, useEffect } from 'react';

interface XYPadProps {
    x: number; // 0 to 1
    y: number; // 0 to 1
    onChange: (x: number, y: number) => void;
    labelX: string;
    labelY: string;
    color?: string;
}

export const XYPad: React.FC<XYPadProps> = ({ x, y, onChange, labelX, labelY, color = 'cyan' }) => {
    const padRef = useRef<HTMLDivElement>(null);
    const [isDragging, setIsDragging] = useState(false);

    const updateFromPointer = (clientX: number, clientY: number) => {
        if (!padRef.current) return;
        const rect = padRef.current.getBoundingClientRect();

        let newX = (clientX - rect.left) / rect.width;
        let newY = 1 - ((clientY - rect.top) / rect.height); // Y is up

        newX = Math.max(0, Math.min(1, newX));
        newY = Math.max(0, Math.min(1, newY));

        onChange(newX, newY);
    };

    useEffect(() => {
        if (isDragging) {
            const move = (e: MouseEvent) => { e.preventDefault(); updateFromPointer(e.clientX, e.clientY); };
            const up = () => setIsDragging(false);
            window.addEventListener('mousemove', move);
            window.addEventListener('mouseup', up);
            return () => { window.removeEventListener('mousemove', move); window.removeEventListener('mouseup', up); };
        }
    }, [isDragging]);

    const colorMap: Record<string, string> = {
        cyan: '#00f0ff', blue: '#2f80ed', purple: '#b721ff', green: '#0aff60', 
        yellow: '#ffcc00', orange: '#ff6600', red: '#ff003c', pink: '#ff00d4'
    };
    const c = colorMap[color] || colorMap['cyan'];

    return (
        <div className="flex flex-col items-center w-full h-full p-2">
            <div 
                ref={padRef}
                className="w-full h-full border border-white/10 bg-black/40 rounded relative cursor-crosshair touch-none overflow-hidden"
                onMouseDown={(e) => { setIsDragging(true); updateFromPointer(e.clientX, e.clientY); }}
            >
                {/* Grid */}
                <div className="absolute inset-0 opacity-20 pointer-events-none" 
                     style={{ backgroundImage: `linear-gradient(${c} 1px, transparent 1px), linear-gradient(90deg, ${c} 1px, transparent 1px)`, backgroundSize: '20px 20px' }} />

                {/* Puck */}
                <div 
                    className="absolute w-4 h-4 rounded-full border-2 border-white bg-black transform -translate-x-1/2 -translate-y-1/2 shadow-[0_0_10px_white]"
                    style={{ left: `${x * 100}%`, bottom: `${y * 100}%`, borderColor: c }}
                />

                {/* Axis Labels */}
                <div className="absolute bottom-1 right-1 text-[7px] font-bold text-slate-500 uppercase">{labelX} →</div>
                <div className="absolute top-1 left-1 text-[7px] font-bold text-slate-500 uppercase">↑ {labelY}</div>
            </div>
        </div>
    );
};

