                                className="absolute h-2.5 w-2.5 rounded-full shadow-[0_0_8px_white] bg-white pointer-events-none transition-transform top-1/2 -translate-y-1/2"
                                style={{ left: `calc(${((track.pan + 1) / 2) * 100}% - 5px)` }}
                            />
                            <input 
                                type="range" min="-1" max="1" step="0.1" 
                                value={track.pan} 
                                onChange={(e) => onUpdate(track.id, { pan: parseFloat(e.target.value) })}
