import React, { useState, useRef, useEffect } from 'react';

interface KnobProps {
  value: number;
  min: number;
  max: number;
  onChange: (val: number) => void;
  label: string;
  color?: string;
  size?: number;
  resetValue?: number; // New: Double click to reset
}

export const Knob: React.FC<KnobProps> = ({ value, min, max, onChange, label, color = 'cyan', size = 46, resetValue }) => {
  const [isDragging, setIsDragging] = useState(false);
  const startY = useRef(0);
  const startVal = useRef(0);

  // Sanitize input value immediately
  const safeValue = Math.min(max, Math.max(min, Number.isFinite(value) ? value : min));

  const handleStart = (clientY: number) => {
    setIsDragging(true);
    startY.current = clientY;
    startVal.current = safeValue;
  };

  const handleMove = (clientY: number) => {
    if (!isDragging) return;
    const delta = startY.current - clientY;
    const range = max - min;

    // Sensitivity: 250px drag = full range (Linear feeling)
    const sensitivity = 250; 
    const change = (delta / sensitivity) * range;

    let newVal = startVal.current + change;

    // Hard Clamp
    newVal = Math.max(min, Math.min(max, newVal));

    onChange(newVal);
  };

  const handleEnd = () => {
    setIsDragging(false);
  };

  const handleDoubleClick = (e: React.MouseEvent | React.TouchEvent) => {
      e.stopPropagation();
      e.preventDefault();
      // If resetValue provided, use it, else midpoint or min? Default to min if undefined, but best to provide one.
      // Usually nice to reset to 0 for dB, or center for Pan.
      const target = resetValue !== undefined ? resetValue : min;
      onChange(target);
  };

  useEffect(() => {
    if (isDragging) {
      const mouseMove = (e: MouseEvent) => { e.preventDefault(); handleMove(e.clientY); };
      const touchMove = (e: TouchEvent) => { e.preventDefault(); handleMove(e.touches[0].clientY); };
      const end = () => handleEnd();

      window.addEventListener('mousemove', mouseMove, { passive: false });
      window.addEventListener('touchmove', touchMove, { passive: false });
      window.addEventListener('mouseup', end);
      window.addEventListener('touchend', end);

      return () => {
        window.removeEventListener('mousemove', mouseMove);
        window.removeEventListener('touchmove', touchMove);
        window.removeEventListener('mouseup', end);
        window.removeEventListener('touchend', end);
      };
    }
  }, [isDragging]);

  const percentage = (safeValue - min) / (max - min);
  const angle = -135 + (percentage * 270);

  const colorMap: Record<string, string> = {
    cyan: '#00f0ff',
    blue: '#2f80ed',
    purple: '#b721ff',
    green: '#0aff60',
    yellow: '#ffcc00',
    orange: '#ff6600',
    red: '#ff003c',
    pink: '#ff00d4',
    white: '#ffffff'
  };
  const accentColor = colorMap[color] || colorMap['cyan'];

  return (
    <div 
      className="flex flex-col items-center justify-center select-none touch-none group relative py-2" 
      onMouseDown={(e) => handleStart(e.clientY)}
      onTouchStart={(e) => handleStart(e.touches[0].clientY)}
      onDoubleClick={handleDoubleClick}
      style={{ width: size + 24, cursor: isDragging ? 'ns-resize' : 'pointer' }}
    >
      <div className="relative flex items-center justify-center" style={{ width: size, height: size }}>

          {/* 1. Outer Tick Ring (Rotates) */}
          <div 
            className="absolute inset-0 rounded-full transition-transform duration-75 ease-out"
            style={{ 
                transform: `rotate(${angle}deg)`,
                opacity: 0.4
            }}
          >
             <div className="absolute top-0 left-1/2 -translate-x-1/2 w-0.5 h-1.5 bg-white shadow-[0_0_5px_white]"></div>
          </div>

          {/* 2. Static Backplate */}
          <div className="absolute inset-0 rounded-full bg-black shadow-[inset_0_1px_5px_rgba(255,255,255,0.1)] border border-white/5"></div>

          {/* 3. The Arc (SVG) */}
          <svg className="absolute top-0 left-0 w-full h-full rotate-90" style={{ transform: 'rotate(135deg)' }}>
             <circle 
                cx="50%" cy="50%" r="44%" 
                fill="none" 
                stroke="#111" 
                strokeWidth="3" 
             />
             <circle 
                cx="50%" cy="50%" r="44%" 
                fill="none" 
                stroke={accentColor} 
                strokeWidth="3"
                strokeDasharray={`${percentage * 206} 300`} 
                strokeLinecap="round"
                style={{ filter: `drop-shadow(0 0 4px ${accentColor})` }}
             />
          </svg>

          {/* 4. The Void Core (Inner Cap) */}
          <div 
            className="absolute rounded-full flex items-center justify-center overflow-hidden transition-all duration-200"
            style={{ 
                width: '70%', 
                height: '70%',
                background: `radial-gradient(circle at 30% 30%, #222, #000)`,
                boxShadow: isDragging 
                    ? `0 0 15px ${accentColor}40, inset 0 0 10px #000` 
                    : `0 5px 10px rgba(0,0,0,0.5), inset 0 0 2px rgba(255,255,255,0.2)`
            }}
          >
             {/* Core Glow */}
             <div 
                className="absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity duration-500"
                style={{
                    background: `radial-gradient(circle, ${accentColor}20 0%, transparent 70%)`
                }}
             ></div>

             {/* Numeric Value (Only on Drag/Hover) */}
             <span className={`text-[9px] font-mono font-bold text-white transition-opacity duration-200 ${isDragging ? 'opacity-100' : 'opacity-0'}`}>
                {safeValue.toFixed(Math.abs(max - min) < 10 ? 2 : 1)}
             </span>
          </div>

      </div>

      {/* Label */}
      <span 
        className="mt-2 text-[8px] font-bold tracking-widest uppercase transition-all duration-300"
        style={{ 
            color: isDragging ? accentColor : '#52525b',
            textShadow: isDragging ? `0 0 8px ${accentColor}` : 'none',
            letterSpacing: '0.1em'
        }}
      >
        {label}
      </span>
    </div>
  );
};

import React, { useEffect, useRef } from 'react';
import { DSPState } from '../types';
import { Knob } from './Knob';
import { Slider } from './Slider';
import { audioEngine } from '../services/audioEngine';

interface DSPRackProps {
  dspState: DSPState;
  onChange: (newState: DSPState) => void;
}

// ... (Numerical Analysis functions) ...
const calculateFilterMagnitude = (freq: number, res: number) => {
    const steps = 12;
    const bars = [];
    for(let i=0; i<steps; i++) {
        const f = 20 * Math.pow(1000, i / (steps-1));
        const ratio = f / freq;
        const mag = 1 / Math.sqrt(Math.pow(1 - ratio*ratio, 2) + Math.pow(ratio/(0.707 + res), 2));
        bars.push(Math.min(1.2, mag)); 
    }
    return bars;
};
const calculateSaturatorShape = (drive: number) => {
    const bars = [];
    const k = drive;
    for(let i=0; i<12; i++) {
        const x = (i / 11) * 2 - 1; 
        let y = x;
        if (k > 0) y = ((Math.PI + k) * x) / (Math.PI + k * Math.abs(x));
        bars.push((y + 1) / 2);
    }
    return bars;
};
const calculateHarmonicsShape = (drive: number) => {
    const bars = new Array(12).fill(0);
    bars[0] = 0.8;
    for(let i=1; i<12; i++) {
       if (i % 2 !== 0) bars[i] = (drive / 100) * (1 / i) * 2; 
       else bars[i] = (drive / 100) * (1 / (i*2));
    }
    return bars;
};
const calculateEQShape = (low: number, mid: number, high: number) => {
    const bars = [];
    for(let i=0; i<12; i++) {
        let gain = 0;
        if (i < 4) gain = low; else if (i < 8) gain = mid; else gain = high;
        if (i===3 || i===4) gain = (low + mid)/2;
        if (i===7 || i===8) gain = (mid + high)/2;
        bars.push((gain + 12) / 24);
    }
    return bars;
};
// Use Real Reduction now
const calculateDynamicsShape = (thresh: number, ratio: number) => {
    const reduction = audioEngine.getMasterGainReduction(); // Returns e.g. -3.0 dB
    // Map -20dB reduction to full bar height
    const normalizedRed = Math.abs(reduction) / 20.0;
    // Return a single bar value indicating reduction amount (0 to 1)
    return [Math.min(1, normalizedRed)];
};
const calculateSpatialShape = (time: number, feedback: number, mix: number) => {
    const bars = new Array(12).fill(0);
    bars[0] = 1.0; 
    const delayStep = Math.max(1, Math.round(time * 5)); 
    for (let i = 0; i < 12; i+=delayStep) {
       const decay = Math.pow(feedback, i/delayStep);
       if(i < 12) bars[i] = decay;
    }
    return bars.map(b => b * (0.3 + mix * 0.7));
};
const calculateOutputShape = (vol: number, dataArray: Uint8Array) => {
    if (!dataArray) return new Array(12).fill(0);
    let sum = 0;
    for(let i=0; i<dataArray.length; i++) sum += dataArray[i] * dataArray[i];
    const rms = Math.sqrt(sum / dataArray.length) / 255;
    const level = Math.min(1, rms * vol * 2.5);
    return Array(12).fill(0).map((_, i) => (level > i/12 ? 1 : 0));
};

const drawPixelLeds = (ctx: CanvasRenderingContext2D, width: number, height: number, bars: number[], baseColor: string, bypassed: boolean, type: string) => {
    ctx.clearRect(0, 0, width, height);

    const dimFactor = bypassed ? 0.2 : 1.0;

    const numCols = 12; const numRows = 8;
    const gap = 2;
    const colWidth = (width - ((numCols - 1) * gap)) / numCols;
    const rowHeight = (height - ((numRows - 1) * gap)) / numRows;

    // Background Grid
    ctx.fillStyle = '#0f172a';
    for (let c = 0; c < numCols; c++) {
        for (let r = 0; r < numRows; r++) {
             const rowIndex = (numRows - 1) - r;
             ctx.fillRect(c * (colWidth + gap), rowIndex * (rowHeight + gap), colWidth, rowHeight);
        }
    }

    // Special Dynamics Renderer (Downwards Red Bar)
    if (type === 'dynamics') {
        const reduction = bars[0]; // 0 to 1
        const activeLeds = Math.floor(reduction * numRows);

        // Fill all columns equally (Top Down)
        for (let c = 0; c < numCols; c++) {
            for (let r = 0; r < numRows; r++) {
                // Top down: r=0 is bottom visually in previous loop logic? 
                // Let's use rowIndex directly.
                const rowIndex = r; // 0 is top

                if (rowIndex < activeLeds) {
                    const y = rowIndex * (rowHeight + gap);
                    const x = c * (colWidth + gap);
                    // Gain Reduction is RED/ORANGE
                    ctx.fillStyle = `rgba(255, 50, 0, ${dimFactor})`;
                    ctx.shadowColor = 'red';
                    ctx.shadowBlur = bypassed ? 0 : 8;
                    ctx.fillRect(x, y, colWidth, rowHeight);
                    ctx.shadowBlur = 0;
                }
            }
        }
        return;
    }

    for (let c = 0; c < numCols; c++) {
        const value = bars[c] || 0; 
        const activeHeight = value * numRows;

        for (let r = 0; r < numRows; r++) {
             const rowIndex = (numRows - 1) - r;
             const y = rowIndex * (rowHeight + gap);
             const x = c * (colWidth + gap);

             let intensity = 0;
             if (r < Math.floor(activeHeight)) intensity = 1.0;
             else if (r < activeHeight) intensity = activeHeight - r;

             if (intensity > 0) {
                 // Gradient Logic: Green (bottom) -> Yellow (mid) -> Red (top)
                 let rCol, gCol, bCol;
                 const normR = r / numRows;

                 if (normR < 0.5) { // Green to Yellow
                     rCol = Math.floor(normR * 2 * 255);
                     gCol = 255;
                     bCol = 0;
                 } else { // Yellow to Red
                     rCol = 255;
                     gCol = Math.floor((1 - (normR - 0.5) * 2) * 255);
                     bCol = 0;
                 }

                 // Override with Module Base Color if needed for style, or keep multi-color
                 // Let's use a tint of the baseColor
                 ctx.fillStyle = baseColor; // Simplified for "Module Identity"
                 // Or actually, let's mix the baseColor with the intensity

                 ctx.globalAlpha = intensity * dimFactor;
                 ctx.fillStyle = baseColor;
                 ctx.shadowBlur = bypassed ? 0 : 4;
                 ctx.shadowColor = baseColor;
                 ctx.fillRect(x, y, colWidth, rowHeight);

                 if (intensity > 0.6) {
                    ctx.fillStyle = 'rgba(255,255,255,0.4)';
                    ctx.shadowBlur = 0;
                    ctx.fillRect(x + 1, y + 1, colWidth - 2, rowHeight - 2);
                 }
                 ctx.shadowBlur = 0;
                 ctx.globalAlpha = 1.0;
             }
        }
    }
};

const RackModule: React.FC<{
  title: string;
  type: 'filter' | 'saturator' | 'exciter' | 'eq' | 'dynamics' | 'spatial' | 'width' | 'output';
  color: string;
  dspState: DSPState;
  children: React.ReactNode;
  isBypassed?: boolean;
  onToggleBypass?: () => void;
}> = ({ title, type, color, dspState, children, isBypassed = false, onToggleBypass }) => {

  const canvasRef = useRef<HTMLCanvasElement>(null);

  // Keep base color for borders/text, but LEDs use gradient
  const colorMap: Record<string, string> = {
    pink: '#ff00d4', orange: '#ff6600', blue: '#2f80ed',
    yellow: '#ffcc00', purple: '#b721ff', cyan: '#00f0ff',
    red: '#ff003c', green: '#0aff60',
  };
  const hexColor = colorMap[color] || '#3b82f6';

  useEffect(() => {
     const canvas = canvasRef.current;
     if(!canvas) return;
     const ctx = canvas.getContext('2d');
     if(!ctx) return;

     let frameId: number;
     const dataArray = new Uint8Array(audioEngine.analyser.frequencyBinCount);

     const render = () => {
         frameId = requestAnimationFrame(render);
         audioEngine.analyser.getByteFrequencyData(dataArray);
         const w = canvas.width;
         const h = canvas.height;
         let bars: number[] = [];

         if (type === 'filter') bars = calculateFilterMagnitude(dspState.masterFilterFreq, dspState.masterFilterRes);
         else if (type === 'saturator') bars = calculateSaturatorShape(dspState.masterSaturation);
         else if (type === 'exciter') bars = calculateHarmonicsShape(dspState.masterExciterDrive * 100);
         else if (type === 'eq') bars = calculateEQShape(dspState.masterEqLow, dspState.masterEqMid, dspState.masterEqHigh);
         else if (type === 'dynamics') bars = calculateDynamicsShape(dspState.masterCompressorThreshold, dspState.masterCompressorRatio);
         else if (type === 'spatial') bars = calculateSpatialShape(dspState.delayTime, dspState.delayFeedback, dspState.reverbMix);
         else if (type === 'width') { const w = dspState.masterStereoWidth; bars = [w/2, w/2, w/2, w/2, 0.1, 0.1, 0.1, 0.1, w/2, w/2, w/2, w/2]; }
         else if (type === 'output') bars = calculateOutputShape(dspState.masterVolume, dataArray);

         drawPixelLeds(ctx, w, h, bars, hexColor, !!isBypassed, type);
     };
     render();
     return () => cancelAnimationFrame(frameId);
  }, [type, dspState, hexColor, isBypassed]);

  return (
    <div className={`flex flex-col h-full backdrop-blur-md border-r border-white/5 relative group min-w-[170px] overflow-hidden transition-colors ${isBypassed ? 'bg-black/40' : 'bg-white/5'}`}>

      {/* VFD Screen Area */}
      <div className="h-24 relative p-3 flex flex-col items-center justify-end bg-black/40 shadow-[inset_0_10px_30px_rgba(0,0,0,0.5)]">
        <div className={`w-full h-full relative rounded border overflow-hidden transition-colors ${isBypassed ? 'border-white/5 bg-black' : 'border-white/10 bg-black/80'}`}>
             {/* Scanlines Overlay */}
             <div className="absolute inset-0 z-20 pointer-events-none opacity-20" style={{ backgroundImage: 'linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.25) 50%), linear-gradient(90deg, rgba(255, 0, 0, 0.06), rgba(0, 255, 0, 0.02), rgba(0, 0, 255, 0.06))', backgroundSize: '100% 2px, 3px 100%' }}></div>
             <canvas ref={canvasRef} width={140} height={60} className="w-full h-full" />
        </div>

        {/* Module Title Badge */}
        <div className={`absolute top-3 left-3 px-1.5 py-0.5 border rounded z-30 shadow-[0_0_10px_rgba(0,0,0,1)] flex items-center gap-2 ${isBypassed ? 'border-white/5 bg-black text-slate-600' : 'border-white/10 bg-black/80'}`}>
            <span className={`text-[9px] font-black tracking-widest uppercase transition-colors ${isBypassed ? 'text-slate-600' : 'text-white/90'}`} style={{ textShadow: isBypassed ? 'none' : `0 0 5px ${hexColor}` }}>{title}</span>
        </div>

        {/* Bypass LED (The "Dimming Light") */}
        {onToggleBypass && (
            <button 
                onClick={onToggleBypass}
                className={`absolute top-3 right-3 w-3 h-3 rounded-full border transition-all z-40 ${isBypassed ? 'bg-slate-900 border-slate-700' : `bg-${color}-500 border-white shadow-[0_0_8px_${hexColor}]`}`}
                style={{ backgroundColor: isBypassed ? '#111' : hexColor }}
                title={isBypassed ? "Enable Effect" : "Bypass Effect"}
            ></button>
        )}
      </div>

      {/* Controls Area */}
      <div className={`flex-1 flex items-center justify-center space-x-4 px-3 py-2 relative transition-opacity duration-300 ${isBypassed ? 'opacity-30 pointer-events-none grayscale' : 'opacity-100'}`}>
         {children}
      </div>

      {/* Edge Highlight */}
      <div className="absolute top-0 bottom-0 left-0 w-px bg-white/10"></div>
    </div>
  );
};

export const DSPRack: React.FC<DSPRackProps> = ({ dspState, onChange }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    let animationId: number;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const dataArray = new Uint8Array(audioEngine.analyser.frequencyBinCount);

    const draw = () => {
      animationId = requestAnimationFrame(draw);
      audioEngine.analyser.getByteFrequencyData(dataArray);
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      const numBlocks = 64;
      const blockWidth = canvas.width / numBlocks;
      const step = Math.floor(dataArray.length / numBlocks);

      for(let i = 0; i < numBlocks; i++) {
        const val = dataArray[i * step] / 255; 
        const activeHeight = val * canvas.height;
        ctx.fillStyle = `hsl(${210 + (val * 60)}, 100%, 60%)`;
        ctx.globalAlpha = 0.8;
        ctx.fillRect(i * blockWidth, canvas.height - activeHeight, blockWidth - 1, activeHeight);

        // Mirror reflection
        ctx.globalAlpha = 0.2;
        ctx.fillRect(i * blockWidth, canvas.height, blockWidth - 1, activeHeight * 0.5);
      }
    };
    draw();
    return () => cancelAnimationFrame(animationId);
  }, []);

  return (
    <div className="fixed bottom-0 left-0 right-0 h-[260px] bg-[#030305]/95 backdrop-blur-xl border-t border-white/10 shadow-[0_-10px_50px_rgba(0,0,0,0.9)] z-50 flex flex-col">
      <div className="flex h-6 border-b border-white/5 bg-black/50 relative shrink-0 items-center px-2 overflow-hidden">
        <canvas ref={canvasRef} width={800} height={32} className="absolute inset-0 w-full h-full opacity-50 mix-blend-screen" />
        <div className="relative z-10 text-[9px] text-cyan-400 font-mono tracking-widest px-2 bg-black/60 rounded">
          QUANTUM DSP MATRIX
        </div>
      </div>
      <div className="flex-1 overflow-x-auto overflow-y-hidden scrollbar-hide">
        <div className="flex h-full min-w-max">

          {/* LOGICAL ORDER: FILTER -> EQ -> DYNAMICS -> SATURATION -> EXCITER -> STEREO -> DIMENSION -> OUTPUT */}

          <RackModule 
            title="RESONANCE" type="filter" color="pink" dspState={dspState} 
            isBypassed={dspState.masterFilterBypass}
            onToggleBypass={() => onChange({...dspState, masterFilterBypass: !dspState.masterFilterBypass})}
          >
             <Knob value={dspState.masterFilterFreq} min={20} max={20000} label="FREQ" color="pink" onChange={(v) => onChange({...dspState, masterFilterFreq: v})} />
             <Knob value={dspState.masterFilterRes} min={0} max={20} label="Q-FAC" color="pink" onChange={(v) => onChange({...dspState, masterFilterRes: v})} />
          </RackModule>

          <RackModule 
            title="EQUALIZER" type="eq" color="blue" dspState={dspState}
            isBypassed={dspState.masterEqBypass}
            onToggleBypass={() => onChange({...dspState, masterEqBypass: !dspState.masterEqBypass})}
          >
             <Slider value={dspState.masterEqLow} min={-12} max={12} label="LO" color="blue" onChange={(v) => onChange({...dspState, masterEqLow: v})} />
             <Slider value={dspState.masterEqMid} min={-12} max={12} label="MID" color="blue" onChange={(v) => onChange({...dspState, masterEqMid: v})} />
             <Slider value={dspState.masterEqHigh} min={-12} max={12} label="HI" color="blue" onChange={(v) => onChange({...dspState, masterEqHigh: v})} />
          </RackModule>

          <RackModule 
            title="DYNAMICS" type="dynamics" color="yellow" dspState={dspState}
            isBypassed={dspState.masterCompressorBypass}
            onToggleBypass={() => onChange({...dspState, masterCompressorBypass: !dspState.masterCompressorBypass})}
          >
             <Knob value={dspState.masterCompressorThreshold} min={-60} max={0} label="THR" color="yellow" resetValue={0} onChange={(v) => onChange({...dspState, masterCompressorThreshold: v})} />
             <Knob value={dspState.masterCompressorRatio} min={1} max={20} label="RAT" color="yellow" resetValue={1} onChange={(v) => onChange({...dspState, masterCompressorRatio: v})} />
          </RackModule>

          <RackModule 
            title="SATURATION" type="saturator" color="orange" dspState={dspState}
            isBypassed={dspState.masterSaturationBypass}
            onToggleBypass={() => onChange({...dspState, masterSaturationBypass: !dspState.masterSaturationBypass})}
          >
             <Slider value={dspState.masterSaturation} min={0} max={100} label="PLASMA" color="orange" onChange={(v) => onChange({...dspState, masterSaturation: v})} />
          </RackModule>

          <RackModule 
            title="HARMONICS" type="exciter" color="purple" dspState={dspState}
            isBypassed={dspState.masterExciterBypass}
            onToggleBypass={() => onChange({...dspState, masterExciterBypass: !dspState.masterExciterBypass})}
          >
             <Knob value={dspState.masterExciterDrive || 0} min={0} max={1} label="EXCITE" color="purple" onChange={(v) => onChange({...dspState, masterExciterDrive: v})} />
          </RackModule>

          <RackModule 
            title="STEREO" type="width" color="green" dspState={dspState}
            isBypassed={dspState.masterStereoBypass}
            onToggleBypass={() => onChange({...dspState, masterStereoBypass: !dspState.masterStereoBypass})}
          >
             <Knob value={dspState.masterStereoWidth || 1} min={0} max={2} label="WIDTH" color="green" resetValue={1} onChange={(v) => onChange({...dspState, masterStereoWidth: v})} />
          </RackModule>

          <RackModule 
            title="DIMENSION" type="spatial" color="cyan" dspState={dspState}
            isBypassed={dspState.masterSpatialBypass}
            onToggleBypass={() => onChange({...dspState, masterSpatialBypass: !dspState.masterSpatialBypass})}
          >
             <Knob value={dspState.delayTime} min={0} max={1.0} label="TIME" color="cyan" onChange={(v) => onChange({...dspState, delayTime: v})} />
             <Knob value={dspState.delayFeedback} min={0} max={0.9} label="FDBK" color="cyan" onChange={(v) => onChange({...dspState, delayFeedback: v})} />
             <Slider value={dspState.reverbMix} min={0} max={1} label="MIX" color="cyan" onChange={(v) => onChange({...dspState, reverbMix: v})} />
          </RackModule>

           <RackModule title="MAIN OUT" type="output" color="red" dspState={dspState}>
             <Slider value={dspState.masterVolume} min={0} max={1.5} label="GAIN" color="red" onChange={(v) => onChange({...dspState, masterVolume: v})} />
          </RackModule>
        </div>
      </div>
    </div>
  );
};

import React, { useEffect, useRef } from 'react';
import { ClipViewConfig } from '../types';

interface WaveformProps {
  buffer: AudioBuffer;
  color: string;
  width: number;
  height: number;
  viewConfig: ClipViewConfig;
}

// Optimized Iterative FFT
const fft = (data: Float32Array): { re: Float32Array, im: Float32Array } => {
    const n = data.length;
    const m = Math.log2(n);

    const re = new Float32Array(n);
    const im = new Float32Array(n);

    for (let i = 0; i < n; i++) {
        let j = 0;
        let k = i;
        for (let l = 0; l < m; l++) {
            j = (j << 1) | (k & 1);
            k >>= 1;
        }
        re[j] = data[i];
        im[j] = 0;
    }

    for (let s = 1; s <= m; s++) {
        const mh = 1 << (s - 1);
        const m = 1 << s;
        const theta = -2 * Math.PI / m;
        const wmRe = Math.cos(theta);
        const wmIm = Math.sin(theta);

        for (let k = 0; k < n; k += m) {
            let wRe = 1;
            let wIm = 0;
            for (let j = 0; j < mh; j++) {
                const tRe = wRe * re[k + j + mh] - wIm * im[k + j + mh];
                const tIm = wRe * im[k + j + mh] + wIm * re[k + j + mh];
                const uRe = re[k + j];
                const uIm = im[k + j];

                re[k + j] = uRe + tRe;
                im[k + j] = uIm + tIm;
                re[k + j + mh] = uRe - tRe;
                im[k + j + mh] = uIm - tIm;

                const wReNew = wRe * wmRe - wIm * wmIm;
                wIm = wRe * wmIm + wIm * wmRe;
                wRe = wReNew;
            }
        }
    }

    return { re, im };
};

const blackmanHarris = (n: number, N: number) => {
    const a0 = 0.35875;
    const a1 = 0.48829;
    const a2 = 0.14128;
    const a3 = 0.01168;
    const term = (2 * Math.PI * n) / (N - 1);
    return a0 - a1 * Math.cos(term) + a2 * Math.cos(2 * term) - a3 * Math.cos(3 * term);
};

export const Waveform: React.FC<WaveformProps> = ({ buffer, color, width, height, viewConfig }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: true });
    if (!ctx) return;

    // Safety: Clamp dimensions to prevent crashes (0 width, or exceeding browser limits)
    // Most browsers choke > 32767 pixels. We cap at 32000 for safety.
    const safeWidth = Math.max(1, Math.min(32000, Math.floor(width)));
    const safeHeight = Math.max(1, Math.floor(height));

    canvas.width = safeWidth;
    canvas.height = safeHeight;
    ctx.clearRect(0, 0, safeWidth, safeHeight);

    const mode = viewConfig?.mode || 'PCM';
    const resolution = viewConfig?.resolution || 1;
    const scale = viewConfig?.scale || 1;

    const data = buffer.getChannelData(0);

    const hexToRgb = (hex: string) => {
        const bigint = parseInt(hex.replace('#', ''), 16);
        return { r: (bigint >> 16) & 255, g: (bigint >> 8) & 255, b: bigint & 255 };
    };
    const rgb = hexToRgb(color);

    if (mode === 'SPECTROGRAM') {
        const fftSize = 256; 
        const binCount = fftSize / 2;
        // Ensure stride is at least 1
        const stride = Math.max(1, Math.floor(data.length / safeWidth));

        try {
            const imgData = ctx.createImageData(safeWidth, safeHeight);
            const pixels = imgData.data;
            const windowData = new Float32Array(fftSize);

            for (let x = 0; x < safeWidth; x++) {
                const startIdx = Math.floor(x * stride);
                if (startIdx + fftSize >= data.length) break;

                for (let i = 0; i < fftSize; i++) {
                    windowData[i] = data[startIdx + i] * blackmanHarris(i, fftSize);
                }

                const { re, im } = fft(windowData);

                for (let y = 0; y < safeHeight; y++) {
                    const normY = 1 - (y / safeHeight);
                    const minLog = Math.log(1);
                    const maxLog = Math.log(binCount);
                    const logBin = Math.exp(minLog + normY * (maxLog - minLog));
                    const binIdx = Math.floor(logBin);

                    if (binIdx < binCount) {
                        const mag = Math.sqrt(re[binIdx] * re[binIdx] + im[binIdx] * im[binIdx]);
                        const intensity = Math.min(255, Math.log10(1 + mag * 100 * scale) * 80);

                        if (intensity > 10) {
                            const cellIdx = (y * safeWidth + x) * 4;
                            pixels[cellIdx] = rgb.r;
                            pixels[cellIdx + 1] = rgb.g;
                            pixels[cellIdx + 2] = rgb.b;
                            pixels[cellIdx + 3] = intensity;
                        }
                    }
                }
            }
            ctx.putImageData(imgData, 0, 0);
        } catch (e) {
            console.error("Spectrogram render failed", e);
        }

        ctx.fillStyle = 'rgba(255,255,255,0.05)';
        for(let i=1; i<4; i++) ctx.fillRect(0, i*(safeHeight/4), safeWidth, 1);

        return;
    }

    if (mode === 'PCM') {
        ctx.lineWidth = 1;

        const step = Math.ceil(data.length / safeWidth);
        const amp = (safeHeight / 2) * scale;
        const mid = safeHeight / 2;

        const drawPath = () => {
             ctx.beginPath();
             ctx.moveTo(0, mid);

             for (let i = 0; i < safeWidth; i+=2) {
               let min = 1.0;
               let max = -1.0;
               const idx = i * step;
               for (let j = 0; j < step; j++) {
                 if (idx + j >= data.length) break;
                 const datum = data[idx + j];
                 if (datum < min) min = datum;
                 if (datum > max) max = datum;
               }
               const val = Math.abs(max) > Math.abs(min) ? max : min;
               const y = mid + (val * amp);
               ctx.lineTo(i, y);
             }
             for (let i = safeWidth; i >= 0; i-=2) {
                  const idx = i * step;
                  const val = data[Math.min(data.length-1, idx)];
                  const y = mid - (val * amp * 0.5); 
                  ctx.lineTo(i, y);
             }
             ctx.closePath();
        };

        // 1. Core Glow (Wide/Faint)
        ctx.globalCompositeOperation = 'screen';
        drawPath();
        ctx.fillStyle = `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, 0.1)`;
        ctx.fill();

        // 2. Mid Glow
        ctx.shadowBlur = 10;
        ctx.shadowColor = color;
        ctx.strokeStyle = `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, 0.5)`;
        ctx.stroke();

        // 3. Hot Core
        ctx.shadowBlur = 2;
        ctx.strokeStyle = '#fff';
        ctx.stroke();

        ctx.shadowBlur = 0;
        return;
    }

    const fftSize = Math.pow(2, 6 + Math.floor(Math.max(1, Math.min(5, resolution)))); 
    const stride = Math.floor(data.length / (safeWidth / (resolution >= 3 ? 1 : 2))); 
    const safeStride = Math.max(fftSize, Math.min(stride, data.length));
    const numSlices = Math.floor((data.length - fftSize) / safeStride);

    ctx.globalCompositeOperation = 'lighter';

    if (mode === 'SEPARATED_SINES') {
        ctx.lineWidth = 1;
        for (let i = 0; i < numSlices; i++) {
            const startIdx = i * safeStride;
            const windowData = new Float32Array(fftSize);
            for (let n = 0; n < fftSize; n++) {
                if(startIdx + n < data.length) {
                    windowData[n] = data[startIdx + n] * blackmanHarris(n, fftSize);
                }
            }

            const { re, im } = fft(windowData);
            const x = (startIdx / data.length) * safeWidth;

            for (let k = 1; k < fftSize / 4; k++) {
                const mag = Math.sqrt(re[k]*re[k] + im[k]*im[k]);
                if (mag > 0.5) {
                    const normMag = Math.min(1, mag * 0.1 * scale);
                    const freqY = (k / (fftSize/4)) * safeHeight; 
                    ctx.strokeStyle = `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, ${normMag})`;
                    ctx.beginPath();
                    const y = safeHeight/2 + (Math.sin(i * 0.5) * freqY * 0.5);
                    ctx.moveTo(x, y - (mag*scale));
                    ctx.lineTo(x + 2, y + (mag*scale));
                    ctx.stroke();
                }
            }
        }
    } 
    else if (mode === 'SPECTRAL_FLUX_3D') {
        for (let i = 0; i < numSlices; i++) {
            const startIdx = i * safeStride;
            const windowData = new Float32Array(fftSize);
            for (let n = 0; n < fftSize; n++) {
                 if(startIdx + n < data.length) {
                    windowData[n] = data[startIdx + n] * blackmanHarris(n, fftSize);
                 }
            }
            const { re, im } = fft(windowData);
            const sliceX = (startIdx / data.length) * safeWidth;
            const maxBin = Math.min(fftSize / 2, 64); 

            ctx.beginPath();
            for (let k = 0; k < maxBin; k++) {
                const mag = Math.sqrt(re[k]*re[k] + im[k]*im[k]);
                const logMag = Math.log10(1 + mag) * 20 * scale; 
                const screenX = sliceX + (k * 0.5); 
                const screenY = safeHeight - (k * (safeHeight/maxBin) * 0.8) - logMag; 
                const alpha = Math.min(1, logMag / 15);

                ctx.strokeStyle = `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, ${alpha})`;
                if (k === 0) ctx.moveTo(screenX, screenY);
                else ctx.lineTo(screenX, screenY);
            }
            ctx.stroke();
        }
    }
    else if (mode === 'HYPER_DIMENSIONAL_4D') {
        const maxBin = Math.min(fftSize / 2, 48);
        for (let i = 0; i < numSlices; i++) {
            const startIdx = i * safeStride;
            const windowData = new Float32Array(fftSize);
            for (let n = 0; n < fftSize; n++) {
                 if(startIdx + n < data.length) {
                    windowData[n] = data[startIdx + n] * blackmanHarris(n, fftSize);
                 }
            }
            const { re, im } = fft(windowData);
            const sliceX = (startIdx / data.length) * safeWidth;

            for (let k = 0; k < maxBin; k++) {
                const mag = Math.sqrt(re[k]*re[k] + im[k]*im[k]);
                if (mag > 0.8) {
                    const phase = Math.atan2(im[k], re[k]);
                    const phaseDeg = ((phase + Math.PI) / (2 * Math.PI)) * 360;
                    const y = safeHeight - (k / maxBin) * safeHeight;
                    const size = Math.min(15, Math.log10(mag) * scale * 3);

                    const gradient = ctx.createRadialGradient(sliceX, y, 0, sliceX, y, size);
                    gradient.addColorStop(0, `hsla(${phaseDeg}, 100%, 80%, 0.8)`);
                    gradient.addColorStop(1, `hsla(${phaseDeg}, 100%, 50%, 0)`);

                    ctx.fillStyle = gradient;
                    ctx.fillRect(sliceX - size, y - size, size * 2, size * 2);
                }
            }
        }
    }

  }, [buffer, color, width, height, viewConfig]);

  return (
    <canvas 
      ref={canvasRef} 
      // Do not bind width/height attributes here to props directly if we are sanitizing them inside useEffect
      // but React warns if they mismatch. Let's strictly control them via logic in useEffect or layout.
      // However, we must ensure style fills container.
      style={{ width: '100%', height: '100%' }}
      className="w-full h-full opacity-100 mix-blend-screen"
    />
  );
};

import React, { useState, useRef, useEffect } from 'react';

interface KnobProps {
  value: number;
  min: number;
  max: number;
  onChange: (val: number) => void;
  label: string;
  color?: string;
  size?: number;
  resetValue?: number;
  logarithmic?: boolean; // New: For Frequency controls
  unit?: string; // New: Hz, dB, %, etc.
}

export const Knob: React.FC<KnobProps> = ({ 
    value, min, max, onChange, label, 
    color = 'cyan', size = 46, resetValue, 
    logarithmic = false, unit = '' 
}) => {
  const [isDragging, setIsDragging] = useState(false);
  const startY = useRef(0);
  const lastVal = useRef(value);

  // Helper: Value <-> 0..1 Position
  const toPosition = (v: number) => {
      const safeV = Math.max(min, Math.min(max, v));
      if (logarithmic) {
          const minLog = Math.log(min === 0 ? 0.001 : min);
          const maxLog = Math.log(max);
          const scale = (maxLog - minLog);
          return (Math.log(safeV) - minLog) / scale;
      }
      return (safeV - min) / (max - min);
  };

  const fromPosition = (p: number) => {
      const clampedP = Math.max(0, Math.min(1, p));
      if (logarithmic) {
          const minLog = Math.log(min === 0 ? 0.001 : min);
          const maxLog = Math.log(max);
          const scale = (maxLog - minLog);
          return Math.exp(minLog + scale * clampedP);
      }
      return min + clampedP * (max - min);
  };

  // Internal state for smooth dragging
  const [currentPos, setCurrentPos] = useState(toPosition(value));

  // Sync external updates if not dragging
  useEffect(() => {
      if (!isDragging) {
          setCurrentPos(toPosition(value));
      }
  }, [value, min, max, logarithmic, isDragging]);

  const handleStart = (clientY: number) => {
    setIsDragging(true);
    startY.current = clientY;
    lastVal.current = currentPos;
    document.body.style.cursor = 'ns-resize';
  };

  const handleMove = (clientY: number) => {
    if (!isDragging) return;

    // DELTA LOGIC: 
    // Moving 200px vertically equals 100% range traversal.
    // This allows for precise control regardless of screen size.
    const sensitivity = 200; 
    const delta = startY.current - clientY;
    const change = delta / sensitivity;

    const newPos = Math.max(0, Math.min(1, lastVal.current + change));

    // Update visuals immediately
    setCurrentPos(newPos);

    // Calculate actual value
    const newValue = fromPosition(newPos);
    onChange(newValue);

    // Debug Output
    console.debug(`[Knob: ${label}] Pos: ${newPos.toFixed(3)} | Val: ${newValue.toFixed(2)}`);
  };

  const handleEnd = () => {
    setIsDragging(false);
    document.body.style.cursor = 'default';
  };

  const handleDoubleClick = (e: React.MouseEvent | React.TouchEvent) => {
      e.stopPropagation();
      e.preventDefault();
      const target = resetValue !== undefined ? resetValue : min;
      onChange(target);
      setCurrentPos(toPosition(target));
  };

  useEffect(() => {
    if (isDragging) {
      const mouseMove = (e: MouseEvent) => { e.preventDefault(); handleMove(e.clientY); };
      const touchMove = (e: TouchEvent) => { e.preventDefault(); handleMove(e.touches[0].clientY); };
      const end = () => handleEnd();

      window.addEventListener('mousemove', mouseMove, { passive: false });
      window.addEventListener('touchmove', touchMove, { passive: false });
      window.addEventListener('mouseup', end);
      window.addEventListener('touchend', end);

      return () => {
        window.removeEventListener('mousemove', mouseMove);
        window.removeEventListener('touchmove', touchMove);
        window.removeEventListener('mouseup', end);
        window.removeEventListener('touchend', end);
      };
    }
  }, [isDragging]);

  const percentage = currentPos;
  const angle = -135 + (percentage * 270);

  const colorMap: Record<string, string> = {
    cyan: '#00f0ff', blue: '#2f80ed', purple: '#b721ff', green: '#0aff60',
    yellow: '#ffcc00', orange: '#ff6600', red: '#ff003c', pink: '#ff00d4', white: '#ffffff'
  };
  const accentColor = colorMap[color] || colorMap['cyan'];

  // Formatting for display
  let displayValue = value.toFixed(1);
  if (Math.abs(value) < 1 && value !== 0) displayValue = value.toFixed(2);
  if (value >= 1000) displayValue = (value / 1000).toFixed(1) + 'k';

  return (
    <div 
      className="flex flex-col items-center justify-center select-none touch-none group relative py-2" 
      onMouseDown={(e) => handleStart(e.clientY)}
      onTouchStart={(e) => handleStart(e.touches[0].clientY)}
      onDoubleClick={handleDoubleClick}
      style={{ width: size + 20, cursor: isDragging ? 'ns-resize' : 'pointer' }}
    >
      {/* Floating Value Readout (Holographic Debug) */}
      {isDragging && (
          <div className="absolute -top-10 left-1/2 -translate-x-1/2 z-50 bg-black/90 border border-white/20 px-2 py-1 rounded shadow-[0_0_15px_rgba(0,0,0,0.8)] backdrop-blur-md pointer-events-none whitespace-nowrap flex flex-col items-center">
              <span className="text-[10px] text-slate-400 font-mono tracking-tighter uppercase">{label}</span>
              <span className="text-sm font-bold text-white font-mono" style={{ textShadow: `0 0 8px ${accentColor}` }}>
                  {displayValue}<span className="text-[9px] text-slate-500 ml-0.5">{unit}</span>
              </span>
              {/* Debug raw position bar */}
              <div className="w-full h-0.5 bg-slate-800 mt-1">
                  <div className="h-full bg-white" style={{ width: `${percentage * 100}%` }}></div>
              </div>
          </div>
      )}

      <div className="relative flex items-center justify-center" style={{ width: size, height: size }}>

          {/* 1. Outer Tick Ring (Rotates) */}
          <div 
            className="absolute inset-0 rounded-full transition-transform duration-75 ease-out will-change-transform"
            style={{ 
                transform: `rotate(${angle}deg)`,
                opacity: 0.8
            }}
          >
             <div className="absolute top-0 left-1/2 -translate-x-1/2 w-0.5 h-1.5 bg-white shadow-[0_0_5px_white]"></div>
          </div>

          {/* 2. Static Backplate */}
          <div className="absolute inset-0 rounded-full bg-[#0a0a0a] shadow-[inset_0_2px_8px_rgba(0,0,0,1)] border border-white/10"></div>

          {/* 3. The Arc (SVG) */}
          <svg className="absolute top-0 left-0 w-full h-full" style={{ transform: 'rotate(135deg)' }}>
             <circle cx="50%" cy="50%" r="44%" fill="none" stroke="#1a1a1a" strokeWidth="4" />
             <circle 
                cx="50%" cy="50%" r="44%" 
                fill="none" 
                stroke={accentColor} 
                strokeWidth="4"
                strokeDasharray={`${percentage * 206} 300`} 
                strokeLinecap="round"
                style={{ filter: `drop-shadow(0 0 3px ${accentColor})` }}
             />
          </svg>

          {/* 4. The Cap */}
          <div 
            className="absolute rounded-full flex items-center justify-center overflow-hidden transition-colors"
            style={{ 
                width: '60%', height: '60%',
                background: isDragging ? '#222' : '#111',
                boxShadow: isDragging ? `inset 0 0 10px ${accentColor}20` : 'inset 0 1px 1px rgba(255,255,255,0.1)'
            }}
          >
          </div>
      </div>

      {/* Label */}
      <span 
        className="mt-2 text-[7px] font-bold tracking-widest uppercase transition-colors duration-200"
        style={{ 
            color: isDragging ? accentColor : '#52525b',
            textShadow: isDragging ? `0 0 8px ${accentColor}` : 'none',
        }}
      >
        {label}
      </span>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';

interface SliderProps {
  value: number;
  min: number;
  max: number;
  onChange: (val: number) => void;
  label: string;
  color?: string;
  height?: number;
  unit?: string;
}

export const Slider: React.FC<SliderProps> = ({ 
    value, min, max, onChange, label, 
    color = 'cyan', height = 110, unit = '' 
}) => {
  const [isDragging, setIsDragging] = useState(false);
  const startY = useRef(0);
  const startVal = useRef(value);

  const safeValue = Math.min(max, Math.max(min, Number.isFinite(value) ? value : min));

  const handleStart = (clientY: number) => {
    setIsDragging(true);
    startY.current = clientY;
    startVal.current = safeValue;
    document.body.style.cursor = 'ns-resize';
  };

  const handleMove = (clientY: number) => {
    if (!isDragging) return;

    // DELTA LOGIC:
    // 200px drag = full slider range. This decouples visual height from control sensitivity.
    const sensitivity = 200; 
    const delta = startY.current - clientY; // Up is positive in delta for value increase
    const range = max - min;
    const change = (delta / sensitivity) * range;

    let newVal = startVal.current + change;
    newVal = Math.max(min, Math.min(max, newVal));

    onChange(newVal);

    // Debug Output
    console.debug(`[Slider: ${label}] InputY: ${clientY} | Val: ${newVal.toFixed(3)}`);
  };

  const handleEnd = () => {
    setIsDragging(false);
    document.body.style.cursor = 'default';
  };

  useEffect(() => {
    if (isDragging) {
      const mouseMove = (e: MouseEvent) => { e.preventDefault(); handleMove(e.clientY); };
      const touchMove = (e: TouchEvent) => { e.preventDefault(); handleMove(e.touches[0].clientY); };
      const end = () => handleEnd();
      window.addEventListener('mousemove', mouseMove, { passive: false });
      window.addEventListener('touchmove', touchMove, { passive: false });
      window.addEventListener('mouseup', end);
      window.addEventListener('touchend', end);
      return () => {
        window.removeEventListener('mousemove', mouseMove);
        window.removeEventListener('touchmove', touchMove);
        window.removeEventListener('mouseup', end);
        window.removeEventListener('touchend', end);
      };
    }
  }, [isDragging]);

  const percentage = Math.max(0, Math.min(1, (safeValue - min) / (max - min)));

  const colorMap: Record<string, string> = {
    cyan: '#00f0ff', blue: '#2f80ed', purple: '#b721ff', green: '#0aff60',
    yellow: '#ffcc00', orange: '#ff6600', red: '#ff003c', pink: '#ff00d4', white: '#ffffff'
  };
  const accentColor = colorMap[color] || colorMap['cyan'];

  return (
    <div className="flex flex-col items-center justify-center space-y-2 select-none touch-none group relative">

      {/* Floating Debug Overlay */}
      {isDragging && (
          <div className="absolute -top-12 z-50 bg-black/90 border border-white/20 px-2 py-1 rounded shadow-[0_0_15px_rgba(0,0,0,0.8)] backdrop-blur-md whitespace-nowrap flex flex-col items-center">
              <span className="text-sm font-bold text-white font-mono" style={{ textShadow: `0 0 8px ${accentColor}` }}>
                  {safeValue.toFixed(2)}<span className="text-[9px] text-slate-500 ml-0.5">{unit}</span>
              </span>
          </div>
      )}

      {/* Touch Target */}
      <div 
        className="relative w-12 flex justify-center cursor-ns-resize py-2"
        style={{ height: height }}
        onMouseDown={(e) => handleStart(e.clientY)}
        onTouchStart={(e) => handleStart(e.touches[0].clientY)}
      >
        {/* Rail */}
        <div className="absolute w-1.5 h-full bg-[#0a0a0a] rounded-full overflow-hidden shadow-[inset_0_0_4px_rgba(0,0,0,1)] border border-white/10 pointer-events-none">
             {/* Fill Level */}
             <div 
                className="absolute bottom-0 w-full transition-all duration-75"
                style={{ 
                    height: `${percentage * 100}%`, 
                    backgroundColor: isDragging ? accentColor : `${accentColor}80`,
                    boxShadow: `0 0 10px ${accentColor}`
                }}
             />
        </div>

        {/* Thumb */}
        <div 
            className="absolute w-8 h-4 flex items-center justify-center transition-all duration-75 z-20 pointer-events-none"
            style={{ bottom: `calc(${percentage * 100}% - 8px)` }}
        >
             <div 
                className="w-full h-[2px] bg-white shadow-[0_0_5px_white]" 
                style={{ 
                    backgroundColor: isDragging ? '#fff' : '#ccc',
                    width: isDragging ? '100%' : '60%'
                }}
             ></div>
        </div>

      </div>

      <span 
        className="text-[7px] font-bold tracking-widest uppercase transition-all duration-200"
        style={{ 
            color: isDragging ? accentColor : '#52525b',
            textShadow: isDragging ? `0 0 5px ${accentColor}` : 'none'
        }}
      >
        {label}
      </span>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Track, ViewSettings } from '../types';
import { COLORS, TRACK_HEIGHT, EXPANDED_TRACK_HEIGHT } from '../constants';
import { Knob } from './Knob';
import { Slider } from './Slider';
import { XYPad } from './XYPad';
import { audioEngine } from '../services/audioEngine';

interface ChannelStripProps {
  track: Track;
  onUpdate: (id: string, updates: Partial<Track>) => void;
  onToggleArm: (id: string) => void;
  onToggleExpand: (id: string) => void;
  onDuplicate: (id: string) => void;
  width: number;
  viewSettings: ViewSettings;
  isCollapsed: boolean;
}

type Tab = 'PRE' | 'EQ' | 'CLR' | 'MOD';

export const ChannelStrip: React.FC<ChannelStripProps> = ({ 
    track, onUpdate, onToggleArm, onToggleExpand, onDuplicate, 
    width, viewSettings, isCollapsed 
}) => {
  const [showColors, setShowColors] = useState(false);
  const [activeTab, setActiveTab] = useState<Tab>('PRE');
  const menuRef = useRef<HTMLDivElement>(null);
  const meterCanvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setShowColors(false);
      }
    };
    if (showColors) document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [showColors]);

  // Meter Animation Loop
  useEffect(() => {
    if (isCollapsed) return;
    const canvas = meterCanvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animId: number;
    let peakHold = 0;
    let peakTimer = 0;

    const drawMeter = () => {
        const rms = audioEngine.getTrackRMS(track.id);
        const w = canvas.width;
        const h = canvas.height;

        ctx.clearRect(0, 0, w, h);

        // Background track
        ctx.fillStyle = '#111';
        ctx.fillRect(0, 0, w, h);

        // Render RMS bar
        const level = Math.min(1.0, rms * 2.5); 
        const activeW = level * w;

        // Gradient for Meter
        const grad = ctx.createLinearGradient(0, 0, w, 0);
        grad.addColorStop(0, track.color + '20'); 
        grad.addColorStop(0.5, track.color);     
        grad.addColorStop(1, '#fff');            

        ctx.fillStyle = grad;
        ctx.shadowBlur = 10;
        ctx.shadowColor = track.color;
        ctx.fillRect(0, 0, activeW, h);
        ctx.shadowBlur = 0;

        // Peak Hold
        if (level > peakHold) {
            peakHold = level;
            peakTimer = 60;
        } else {
            if (peakTimer > 0) peakTimer--;
            else peakHold *= 0.95;
        }

        ctx.fillStyle = '#fff';
        ctx.fillRect(peakHold * w, 0, 2, h);

        // Grid lines (dB markers visualization)
        ctx.fillStyle = 'rgba(0,0,0,0.5)';
        for(let i=1; i<10; i++) ctx.fillRect(i * (w/10), 0, 1, h);

        animId = requestAnimationFrame(drawMeter);
    };

    drawMeter();
    return () => cancelAnimationFrame(animId);
  }, [track.id, track.color, isCollapsed]);

  const updateFX = (key: keyof typeof track.fx, value: any) => {
      onUpdate(track.id, {
          fx: { ...track.fx, [key]: value }
      });
  };

  const isWide = width > 200;

  return (
    <div 
        className="sticky left-0 z-20 flex flex-col transition-all duration-300 ease-out group shadow-[4px_0_20px_rgba(0,0,0,0.8)] overflow-hidden" 
        style={{ 
            width: width,
            height: track.isExpanded ? EXPANDED_TRACK_HEIGHT : TRACK_HEIGHT,
            background: '#0a0a0c',
            borderRight: `1px solid ${track.color}20`
        }}
    >
       {/* --- HEADER SECTION --- */}
       <div className="p-3 flex-shrink-0 flex flex-col relative" style={{ height: TRACK_HEIGHT }}>
            {/* Identity Row */}
            <div className={`flex items-center gap-2 relative z-30 transition-all ${isCollapsed ? 'justify-center flex-col h-full space-y-4' : 'justify-between mb-2'}`}>
                <div className="relative flex-shrink-0" ref={menuRef}>
                    <button
                        className="w-3 h-3 rounded-full transition-all duration-300 hover:scale-125"
                        style={{ backgroundColor: track.color, boxShadow: `0 0 8px ${track.color}` }}
                        onClick={() => setShowColors(!showColors)}
                    />
                    {showColors && (
                    <div className="absolute top-full left-0 mt-2 bg-black/90 backdrop-blur-xl border border-white/10 p-2 rounded-lg grid grid-cols-4 gap-2 shadow-2xl z-50 w-32 animate-in zoom-in-95 duration-100">
                        {COLORS.map(c => (
                            <button key={c} className="w-5 h-5 rounded-full border border-white/10 hover:scale-110 transition-transform" style={{ backgroundColor: c, boxShadow: `0 0 10px ${c}` }}
                            onClick={(e) => { e.stopPropagation(); onUpdate(track.id, { color: c }); setShowColors(false); }} />
                        ))}
                    </div>
                    )}
                </div>
                {!isCollapsed && (
                    <input
                        className="bg-transparent text-[13px] font-bold text-slate-200 w-full outline-none px-0.5 truncate tracking-wide focus:text-white placeholder-slate-600 font-mono transition-all"
                        value={track.name}
                        onChange={(e) => onUpdate(track.id, { name: e.target.value })}
                        style={{ opacity: width < 60 ? 0 : 1 }}
                    />
                )}
                <button 
                    onClick={() => onToggleArm(track.id)} 
                    className={`w-6 h-6 rounded-full flex-shrink-0 flex items-center justify-center transition-all ${track.armed ? 'bg-red-500/10 shadow-[0_0_15px_rgba(220,38,38,0.4)]' : 'bg-transparent hover:bg-white/5'}`}
                >
                    <div className={`w-2.5 h-2.5 rounded-full transition-all ${track.armed ? 'bg-red-500 animate-pulse' : 'bg-slate-700'}`} />
                </button>
            </div>

            {/* Transport */}
            {!isCollapsed && (
                <div className={`flex space-x-1 mb-3 transition-all duration-300 overflow-hidden ${viewSettings.showTransport ? 'opacity-100 max-h-10' : 'opacity-0 max-h-0'}`}>
                    <button className={`flex-1 py-1.5 text-[10px] font-bold rounded transition-all tracking-wider ${track.muted ? 'bg-orange-500 text-black' : 'bg-[#1a1a1e] text-slate-500 hover:bg-[#222]'}`} onClick={() => onUpdate(track.id, { muted: !track.muted })}>MUTE</button>
                    <button className={`flex-1 py-1.5 text-[10px] font-bold rounded transition-all tracking-wider ${track.solo ? 'bg-yellow-400 text-black' : 'bg-[#1a1a1e] text-slate-500 hover:bg-[#222]'}`} onClick={() => onUpdate(track.id, { solo: !track.solo })}>SOLO</button>
                    {viewSettings.showRack && (
                        <button className={`flex-1 py-1.5 text-[10px] font-bold rounded transition-all tracking-wider ${track.isExpanded ? 'bg-blue-600 text-white' : 'bg-[#1a1a1e] text-blue-500 hover:bg-[#222]'}`} onClick={() => onToggleExpand(track.id)}>FX</button>
                    )}
                </div>
            )}

            {!isCollapsed && width > 100 && (
                <button 
                    className="absolute right-2 top-10 text-[8px] text-slate-700 hover:text-white uppercase tracking-wider opacity-0 group-hover:opacity-100 transition-opacity"
                    onClick={() => onDuplicate(track.id)}
                >Dup</button>
             )}

            {/* Mix */}
            {!isCollapsed && (
                <div className={`flex flex-col space-y-3 transition-all duration-500 overflow-hidden ${viewSettings.showMix ? 'opacity-100 max-h-24' : 'opacity-0 max-h-0'}`}>
                    {/* Volume */}
                    <div className="flex items-center space-x-2 group/vol relative">
                         {isWide && <span className="text-[8px] font-bold text-slate-600 w-8 text-right">VOL</span>}
                        <div className="flex-1 h-3 relative flex items-center bg-[#111] rounded-sm overflow-hidden border border-white/10 cursor-ew-resize">
                            <canvas ref={meterCanvasRef} width={200} height={12} className="absolute inset-0 w-full h-full opacity-60 pointer-events-none" />
                            <div className="absolute top-0 bottom-0 w-1 bg-white shadow-[0_0_10px_white] z-10 pointer-events-none" style={{ left: `${track.volume * 100}%` }}></div>

                            {/* Invisible Range Input for Interaction */}
                            <input 
                                type="range" min="0" max="1" step="0.01" 
                                value={track.volume} 
                                onChange={(e) => onUpdate(track.id, { volume: parseFloat(e.target.value) })}
                                className="absolute w-full h-full opacity-0 cursor-ew-resize z-20" 
                            />
                        </div>
                        {isWide && <span className="text-[9px] font-mono text-white w-8 text-right">{(track.volume * 100).toFixed(0)}</span>}
                    </div>

                    {/* Pan */}
                    <div className="flex items-center space-x-2 group/pan">
                         {isWide && <span className="text-[8px] font-bold text-slate-600 w-8 text-right">PAN</span>}
                        <div className="flex-1 h-1.5 relative flex items-center bg-[#111] rounded-full border border-white/5 cursor-ew-resize">
                            <div className="absolute left-1/2 w-px h-full bg-slate-600"></div>
                            <div className="absolute h-2.5 w-2.5 rounded-full shadow-[0_0_8px_white] bg-white pointer-events-none transition-transform top-1/2 -translate-y-1/2" style={{ left: `calc(${((track.pan + 1) / 2) * 100}% - 5px)` }} />
                            <input 
                                type="range" min="-1" max="1" step="0.1" 
                                value={track.pan} 
                                onChange={(e) => onUpdate(track.id, { pan: parseFloat(e.target.value) })}
                                className="absolute w-full h-full opacity-0 cursor-ew-resize" 
                            />
                        </div>
                        {isWide && <span className="text-[9px] font-mono text-slate-400 w-8 text-right">{track.pan.toFixed(1)}</span>}
                    </div>
                </div>
            )}
       </div>

       {/* --- TABBED FX RACK --- */}
       {track.isExpanded && !isCollapsed && (
           <div className="flex-1 flex flex-col overflow-hidden relative bg-black/40 backdrop-blur-md animate-in slide-in-from-left duration-300">

               {/* TABS */}
               <div className="flex border-b border-white/10 bg-black/60">
                   {(['PRE', 'EQ', 'CLR', 'MOD'] as Tab[]).map(tab => (
                       <button
                           key={tab}
                           onClick={() => setActiveTab(tab)}
                           className={`flex-1 py-2 text-[9px] font-black tracking-widest border-r border-white/5 transition-colors
                           ${activeTab === tab ? 'bg-white/10 text-white' : 'text-slate-600 hover:text-slate-400'}`}
                       >{tab}</button>
                   ))}
               </div>

               {/* TAB CONTENT */}
               <div className="flex-1 overflow-y-auto p-3 scrollbar-hide">

                   {/* PRE: DYNAMICS (Gate + Comp) */}
                   {activeTab === 'PRE' && (
                       <div className="grid grid-cols-2 gap-3 h-full content-start">
                           <div className="col-span-2 bg-white/5 rounded border border-white/5 p-3 flex items-center justify-between">
                               <div className="text-[9px] font-black text-green-500 -rotate-90 w-4">GATE</div>
                               <Slider value={track.fx.gateThreshold} min={-80} max={0} label="THRESH" unit="dB" color="green" height={90} onChange={(v) => updateFX('gateThreshold', v)} />
                               <Knob value={track.fx.highPassFreq} min={20} max={1000} label="HPF" unit="Hz" logarithmic color="green" size={36} onChange={(v) => updateFX('highPassFreq', v)} />
                           </div>
                           <div className="col-span-2 bg-white/5 rounded border border-white/5 p-3 flex flex-col items-center space-y-3">
                               <div className="w-full flex justify-between border-b border-white/10 pb-1">
                                   <span className="text-[9px] font-black text-yellow-500">COMPRESSOR</span>
                               </div>
                               <div className="flex justify-around w-full">
                                    <Knob value={track.fx.compressorThreshold} min={-60} max={0} label="THRESH" unit="dB" color="yellow" size={42} onChange={(v) => updateFX('compressorThreshold', v)} />
                                    <Knob value={track.fx.compressorRatio} min={1} max={20} label="RATIO" unit=":1" color="yellow" size={42} onChange={(v) => updateFX('compressorRatio', v)} />
                               </div>
                               <div className="flex justify-around w-full bg-black/20 p-2 rounded">
                                    <Knob value={(track.fx.compressorAttack || 0.003) * 1000} min={1} max={100} label="ATK" unit="ms" color="yellow" size={28} onChange={(v) => updateFX('compressorAttack', v/1000)} />
                                    <Knob value={(track.fx.compressorRelease || 0.25) * 1000} min={10} max={1000} label="REL" unit="ms" color="yellow" size={28} onChange={(v) => updateFX('compressorRelease', v/1000)} />
                               </div>
                           </div>
                       </div>
                   )}

                   {/* EQ: 3 Band + Presence */}
                   {activeTab === 'EQ' && (
                       <div className="flex flex-col h-full bg-white/5 rounded border border-white/5 p-3">
                            <div className="flex justify-around items-end flex-1 pb-4">
                                <Slider value={track.fx.eqLow} min={-12} max={12} label="LOW" unit="dB" color="cyan" height={140} onChange={(v) => updateFX('eqLow', v)} />
                                <Slider value={track.fx.eqMid} min={-12} max={12} label="MID" unit="dB" color="cyan" height={140} onChange={(v) => updateFX('eqMid', v)} />
                                <Slider value={track.fx.eqHigh} min={-12} max={12} label="HIGH" unit="dB" color="cyan" height={140} onChange={(v) => updateFX('eqHigh', v)} />
                            </div>
                            <div className="mt-2 pt-2 border-t border-white/10 flex justify-center bg-black/20 rounded py-2">
                                <Knob value={track.fx.presence || 4000} min={1000} max={10000} logarithmic label="AIR" unit="Hz" color="cyan" size={36} onChange={(v) => updateFX('presence', v)} />
                            </div>
                       </div>
                   )}

                   {/* CLR: Saturation + Bitcrush */}
                   {activeTab === 'CLR' && (
                       <div className="grid grid-cols-2 gap-3 h-full">
                           <div className="col-span-2 h-40 border border-white/10 rounded overflow-hidden">
                               <XYPad 
                                 x={(track.fx.saturation || 0) / 100} 
                                 y={(Math.min(20000, Math.max(1000, track.fx.distortionTone || 20000)) - 1000) / 19000}
                                 labelX="DRIVE" labelY="TONE" color="orange"
                                 onChange={(x, y) => {
                                     updateFX('saturation', x * 100);
                                     updateFX('distortionTone', 1000 + (y * 19000));
                                 }}
                               />
                           </div>
                           <div className="col-span-2 bg-white/5 rounded p-3 flex justify-around items-center">
                               <div className="flex flex-col items-center justify-center">
                                    <span className="text-[7px] text-red-500 font-bold mb-2">BITCRUSH</span>
                                    <Knob value={track.fx.bitCrushMix || 0} min={0} max={1} label="MIX" unit="%" color="red" size={36} onChange={(v) => updateFX('bitCrushMix', v)} />
                               </div>
                               <Slider value={track.fx.bitCrushBits || 16} min={1} max={16} label="BITS" unit="b" color="red" height={80} onChange={(v) => updateFX('bitCrushBits', Math.round(v))} />
                           </div>
                       </div>
                   )}

                   {/* MOD: Chorus + Sends */}
                   {activeTab === 'MOD' && (
                       <div className="grid grid-cols-2 gap-3 h-full">
                            <div className="col-span-2 h-32 border border-white/10 rounded overflow-hidden">
                               <XYPad 
                                 x={(track.fx.chorusRate || 0) / 10} 
                                 y={(track.fx.chorusDepth || 0) * 100}
                                 labelX="RATE" labelY="DEPTH" color="purple"
                                 onChange={(x, y) => {
                                     updateFX('chorusRate', x * 10);
                                     updateFX('chorusDepth', y / 100);
                                 }}
                               />
                            </div>
                            <div className="col-span-2 flex justify-around items-center bg-white/5 rounded p-2">
                                <Knob value={track.fx.chorusMix || 0} min={0} max={1} label="CHORUS" unit="%" color="purple" size={32} onChange={(v) => updateFX('chorusMix', v)} />
                                <Knob value={track.fx.sendReverb} min={0} max={1} label="VERB" unit="%" color="blue" size={32} onChange={(v) => updateFX('sendReverb', v)} />
                                <Knob value={track.fx.sendDelay} min={0} max={1} label="ECHO" unit="%" color="blue" size={32} onChange={(v) => updateFX('sendDelay', v)} />
                            </div>
                       </div>
                   )}

               </div>
           </div>
       )}
    </div>
  );
};

import React from 'react';
import { AudioClip, WaveformMode } from '../types';
import { Knob } from './Knob';

interface ClipInspectorProps {
  clip: AudioClip;
  onUpdate: (clipId: string, updates: Partial<AudioClip['fx']> | { viewConfig: any }) => void;
  onClose: () => void;
}

const InspectorModule: React.FC<{ title: string; children: React.ReactNode }> = ({ title, children }) => (
    <div className="flex flex-col h-full bg-[#0b1120] border-r border-slate-800 relative group min-w-[140px]">
         {/* Industrial Header */}
         <div className="h-7 bg-black border-b border-slate-800 flex items-center justify-center relative">
             <div className="text-[8px] font-black tracking-widest uppercase text-slate-500">{title}</div>
         </div>
         {/* Controls */}
         <div className="flex-1 flex items-center justify-center space-x-3 px-2 relative">
            {children}
         </div>
         {/* Screws */}
         <div className="absolute top-1 right-1 w-0.5 h-0.5 rounded-full bg-slate-700"></div>
         <div className="absolute top-1 left-1 w-0.5 h-0.5 rounded-full bg-slate-700"></div>
    </div>
);

export const ClipInspector: React.FC<ClipInspectorProps> = ({ clip, onUpdate, onClose }) => {
  const updateFX = (key: keyof AudioClip['fx'], value: any) => {
    onUpdate(clip.id, { [key]: value });
  };

  const updateView = (key: keyof AudioClip['viewConfig'], value: any) => {
      const currentConfig = clip.viewConfig || { mode: 'PCM', resolution: 2, scale: 1.0 };
      onUpdate(clip.id, { 
          viewConfig: { ...currentConfig, [key]: value } 
      });
  };

  const viewMode = clip.viewConfig?.mode || 'PCM';
  const viewRes = clip.viewConfig?.resolution || 2;
  const viewScale = clip.viewConfig?.scale || 1;

  return (
    <div className="fixed bottom-0 left-0 right-0 h-[200px] bg-[#020617] border-t-2 border-slate-700 shadow-[0_-10px_50px_rgba(0,0,0,0.9)] z-[60] flex flex-col animate-in slide-in-from-bottom duration-300">

      {/* Main Header */}
      <div className="h-8 bg-black flex items-center justify-between px-3 border-b border-slate-800 relative">
         <div className="absolute inset-0 opacity-20 pointer-events-none" 
              style={{ backgroundImage: 'repeating-linear-gradient(45deg, transparent, transparent 5px, rgba(255,255,255,0.05) 5px, rgba(255,255,255,0.05) 10px)' }}></div>

         <div className="flex items-center space-x-3 z-10">
            <div className="w-1.5 h-1.5 rounded-full bg-yellow-500 animate-pulse shadow-[0_0_8px_rgba(234,179,8,0.8)]"></div>
            <span className="text-[10px] font-black text-yellow-500 tracking-widest uppercase">CLIP EDITOR</span>
            <span className="text-[10px] text-slate-600">|</span>
            <span className="text-[10px] text-white font-mono uppercase truncate max-w-[200px]">{clip.name}</span>
         </div>

         <button onClick={onClose} className="text-slate-500 hover:text-white px-3 font-bold z-10 uppercase text-[9px] tracking-widest border border-transparent hover:border-slate-700 rounded transition-all">
            EXIT
         </button>
      </div>

      {/* Rack Container */}
      <div className="flex-1 overflow-x-auto overflow-y-hidden scrollbar-hide bg-[#050a15] relative">
          {/* Background Grid */}
          <div className="absolute inset-0 opacity-5 pointer-events-none" 
               style={{ backgroundImage: 'linear-gradient(#fff 1px, transparent 1px), linear-gradient(90deg, #fff 1px, transparent 1px)', backgroundSize: '20px 20px' }}></div>

          <div className="flex h-full min-w-max">

            {/* 1. VISUALS */}
            <InspectorModule title="VISUALIZATION">
                <div className="flex flex-col space-y-2 mr-2">
                    <div className="flex space-x-1">
                        {['PCM', 'SPECT'].map(m => (
                            <button 
                                key={m}
                                onClick={() => updateView('mode', m === 'SPECT' ? 'SPECTROGRAM' : 'PCM')}
                                className={`text-[7px] font-bold px-1.5 py-1 rounded border min-w-[36px] transition-all ${viewMode === (m === 'SPECT' ? 'SPECTROGRAM' : 'PCM') ? 'bg-blue-600 border-blue-500 text-white' : 'border-slate-800 text-slate-500'}`}
                            >{m}</button>
                        ))}
                    </div>
                    <div className="flex space-x-1">
                         {['3D', '4D'].map(m => (
                            <button 
                                key={m}
                                onClick={() => updateView('mode', m === '3D' ? 'SPECTRAL_FLUX_3D' : 'HYPER_DIMENSIONAL_4D')}
                                className={`text-[7px] font-bold px-1.5 py-1 rounded border min-w-[36px] transition-all ${viewMode === (m === '3D' ? 'SPECTRAL_FLUX_3D' : 'HYPER_DIMENSIONAL_4D') ? 'bg-purple-600 border-purple-500 text-white' : 'border-slate-800 text-slate-500'}`}
                            >{m}</button>
                        ))}
                    </div>
                </div>
                <Knob value={viewRes} min={1} max={5} label="RES" unit="" color="white" size={32} onChange={(v) => updateView('resolution', v)} />
                <Knob value={viewScale} min={0.5} max={3.0} label="ZOOM" unit="x" color="white" size={32} onChange={(v) => updateView('scale', v)} />
            </InspectorModule>

            {/* 2. SOURCE */}
            <InspectorModule title="SOURCE">
                <Knob value={clip.fx.gain} min={0} max={2} label="GAIN" unit="" color="green" size={40} onChange={(v) => updateFX('gain', v)} />
                <Knob value={clip.fx.pan} min={-1} max={1} label="PAN" unit="" color="yellow" size={40} resetValue={0} onChange={(v) => updateFX('pan', v)} />
            </InspectorModule>

            {/* 3. TIME */}
            <InspectorModule title="TIME / PITCH">
                <Knob value={clip.fx.pitch} min={0.25} max={2.0} label="RATE" unit="x" color="cyan" size={40} resetValue={1} onChange={(v) => updateFX('pitch', v)} />
                <div className="flex flex-col items-center justify-center space-y-2 ml-1">
                    <button 
                        onClick={() => updateFX('isReversed', !clip.fx.isReversed)}
                        className={`w-8 h-8 rounded border-2 flex items-center justify-center transition-all ${clip.fx.isReversed ? 'border-pink-500 bg-pink-500/20 text-pink-400 shadow-[0_0_10px_rgba(236,72,153,0.4)]' : 'border-slate-800 text-slate-700 hover:border-slate-600'}`}
                    >
                        <span className="font-black text-[8px]">REV</span>
                    </button>
                    <span className="text-[7px] text-slate-600 font-bold uppercase">DIR</span>
                </div>
            </InspectorModule>

            {/* 4. ENVELOPE */}
            <InspectorModule title="FADES">
                <Knob value={clip.fx.fadeIn || 0.01} min={0.01} max={2.0} label="IN" unit="s" color="green" size={32} onChange={(v) => updateFX('fadeIn', v)} />
                <Knob value={clip.fx.fadeOut || 0.01} min={0.01} max={2.0} label="OUT" unit="s" color="green" size={32} onChange={(v) => updateFX('fadeOut', v)} />
            </InspectorModule>

            {/* 5. FILTER */}
            <InspectorModule title="FILTER">
                <Knob value={clip.fx.filterFreq || 20000} min={100} max={20000} logarithmic label="FREQ" unit="Hz" color="pink" size={36} onChange={(v) => updateFX('filterFreq', v)} />
                <Knob value={clip.fx.filterRes || 0} min={0} max={20} label="RES" unit="" color="pink" size={36} onChange={(v) => updateFX('filterRes', v)} />
            </InspectorModule>

            {/* 6. FX */}
            <InspectorModule title="EFFECTS">
                 <Knob value={clip.fx.saturation || 0} min={0} max={100} label="DRIVE" unit="%" color="orange" size={32} onChange={(v) => updateFX('saturation', v)} />
                 <div className="w-px h-10 bg-slate-800 mx-1"></div>
                 <Knob value={clip.fx.tremoloDepth || 0} min={0} max={1} label="TREM" unit="%" color="purple" size={32} onChange={(v) => updateFX('tremoloDepth', v)} />
                 <Knob value={clip.fx.tremoloRate || 4} min={0.5} max={20} label="RATE" unit="Hz" color="purple" size={32} onChange={(v) => updateFX('tremoloRate', v)} />
            </InspectorModule>

          </div>
      </div>
    </div>
  );
};

export interface TrackFX {
  // Dynamics
  gateThreshold: number; // -60 to 0 dB (Expander)
  compressorThreshold: number; // dB
  compressorRatio: number; // Ratio
  compressorAttack: number; // ms
  compressorRelease: number; // ms

  // EQ
  highPassFreq: number; // Hz
  eqLow: number; // dB
  eqMid: number; // dB
  eqHigh: number; // dB
  presence: number; // Hz (High shelf freq adjust)

  // Color
  saturation: number; // 0-100
  distortionTone: number; // Hz (LPF)
  bitCrushBits: number; // 16 (clean) to 1 (destroyed)
  bitCrushMix: number; // 0-1

  // Cabinet
  cabinetOn: boolean;
  cabinetTone: number; // 0-1

  // Modulation
  chorusMix: number; // 0-1
  chorusRate: number; // Hz
  chorusDepth: number; // ms

  // Sends
  sendReverb: number; // 0-1
  reverbTone: number; // 0-1
  sendDelay: number; // 0-1
}

export interface ClipFX {
  gain: number; // 0-2 (1 is unity)
  pitch: number; // Playback rate
  pan: number; // -1 to 1
  isReversed: boolean;

  // Envelopes
  fadeIn: number; // seconds
  fadeOut: number; // seconds

  // Modulation
  tremoloDepth: number; // 0-1
  tremoloRate: number; // Hz

  // DSP
  filterFreq: number; // Hz
  filterRes: number; 
  saturation: number; 
}

export type WaveformMode = 'PCM' | 'SPECTROGRAM' | 'SEPARATED_SINES' | 'SPECTRAL_FLUX_3D' | 'HYPER_DIMENSIONAL_4D' | 'TENSOR_FLOW';

export interface ClipViewConfig {
    mode: WaveformMode;
    resolution: number; // 1 to 5
    scale: number; // 0.5 to 3.0
}

export interface Track {
  id: string;
  name: string;
  color: string;
  muted: boolean;
  solo: boolean;
  armed: boolean;
  volume: number;
  pan: number;
  fx: TrackFX; 
  isExpanded: boolean; 
}

export interface AudioClip {
  id: string;
  trackId: string;
  buffer: AudioBuffer;
  startTime: number;
  duration: number;
  offset: number;
  name: string;
  fx: ClipFX;
  viewConfig: ClipViewConfig; 
}

export interface ProjectMetadata {
  title: string;
  artist: string;
  album: string;
  year: string;
}

export enum EditMode {
  MOVE = 'MOVE',
  SPLIT = 'SPLIT',
  DELETE = 'DELETE'
}

export interface ViewSettings {
    showTransport: boolean; 
    showMix: boolean;       
    showRack: boolean;      
    isCollapsed: boolean;   
}

export interface DSPState {
  // Master Output
  masterVolume: number; 

  // Master Filter
  masterFilterFreq: number; 
  masterFilterRes: number; 
  masterFilterBypass: boolean; 

  // Master EQ
  masterEqLow: number; 
  masterEqMid: number; 
  masterEqHigh: number; 
  masterEqBypass: boolean;

  // Master Saturation
  masterSaturation: number; 
  masterSaturationBypass: boolean;

  // Master Exciter
  masterExciterDrive: number; 
  masterExciterBypass: boolean;

  // Master Stereo Width
  masterStereoWidth: number; 
  masterStereoBypass: boolean;

  // Master Dynamics
  masterCompressorThreshold: number; 
  masterCompressorRatio: number; 
  masterCompressorBypass: boolean;

  // Master Spatial
  delayTime: number; 
  delayFeedback: number; 
  reverbMix: number; 
  masterSpatialBypass: boolean;

  // Legacy
  limiterThreshold: number;
  reverbDecay: number; 
}

export interface Notification {
    id: string;
    message: string;
    type: 'info' | 'success' | 'warning' | 'error';
    timestamp: number;
}

import React, { useEffect, useState } from 'react';
import { Notification } from '../types';

interface NotificationSystemProps {
