import React, { useEffect, useRef } from 'react';
import { ClipViewConfig } from '../types';

interface WaveformProps {
  buffer: AudioBuffer;
  color: string;
  width: number;
  height: number;
  viewConfig: ClipViewConfig;
}

// Optimized Iterative FFT
const fft = (data: Float32Array): { re: Float32Array, im: Float32Array } => {
    const n = data.length;
    const m = Math.log2(n);
    const re = new Float32Array(n);
    const im = new Float32Array(n);
    for (let i = 0; i < n; i++) {
        let j = 0; let k = i;
        for (let l = 0; l < m; l++) { j = (j << 1) | (k & 1); k >>= 1; }
        re[j] = data[i]; im[j] = 0;
    }
    for (let s = 1; s <= m; s++) {
        const mh = 1 << (s - 1); const m = 1 << s;
        const theta = -2 * Math.PI / m;
        const wmRe = Math.cos(theta); const wmIm = Math.sin(theta);
        for (let k = 0; k < n; k += m) {
            let wRe = 1; let wIm = 0;
            for (let j = 0; j < mh; j++) {
                const tRe = wRe * re[k + j + mh] - wIm * im[k + j + mh];
                const tIm = wRe * im[k + j + mh] + wIm * re[k + j + mh];
                const uRe = re[k + j]; const uIm = im[k + j];
                re[k + j] = uRe + tRe; im[k + j] = uIm + tIm;
                re[k + j + mh] = uRe - tRe; im[k + j + mh] = uIm - tIm;
                const wReNew = wRe * wmRe - wIm * wmIm;
                wIm = wRe * wmIm + wIm * wmRe; wRe = wReNew;
            }
        }
    }
    return { re, im };
};

const blackmanHarris = (n: number, N: number) => {
    const a0 = 0.35875; const a1 = 0.48829; const a2 = 0.14128; const a3 = 0.01168;
    const term = (2 * Math.PI * n) / (N - 1);
    return a0 - a1 * Math.cos(term) + a2 * Math.cos(2 * term) - a3 * Math.cos(3 * term);
};

export const Waveform: React.FC<WaveformProps> = ({ buffer, color, width, height, viewConfig }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: true });
    if (!ctx) return;

    const safeWidth = Math.max(1, Math.min(32000, Math.floor(width)));
    const safeHeight = Math.max(1, Math.floor(height));

    canvas.width = safeWidth;
    canvas.height = safeHeight;
    ctx.clearRect(0, 0, safeWidth, safeHeight);

    const mode = viewConfig?.mode || 'PCM';
    const resolution = viewConfig?.resolution || 1;
    const scale = viewConfig?.scale || 1;

    const data = buffer.getChannelData(0);

    const hexToRgb = (hex: string) => {
        const bigint = parseInt(hex.replace('#', ''), 16);
        return { r: (bigint >> 16) & 255, g: (bigint >> 8) & 255, b: bigint & 255 };
    };
    const rgb = hexToRgb(color);

    if (mode === 'TENSOR_FLOW') {
        // "Tensor Flow" visualizer: Probability cloud + vector direction
        const step = Math.ceil(data.length / safeWidth);
        const mid = safeHeight / 2;

        // Draw Field Background
        const grad = ctx.createLinearGradient(0, 0, 0, safeHeight);
        grad.addColorStop(0, `rgba(${rgb.r},${rgb.g},${rgb.b},0)`);
        grad.addColorStop(0.5, `rgba(${rgb.r},${rgb.g},${rgb.b},0.1)`);
        grad.addColorStop(1, `rgba(${rgb.r},${rgb.g},${rgb.b},0)`);
        ctx.fillStyle = grad;
        ctx.fillRect(0,0,safeWidth, safeHeight);

        ctx.beginPath();

        for(let x=0; x<safeWidth; x+=2) {
            const idx = x * step;
            if(idx >= data.length) break;
            const val = data[idx];
            const absVal = Math.abs(val);

            // Vector Height
            const h = absVal * safeHeight * scale;
            const y = mid + (val * safeHeight * 0.5 * scale);

            // Draw "Particle" line
            ctx.moveTo(x, mid);
            ctx.lineTo(x, y);

            // Flow dots
            if (x % 20 === 0 && absVal > 0.1) {
                const size = absVal * 4;
                ctx.moveTo(x + size, y);
                ctx.arc(x, y, size, 0, Math.PI*2);
            }
        }

        ctx.strokeStyle = `rgba(${rgb.r},${rgb.g},${rgb.b},0.6)`;
        ctx.lineWidth = 1;
        ctx.stroke();

        // Topological overlay
        ctx.beginPath();
        for(let x=0; x<safeWidth; x+=4) {
             const idx = x * step;
             const val = data[idx] || 0;
             const y = mid - (val * safeHeight * 0.8 * scale);
             if (x===0) ctx.moveTo(x, y);
             else ctx.lineTo(x, y);
        }
        ctx.strokeStyle = '#fff';
        ctx.globalCompositeOperation = 'overlay';
        ctx.stroke();

        return;
    }

    if (mode === 'PCM') {
        ctx.lineWidth = 1;
        const step = Math.ceil(data.length / safeWidth);
        const amp = (safeHeight / 2) * scale;
        const mid = safeHeight / 2;

        const drawPath = () => {
             ctx.beginPath();
             ctx.moveTo(0, mid);
             for (let i = 0; i < safeWidth; i+=2) {
               let min = 1.0; let max = -1.0;
               const idx = i * step;
               for (let j = 0; j < step; j++) {
                 if (idx + j >= data.length) break;
                 const datum = data[idx + j];
                 if (datum < min) min = datum;
                 if (datum > max) max = datum;
               }
               const val = Math.abs(max) > Math.abs(min) ? max : min;
               const y = mid + (val * amp);
               ctx.lineTo(i, y);
             }
             for (let i = safeWidth; i >= 0; i-=2) {
                  const idx = i * step;
                  const val = data[Math.min(data.length-1, idx)];
                  const y = mid - (val * amp * 0.5); 
                  ctx.lineTo(i, y);
             }
             ctx.closePath();
        };

        ctx.globalCompositeOperation = 'screen';
        drawPath();
        ctx.fillStyle = `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, 0.15)`;
        ctx.fill();

        ctx.shadowBlur = 10;
        ctx.shadowColor = color;
        ctx.strokeStyle = `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, 0.8)`;
        ctx.stroke();

        ctx.shadowBlur = 2;
        ctx.strokeStyle = 'rgba(255,255,255,0.8)';
        ctx.stroke();
        ctx.shadowBlur = 0;
        return;
    }

    // FFT Based Modes
    const fftSize = Math.pow(2, 6 + Math.floor(Math.max(1, Math.min(5, resolution)))); 
    const stride = Math.floor(data.length / (safeWidth / (resolution >= 3 ? 1 : 2))); 
    const safeStride = Math.max(fftSize, Math.min(stride, data.length));
    const numSlices = Math.floor((data.length - fftSize) / safeStride);

    ctx.globalCompositeOperation = 'lighter';

    if (mode === 'SEPARATED_SINES') {
        ctx.lineWidth = 1;
        for (let i = 0; i < numSlices; i++) {
            const startIdx = i * safeStride;
            const windowData = new Float32Array(fftSize);
            for (let n = 0; n < fftSize; n++) { if(startIdx + n < data.length) windowData[n] = data[startIdx + n] * blackmanHarris(n, fftSize); }
            const { re, im } = fft(windowData);
            const x = (startIdx / data.length) * safeWidth;

            for (let k = 1; k < fftSize / 4; k++) {
                const mag = Math.sqrt(re[k]*re[k] + im[k]*im[k]);
                if (mag > 0.5) {
                    const normMag = Math.min(1, mag * 0.1 * scale);
                    const freqY = (k / (fftSize/4)) * safeHeight; 
                    ctx.strokeStyle = `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, ${normMag})`;
                    ctx.beginPath();
                    const y = safeHeight/2 + (Math.sin(i * 0.5) * freqY * 0.5);
                    ctx.moveTo(x, y - (mag*scale));
                    ctx.lineTo(x + 2, y + (mag*scale));
                    ctx.stroke();
                }
            }
        }
    } 
    else if (mode === 'SPECTRAL_FLUX_3D') {
        for (let i = 0; i < numSlices; i++) {
            const startIdx = i * safeStride;
            const windowData = new Float32Array(fftSize);
            for (let n = 0; n < fftSize; n++) { if(startIdx + n < data.length) windowData[n] = data[startIdx + n] * blackmanHarris(n, fftSize); }
            const { re, im } = fft(windowData);
            const sliceX = (startIdx / data.length) * safeWidth;
            const maxBin = Math.min(fftSize / 2, 64); 
            ctx.beginPath();
            for (let k = 0; k < maxBin; k++) {
                const mag = Math.sqrt(re[k]*re[k] + im[k]*im[k]);
                const logMag = Math.log10(1 + mag) * 20 * scale; 
                const screenX = sliceX + (k * 0.5); 
                const screenY = safeHeight - (k * (safeHeight/maxBin) * 0.8) - logMag; 
                const alpha = Math.min(1, logMag / 15);
                ctx.strokeStyle = `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, ${alpha})`;
                if (k === 0) ctx.moveTo(screenX, screenY);
                else ctx.lineTo(screenX, screenY);
            }
            ctx.stroke();
        }
    }
    else if (mode === 'HYPER_DIMENSIONAL_4D') {
        const maxBin = Math.min(fftSize / 2, 48);
        for (let i = 0; i < numSlices; i++) {
            const startIdx = i * safeStride;
            const windowData = new Float32Array(fftSize);
            for (let n = 0; n < fftSize; n++) { if(startIdx + n < data.length) windowData[n] = data[startIdx + n] * blackmanHarris(n, fftSize); }
            const { re, im } = fft(windowData);
            const sliceX = (startIdx / data.length) * safeWidth;
            for (let k = 0; k < maxBin; k++) {
                const mag = Math.sqrt(re[k]*re[k] + im[k]*im[k]);
                if (mag > 0.8) {
                    const phase = Math.atan2(im[k], re[k]);
                    const phaseDeg = ((phase + Math.PI) / (2 * Math.PI)) * 360;
                    const y = safeHeight - (k / maxBin) * safeHeight;
                    const size = Math.min(15, Math.log10(mag) * scale * 3);
                    const gradient = ctx.createRadialGradient(sliceX, y, 0, sliceX, y, size);
                    gradient.addColorStop(0, `hsla(${phaseDeg}, 100%, 80%, 0.8)`);
                    gradient.addColorStop(1, `hsla(${phaseDeg}, 100%, 50%, 0)`);
                    ctx.fillStyle = gradient;
                    ctx.fillRect(sliceX - size, y - size, size * 2, size * 2);
                }
            }
        }
    }
  }, [buffer, color, width, height, viewConfig]);

  return <canvas ref={canvasRef} style={{ width: '100%', height: '100%' }} className="w-full h-full opacity-100 mix-blend-screen" />;
};

import React, { useEffect, useRef } from 'react';

export const BackgroundInterference: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) return;

    let w = 0, h = 0;
    let time = 0;
    const gridSize = 40;

    const resize = () => {
      w = canvas.width = window.innerWidth;
      h = canvas.height = window.innerHeight;
    };
    window.addEventListener('resize', resize);
    resize();

    const draw = () => {
      time += 0.005;

      // Clear with Void
      ctx.fillStyle = '#030305';
      ctx.fillRect(0, 0, w, h);

      ctx.strokeStyle = '#1e293b';
      ctx.lineWidth = 1;

      const cols = Math.ceil(w / gridSize);
      const rows = Math.ceil(h / gridSize);

      for (let x = 0; x < cols; x++) {
          for (let y = 0; y < rows; y++) {
              // Noise-based angle
              const angle = (Math.cos(x * 0.1 + time) + Math.sin(y * 0.1 + time)) * Math.PI;
              const length = (Math.cos(x * 0.2 - time) + 1) * 10;

              const px = x * gridSize;
              const py = y * gridSize;

              // Draw Grid Point
              ctx.fillStyle = `rgba(56, 189, 248, ${Math.min(0.2, length/30)})`;
              ctx.fillRect(px - 1, py - 1, 2, 2);

              // Draw Vector Line (Tensor)
              ctx.beginPath();
              ctx.moveTo(px, py);
              ctx.lineTo(px + Math.cos(angle) * length, py + Math.sin(angle) * length);
              ctx.strokeStyle = `rgba(34, 211, 238, ${Math.min(0.1, length/40)})`;
              ctx.stroke();
          }
      }

      // Add Vignette
      const gradient = ctx.createRadialGradient(w/2, h/2, w/4, w/2, h/2, w);
      gradient.addColorStop(0, 'transparent');
      gradient.addColorStop(1, 'rgba(0,0,0,0.6)');
      ctx.fillStyle = gradient;
      ctx.fillRect(0, 0, w, h);

      requestAnimationFrame(draw);
    };

    const animId = requestAnimationFrame(draw);
    return () => {
      window.removeEventListener('resize', resize);
      cancelAnimationFrame(animId);
    };
  }, []);

  return (
    <canvas 
      ref={canvasRef} 
      className="fixed inset-0 pointer-events-none z-0"
    />
  );
};

import React, { useEffect, useRef } from 'react';
import { DSPState } from '../types';
import { Knob } from './Knob';
import { Slider } from './Slider';
import { audioEngine } from '../services/audioEngine';

interface DSPRackProps {
  dspState: DSPState;
  onChange: (newState: DSPState) => void;
}

// ... (Existing helper calculations kept, Phase correlation added directly in render) ...
const calculateFilterMagnitude = (freq: number, res: number) => {
    const steps = 12;
    const bars = [];
    for(let i=0; i<steps; i++) {
        const f = 20 * Math.pow(1000, i / (steps-1));
        const ratio = f / freq;
        const mag = 1 / Math.sqrt(Math.pow(1 - ratio*ratio, 2) + Math.pow(ratio/(0.707 + res), 2));
        bars.push(Math.min(1.2, mag)); 
    }
    return bars;
};
const calculateSaturatorShape = (drive: number) => {
    const bars = [];
    const k = drive;
    for(let i=0; i<12; i++) {
        const x = (i / 11) * 2 - 1; 
        let y = x;
        if (k > 0) y = ((Math.PI + k) * x) / (Math.PI + k * Math.abs(x));
        bars.push((y + 1) / 2);
    }
    return bars;
};
const calculateHarmonicsShape = (drive: number) => {
    const bars = new Array(12).fill(0);
    bars[0] = 0.8;
    for(let i=1; i<12; i++) {
       if (i % 2 !== 0) bars[i] = (drive / 100) * (1 / i) * 2; 
       else bars[i] = (drive / 100) * (1 / (i*2));
    }
    return bars;
};
const calculateEQShape = (low: number, mid: number, high: number) => {
    const bars = [];
    for(let i=0; i<12; i++) {
        let gain = 0;
        if (i < 4) gain = low; else if (i < 8) gain = mid; else gain = high;
        if (i===3 || i===4) gain = (low + mid)/2;
        if (i===7 || i===8) gain = (mid + high)/2;
        bars.push((gain + 12) / 24);
    }
    return bars;
};
const calculateDynamicsShape = (thresh: number, ratio: number) => {
    const reduction = audioEngine.getMasterGainReduction(); 
    const normalizedRed = Math.abs(reduction) / 20.0;
    return [Math.min(1, normalizedRed)];
};
const calculateSpatialShape = (time: number, feedback: number, mix: number) => {
    const bars = new Array(12).fill(0);
    bars[0] = 1.0; 
    const delayStep = Math.max(1, Math.round(time * 5)); 
    for (let i = 0; i < 12; i+=delayStep) {
       const decay = Math.pow(feedback, i/delayStep);
       if(i < 12) bars[i] = decay;
    }
    return bars.map(b => b * (0.3 + mix * 0.7));
};
const calculateOutputShape = (vol: number, dataArray: Uint8Array) => {
    if (!dataArray) return new Array(12).fill(0);
    let sum = 0;
    for(let i=0; i<dataArray.length; i++) sum += dataArray[i] * dataArray[i];
    const rms = Math.sqrt(sum / dataArray.length) / 255;
    const level = Math.min(1, rms * vol * 2.5);
    return Array(12).fill(0).map((_, i) => (level > i/12 ? 1 : 0));
};

const drawPixelLeds = (ctx: CanvasRenderingContext2D, width: number, height: number, bars: number[], baseColor: string, bypassed: boolean, type: string) => {
    ctx.clearRect(0, 0, width, height);
    const dimFactor = bypassed ? 0.2 : 1.0;
    const numCols = 12; const numRows = 8;
    const gap = 2;
    const colWidth = (width - ((numCols - 1) * gap)) / numCols;
    const rowHeight = (height - ((numRows - 1) * gap)) / numRows;

    // Background Grid
    ctx.fillStyle = '#0f172a';
    for (let c = 0; c < numCols; c++) {
        for (let r = 0; r < numRows; r++) {
             const rowIndex = (numRows - 1) - r;
             ctx.fillRect(c * (colWidth + gap), rowIndex * (rowHeight + gap), colWidth, rowHeight);
        }
    }

    if (type === 'dynamics') {
        const reduction = bars[0]; 
        const activeLeds = Math.floor(reduction * numRows);
        for (let c = 0; c < numCols; c++) {
            for (let r = 0; r < numRows; r++) {
                if (r < activeLeds) {
                    const y = r * (rowHeight + gap);
                    const x = c * (colWidth + gap);
                    ctx.fillStyle = `rgba(255, 50, 0, ${dimFactor})`;
                    ctx.shadowColor = 'red';
                    ctx.shadowBlur = bypassed ? 0 : 8;
                    ctx.fillRect(x, y, colWidth, rowHeight);
                    ctx.shadowBlur = 0;
                }
            }
        }
        return;
    }

    // Lissajous Phase Simulation for Width
    if (type === 'width') {
         const w = bars[0]; // normalized width
         ctx.strokeStyle = baseColor;
         ctx.lineWidth = 1.5;
         ctx.beginPath();
         const cx = width/2; const cy = height/2;
         const rx = width * 0.4 * w; // Width affects X spread
         const ry = height * 0.4;
         // Simulate phase trace
         for(let t=0; t<Math.PI*2; t+=0.1) {
             const x = cx + Math.sin(t * 3) * rx;
             const y = cy + Math.sin(t * 2) * ry;
             if(t===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
         }
         ctx.shadowBlur = 5;
         ctx.shadowColor = baseColor;
         ctx.stroke();
         ctx.shadowBlur = 0;
         return;
    }

    for (let c = 0; c < numCols; c++) {
        const value = bars[c] || 0; 
        const activeHeight = value * numRows;

        for (let r = 0; r < numRows; r++) {
             const y = ((numRows - 1) - r) * (rowHeight + gap);
             const x = c * (colWidth + gap);

             let intensity = 0;
             if (r < Math.floor(activeHeight)) intensity = 1.0;
             else if (r < activeHeight) intensity = activeHeight - r;

             if (intensity > 0) {
                 ctx.globalAlpha = intensity * dimFactor;
                 ctx.fillStyle = baseColor;
                 ctx.shadowBlur = bypassed ? 0 : 4;
                 ctx.shadowColor = baseColor;
                 ctx.fillRect(x, y, colWidth, rowHeight);

                 if (intensity > 0.6) {
                    ctx.fillStyle = 'rgba(255,255,255,0.4)';
                    ctx.shadowBlur = 0;
                    ctx.fillRect(x + 1, y + 1, colWidth - 2, rowHeight - 2);
                 }
                 ctx.shadowBlur = 0;
                 ctx.globalAlpha = 1.0;
             }
        }
    }
};

const RackModule: React.FC<{
  title: string;
  type: 'filter' | 'saturator' | 'exciter' | 'eq' | 'dynamics' | 'spatial' | 'width' | 'output';
  color: string;
  dspState: DSPState;
  children: React.ReactNode;
  isBypassed?: boolean;
  onToggleBypass?: () => void;
}> = ({ title, type, color, dspState, children, isBypassed = false, onToggleBypass }) => {

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const colorMap: Record<string, string> = {
    pink: '#ff00d4', orange: '#ff6600', blue: '#2f80ed',
    yellow: '#ffcc00', purple: '#b721ff', cyan: '#00f0ff',
    red: '#ff003c', green: '#0aff60',
  };
  const hexColor = colorMap[color] || '#3b82f6';

  useEffect(() => {
     const canvas = canvasRef.current;
     if(!canvas) return;
     const ctx = canvas.getContext('2d');
     if(!ctx) return;

     let frameId: number;
     const dataArray = new Uint8Array(audioEngine.analyser.frequencyBinCount);

     const render = () => {
         frameId = requestAnimationFrame(render);
         audioEngine.analyser.getByteFrequencyData(dataArray);
         const w = canvas.width;
         const h = canvas.height;
         let bars: number[] = [];

         if (type === 'filter') bars = calculateFilterMagnitude(dspState.masterFilterFreq, dspState.masterFilterRes);
         else if (type === 'saturator') bars = calculateSaturatorShape(dspState.masterSaturation);
         else if (type === 'exciter') bars = calculateHarmonicsShape(dspState.masterExciterDrive * 100);
         else if (type === 'eq') bars = calculateEQShape(dspState.masterEqLow, dspState.masterEqMid, dspState.masterEqHigh);
         else if (type === 'dynamics') bars = calculateDynamicsShape(dspState.masterCompressorThreshold, dspState.masterCompressorRatio);
         else if (type === 'spatial') bars = calculateSpatialShape(dspState.delayTime, dspState.delayFeedback, dspState.reverbMix);
         else if (type === 'width') bars = [dspState.masterStereoWidth]; // Use width for lissajous
         else if (type === 'output') bars = calculateOutputShape(dspState.masterVolume, dataArray);

         drawPixelLeds(ctx, w, h, bars, hexColor, !!isBypassed, type);
     };
     render();
     return () => cancelAnimationFrame(frameId);
  }, [type, dspState, hexColor, isBypassed]);

  return (
    <div className={`flex flex-col h-full backdrop-blur-md border-r border-white/5 relative group min-w-[170px] overflow-hidden transition-colors ${isBypassed ? 'bg-black/40' : 'bg-white/5'}`}>

      {/* VFD Screen Area */}
      <div className="h-24 relative p-3 flex flex-col items-center justify-end bg-black/40 shadow-[inset_0_10px_30px_rgba(0,0,0,0.5)]">
        <div className={`w-full h-full relative rounded border overflow-hidden transition-colors ${isBypassed ? 'border-white/5 bg-black' : 'border-white/10 bg-black/80'}`}>
             <div className="absolute inset-0 z-20 pointer-events-none opacity-20" style={{ backgroundImage: 'linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.25) 50%), linear-gradient(90deg, rgba(255, 0, 0, 0.06), rgba(0, 255, 0, 0.02), rgba(0, 0, 255, 0.06))', backgroundSize: '100% 2px, 3px 100%' }}></div>
             <canvas ref={canvasRef} width={140} height={60} className="w-full h-full" />
        </div>

        {/* Module Title Badge */}
        <div className={`absolute top-3 left-3 px-1.5 py-0.5 border rounded z-30 shadow-[0_0_10px_rgba(0,0,0,1)] flex items-center gap-2 ${isBypassed ? 'border-white/5 bg-black text-slate-600' : 'border-white/10 bg-black/80'}`}>
            <span className={`text-[9px] font-black tracking-widest uppercase transition-colors ${isBypassed ? 'text-slate-600' : 'text-white/90'}`} style={{ textShadow: isBypassed ? 'none' : `0 0 5px ${hexColor}` }}>{title}</span>
        </div>

        {/* Bypass LED */}
        {onToggleBypass && (
            <button 
                onClick={onToggleBypass}
                className={`absolute top-3 right-3 w-3 h-3 rounded-full border transition-all z-40 ${isBypassed ? 'bg-slate-900 border-slate-700' : `bg-${color}-500 border-white shadow-[0_0_8px_${hexColor}]`}`}
                style={{ backgroundColor: isBypassed ? '#111' : hexColor }}
            ></button>
        )}
      </div>

      {/* Controls Area */}
      <div className={`flex-1 flex items-center justify-center space-x-4 px-3 py-2 relative transition-opacity duration-300 ${isBypassed ? 'opacity-30 pointer-events-none grayscale' : 'opacity-100'}`}>
         {children}
      </div>
      <div className="absolute top-0 bottom-0 left-0 w-px bg-white/10"></div>
    </div>
  );
};

export const DSPRack: React.FC<DSPRackProps> = ({ dspState, onChange }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    let animationId: number;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const dataArray = new Uint8Array(audioEngine.analyser.frequencyBinCount);

    const draw = () => {
      animationId = requestAnimationFrame(draw);
      audioEngine.analyser.getByteFrequencyData(dataArray);
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      const numBlocks = 64;
      const blockWidth = canvas.width / numBlocks;
      const step = Math.floor(dataArray.length / numBlocks);

      for(let i = 0; i < numBlocks; i++) {
        const val = dataArray[i * step] / 255; 
        const activeHeight = val * canvas.height;
        ctx.fillStyle = `hsl(${210 + (val * 60)}, 100%, 60%)`;
        ctx.globalAlpha = 0.8;
        ctx.fillRect(i * blockWidth, canvas.height - activeHeight, blockWidth - 1, activeHeight);

        ctx.globalAlpha = 0.2;
        ctx.fillRect(i * blockWidth, canvas.height, blockWidth - 1, activeHeight * 0.5);
      }
    };
    draw();
    return () => cancelAnimationFrame(animationId);
  }, []);

  return (
    <div className="fixed bottom-0 left-0 right-0 h-[260px] bg-[#030305]/95 backdrop-blur-xl border-t border-white/10 shadow-[0_-10px_50px_rgba(0,0,0,0.9)] z-50 flex flex-col">
      <div className="flex h-6 border-b border-white/5 bg-black/50 relative shrink-0 items-center px-2 overflow-hidden">
        <canvas ref={canvasRef} width={800} height={32} className="absolute inset-0 w-full h-full opacity-50 mix-blend-screen" />
        <div className="relative z-10 text-[9px] text-cyan-400 font-mono tracking-widest px-2 bg-black/60 rounded border border-cyan-900/50">
          QUANTUM DSP MATRIX // SYSTEM ONLINE
        </div>
      </div>
      <div className="flex-1 overflow-x-auto overflow-y-hidden scrollbar-hide">
        <div className="flex h-full min-w-max">
          <RackModule title="RESONANCE" type="filter" color="pink" dspState={dspState} isBypassed={dspState.masterFilterBypass} onToggleBypass={() => onChange({...dspState, masterFilterBypass: !dspState.masterFilterBypass})}>
             <Knob value={dspState.masterFilterFreq} min={20} max={20000} logarithmic label="FREQ" unit="Hz" color="pink" onChange={(v) => onChange({...dspState, masterFilterFreq: v})} />
             <Knob value={dspState.masterFilterRes} min={0} max={20} label="Q-FAC" color="pink" onChange={(v) => onChange({...dspState, masterFilterRes: v})} />
          </RackModule>
          <RackModule title="EQUALIZER" type="eq" color="blue" dspState={dspState} isBypassed={dspState.masterEqBypass} onToggleBypass={() => onChange({...dspState, masterEqBypass: !dspState.masterEqBypass})}>
             <Slider value={dspState.masterEqLow} min={-12} max={12} label="LO" unit="dB" color="blue" onChange={(v) => onChange({...dspState, masterEqLow: v})} />
             <Slider value={dspState.masterEqMid} min={-12} max={12} label="MID" unit="dB" color="blue" onChange={(v) => onChange({...dspState, masterEqMid: v})} />
             <Slider value={dspState.masterEqHigh} min={-12} max={12} label="HI" unit="dB" color="blue" onChange={(v) => onChange({...dspState, masterEqHigh: v})} />
          </RackModule>
          <RackModule title="DYNAMICS" type="dynamics" color="yellow" dspState={dspState} isBypassed={dspState.masterCompressorBypass} onToggleBypass={() => onChange({...dspState, masterCompressorBypass: !dspState.masterCompressorBypass})}>
             <Knob value={dspState.masterCompressorThreshold} min={-60} max={0} label="THR" unit="dB" color="yellow" resetValue={0} onChange={(v) => onChange({...dspState, masterCompressorThreshold: v})} />
             <Knob value={dspState.masterCompressorRatio} min={1} max={20} label="RAT" unit=":1" color="yellow" resetValue={1} onChange={(v) => onChange({...dspState, masterCompressorRatio: v})} />
          </RackModule>
          <RackModule title="SATURATION" type="saturator" color="orange" dspState={dspState} isBypassed={dspState.masterSaturationBypass} onToggleBypass={() => onChange({...dspState, masterSaturationBypass: !dspState.masterSaturationBypass})}>
             <Slider value={dspState.masterSaturation} min={0} max={100} label="PLASMA" unit="%" color="orange" onChange={(v) => onChange({...dspState, masterSaturation: v})} />
          </RackModule>
          <RackModule title="HARMONICS" type="exciter" color="purple" dspState={dspState} isBypassed={dspState.masterExciterBypass} onToggleBypass={() => onChange({...dspState, masterExciterBypass: !dspState.masterExciterBypass})}>
             <Knob value={dspState.masterExciterDrive || 0} min={0} max={1} label="EXCITE" unit="%" color="purple" onChange={(v) => onChange({...dspState, masterExciterDrive: v})} />
          </RackModule>
          <RackModule title="STEREO" type="width" color="green" dspState={dspState} isBypassed={dspState.masterStereoBypass} onToggleBypass={() => onChange({...dspState, masterStereoBypass: !dspState.masterStereoBypass})}>
             <Knob value={dspState.masterStereoWidth || 1} min={0} max={2} label="WIDTH" unit="%" color="green" resetValue={1} onChange={(v) => onChange({...dspState, masterStereoWidth: v})} />
          </RackModule>
          <RackModule title="DIMENSION" type="spatial" color="cyan" dspState={dspState} isBypassed={dspState.masterSpatialBypass} onToggleBypass={() => onChange({...dspState, masterSpatialBypass: !dspState.masterSpatialBypass})}>
             <Knob value={dspState.delayTime} min={0} max={1.0} label="TIME" unit="s" color="cyan" onChange={(v) => onChange({...dspState, delayTime: v})} />
             <Knob value={dspState.delayFeedback} min={0} max={0.9} label="FDBK" unit="%" color="cyan" onChange={(v) => onChange({...dspState, delayFeedback: v})} />
             <Slider value={dspState.reverbMix} min={0} max={1} label="MIX" unit="%" color="cyan" onChange={(v) => onChange({...dspState, reverbMix: v})} />
          </RackModule>
           <RackModule title="MAIN OUT" type="output" color="red" dspState={dspState}>
             <Slider value={dspState.masterVolume} min={0} max={1.5} label="GAIN" unit="dB" color="red" onChange={(v) => onChange({...dspState, masterVolume: v})} />
          </RackModule>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { audioEngine } from './services/audioEngine';
import { storageService } from './services/storageService';
import { Controls } from './components/Controls';
import { TrackLane } from './components/TrackLane';
import { ChannelStrip } from './components/ChannelStrip';
import { DSPRack } from './components/DSPRack';
import { ClipInspector } from './components/ClipInspector';
import { BackgroundInterference } from './components/BackgroundInterference';
import { ProjectInfoPanel } from './components/ProjectInfoPanel';
import { CreditsModal } from './components/CreditsModal';
import { NotificationSystem } from './components/NotificationSystem';
import { Track, AudioClip, EditMode, DSPState, TrackFX, ProjectMetadata, ClipViewConfig, ViewSettings, Notification } from './types';
import { COLORS, TRACK_HEIGHT, EXPANDED_TRACK_HEIGHT, CHANNEL_WIDTH_DEFAULT, CHANNEL_WIDTH_EXPANDED, CHANNEL_WIDTH_COLLAPSED } from './constants';

const DEFAULT_TRACK_FX: TrackFX = {
    gateThreshold: -60, compressorThreshold: 0, compressorRatio: 1, compressorAttack: 0.003, compressorRelease: 0.25,
    highPassFreq: 20, eqLow: 0, eqMid: 0, eqHigh: 0, presence: 4000,
    saturation: 0, distortionTone: 20000, bitCrushBits: 16, bitCrushMix: 0,
    cabinetOn: false, cabinetTone: 0.5,
    chorusMix: 0, chorusRate: 1.5, chorusDepth: 0.002,
    sendReverb: 0, reverbTone: 0.5, sendDelay: 0,
};

const DEFAULT_CLIP_FX = {
    gain: 1.0, pitch: 1.0, pan: 0, isReversed: false,
    fadeIn: 0.01, fadeOut: 0.01,
    tremoloDepth: 0, tremoloRate: 4,
    filterFreq: 20000, filterRes: 0, saturation: 0
};

const DEFAULT_VIEW_CONFIG: ClipViewConfig = {
    mode: 'TENSOR_FLOW', // New default high-tech visual
    resolution: 2, scale: 1.0
};

const App: React.FC = () => {
  // State
  const [tracks, setTracks] = useState<Track[]>([
    { id: 't1', name: 'Vocals', color: COLORS[0], muted: false, solo: false, armed: true, volume: 0.8, pan: 0, fx: {...DEFAULT_TRACK_FX}, isExpanded: false },
    { id: 't2', name: 'Guitars', color: COLORS[1], muted: false, solo: false, armed: false, volume: 0.8, pan: -0.3, fx: {...DEFAULT_TRACK_FX}, isExpanded: false },
    { id: 't3', name: 'Bass', color: COLORS[2], muted: false, solo: false, armed: false, volume: 0.8, pan: 0, fx: {...DEFAULT_TRACK_FX}, isExpanded: false },
    { id: 't4', name: 'Drums', color: COLORS[3], muted: false, solo: false, armed: false, volume: 0.8, pan: 0, fx: {...DEFAULT_TRACK_FX}, isExpanded: false },
  ]);
  const [clips, setClips] = useState<AudioClip[]>([]);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0); 
  const [zoom, setZoom] = useState(100); 
  const [selectedClipId, setSelectedClipId] = useState<string | null>(null);
  const [snapTime, setSnapTime] = useState<number | null>(null);
  const [viewSettings, setViewSettings] = useState<ViewSettings>({ showTransport: true, showMix: true, showRack: true, isCollapsed: false });
  const [clipClipboard, setClipClipboard] = useState<AudioClip | null>(null);
  const [loopRange, setLoopRange] = useState<{ start: number, end: number } | null>(null);
  const [isLooping, setIsLooping] = useState(false);
  const [editMode, setEditMode] = useState<EditMode>(EditMode.MOVE);
  const [metadata, setMetadata] = useState<ProjectMetadata>({ title: 'New Project', artist: 'Artist', album: '', year: new Date().getFullYear().toString() });
  const [showInfoPanel, setShowInfoPanel] = useState(false);
  const [showCredits, setShowCredits] = useState(true);
  const [isExporting, setIsExporting] = useState(false);
  const [dspState, setDspState] = useState<DSPState>({ 
      masterVolume: 1.0, masterFilterFreq: 20000, masterFilterRes: 0, masterFilterBypass: false,
      masterEqLow: 0, masterEqMid: 0, masterEqHigh: 0, masterEqBypass: false,
      masterSaturation: 0, masterSaturationBypass: false, masterExciterDrive: 0, masterExciterBypass: false,
      masterStereoWidth: 1, masterStereoBypass: false, masterCompressorThreshold: 0, masterCompressorRatio: 1, masterCompressorBypass: false,
      delayTime: 0.3, delayFeedback: 0.3, reverbMix: 0.2, masterSpatialBypass: false, limiterThreshold: -1.0, reverbDecay: 2.0
  });
  const [isRecording, setIsRecording] = useState(false);
  const [monitor, setMonitor] = useState(false);

  // Notification System State
  const [notifications, setNotifications] = useState<Notification[]>([]);

  // Refs
  const rafRef = useRef<number>();
  const startTimeRef = useRef<number>(0); 
  const startOffsetRef = useRef<number>(0); 
  const recordingStartRef = useRef<number>(0); 
  const dragRef = useRef<{ clipId: string; startX: number; originalStart: number } | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  const addNotification = (message: string, type: 'info' | 'success' | 'warning' | 'error' = 'info') => {
      setNotifications(prev => [...prev, { id: Date.now().toString(), message, type, timestamp: Date.now() }]);
  };

  // --- Layout Calculation ---
  const isAnyExpanded = tracks.some(t => t.isExpanded);
  const currentChannelWidth = viewSettings.isCollapsed ? CHANNEL_WIDTH_COLLAPSED : (isAnyExpanded ? CHANNEL_WIDTH_EXPANDED : CHANNEL_WIDTH_DEFAULT);

  // --- Initialization ---
  useEffect(() => {
    storageService.init();
    const handleTouch = () => audioEngine.resume();
    document.addEventListener('touchstart', handleTouch, { once: true });
    document.addEventListener('click', handleTouch, { once: true });
    tracks.forEach(t => audioEngine.ensureTrackChannel(t));
    addNotification('SYSTEM ONLINE. AUDIO ENGINE READY.', 'success');
    return () => cancelAnimationFrame(rafRef.current!);
  }, []);

  useEffect(() => { tracks.forEach(t => audioEngine.updateTrackState(t)); }, [tracks]);
  useEffect(() => { audioEngine.updateMasterDSP(dspState); }, [dspState]);

  // --- Keyboard Shortcuts ---
  useEffect(() => {
      const handleKeyDown = (e: KeyboardEvent) => {
          if (e.target instanceof HTMLInputElement) return; 

          switch(e.key) {
              case ' ': 
                  e.preventDefault(); 
                  togglePlay(); 
                  break;
              case 's':
              case 'S':
                  if(selectedClipId) splitClip(selectedClipId, currentTime);
                  else if (isPlaying) addNotification('SELECT CLIP TO SPLIT', 'warning');
                  break;
              case 'Delete':
              case 'Backspace':
                  if(selectedClipId) deleteSelectedClip();
                  break;
              case 'c':
                  if ((e.ctrlKey || e.metaKey) && selectedClipId) handleCopy();
                  break;
              case 'v':
                  if (e.ctrlKey || e.metaKey) handlePaste();
                  break;
              case 'd':
                  if ((e.ctrlKey || e.metaKey) && selectedClipId) {
                      e.preventDefault();
                      const clip = clips.find(c => c.id === selectedClipId);
                      if (clip) handleDuplicateTrack(clip.trackId);
                  }
                  break;
          }
      };
      window.addEventListener('keydown', handleKeyDown);
      return () => window.removeEventListener('keydown', handleKeyDown);
  }, [selectedClipId, currentTime, isPlaying, clipClipboard, clips]); // Deps needed for closure scope

  const calculateSnap = (time: number, zoomLevel: number): number => {
      let gridSize = 1.0;
      if (zoomLevel > 150) gridSize = 0.25;
      if (zoomLevel > 300) gridSize = 0.1;
      const snapped = Math.round(time / gridSize) * gridSize;
      const pixelDiff = Math.abs(snapped - time) * zoomLevel;
      if (pixelDiff < 15) return snapped;
      return time;
  };

  const restartPlayback = async (startAt: number) => {
    audioEngine.stopAll();
    setCurrentTime(startAt);
    startTimeRef.current = audioEngine.ctx.currentTime;
    startOffsetRef.current = startAt;
    clips.forEach(clip => {
      const track = tracks.find(t => t.id === clip.trackId);
      if (track && !track.muted && (!tracks.some(t => t.solo) || track.solo)) audioEngine.playClip(clip, startAt);
    });
  };

  const updatePlayhead = useCallback(() => {
    if (audioEngine.ctx.state === 'running' && isPlaying) {
        const elapsed = audioEngine.ctx.currentTime - startTimeRef.current;
        const newTime = startOffsetRef.current + elapsed;
        if (isLooping && loopRange && newTime >= loopRange.end) {
            restartPlayback(loopRange.start);
        } else if (isExporting) {
            const maxDuration = Math.max(...clips.map(c => c.startTime + c.duration)) + 2.0;
            if (newTime >= maxDuration) finishExport();
            else setCurrentTime(newTime);
        } else {
            setCurrentTime(newTime);
        }
    }
    rafRef.current = requestAnimationFrame(updatePlayhead);
  }, [isPlaying, isLooping, loopRange, isExporting, clips]);

  useEffect(() => {
    if (isPlaying) rafRef.current = requestAnimationFrame(updatePlayhead);
    else cancelAnimationFrame(rafRef.current!);
  }, [isPlaying, updatePlayhead]);

  const togglePlay = async () => {
    await audioEngine.resume();
    if (isPlaying) {
      audioEngine.stopAll();
      setIsPlaying(false);
      const elapsed = audioEngine.ctx.currentTime - startTimeRef.current;
      const newTime = startOffsetRef.current + elapsed;
      setCurrentTime(newTime);
      startOffsetRef.current = newTime;
    } else {
      startTimeRef.current = audioEngine.ctx.currentTime;
      startOffsetRef.current = currentTime; 
      clips.forEach(clip => {
        const track = tracks.find(t => t.id === clip.trackId);
        if (track && !track.muted && (!tracks.some(t => t.solo) || track.solo)) audioEngine.playClip(clip, currentTime);
      });
      setIsPlaying(true);
    }
  };

  const handleCopy = () => {
      if (!selectedClipId) return;
      const clip = clips.find(c => c.id === selectedClipId);
      if (clip) {
          setClipClipboard(clip);
          addNotification('CLIP COPIED TO BUFFER', 'info');
      }
  };

  const handlePaste = () => {
      if (!clipClipboard) return;
      let targetTrackId = tracks[0].id;
      if (selectedClipId) {
          const selected = clips.find(c => c.id === selectedClipId);
          if (selected) targetTrackId = selected.trackId;
      }
      const newClip: AudioClip = {
          ...clipClipboard,
          id: Date.now().toString() + Math.random().toString().slice(2,5),
          startTime: currentTime, // Smart Paste at Playhead
          trackId: targetTrackId
      };
      setClips(prev => [...prev, newClip]);
      setSelectedClipId(newClip.id);
      addNotification('BUFFER PASTED AT PLAYHEAD', 'success');
  };

  const handleTrackUpdate = (trackId: string, updates: Partial<Track>) => {
    setTracks(prev => prev.map(t => t.id === trackId ? { ...t, ...updates } : t));
  };
  const toggleTrackArm = (trackId: string) => setTracks(prev => prev.map(t => ({ ...t, armed: t.id === trackId })));
  const toggleTrackExpand = (trackId: string) => setTracks(prev => prev.map(t => ({ ...t, isExpanded: t.id === trackId ? !t.isExpanded : false })));

  const handleDuplicateTrack = (trackId: string) => {
      const originalTrack = tracks.find(t => t.id === trackId);
      if (!originalTrack) return;
      const newTrackId = Date.now().toString();
      const newTrack: Track = { ...originalTrack, id: newTrackId, name: originalTrack.name + ' (Copy)', isExpanded: false };
      const originalClips = clips.filter(c => c.trackId === trackId);
      const newClips = originalClips.map(c => ({ ...c, id: c.id + '_copy_' + Math.random().toString().slice(2,5), trackId: newTrackId }));
      const index = tracks.findIndex(t => t.id === trackId);
      const newTracks = [...tracks];
      newTracks.splice(index + 1, 0, newTrack);
      setTracks(newTracks);
      setClips(prev => [...prev, ...newClips]);
      audioEngine.ensureTrackChannel(newTrack);
      addNotification('TRACK DUPLICATION COMPLETE', 'success');
  };

  const handleExport = async (format: 'mp4') => {
      if (isPlaying) await togglePlay();
      setIsExporting(true);
      addNotification('STARTING REAL-TIME EXPORT...', 'info');
      audioEngine.startBounceRecorder();
      startTimeRef.current = audioEngine.ctx.currentTime;
      startOffsetRef.current = 0;
      setCurrentTime(0);
      clips.forEach(clip => {
        const track = tracks.find(t => t.id === clip.trackId);
        if (track && !track.muted && (!tracks.some(t => t.solo) || track.solo)) audioEngine.playClip(clip, 0);
      });
      setIsPlaying(true);
  };

  const finishExport = async () => {
      setIsPlaying(false);
      audioEngine.stopAll();
      const blob = await audioEngine.stopBounceRecorder();
      setIsExporting(false);
      setShowInfoPanel(false);
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.style.display = 'none'; a.href = url;
      const cleanTitle = metadata.title.replace(/[^a-z0-9]/gi, '_').toLowerCase();
      a.download = `${cleanTitle}_bounce.mp4`;
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      addNotification('EXPORT COMPLETE. FILE SAVED.', 'success');
  };

  const stopRecordingAndSave = async () => {
      const blob = await audioEngine.stopRecording();
      setIsRecording(false);
      const id = Date.now().toString();
      await storageService.saveBlob(id, blob);
      const buffer = await audioEngine.decodeAudioData(blob);
      const armedTrack = tracks.find(t => t.armed) || tracks[0];
      const newClip: AudioClip = {
        id, trackId: armedTrack.id, buffer, startTime: recordingStartRef.current,
        duration: buffer.duration, offset: 0, name: `Rec ${id.substr(-4)}`,
        fx: {...DEFAULT_CLIP_FX}, viewConfig: {...DEFAULT_VIEW_CONFIG}
      };
      setClips(prev => [...prev, newClip]);
      setSelectedClipId(id);
      addNotification(`RECORDING SAVED: ${newClip.name}`, 'success');
  };

  const toggleRecord = async () => {
    if (isRecording) {
      await stopRecordingAndSave();
    } else {
      recordingStartRef.current = currentTime; 
      try {
        await audioEngine.startRecording(monitor);
        setIsRecording(true);
        addNotification('RECORDING STARTED', 'warning');
        if (!isPlaying) await togglePlay();
      } catch (err) {
        addNotification('MICROPHONE INIT FAILED', 'error');
        console.error("Failed to start recording:", err);
      }
    }
  };

  const stop = async () => {
    audioEngine.stopAll();
    setIsPlaying(false);
    if (isExporting) {
        audioEngine.stopBounceRecorder();
        setIsExporting(false);
        addNotification('EXPORT CANCELLED', 'error');
        return;
    }
    if (isRecording) {
        try { await stopRecordingAndSave(); } catch(e) { console.error("Error saving:", e); setIsRecording(false); }
    }
    const returnTime = isRecording ? recordingStartRef.current : (isLooping && loopRange ? loopRange.start : 0);
    setCurrentTime(returnTime);
    startOffsetRef.current = returnTime;
  };

  // --- Clip Interaction (Move/Split/Context) ---
  const handleClipInteract = (clipId: string, action: string, data?: any) => {
    if (action === 'context') {
        const { action: ctxAction } = data;
        if (ctxAction === 'copy') { setSelectedClipId(clipId); handleCopy(); }
        if (ctxAction === 'split') { splitClip(clipId, currentTime); }
        if (ctxAction === 'delete') { setSelectedClipId(clipId); deleteSelectedClip(); }
        if (ctxAction === 'reverse') {
             const c = clips.find(x => x.id === clipId);
             if (c) {
                handleClipFXUpdate(clipId, { isReversed: !c.fx.isReversed });
                addNotification(c.fx.isReversed ? 'CLIP NORMALIZED' : 'CLIP REVERSED', 'info');
             }
        }
        return;
    }
    if (action === 'tap') {
        setSelectedClipId(clipId);
        return;
    }
    if (editMode === EditMode.MOVE && action === 'start') {
      setSelectedClipId(clipId);
      dragRef.current = { clipId, startX: data.x, originalStart: data.originalStart };

      const handleMove = (e: any) => {
        if (!dragRef.current || !containerRef.current) return;
        const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
        const deltaX = clientX - dragRef.current.startX;
        const deltaTime = deltaX / zoom; 

        let newStart = Math.max(0, dragRef.current.originalStart + deltaTime);

        const snappedStart = calculateSnap(newStart, zoom);
        if (Math.abs(snappedStart - newStart) * zoom < 15) {
            setSnapTime(snappedStart);
            newStart = snappedStart;
        } else {
            setSnapTime(null);
        }

        const containerRect = containerRef.current.getBoundingClientRect();
        const scrollY = containerRef.current.scrollTop;
        const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
        const relativeY = clientY - containerRect.top + scrollY;

        let accumulatedHeight = 0;
        let targetTrackId = null;
        for (const track of tracks) {
            const h = track.isExpanded ? EXPANDED_TRACK_HEIGHT : TRACK_HEIGHT;
            if (relativeY >= accumulatedHeight && relativeY < accumulatedHeight + h) {
                targetTrackId = track.id;
                break;
            }
            accumulatedHeight += h;
        }

        setClips(prev => prev.map(c => 
          c.id === dragRef.current?.clipId ? { 
              ...c, startTime: newStart, 
              trackId: targetTrackId || c.trackId 
          } : c
        ));
      };

      const handleEnd = () => {
        dragRef.current = null;
        setSnapTime(null);
        window.removeEventListener('touchmove', handleMove); window.removeEventListener('touchend', handleEnd);
        window.removeEventListener('mousemove', handleMove); window.addEventListener('mouseup', handleEnd);
      };
      window.addEventListener('touchmove', handleMove, { passive: false }); window.addEventListener('touchend', handleEnd);
      window.addEventListener('mousemove', handleMove); window.addEventListener('mouseup', handleEnd);
    }
  };

  const handleClipFXUpdate = (clipId: string, updates: Partial<AudioClip['fx']> | { viewConfig: any }) => {
      setClips(prev => prev.map(c => c.id === clipId ? { ...c, ...('viewConfig' in updates ? { viewConfig: updates.viewConfig } : { fx: { ...c.fx, ...updates } }) } : c));
      if (!('viewConfig' in updates)) audioEngine.updateClipParams(clipId, updates as Partial<typeof DEFAULT_CLIP_FX>);
  };

  const splitClip = (clipId: string, splitTimeOverride?: number) => {
    const clip = clips.find(c => c.id === clipId);
    if (!clip) return;
    const timeToSplitAt = splitTimeOverride !== undefined ? splitTimeOverride : currentTime;

    // Snap Split
    const snappedSplit = calculateSnap(timeToSplitAt, zoom);

    const relativeSplitTime = (snappedSplit - clip.startTime); 
    if (relativeSplitTime <= 0.01 || relativeSplitTime >= clip.duration - 0.01) {
        addNotification('CANNOT SPLIT: TOO CLOSE TO EDGE', 'error');
        return;
    }

    const clip1: AudioClip = { ...clip, id: clip.id + '_1', duration: relativeSplitTime };
    const clip2: AudioClip = { ...clip, id: clip.id + '_2', startTime: snappedSplit, duration: clip.duration - relativeSplitTime, offset: clip.offset + relativeSplitTime };
    setClips(prev => prev.filter(c => c.id !== clipId).concat([clip1, clip2]));
    setSelectedClipId(clip2.id);
    addNotification('CLIP SPLIT SUCCESSFUL', 'success');
  };

  const handleSplitButton = () => { if (selectedClipId) splitClip(selectedClipId, currentTime); else addNotification('NO CLIP SELECTED', 'error'); };
  const deleteSelectedClip = () => { if (selectedClipId) { setClips(prev => prev.filter(c => c.id !== selectedClipId)); setSelectedClipId(null); addNotification('CLIP DELETED', 'info'); }};

  const handleTimelineScrub = (e: any) => {
     if (e.target.dataset.bg) setSelectedClipId(null);
     if (!containerRef.current) return;
     const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
     const containerLeft = containerRef.current.getBoundingClientRect().left;
     const scrollLeft = containerRef.current.scrollLeft;
     const relativeX = clientX - containerLeft + scrollLeft;
     const rawTime = Math.max(0, (relativeX - currentChannelWidth) / zoom);
     const snappedTime = calculateSnap(rawTime, zoom);
     setCurrentTime(snappedTime);
     startOffsetRef.current = snappedTime;
  };

  const selectedClip = clips.find(c => c.id === selectedClipId);

  return (
    <div className="flex flex-col h-screen w-screen bg-transparent text-slate-100 overflow-hidden select-none font-sans relative">
      <BackgroundInterference />
      <NotificationSystem notifications={notifications} />

      <div className="flex flex-col h-full w-full z-10 relative bg-black/10 backdrop-blur-[1px]">
        <Controls 
            isPlaying={isPlaying} isRecording={isRecording} isLooping={isLooping} loopRange={loopRange}
            onPlayPause={togglePlay} onRecord={toggleRecord} onStop={stop} onBounce={() => setShowInfoPanel(true)} 
            onDelete={deleteSelectedClip} onSplit={handleSplitButton} onCopy={handleCopy} onPaste={handlePaste}
            onToggleLoop={handleToggleLoop} onSetLoopIn={handleSetLoopIn} onSetLoopOut={handleSetLoopOut}
            onOpenInfo={() => setShowInfoPanel(true)} onShowCredits={() => setShowCredits(true)}
            editMode={editMode} setEditMode={setEditMode} monitor={monitor} setMonitor={setMonitor}
            zoom={zoom} setZoom={setZoom} hasSelection={!!selectedClipId} hasClipboard={!!clipClipboard}
            viewSettings={viewSettings} setViewSettings={setViewSettings}
        />

        <div ref={containerRef} className="flex-1 overflow-y-auto overflow-x-auto relative mt-[60px] mb-[260px]" 
            onClick={() => setSelectedClipId(null)} data-bg="true">

            {/* Snap Guide Line */}
            {snapTime !== null && (
                <div className="absolute top-0 bottom-0 border-l border-yellow-400 z-50 pointer-events-none opacity-80"
                     style={{ left: `${(snapTime * zoom) + currentChannelWidth}px` }}></div>
            )}

            {/* Playhead */}
            <div className="absolute top-0 bottom-0 z-40 pointer-events-none border-r border-cyan-500 shadow-[0_0_15px_rgba(6,182,212,0.6)]"
                style={{ left: `${(currentTime * zoom) + currentChannelWidth}px`, width: '1px' }}>
                <div className="absolute -top-4 -translate-x-1/2 bg-cyan-900 text-[9px] px-1.5 py-0.5 rounded-sm text-cyan-200 font-mono shadow-md whitespace-nowrap z-50 border border-cyan-500/50">
                    {currentTime.toFixed(2)}s
                </div>
                <div className="absolute top-0 bottom-0 w-px bg-cyan-500/50"></div>
            </div>

            {/* Ruler */}
            <div className="h-8 min-w-full bg-[#030305]/90 border-b border-white/10 relative cursor-pointer shadow-lg z-30 transition-all duration-300"
                style={{ width: `${Math.max(window.innerWidth, (300 * zoom) + currentChannelWidth)}px` }}
                onClick={(e) => { e.stopPropagation(); handleTimelineScrub(e); }}>
                {loopRange && (
                    <div className="absolute top-0 bottom-0 bg-blue-500/10 border-x border-blue-500/50 z-0"
                        style={{ left: `${loopRange.start * zoom + currentChannelWidth}px`, width: `${(loopRange.end - loopRange.start) * zoom}px` }}>
                    </div>
                )}
                {/* Adaptive Ticks */}
                {Array.from({ length: Math.ceil(300 * zoom / 100) * (zoom > 150 ? 8 : 4) }).map((_, i) => {
                    const step = zoom > 150 ? 0.125 : 0.25;
                    const sec = i * step;
                    const isMajor = Math.abs(sec % 1) < 0.001;
                    const isMedium = Math.abs(sec % 0.5) < 0.001;
                    let h = 'h-1 border-slate-700';
                    if (isMajor) h = 'h-3 border-slate-500';
                    else if (isMedium) h = 'h-2 border-slate-600';
                    return (
                    <div key={i} className={`absolute bottom-0 border-l z-10 pointer-events-none ${h}`} 
                        style={{ left: (sec * zoom) + currentChannelWidth }}>
                        {isMajor && <span className="text-[8px] font-mono font-medium text-slate-500 pl-1.5 -mt-4 block">{sec}</span>}
                    </div>
                )})}
            </div>

            {/* Tracks Container */}
            <div className="min-w-full pb-20 relative bg-transparent transition-all duration-300" style={{ width: `${Math.max(window.innerWidth, (300 * zoom) + currentChannelWidth)}px` }} data-bg="true">
            {tracks.map(track => (
                <div key={track.id} className="flex border-b border-white/5 bg-black/20" style={{ height: track.isExpanded ? EXPANDED_TRACK_HEIGHT : TRACK_HEIGHT }}>
                <ChannelStrip 
                    track={track} onUpdate={handleTrackUpdate} onToggleArm={toggleTrackArm} onToggleExpand={toggleTrackExpand} onDuplicate={handleDuplicateTrack}
                    width={currentChannelWidth} viewSettings={viewSettings} isCollapsed={viewSettings.isCollapsed}
                />
                <div className="relative w-full z-10 flex-1 min-w-0">
                    <TrackLane track={track} clips={clips.filter(c => c.trackId === track.id)} editMode={editMode} selectedClipId={selectedClipId} onClipInteract={handleClipInteract} currentTime={currentTime} isPlaying={isPlaying} zoom={zoom} />
                </div>
                </div>
            ))}
            </div>
        </div>

        {selectedClip ? (
            <ClipInspector clip={selectedClip} onUpdate={handleClipFXUpdate} onClose={() => setSelectedClipId(null)} />
        ) : (
            <DSPRack dspState={dspState} onChange={(s) => { setDspState(s); audioEngine.updateMasterDSP(s); }} />
        )}

        {showInfoPanel && (
            <ProjectInfoPanel metadata={metadata} onChange={setMetadata} onClose={() => !isExporting && setShowInfoPanel(false)} onExport={handleExport} isExporting={isExporting} />
        )}
        {showCredits && (
            <CreditsModal onClose={() => setShowCredits(false)} />
        )}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { audioEngine } from './services/audioEngine';
import { storageService } from './services/storageService';
import { Controls } from './components/Controls';
import { TrackLane } from './components/TrackLane';
import { ChannelStrip } from './components/ChannelStrip';
import { DSPRack } from './components/DSPRack';
import { ClipInspector } from './components/ClipInspector';
import { BackgroundInterference } from './components/BackgroundInterference';
import { ProjectInfoPanel } from './components/ProjectInfoPanel';
import { CreditsModal } from './components/CreditsModal';
import { NotificationSystem } from './components/NotificationSystem';
import { Track, AudioClip, EditMode, DSPState, TrackFX, ProjectMetadata, ClipViewConfig, ViewSettings, Notification } from './types';
import { COLORS, TRACK_HEIGHT, EXPANDED_TRACK_HEIGHT, CHANNEL_WIDTH_DEFAULT, CHANNEL_WIDTH_EXPANDED, CHANNEL_WIDTH_COLLAPSED } from './constants';

const DEFAULT_TRACK_FX: TrackFX = {
    gateThreshold: -60, compressorThreshold: 0, compressorRatio: 1, compressorAttack: 0.003, compressorRelease: 0.25,
    highPassFreq: 20, eqLow: 0, eqMid: 0, eqHigh: 0, presence: 4000,
    saturation: 0, distortionTone: 20000, bitCrushBits: 16, bitCrushMix: 0,
    cabinetOn: false, cabinetTone: 0.5,
    chorusMix: 0, chorusRate: 1.5, chorusDepth: 0.002,
    sendReverb: 0, reverbTone: 0.5, sendDelay: 0,
};

const DEFAULT_CLIP_FX = {
    gain: 1.0, pitch: 1.0, pan: 0, isReversed: false,
    fadeIn: 0.01, fadeOut: 0.01,
    tremoloDepth: 0, tremoloRate: 4,
    filterFreq: 20000, filterRes: 0, saturation: 0
};

const DEFAULT_VIEW_CONFIG: ClipViewConfig = {
    mode: 'TENSOR_FLOW', // New default high-tech visual
    resolution: 2, scale: 1.0
};

const App: React.FC = () => {
  // State
  const [tracks, setTracks] = useState<Track[]>([
    { id: 't1', name: 'Vocals', color: COLORS[0], muted: false, solo: false, armed: true, volume: 0.8, pan: 0, fx: {...DEFAULT_TRACK_FX}, isExpanded: false },
    { id: 't2', name: 'Guitars', color: COLORS[1], muted: false, solo: false, armed: false, volume: 0.8, pan: -0.3, fx: {...DEFAULT_TRACK_FX}, isExpanded: false },
    { id: 't3', name: 'Bass', color: COLORS[2], muted: false, solo: false, armed: false, volume: 0.8, pan: 0, fx: {...DEFAULT_TRACK_FX}, isExpanded: false },
    { id: 't4', name: 'Drums', color: COLORS[3], muted: false, solo: false, armed: false, volume: 0.8, pan: 0, fx: {...DEFAULT_TRACK_FX}, isExpanded: false },
  ]);
  const [clips, setClips] = useState<AudioClip[]>([]);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0); 
  const [zoom, setZoom] = useState(100); 
  const [selectedClipId, setSelectedClipId] = useState<string | null>(null);
  const [snapTime, setSnapTime] = useState<number | null>(null);
  const [viewSettings, setViewSettings] = useState<ViewSettings>({ showTransport: true, showMix: true, showRack: true, isCollapsed: false });
  const [clipClipboard, setClipClipboard] = useState<AudioClip | null>(null);
  const [loopRange, setLoopRange] = useState<{ start: number, end: number } | null>(null);
  const [isLooping, setIsLooping] = useState(false);
  const [editMode, setEditMode] = useState<EditMode>(EditMode.MOVE);
  const [metadata, setMetadata] = useState<ProjectMetadata>({ title: 'New Project', artist: 'Artist', album: '', year: new Date().getFullYear().toString() });
  const [showInfoPanel, setShowInfoPanel] = useState(false);
  const [showCredits, setShowCredits] = useState(true);
  const [isExporting, setIsExporting] = useState(false);
  const [dspState, setDspState] = useState<DSPState>({ 
      masterVolume: 1.0, masterFilterFreq: 20000, masterFilterRes: 0, masterFilterBypass: false,
      masterEqLow: 0, masterEqMid: 0, masterEqHigh: 0, masterEqBypass: false,
      masterSaturation: 0, masterSaturationBypass: false, masterExciterDrive: 0, masterExciterBypass: false,
      masterStereoWidth: 1, masterStereoBypass: false, masterCompressorThreshold: 0, masterCompressorRatio: 1, masterCompressorBypass: false,
      delayTime: 0.3, delayFeedback: 0.3, reverbMix: 0.2, masterSpatialBypass: false, limiterThreshold: -1.0, reverbDecay: 2.0
  });
  const [isRecording, setIsRecording] = useState(false);
  const [monitor, setMonitor] = useState(false);

  // Notification System State
  const [notifications, setNotifications] = useState<Notification[]>([]);

  // Refs
  const rafRef = useRef<number>();
  const startTimeRef = useRef<number>(0); 
  const startOffsetRef = useRef<number>(0); 
  const recordingStartRef = useRef<number>(0); 
  const dragRef = useRef<{ clipId: string; startX: number; originalStart: number } | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  const addNotification = (message: string, type: 'info' | 'success' | 'warning' | 'error' = 'info') => {
      setNotifications(prev => [...prev, { id: Date.now().toString(), message, type, timestamp: Date.now() }]);
  };

  // --- Layout Calculation ---
  const isAnyExpanded = tracks.some(t => t.isExpanded);
  const currentChannelWidth = viewSettings.isCollapsed ? CHANNEL_WIDTH_COLLAPSED : (isAnyExpanded ? CHANNEL_WIDTH_EXPANDED : CHANNEL_WIDTH_DEFAULT);

  // --- Initialization ---
  useEffect(() => {
    storageService.init();
    const handleTouch = () => audioEngine.resume();
    document.addEventListener('touchstart', handleTouch, { once: true });
    document.addEventListener('click', handleTouch, { once: true });
    tracks.forEach(t => audioEngine.ensureTrackChannel(t));
    addNotification('SYSTEM ONLINE. AUDIO ENGINE READY.', 'success');
    return () => cancelAnimationFrame(rafRef.current!);
  }, []);

  useEffect(() => { tracks.forEach(t => audioEngine.updateTrackState(t)); }, [tracks]);
  useEffect(() => { audioEngine.updateMasterDSP(dspState); }, [dspState]);

  // --- Keyboard Shortcuts ---
  useEffect(() => {
      const handleKeyDown = (e: KeyboardEvent) => {
          if (e.target instanceof HTMLInputElement) return; 

          switch(e.key) {
              case ' ': 
                  e.preventDefault(); 
                  togglePlay(); 
                  break;
              case 's':
              case 'S':
                  if(selectedClipId) splitClip(selectedClipId, currentTime);
                  else if (isPlaying) addNotification('SELECT CLIP TO SPLIT', 'warning');
                  break;
              case 'Delete':
              case 'Backspace':
                  if(selectedClipId) deleteSelectedClip();
                  break;
              case 'c':
                  if ((e.ctrlKey || e.metaKey) && selectedClipId) handleCopy();
                  break;
              case 'v':
                  if (e.ctrlKey || e.metaKey) handlePaste();
                  break;
              case 'd':
                  if ((e.ctrlKey || e.metaKey) && selectedClipId) {
                      e.preventDefault();
                      const clip = clips.find(c => c.id === selectedClipId);
                      if (clip) handleDuplicateTrack(clip.trackId);
                  }
                  break;
          }
      };
      window.addEventListener('keydown', handleKeyDown);
      return () => window.removeEventListener('keydown', handleKeyDown);
  }, [selectedClipId, currentTime, isPlaying, clipClipboard, clips]); // Deps needed for closure scope

  const calculateSnap = (time: number, zoomLevel: number): number => {
      let gridSize = 1.0;
      if (zoomLevel > 150) gridSize = 0.25;
      if (zoomLevel > 300) gridSize = 0.1;
      const snapped = Math.round(time / gridSize) * gridSize;
      const pixelDiff = Math.abs(snapped - time) * zoomLevel;
      if (pixelDiff < 15) return snapped;
      return time;
  };

  const restartPlayback = async (startAt: number) => {
    audioEngine.stopAll();
    setCurrentTime(startAt);
    startTimeRef.current = audioEngine.ctx.currentTime;
    startOffsetRef.current = startAt;
    clips.forEach(clip => {
      const track = tracks.find(t => t.id === clip.trackId);
      if (track && !track.muted && (!tracks.some(t => t.solo) || track.solo)) audioEngine.playClip(clip, startAt);
    });
  };

  const updatePlayhead = useCallback(() => {
    if (audioEngine.ctx.state === 'running' && isPlaying) {
        const elapsed = audioEngine.ctx.currentTime - startTimeRef.current;
        const newTime = startOffsetRef.current + elapsed;
        if (isLooping && loopRange && newTime >= loopRange.end) {
            restartPlayback(loopRange.start);
        } else if (isExporting) {
            const maxDuration = Math.max(...clips.map(c => c.startTime + c.duration)) + 2.0;
            if (newTime >= maxDuration) finishExport();
            else setCurrentTime(newTime);
        } else {
            setCurrentTime(newTime);
        }
    }
    rafRef.current = requestAnimationFrame(updatePlayhead);
  }, [isPlaying, isLooping, loopRange, isExporting, clips]);

  useEffect(() => {
    if (isPlaying) rafRef.current = requestAnimationFrame(updatePlayhead);
    else cancelAnimationFrame(rafRef.current!);
  }, [isPlaying, updatePlayhead]);

  const togglePlay = async () => {
    await audioEngine.resume();
    if (isPlaying) {
      audioEngine.stopAll();
      setIsPlaying(false);
      const elapsed = audioEngine.ctx.currentTime - startTimeRef.current;
      const newTime = startOffsetRef.current + elapsed;
      setCurrentTime(newTime);
      startOffsetRef.current = newTime;
    } else {
      startTimeRef.current = audioEngine.ctx.currentTime;
      startOffsetRef.current = currentTime; 
      clips.forEach(clip => {
        const track = tracks.find(t => t.id === clip.trackId);
        if (track && !track.muted && (!tracks.some(t => t.solo) || track.solo)) audioEngine.playClip(clip, currentTime);
      });
      setIsPlaying(true);
    }
  };

  const handleCopy = () => {
      if (!selectedClipId) return;
      const clip = clips.find(c => c.id === selectedClipId);
      if (clip) {
          setClipClipboard(clip);
          addNotification('CLIP COPIED TO BUFFER', 'info');
      }
  };

  const handlePaste = () => {
      if (!clipClipboard) return;
      let targetTrackId = tracks[0].id;
      if (selectedClipId) {
          const selected = clips.find(c => c.id === selectedClipId);
          if (selected) targetTrackId = selected.trackId;
      }
      const newClip: AudioClip = {
          ...clipClipboard,
          id: Date.now().toString() + Math.random().toString().slice(2,5),
          startTime: currentTime, // Smart Paste at Playhead
          trackId: targetTrackId
      };
      setClips(prev => [...prev, newClip]);
      setSelectedClipId(newClip.id);
      addNotification('BUFFER PASTED AT PLAYHEAD', 'success');
  };

  const handleToggleLoop = () => {
      setIsLooping(prev => {
          const newState = !prev;
          addNotification(newState ? 'LOOP ENABLED' : 'LOOP DISABLED', 'info');
          return newState;
      });
  };

  const handleSetLoopIn = () => {
      setLoopRange(prev => {
          const end = prev ? prev.end : currentTime + 4;
          if (currentTime >= end) {
              addNotification('INVALID LOOP RANGE', 'warning');
              return prev;
          }
          addNotification(`LOOP IN: ${currentTime.toFixed(2)}s`, 'success');
          return { start: currentTime, end };
      });
      setIsLooping(true);
  };

  const handleSetLoopOut = () => {
      setLoopRange(prev => {
          const start = prev ? prev.start : Math.max(0, currentTime - 4);
          if (currentTime <= start) {
               addNotification('INVALID LOOP RANGE', 'warning');
               return prev;
          }
          addNotification(`LOOP OUT: ${currentTime.toFixed(2)}s`, 'success');
          return { start, end: currentTime };
      });
      setIsLooping(true);
  };

  const handleTrackUpdate = (trackId: string, updates: Partial<Track>) => {
    setTracks(prev => prev.map(t => t.id === trackId ? { ...t, ...updates } : t));
  };
  const toggleTrackArm = (trackId: string) => setTracks(prev => prev.map(t => ({ ...t, armed: t.id === trackId })));
  const toggleTrackExpand = (trackId: string) => setTracks(prev => prev.map(t => ({ ...t, isExpanded: t.id === trackId ? !t.isExpanded : false })));

  const handleDuplicateTrack = (trackId: string) => {
      const originalTrack = tracks.find(t => t.id === trackId);
      if (!originalTrack) return;
      const newTrackId = Date.now().toString();
      const newTrack: Track = { ...originalTrack, id: newTrackId, name: originalTrack.name + ' (Copy)', isExpanded: false };
      const originalClips = clips.filter(c => c.trackId === trackId);
      const newClips = originalClips.map(c => ({ ...c, id: c.id + '_copy_' + Math.random().toString().slice(2,5), trackId: newTrackId }));
      const index = tracks.findIndex(t => t.id === trackId);
      const newTracks = [...tracks];
      newTracks.splice(index + 1, 0, newTrack);
      setTracks(newTracks);
      setClips(prev => [...prev, ...newClips]);
      audioEngine.ensureTrackChannel(newTrack);
      addNotification('TRACK DUPLICATION COMPLETE', 'success');
  };

  const handleExport = async (format: 'mp4') => {
      if (isPlaying) await togglePlay();
      setIsExporting(true);
      addNotification('STARTING REAL-TIME EXPORT...', 'info');
      audioEngine.startBounceRecorder();
      startTimeRef.current = audioEngine.ctx.currentTime;
      startOffsetRef.current = 0;
      setCurrentTime(0);
      clips.forEach(clip => {
        const track = tracks.find(t => t.id === clip.trackId);
        if (track && !track.muted && (!tracks.some(t => t.solo) || track.solo)) audioEngine.playClip(clip, 0);
      });
      setIsPlaying(true);
  };

  const finishExport = async () => {
      setIsPlaying(false);
      audioEngine.stopAll();
      const blob = await audioEngine.stopBounceRecorder();
      setIsExporting(false);
      setShowInfoPanel(false);
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.style.display = 'none'; a.href = url;
      const cleanTitle = metadata.title.replace(/[^a-z0-9]/gi, '_').toLowerCase();
      a.download = `${cleanTitle}_bounce.mp4`;
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      addNotification('EXPORT COMPLETE. FILE SAVED.', 'success');
  };

  const stopRecordingAndSave = async () => {
      const blob = await audioEngine.stopRecording();
      setIsRecording(false);
      const id = Date.now().toString();
      await storageService.saveBlob(id, blob);
      const buffer = await audioEngine.decodeAudioData(blob);
      const armedTrack = tracks.find(t => t.armed) || tracks[0];
      const newClip: AudioClip = {
        id, trackId: armedTrack.id, buffer, startTime: recordingStartRef.current,
        duration: buffer.duration, offset: 0, name: `Rec ${id.substr(-4)}`,
        fx: {...DEFAULT_CLIP_FX}, viewConfig: {...DEFAULT_VIEW_CONFIG}
      };
      setClips(prev => [...prev, newClip]);
      setSelectedClipId(id);
      addNotification(`RECORDING SAVED: ${newClip.name}`, 'success');
  };

  const toggleRecord = async () => {
    if (isRecording) {
      await stopRecordingAndSave();
    } else {
      recordingStartRef.current = currentTime; 
      try {
        await audioEngine.startRecording(monitor);
        setIsRecording(true);
        addNotification('RECORDING STARTED', 'warning');
        if (!isPlaying) await togglePlay();
      } catch (err) {
        addNotification('MICROPHONE INIT FAILED', 'error');
        console.error("Failed to start recording:", err);
      }
    }
  };

  const stop = async () => {
    audioEngine.stopAll();
    setIsPlaying(false);
    if (isExporting) {
        audioEngine.stopBounceRecorder();
        setIsExporting(false);
        addNotification('EXPORT CANCELLED', 'error');
        return;
    }
    if (isRecording) {
        try { await stopRecordingAndSave(); } catch(e) { console.error("Error saving:", e); setIsRecording(false); }
    }
    const returnTime = isRecording ? recordingStartRef.current : (isLooping && loopRange ? loopRange.start : 0);
    setCurrentTime(returnTime);
    startOffsetRef.current = returnTime;
  };

  // --- Clip Interaction (Move/Split/Context) ---
  const handleClipInteract = (clipId: string, action: string, data?: any) => {
    if (action === 'context') {
        const { action: ctxAction } = data;
        if (ctxAction === 'copy') { setSelectedClipId(clipId); handleCopy(); }
        if (ctxAction === 'split') { splitClip(clipId, currentTime); }
        if (ctxAction === 'delete') { setSelectedClipId(clipId); deleteSelectedClip(); }
        if (ctxAction === 'reverse') {
             const c = clips.find(x => x.id === clipId);
             if (c) {
                handleClipFXUpdate(clipId, { isReversed: !c.fx.isReversed });
                addNotification(c.fx.isReversed ? 'CLIP NORMALIZED' : 'CLIP REVERSED', 'info');
             }
        }
        return;
    }
    if (action === 'tap') {
        setSelectedClipId(clipId);
        return;
    }
    if (editMode === EditMode.MOVE && action === 'start') {
      setSelectedClipId(clipId);
      dragRef.current = { clipId, startX: data.x, originalStart: data.originalStart };

      const handleMove = (e: any) => {
        if (!dragRef.current || !containerRef.current) return;
        const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
        const deltaX = clientX - dragRef.current.startX;
        const deltaTime = deltaX / zoom; 

        let newStart = Math.max(0, dragRef.current.originalStart + deltaTime);

        const snappedStart = calculateSnap(newStart, zoom);
        if (Math.abs(snappedStart - newStart) * zoom < 15) {
            setSnapTime(snappedStart);
            newStart = snappedStart;
        } else {
            setSnapTime(null);
        }

        const containerRect = containerRef.current.getBoundingClientRect();
        const scrollY = containerRef.current.scrollTop;
        const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
        const relativeY = clientY - containerRect.top + scrollY;

        let accumulatedHeight = 0;
        let targetTrackId = null;
        for (const track of tracks) {
            const h = track.isExpanded ? EXPANDED_TRACK_HEIGHT : TRACK_HEIGHT;
            if (relativeY >= accumulatedHeight && relativeY < accumulatedHeight + h) {
                targetTrackId = track.id;
                break;
            }
            accumulatedHeight += h;
        }

        setClips(prev => prev.map(c => 
          c.id === dragRef.current?.clipId ? { 
              ...c, startTime: newStart, 
              trackId: targetTrackId || c.trackId 
          } : c
        ));
      };

      const handleEnd = () => {
        dragRef.current = null;
        setSnapTime(null);
        window.removeEventListener('touchmove', handleMove); window.removeEventListener('touchend', handleEnd);
        window.removeEventListener('mousemove', handleMove); window.addEventListener('mouseup', handleEnd);
      };
      window.addEventListener('touchmove', handleMove, { passive: false }); window.addEventListener('touchend', handleEnd);
      window.addEventListener('mousemove', handleMove); window.addEventListener('mouseup', handleEnd);
    }
  };

  const handleClipFXUpdate = (clipId: string, updates: Partial<AudioClip['fx']> | { viewConfig: any }) => {
      setClips(prev => prev.map(c => c.id === clipId ? { ...c, ...('viewConfig' in updates ? { viewConfig: updates.viewConfig } : { fx: { ...c.fx, ...updates } }) } : c));
      if (!('viewConfig' in updates)) audioEngine.updateClipParams(clipId, updates as Partial<typeof DEFAULT_CLIP_FX>);
  };

  const splitClip = (clipId: string, splitTimeOverride?: number) => {
    const clip = clips.find(c => c.id === clipId);
    if (!clip) return;
    const timeToSplitAt = splitTimeOverride !== undefined ? splitTimeOverride : currentTime;

    // Snap Split
    const snappedSplit = calculateSnap(timeToSplitAt, zoom);

    const relativeSplitTime = (snappedSplit - clip.startTime); 
    if (relativeSplitTime <= 0.01 || relativeSplitTime >= clip.duration - 0.01) {
        addNotification('CANNOT SPLIT: TOO CLOSE TO EDGE', 'error');
        return;
    }

    const clip1: AudioClip = { ...clip, id: clip.id + '_1', duration: relativeSplitTime };
    const clip2: AudioClip = { ...clip, id: clip.id + '_2', startTime: snappedSplit, duration: clip.duration - relativeSplitTime, offset: clip.offset + relativeSplitTime };
    setClips(prev => prev.filter(c => c.id !== clipId).concat([clip1, clip2]));
    setSelectedClipId(clip2.id);
    addNotification('CLIP SPLIT SUCCESSFUL', 'success');
  };

  const handleSplitButton = () => { if (selectedClipId) splitClip(selectedClipId, currentTime); else addNotification('NO CLIP SELECTED', 'error'); };
  const deleteSelectedClip = () => { if (selectedClipId) { setClips(prev => prev.filter(c => c.id !== selectedClipId)); setSelectedClipId(null); addNotification('CLIP DELETED', 'info'); }};

  const handleTimelineScrub = (e: any) => {
     if (e.target.dataset.bg) setSelectedClipId(null);
     if (!containerRef.current) return;
     const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
     const containerLeft = containerRef.current.getBoundingClientRect().left;
     const scrollLeft = containerRef.current.scrollLeft;
     const relativeX = clientX - containerLeft + scrollLeft;
     const rawTime = Math.max(0, (relativeX - currentChannelWidth) / zoom);
     const snappedTime = calculateSnap(rawTime, zoom);
     setCurrentTime(snappedTime);
     startOffsetRef.current = snappedTime;
  };

  const selectedClip = clips.find(c => c.id === selectedClipId);

  return (
    <div className="flex flex-col h-screen w-screen bg-transparent text-slate-100 overflow-hidden select-none font-sans relative">
      <BackgroundInterference />
      <NotificationSystem notifications={notifications} />

      <div className="flex flex-col h-full w-full z-10 relative bg-black/10 backdrop-blur-[1px]">
        <Controls 
            isPlaying={isPlaying} isRecording={isRecording} isLooping={isLooping} loopRange={loopRange}
            onPlayPause={togglePlay} onRecord={toggleRecord} onStop={stop} onBounce={() => setShowInfoPanel(true)} 
            onDelete={deleteSelectedClip} onSplit={handleSplitButton} onCopy={handleCopy} onPaste={handlePaste}
            onToggleLoop={handleToggleLoop} onSetLoopIn={handleSetLoopIn} onSetLoopOut={handleSetLoopOut}
            onOpenInfo={() => setShowInfoPanel(true)} onShowCredits={() => setShowCredits(true)}
            editMode={editMode} setEditMode={setEditMode} monitor={monitor} setMonitor={setMonitor}
            zoom={zoom} setZoom={setZoom} hasSelection={!!selectedClipId} hasClipboard={!!clipClipboard}
            viewSettings={viewSettings} setViewSettings={setViewSettings}
        />

        <div ref={containerRef} className="flex-1 overflow-y-auto overflow-x-auto relative mt-[60px] mb-[260px]" 
            onClick={() => setSelectedClipId(null)} data-bg="true">

            {/* Snap Guide Line */}
            {snapTime !== null && (
                <div className="absolute top-0 bottom-0 border-l border-yellow-400 z-50 pointer-events-none opacity-80"
                     style={{ left: `${(snapTime * zoom) + currentChannelWidth}px` }}></div>
            )}

            {/* Playhead */}
            <div className="absolute top-0 bottom-0 z-40 pointer-events-none border-r border-cyan-500 shadow-[0_0_15px_rgba(6,182,212,0.6)]"
                style={{ left: `${(currentTime * zoom) + currentChannelWidth}px`, width: '1px' }}>
                <div className="absolute -top-4 -translate-x-1/2 bg-cyan-900 text-[9px] px-1.5 py-0.5 rounded-sm text-cyan-200 font-mono shadow-md whitespace-nowrap z-50 border border-cyan-500/50">
                    {currentTime.toFixed(2)}s
                </div>
                <div className="absolute top-0 bottom-0 w-px bg-cyan-500/50"></div>
            </div>

            {/* Ruler */}
            <div className="h-8 min-w-full bg-[#030305]/90 border-b border-white/10 relative cursor-pointer shadow-lg z-30 transition-all duration-300"
                style={{ width: `${Math.max(window.innerWidth, (300 * zoom) + currentChannelWidth)}px` }}
                onClick={(e) => { e.stopPropagation(); handleTimelineScrub(e); }}>
                {loopRange && (
                    <div className="absolute top-0 bottom-0 bg-blue-500/10 border-x border-blue-500/50 z-0"
                        style={{ left: `${loopRange.start * zoom + currentChannelWidth}px`, width: `${(loopRange.end - loopRange.start) * zoom}px` }}>
                    </div>
                )}
                {/* Adaptive Ticks */}
                {Array.from({ length: Math.ceil(300 * zoom / 100) * (zoom > 150 ? 8 : 4) }).map((_, i) => {
                    const step = zoom > 150 ? 0.125 : 0.25;
                    const sec = i * step;
                    const isMajor = Math.abs(sec % 1) < 0.001;
                    const isMedium = Math.abs(sec % 0.5) < 0.001;
                    let h = 'h-1 border-slate-700';
                    if (isMajor) h = 'h-3 border-slate-500';
                    else if (isMedium) h = 'h-2 border-slate-600';
                    return (
                    <div key={i} className={`absolute bottom-0 border-l z-10 pointer-events-none ${h}`} 
                        style={{ left: (sec * zoom) + currentChannelWidth }}>
                        {isMajor && <span className="text-[8px] font-mono font-medium text-slate-500 pl-1.5 -mt-4 block">{sec}</span>}
                    </div>
                )})}
            </div>

            {/* Tracks Container */}
            <div className="min-w-full pb-20 relative bg-transparent transition-all duration-300" style={{ width: `${Math.max(window.innerWidth, (300 * zoom) + currentChannelWidth)}px` }} data-bg="true">
            {tracks.map(track => (
                <div key={track.id} className="flex border-b border-white/5 bg-black/20" style={{ height: track.isExpanded ? EXPANDED_TRACK_HEIGHT : TRACK_HEIGHT }}>
                <ChannelStrip 
                    track={track} onUpdate={handleTrackUpdate} onToggleArm={toggleTrackArm} onToggleExpand={toggleTrackExpand} onDuplicate={handleDuplicateTrack}
                    width={currentChannelWidth} viewSettings={viewSettings} isCollapsed={viewSettings.isCollapsed}
                />
                <div className="relative w-full z-10 flex-1 min-w-0">
                    <TrackLane track={track} clips={clips.filter(c => c.trackId === track.id)} editMode={editMode} selectedClipId={selectedClipId} onClipInteract={handleClipInteract} currentTime={currentTime} isPlaying={isPlaying} zoom={zoom} />
                </div>
                </div>
            ))}
            </div>
        </div>

        {selectedClip ? (
            <ClipInspector clip={selectedClip} onUpdate={handleClipFXUpdate} onClose={() => setSelectedClipId(null)} />
        ) : (
            <DSPRack dspState={dspState} onChange={(s) => { setDspState(s); audioEngine.updateMasterDSP(s); }} />
        )}

        {showInfoPanel && (
            <ProjectInfoPanel metadata={metadata} onChange={setMetadata} onClose={() => !isExporting && setShowInfoPanel(false)} onExport={handleExport} isExporting={isExporting} />
        )}
        {showCredits && (
            <CreditsModal onClose={() => setShowCredits(false)} />
        )}
      </div>
    </div>
  );
};

export default App;

// Scientific Math Library for Signal Processing & Tensor Visualizations

export const TWO_PI = Math.PI * 2;

// --- Curve Generation ---

export const generateDriveCurve = (amount: number, samples: number = 8192): Float32Array => {
    if (!Number.isFinite(amount) || amount < 1) {
        const curve = new Float32Array(2);
        curve[0] = -1; curve[1] = 1;
        return curve;
    }
    const k = amount;
    const curve = new Float32Array(samples);
    for (let i = 0; i < samples; ++i) {
      const x = (i * 2) / samples - 1;
      // Sigmoid-like distortion transfer function
      curve[i] = (Math.PI + 50) * x / (Math.PI + 50 * Math.abs(x));
    }
    return curve;
};

export const generateBitcrushCurve = (bits: number, samples: number = 4096): Float32Array => {
    if (!Number.isFinite(bits)) return new Float32Array(samples);
    const step = Math.pow(0.5, bits);
    const curve = new Float32Array(samples);
    for (let i = 0; i < samples; i++) {
        const x = (i / (samples - 1)) * 2 - 1;
        curve[i] = Math.round(x / step) * step;
    }
    return curve;
};

export const generateExpanderCurve = (threshDb: number, samples: number = 4096): Float32Array => {
    const curve = new Float32Array(samples);
    const thresh = Math.pow(10, threshDb / 20);
    for(let i=0; i < samples; i++) {
        const x = (i / (samples - 1)) * 2 - 1;
        const absX = Math.abs(x);
        if (absX < thresh) {
            // Cubic expansion downwards
            const factor = absX / thresh;
            curve[i] = Math.sign(x) * thresh * Math.pow(factor, 3);
        } else {
            curve[i] = x;
        }
    }
    return curve;
};

// --- Spectral Analysis ---

export const blackmanHarris = (n: number, N: number): number => {
    const a0 = 0.35875;
    const a1 = 0.48829;
    const a2 = 0.14128;
    const a3 = 0.01168;
    const term = (TWO_PI * n) / (N - 1);
    return a0 - a1 * Math.cos(term) + a2 * Math.cos(2 * term) - a3 * Math.cos(3 * term);
};

// Iterative Fast Fourier Transform
// Returns { re, im } arrays of size N
export const fft = (data: Float32Array): { re: Float32Array, im: Float32Array } => {
    const n = data.length;
    const m = Math.log2(n);

    // Bit-reversal permutation
    const re = new Float32Array(n);
    const im = new Float32Array(n);
    for (let i = 0; i < n; i++) {
        let j = 0;
        let k = i;
        for (let l = 0; l < m; l++) {
            j = (j << 1) | (k & 1);
            k >>= 1;
        }
        re[j] = data[i];
        im[j] = 0;
    }

    // Cooley-Tukey butterfly operations
    for (let s = 1; s <= m; s++) {
        const mh = 1 << (s - 1);
        const m_len = 1 << s;
        const theta = -TWO_PI / m_len;
        const wmRe = Math.cos(theta);
        const wmIm = Math.sin(theta);

        for (let k = 0; k < n; k += m_len) {
            let wRe = 1;
            let wIm = 0;
            for (let j = 0; j < mh; j++) {
                const tRe = wRe * re[k + j + mh] - wIm * im[k + j + mh];
                const tIm = wRe * im[k + j + mh] + wIm * re[k + j + mh];
                const uRe = re[k + j];
                const uIm = im[k + j];

                re[k + j] = uRe + tRe;
                im[k + j] = uIm + tIm;
                re[k + j + mh] = uRe - tRe;
                im[k + j + mh] = uIm - tIm;

                const wReNew = wRe * wmRe - wIm * wmIm;
                wIm = wRe * wmIm + wIm * wmRe;
                wRe = wReNew;
            }
        }
    }

    return { re, im };
};

// --- Vector Math ---

export const lerp = (a: number, b: number, t: number) => a + (b - a) * t;

export const clamp = (val: number, min: number, max: number) => Math.min(max, Math.max(min, val));

export const mapRange = (value: number, inMin: number, inMax: number, outMin: number, outMax: number) => {
    return outMin + (outMax - outMin) * ((value - inMin) / (inMax - inMin));
};

import { DSPState, Track, AudioClip, TrackFX, ClipFX } from '../types';
import { generateDriveCurve, generateBitcrushCurve, generateExpanderCurve } from '../utils/dsp';

interface TrackChannel {
  input: GainNode;
  gate: WaveShaperNode; 
  hpf: BiquadFilterNode;
  eqLow: BiquadFilterNode;
  eqMid: BiquadFilterNode;
  eqHigh: BiquadFilterNode;
  bitCrush: WaveShaperNode; 
