                <Knob value={clip.fx.fadeOut || 0.01} min={0.01} max={2.0} label="OUT" unit="s" color="green" size={32} onChange={(v) => updateFX('fadeOut', v)} />
            </InspectorModule>

            {/* 5. FILTER */}
            <InspectorModule title="FILTER">
                <Knob value={clip.fx.filterFreq || 20000} min={100} max={20000} logarithmic label="FREQ" unit="Hz" color="pink" size={36} onChange={(v) => updateFX('filterFreq', v)} />
                <Knob value={clip.fx.filterRes || 0} min={0} max={20} label="RES" unit="" color="pink" size={36} onChange={(v) => updateFX('filterRes', v)} />
            </InspectorModule>

            {/* 6. FX */}
            <InspectorModule title="EFFECTS">
                 <Knob value={clip.fx.saturation || 0} min={0} max={100} label="DRIVE" unit="%" color="orange" size={32} onChange={(v) => updateFX('saturation', v)} />
                 <div className="w-px h-10 bg-slate-800 mx-1"></div>
                 <Knob value={clip.fx.tremoloDepth || 0} min={0} max={1} label="TREM" unit="%" color="purple" size={32} onChange={(v) => updateFX('tremoloDepth', v)} />
                 <Knob value={clip.fx.tremoloRate || 4} min={0.5} max={20} label="RATE" unit="Hz" color="purple" size={32} onChange={(v) => updateFX('tremoloRate', v)} />
            </InspectorModule>

          </div>
      </div>
    </div>
  );
};

// Scientific Math Library for Signal Processing & Tensor Visualizations

export const TWO_PI = Math.PI * 2;

// --- Curve Generation ---

export const generateDriveCurve = (amount: number, samples: number = 8192): Float32Array => {
    if (!Number.isFinite(amount) || amount < 1) {
        const curve = new Float32Array(2);
        curve[0] = -1; curve[1] = 1;
        return curve;
    }
    const k = amount;
    const curve = new Float32Array(samples);
    for (let i = 0; i < samples; ++i) {
      const x = (i * 2) / samples - 1;
      // Sigmoid-like distortion transfer function
      curve[i] = (Math.PI + 50) * x / (Math.PI + 50 * Math.abs(x));
    }
    return curve;
};

export const generateBitcrushCurve = (bits: number, samples: number = 4096): Float32Array => {
    if (!Number.isFinite(bits)) return new Float32Array(samples);
    const step = Math.pow(0.5, bits);
    const curve = new Float32Array(samples);
    for (let i = 0; i < samples; i++) {
        const x = (i / (samples - 1)) * 2 - 1;
        curve[i] = Math.round(x / step) * step;
    }
    return curve;
};

export const generateExpanderCurve = (threshDb: number, samples: number = 4096): Float32Array => {
    const curve = new Float32Array(samples);
    const thresh = Math.pow(10, threshDb / 20);
    for(let i=0; i < samples; i++) {
        const x = (i / (samples - 1)) * 2 - 1;
        const absX = Math.abs(x);
        if (absX < thresh) {
            // Cubic expansion downwards
            const factor = absX / thresh;
            curve[i] = Math.sign(x) * thresh * Math.pow(factor, 3);
        } else {
            curve[i] = x;
        }
    }
    return curve;
};

// --- Spectral Analysis ---

export const blackmanHarris = (n: number, N: number): number => {
    const a0 = 0.35875;
    const a1 = 0.48829;
    const a2 = 0.14128;
    const a3 = 0.01168;
    const term = (TWO_PI * n) / (N - 1);
    return a0 - a1 * Math.cos(term) + a2 * Math.cos(2 * term) - a3 * Math.cos(3 * term);
};

// Iterative Fast Fourier Transform
// Returns { re, im } arrays of size N
export const fft = (data: Float32Array): { re: Float32Array, im: Float32Array } => {
    const n = data.length;
    const m = Math.log2(n);

    // Bit-reversal permutation
    const re = new Float32Array(n);
    const im = new Float32Array(n);
    for (let i = 0; i < n; i++) {
        let j = 0;
        let k = i;
        for (let l = 0; l < m; l++) {
            j = (j << 1) | (k & 1);
            k >>= 1;
        }
        re[j] = data[i];
        im[j] = 0;
    }

    // Cooley-Tukey butterfly operations
    for (let s = 1; s <= m; s++) {
        const mh = 1 << (s - 1);
        const m_len = 1 << s;
        const theta = -TWO_PI / m_len;
        const wmRe = Math.cos(theta);
        const wmIm = Math.sin(theta);

        for (let k = 0; k < n; k += m_len) {
            let wRe = 1;
            let wIm = 0;
            for (let j = 0; j < mh; j++) {
                const tRe = wRe * re[k + j + mh] - wIm * im[k + j + mh];
                const tIm = wRe * im[k + j + mh] + wIm * re[k + j + mh];
                const uRe = re[k + j];
                const uIm = im[k + j];

                re[k + j] = uRe + tRe;
                im[k + j] = uIm + tIm;
                re[k + j + mh] = uRe - tRe;
                im[k + j + mh] = uIm - tIm;

                const wReNew = wRe * wmRe - wIm * wmIm;
                wIm = wRe * wmIm + wIm * wmRe;
                wRe = wReNew;
            }
        }
    }

    return { re, im };
};

// --- Vector Math & Interpolation ---

export const lerp = (a: number, b: number, t: number) => a + (b - a) * t;

export const clamp = (val: number, min: number, max: number) => Math.min(max, Math.max(min, val));

export const mapRange = (value: number, inMin: number, inMax: number, outMin: number, outMax: number) => {
    return outMin + (outMax - outMin) * ((value - inMin) / (inMax - inMin));
};

// Cubic Hermite Spline Interpolation for high-fidelity waveform rendering at low zoom levels
export const cubicHermite = (y0: number, y1: number, y2: number, y3: number, t: number): number => {
    const a = -0.5 * y0 + 1.5 * y1 - 1.5 * y2 + 0.5 * y3;
    const b = y0 - 2.5 * y1 + 2 * y2 - 0.5 * y3;
    const c = -0.5 * y0 + 0.5 * y2;
    const d = y1;
    return a * t * t * t + b * t * t + c * t + d;
};

import React, { useEffect, useRef } from 'react';
import { ClipViewConfig } from '../types';
import { cubicHermite } from '../utils/dsp';

interface WaveformProps {
  buffer: AudioBuffer;
  color: string;
  width: number;
  height: number;
  viewConfig: ClipViewConfig;
}

export const Waveform: React.FC<WaveformProps> = ({ buffer, color, width, height, viewConfig }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: true });
    if (!ctx) return;

    // Safety Constraint
    const safeWidth = Math.max(1, Math.min(32000, Math.floor(width)));
    const safeHeight = Math.max(1, Math.floor(height));

    canvas.width = safeWidth;
    canvas.height = safeHeight;
    ctx.clearRect(0, 0, safeWidth, safeHeight);

    // Parse Color
    const hexToRgb = (hex: string) => {
        const bigint = parseInt(hex.replace('#', ''), 16);
        return { r: (bigint >> 16) & 255, g: (bigint >> 8) & 255, b: bigint & 255 };
    };
    const rgb = hexToRgb(color);

    const scale = viewConfig?.scale || 1;
    const data = buffer.getChannelData(0);
    const mid = safeHeight / 2;

    // TENSOR FIELD VISUALIZATION
    // This renders the PCM data as a probability field with vector flux lines.

    // 1. Field Background (Energy Density)
    const grad = ctx.createLinearGradient(0, 0, 0, safeHeight);
    grad.addColorStop(0, `rgba(${rgb.r},${rgb.g},${rgb.b},0)`);
    grad.addColorStop(0.5, `rgba(${rgb.r},${rgb.g},${rgb.b},0.15)`); // Subtle core glow
    grad.addColorStop(1, `rgba(${rgb.r},${rgb.g},${rgb.b},0)`);
    ctx.fillStyle = grad;
    ctx.fillRect(0,0,safeWidth, safeHeight);

    ctx.lineWidth = 1;
    const step = data.length / safeWidth;

    // 2. Vector Flux Lines (Discrete sampling of amplitude)
    // Drawn as vertical lines representing signal strength at intervals
    ctx.beginPath();
    const vectorSpacing = Math.max(3, 6 / scale); // Spacing adapts to scale

    for (let x = 0; x < safeWidth; x += vectorSpacing) {
         const idx = Math.floor(x * step);
         if (idx >= data.length) break;

         // Peak detect in this slice
         let maxAbs = 0;
         const sliceWidth = Math.max(1, Math.floor(step));
         for (let j = 0; j < sliceWidth; j++) {
             if (idx + j >= data.length) break;
             const abs = Math.abs(data[idx + j]);
             if (abs > maxAbs) maxAbs = abs;
         }

         const h = maxAbs * (safeHeight / 2) * scale;
         if (h > 1) {
            ctx.moveTo(x, mid - h);
            ctx.lineTo(x, mid + h);
         }
    }
    ctx.strokeStyle = `rgba(${rgb.r},${rgb.g},${rgb.b},0.3)`;
    ctx.stroke();

    // 3. Main Envelope (The Tensor Boundary)
    ctx.beginPath();
    ctx.moveTo(0, mid);

    if (step >= 1) {
        // --- ZOOMED OUT: MIN/MAX DECIMATION ---
        // standard drawing for density
        const intStep = Math.ceil(step);
        for (let i = 0; i < safeWidth; i+=2) {
            let min = 1.0; let max = -1.0;
            const idx = Math.floor(i * step);
            for (let j = 0; j < intStep; j++) {
                if (idx + j >= data.length) break;
                const datum = data[idx + j];
                if (datum < min) min = datum;
                if (datum > max) max = datum;
            }
            // Draw max peak
            const val = Math.abs(max) > Math.abs(min) ? max : min;
            const y = mid - (val * (safeHeight/2) * scale);
            ctx.lineTo(i, y);
        }
        // Mirror pass for symmetry/aesthetic (Tensor look)
        for (let i = safeWidth; i >= 0; i-=2) {
            const idx = Math.floor(i * step);
            const y = mid + (data[Math.min(data.length-1, idx)] * (safeHeight/2) * scale * 0.1); // Small reflection
            ctx.lineTo(i, y);
        }

    } else {
        // --- ZOOMED IN: CUBIC HERMITE INTERPOLATION ---
        // Numerically reconstructed analog curve
        for (let x = 0; x < safeWidth; x++) {
            const indexExact = x * step;
            const indexInt = Math.floor(indexExact);
            const t = indexExact - indexInt;

            // Get neighbor samples for interpolation
            const y0 = data[Math.max(0, indexInt - 1)];
            const y1 = data[indexInt];
            const y2 = data[Math.min(data.length - 1, indexInt + 1)];
            const y3 = data[Math.min(data.length - 1, indexInt + 2)];

            const val = cubicHermite(y0, y1, y2, y3, t);
            const y = mid - (val * (safeHeight/2) * scale);
            ctx.lineTo(x, y);
        }
    }

    // Stroke Styling
    ctx.globalCompositeOperation = 'source-over';
    ctx.shadowBlur = 8;
    ctx.shadowColor = color;
    ctx.strokeStyle = `rgba(${rgb.r},${rgb.g},${rgb.b},0.9)`;
    ctx.stroke();

    // 4. Highlight Overlay (White Hot Core)
    ctx.strokeStyle = 'rgba(255,255,255,0.6)';
    ctx.lineWidth = 0.5;
    ctx.shadowBlur = 0;
    ctx.stroke();

    // 5. Critical Points (Nodes)
    // Draw glowing dots at significant peaks to visualize transient attacks
    ctx.fillStyle = '#fff';
    ctx.beginPath();
    const nodeSpacing = Math.max(10, 50 / scale);
    for (let x = 0; x < safeWidth; x += nodeSpacing) {
        const idx = Math.floor(x * step);
        if (idx < data.length) {
            const val = data[idx];
            if (Math.abs(val) > 0.4) {
                 const y = mid - (val * (safeHeight/2) * scale);
                 ctx.moveTo(x + 1.5, y);
                 ctx.arc(x, y, 1.5, 0, Math.PI * 2);
            }
        }
    }
    ctx.fill();

  }, [buffer, color, width, height, viewConfig]);

  return <canvas ref={canvasRef} style={{ width: '100%', height: '100%' }} className="w-full h-full opacity-100 mix-blend-screen" />;
};

