            </InspectorModule>

          </div>
      </div>
    </div>
  );
};

import React, { useEffect, useRef } from 'react';

// --- MATH HELPERS ---
const dbToGain = (db: number) => Math.pow(10, db / 20);
const gainToDb = (gain: number) => 20 * Math.log10(gain);

// --- 1. FILTER RESPONSE (Bode Plot Approx) ---
interface FilterResponseProps {
    freq: number;
    res: number; // Q
    gain?: number;
    type: 'lowpass' | 'highpass' | 'peaking' | 'lowshelf' | 'highshelf';
    color: string;
}

export const FilterResponse: React.FC<FilterResponseProps> = ({ freq, res, gain = 0, type, color }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        const w = canvas.width = canvas.offsetWidth;
        const h = canvas.height = canvas.offsetHeight;

        ctx.clearRect(0,0,w,h);

        // Grid
        ctx.strokeStyle = '#333';
        ctx.lineWidth = 1;
        ctx.beginPath();
        for(let i=0; i<10; i++) {
            const x = (i/9)*w;
            ctx.moveTo(x,0); ctx.lineTo(x,h);
        }
        ctx.stroke();

        // Calculate Response
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        ctx.shadowBlur = 10;
        ctx.shadowColor = color;
        ctx.beginPath();

        for (let i = 0; i < w; i++) {
            // Logarithmic mapping 20Hz - 20kHz
            const f = 20 * Math.pow(1000, i / w);

            let mag = 1.0;
            const w0 = (2 * Math.PI * f) / 48000;
            const alpha = Math.sin(w0) / (2 * (res || 0.707));
            const cosW = Math.cos(w0);

            // Simplified magnitude approximations for visualization speed
            // (Real biquad coefficient calc is heavy for 60fps React loop, using shape functions)

            if (type === 'lowpass') {
                 // 2nd Order LP Roll-off
                 const ratio = f / freq;
                 // Resonant bump
                 const qFactor = Math.max(0, res * 0.5); 
                 mag = 1 / Math.sqrt(1 + Math.pow(ratio, 4));
                 if (Math.abs(ratio - 1) < 0.5) mag += qFactor * (1 - Math.abs(ratio - 1)*2);
            } else if (type === 'highpass') {
                 const ratio = freq / f;
                 const qFactor = Math.max(0, res * 0.5);
                 mag = 1 / Math.sqrt(1 + Math.pow(ratio, 4));
                 if (Math.abs(f/freq - 1) < 0.5) mag += qFactor * (1 - Math.abs(f/freq - 1)*2);
            } else if (type === 'peaking') {
                 // Bell curve
                 const width = 1 / (res + 0.1); 
                 const diff = Math.abs(Math.log10(f) - Math.log10(freq));
                 const bell = Math.exp(-(diff * diff) / (width * 0.1));
                 const dbBoost = gain; 
                 // Convert dB boost to magnitude scaler
                 mag = 1 + (dbToGain(dbBoost) - 1) * bell;
            } else if (type === 'lowshelf') {
                 if (f < freq) mag = dbToGain(gain);
                 else mag = 1.0;
                 // Smooth transition logic omitted for brevity in visualizer
            } else if (type === 'highshelf') {
                if (f > freq) mag = dbToGain(gain);
                else mag = 1.0;
            }

            // Map magnitude to Y pixels
            // 0dB = center (h/2), range +/- 18dB
            const db = gainToDb(mag);
            const y = (h/2) - (db * (h/40)); 

            if (i===0) ctx.moveTo(i, clamp(y, 0, h));
            else ctx.lineTo(i, clamp(y, 0, h));
        }
        ctx.stroke();

    }, [freq, res, gain, type, color]);

    return <canvas ref={canvasRef} className="absolute inset-0 w-full h-full opacity-40 pointer-events-none" />;
};

// --- 2. DYNAMICS TRANSFER (Input/Output Graph) ---
interface DynamicsProps {
    threshold: number; // dB
    ratio: number;
    knee?: number;
    color: string;
}
export const DynamicsTransfer: React.FC<DynamicsProps> = ({ threshold, ratio, color }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;
        const w = canvas.width = canvas.offsetWidth;
        const h = canvas.height = canvas.offsetHeight;
        ctx.clearRect(0,0,w,h);

        // Grid (Diagonal Unity Line)
        ctx.strokeStyle = '#333';
        ctx.setLineDash([2, 4]);
        ctx.beginPath();
        ctx.moveTo(0, h); ctx.lineTo(w, 0);
        ctx.stroke();
        ctx.setLineDash([]);

        // Transfer Curve
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        ctx.shadowColor = color;
        ctx.shadowBlur = 8;
        ctx.beginPath();

        // Map -60dB to 0dB range
        for(let i=0; i<=w; i++) {
            const inputDb = -60 + (i/w)*60; // x axis
            let outputDb = inputDb;

            if (inputDb > threshold) {
                const over = inputDb - threshold;
                outputDb = threshold + (over / ratio);
            }

            const y = h - ((outputDb + 60) / 60) * h;
            if (i===0) ctx.moveTo(i, y); else ctx.lineTo(i, y);
        }
        ctx.stroke();

        // Threshold Point
        const threshX = ((threshold + 60) / 60) * w;
        const threshY = h - ((threshold + 60) / 60) * h;
        ctx.fillStyle = '#fff';
        ctx.beginPath(); ctx.arc(threshX, threshY, 3, 0, Math.PI*2); ctx.fill();

    }, [threshold, ratio, color]);

    return <canvas ref={canvasRef} className="absolute inset-0 w-full h-full opacity-30 pointer-events-none" />;
};

// --- 3. ENVELOPE SHAPE ---
interface EnvelopeProps {
    fadeIn: number;
    fadeOut: number;
    color: string;
}
export const EnvelopeGraph: React.FC<EnvelopeProps> = ({ fadeIn, fadeOut, color }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;
        const w = canvas.width = canvas.offsetWidth;
        const h = canvas.height = canvas.offsetHeight;
        ctx.clearRect(0,0,w,h);

        const inPx = Math.min(w/2, (fadeIn * 20)); // Scale for visual
        const outPx = Math.min(w/2, (fadeOut * 20));

        ctx.strokeStyle = color;
        ctx.fillStyle = color;
        ctx.lineWidth = 2;
        ctx.beginPath();

        ctx.moveTo(0, h);
        // Fade In
        ctx.lineTo(inPx, 0); // Attack
        // Sustain
        ctx.lineTo(w - outPx, 0); 
        // Fade Out
        ctx.lineTo(w, h); // Release

        ctx.stroke();
        ctx.globalAlpha = 0.1;
        ctx.fill();
        ctx.globalAlpha = 1.0;

    }, [fadeIn, fadeOut, color]);
    return <canvas ref={canvasRef} className="absolute inset-0 w-full h-full opacity-40 pointer-events-none" />;
};

// --- 4. LFO OSCILLOSCOPE ---
interface LFOProps {
    rate: number;
    depth: number;
    color: string;
}
export const LFOOscilloscope: React.FC<LFOProps> = ({ rate, depth, color }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let frameId: number;
        let time = 0;

        const render = () => {
            time += 0.016;
            const w = canvas.width = canvas.offsetWidth;
            const h = canvas.height = canvas.offsetHeight;
            ctx.clearRect(0,0,w,h);

            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.shadowColor = color;
            ctx.shadowBlur = 4;
            ctx.beginPath();

            const cycles = 4;
            for(let x=0; x<w; x++) {
                const t = x / w; // 0 to 1
                // Moving wave
                const phase = time * rate * Math.PI * 2;
                const val = Math.sin(t * Math.PI * 2 * cycles + phase);

                const y = (h/2) + (val * depth * (h/2) * 0.9);
                if (x===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
            }
            ctx.stroke();
            frameId = requestAnimationFrame(render);
        };
        render();
        return () => cancelAnimationFrame(frameId);
    }, [rate, depth, color]);
    return <canvas ref={canvasRef} className="absolute inset-0 w-full h-full opacity-50 pointer-events-none" />;
};


function clamp(v: number, min: number, max: number) { return Math.min(max, Math.max(min, v)); }

import React, { useState, useRef, useEffect } from 'react';
import { Track, ViewSettings } from '../types';
import { COLORS, TRACK_HEIGHT, EXPANDED_TRACK_HEIGHT } from '../constants';
