  const [clipClipboard, setClipClipboard] = useState<AudioClip | null>(null);
  const [loopRange, setLoopRange] = useState<{ start: number, end: number } | null>(null);
  const [isLooping, setIsLooping] = useState(false);
  const [editMode, setEditMode] = useState<EditMode>(EditMode.MOVE);
  const [metadata, setMetadata] = useState<ProjectMetadata>({ title: 'New Project', artist: 'Artist', album: '', year: new Date().getFullYear().toString() });
  const [showInfoPanel, setShowInfoPanel] = useState(false);
  const [showCredits, setShowCredits] = useState(true);
  const [showLogs, setShowLogs] = useState(false); 
  const [isExporting, setIsExporting] = useState(false);
  const [dspState, setDspState] = useState<DSPState>({ 
      masterVolume: 1.0, masterFilterFreq: 20000, masterFilterRes: 0, masterFilterBypass: false,
      masterEqLow: 0, masterEqMid: 0, masterEqHigh: 0, masterEqBypass: false,
      masterSaturation: 0, masterSaturationBypass: false, masterExciterDrive: 0, masterExciterBypass: false,
      masterStereoWidth: 1, masterStereoBypass: false, masterCompressorThreshold: 0, masterCompressorRatio: 1, masterCompressorBypass: false,
      delayTime: 0.3, delayFeedback: 0.3, reverbMix: 0.2, masterSpatialBypass: false, limiterThreshold: -1.0, reverbDecay: 2.0
  });
  const [isRecording, setIsRecording] = useState(false);
  const [monitor, setMonitor] = useState(false);

  // Notification System State
  const [notifications, setNotifications] = useState<Notification[]>([]);

  // Refs
  const rafRef = useRef<number>();
  const startTimeRef = useRef<number>(0); 
  const startOffsetRef = useRef<number>(0); 
  const recordingStartRef = useRef<number>(0); 
  const dragRef = useRef<{ clipId: string; startX: number; originalStart: number } | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const pinchStartRef = useRef<{ dist: number, zoom: number } | null>(null);

  const addNotification = (message: string, type: 'info' | 'success' | 'warning' | 'error' = 'info') => {
      setNotifications(prev => [...prev, { id: Date.now().toString(), message, type, timestamp: Date.now() }]);
  };

  // --- Layout Calculation ---
  const isAnyExpanded = tracks.some(t => t.isExpanded);
  const currentChannelWidth = viewSettings.isCollapsed ? CHANNEL_WIDTH_COLLAPSED : (isAnyExpanded ? CHANNEL_WIDTH_EXPANDED : CHANNEL_WIDTH_DEFAULT);

  // --- Initialization ---
  useEffect(() => {
    storageService.init();
    const handleTouch = () => audioEngine.resume();
    document.addEventListener('touchstart', handleTouch, { once: true });
    document.addEventListener('click', handleTouch, { once: true });
    tracks.forEach(t => audioEngine.ensureTrackChannel(t));
    addNotification('SYSTEM ONLINE. AUDIO ENGINE READY.', 'success');
    return () => cancelAnimationFrame(rafRef.current!);
  }, []);

  useEffect(() => { tracks.forEach(t => audioEngine.updateTrackState(t)); }, [tracks]);
  useEffect(() => { audioEngine.updateMasterDSP(dspState); }, [dspState]);

  // --- Keyboard Shortcuts ---
  useEffect(() => {
      const handleKeyDown = (e: KeyboardEvent) => {
          if (e.target instanceof HTMLInputElement) return; 

          switch(e.key) {
              case ' ': 
                  e.preventDefault(); 
                  togglePlay(); 
                  break;
              case 's':
              case 'S':
                  if(selectedClipId) splitClip(selectedClipId, currentTime);
                  else if (isPlaying) addNotification('SELECT CLIP TO SPLIT', 'warning');
                  break;
              case 'Delete':
              case 'Backspace':
                  if(selectedClipId) deleteSelectedClip();
                  break;
              case 'c':
                  if ((e.ctrlKey || e.metaKey) && selectedClipId) handleCopy();
                  break;
              case 'v':
                  if (e.ctrlKey || e.metaKey) handlePaste();
                  break;
              case 'd':
                  if ((e.ctrlKey || e.metaKey) && selectedClipId) {
                      e.preventDefault();
                      const clip = clips.find(c => c.id === selectedClipId);
                      if (clip) handleDuplicateTrack(clip.trackId);
                  }
                  break;
          }
      };
      window.addEventListener('keydown', handleKeyDown);
      return () => window.removeEventListener('keydown', handleKeyDown);
  }, [selectedClipId, currentTime, isPlaying, clipClipboard, clips]); 

  const calculateSnap = (time: number, zoomLevel: number): number => {
      let gridSize = 1.0;
      if (zoomLevel > 150) gridSize = 0.25;
      if (zoomLevel > 300) gridSize = 0.1;
      const snapped = Math.round(time / gridSize) * gridSize;
      const pixelDiff = Math.abs(snapped - time) * zoomLevel;
      if (pixelDiff < 15) return snapped;
      return time;
  };

  const restartPlayback = async (startAt: number) => {
    audioEngine.stopAll();
    setCurrentTime(startAt);
    startTimeRef.current = audioEngine.ctx.currentTime;
    startOffsetRef.current = startAt;
    clips.forEach(clip => {
      const track = tracks.find(t => t.id === clip.trackId);
      if (track && !track.muted && (!tracks.some(t => t.solo) || track.solo)) audioEngine.playClip(clip, startAt);
    });
  };

  const updatePlayhead = useCallback(() => {
    if (audioEngine.ctx.state === 'running' && isPlaying) {
        const elapsed = audioEngine.ctx.currentTime - startTimeRef.current;
        const newTime = startOffsetRef.current + elapsed;
        if (isLooping && loopRange && newTime >= loopRange.end) {
            restartPlayback(loopRange.start);
        } else if (isExporting) {
            const maxDuration = Math.max(...clips.map(c => c.startTime + c.duration)) + 2.0;
            if (newTime >= maxDuration) finishExport();
            else setCurrentTime(newTime);
        } else {
            setCurrentTime(newTime);
        }
    }
    rafRef.current = requestAnimationFrame(updatePlayhead);
  }, [isPlaying, isLooping, loopRange, isExporting, clips]);

  useEffect(() => {
    if (isPlaying) rafRef.current = requestAnimationFrame(updatePlayhead);
    else cancelAnimationFrame(rafRef.current!);
  }, [isPlaying, updatePlayhead]);

  const togglePlay = async () => {
    await audioEngine.resume();
    if (isPlaying) {
      audioEngine.stopAll();
      setIsPlaying(false);
      const elapsed = audioEngine.ctx.currentTime - startTimeRef.current;
      const newTime = startOffsetRef.current + elapsed;
      setCurrentTime(newTime);
      startOffsetRef.current = newTime;
    } else {
      startTimeRef.current = audioEngine.ctx.currentTime;
      startOffsetRef.current = currentTime; 
      clips.forEach(clip => {
        const track = tracks.find(t => t.id === clip.trackId);
        if (track && !track.muted && (!tracks.some(t => t.solo) || track.solo)) audioEngine.playClip(clip, currentTime);
      });
      setIsPlaying(true);
    }
  };

  const handleCopy = () => { if (!selectedClipId) return; const clip = clips.find(c => c.id === selectedClipId); if (clip) { setClipClipboard(clip); addNotification('CLIP COPIED TO BUFFER', 'info'); } };
  const handlePaste = () => { if (!clipClipboard) return; let targetTrackId = tracks[0].id; if (selectedClipId) { const selected = clips.find(c => c.id === selectedClipId); if (selected) targetTrackId = selected.trackId; } const newClip: AudioClip = { ...clipClipboard, id: Date.now().toString() + Math.random().toString().slice(2,5), startTime: currentTime, trackId: targetTrackId }; setClips(prev => [...prev, newClip]); setSelectedClipId(newClip.id); addNotification('BUFFER PASTED AT PLAYHEAD', 'success'); };
  const handleToggleLoop = () => { setIsLooping(prev => { const newState = !prev; addNotification(newState ? 'LOOP ENABLED' : 'LOOP DISABLED', 'info'); return newState; }); };
  const handleSetLoopIn = () => { setLoopRange(prev => { const end = prev ? prev.end : currentTime + 4; if (currentTime >= end) { addNotification('INVALID LOOP RANGE', 'warning'); return prev; } addNotification(`LOOP IN: ${currentTime.toFixed(2)}s`, 'success'); return { start: currentTime, end }; }); setIsLooping(true); };
  const handleSetLoopOut = () => { setLoopRange(prev => { const start = prev ? prev.start : Math.max(0, currentTime - 4); if (currentTime <= start) { addNotification('INVALID LOOP RANGE', 'warning'); return prev; } addNotification(`LOOP OUT: ${currentTime.toFixed(2)}s`, 'success'); return { start, end: currentTime }; }); setIsLooping(true); };
  const handleTrackUpdate = (trackId: string, updates: Partial<Track>) => { setTracks(prev => prev.map(t => t.id === trackId ? { ...t, ...updates } : t)); };
  const toggleTrackArm = (trackId: string) => setTracks(prev => prev.map(t => ({ ...t, armed: t.id === trackId })));
  const toggleTrackExpand = (trackId: string) => setTracks(prev => prev.map(t => ({ ...t, isExpanded: t.id === trackId ? !t.isExpanded : false })));
  const handleDuplicateTrack = (trackId: string) => { const originalTrack = tracks.find(t => t.id === trackId); if (!originalTrack) return; const newTrackId = Date.now().toString(); const newTrack: Track = { ...originalTrack, id: newTrackId, name: originalTrack.name + ' (Copy)', isExpanded: false }; const originalClips = clips.filter(c => c.trackId === trackId); const newClips = originalClips.map(c => ({ ...c, id: c.id + '_copy_' + Math.random().toString().slice(2,5), trackId: newTrackId })); const index = tracks.findIndex(t => t.id === trackId); const newTracks = [...tracks]; newTracks.splice(index + 1, 0, newTrack); setTracks(newTracks); setClips(prev => [...prev, ...newClips]); audioEngine.ensureTrackChannel(newTrack); addNotification('TRACK DUPLICATION COMPLETE', 'success'); };
  const handleExport = async (format: 'mp4') => { if (isPlaying) await togglePlay(); setIsExporting(true); addNotification('STARTING REAL-TIME EXPORT...', 'info'); audioEngine.startBounceRecorder(); startTimeRef.current = audioEngine.ctx.currentTime; startOffsetRef.current = 0; setCurrentTime(0); clips.forEach(clip => { const track = tracks.find(t => t.id === clip.trackId); if (track && !track.muted && (!tracks.some(t => t.solo) || track.solo)) audioEngine.playClip(clip, 0); }); setIsPlaying(true); };
  const finishExport = async () => { setIsPlaying(false); audioEngine.stopAll(); const blob = await audioEngine.stopBounceRecorder(); setIsExporting(false); setShowInfoPanel(false); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.style.display = 'none'; a.href = url; const cleanTitle = metadata.title.replace(/[^a-z0-9]/gi, '_').toLowerCase(); a.download = `${cleanTitle}_bounce.mp4`; document.body.appendChild(a); a.click(); window.URL.revokeObjectURL(url); addNotification('EXPORT COMPLETE. FILE SAVED.', 'success'); };
  const stopRecordingAndSave = async () => { const blob = await audioEngine.stopRecording(); setIsRecording(false); const id = Date.now().toString(); await storageService.saveBlob(id, blob); const buffer = await audioEngine.decodeAudioData(blob); const armedTrack = tracks.find(t => t.armed) || tracks[0]; const newClip: AudioClip = { id, trackId: armedTrack.id, buffer, startTime: recordingStartRef.current, duration: buffer.duration, offset: 0, name: `Rec ${id.substr(-4)}`, fx: {...DEFAULT_CLIP_FX}, viewConfig: {...DEFAULT_VIEW_CONFIG} }; setClips(prev => [...prev, newClip]); setSelectedClipId(id); addNotification(`RECORDING SAVED: ${newClip.name}`, 'success'); };
  const toggleRecord = async () => { if (isRecording) { await stopRecordingAndSave(); } else { recordingStartRef.current = currentTime; try { await audioEngine.startRecording(monitor); setIsRecording(true); addNotification('RECORDING STARTED', 'warning'); if (!isPlaying) await togglePlay(); } catch (err) { addNotification('MICROPHONE INIT FAILED', 'error'); console.error("Failed to start recording:", err); } } };
  const stop = async () => { audioEngine.stopAll(); setIsPlaying(false); if (isExporting) { audioEngine.stopBounceRecorder(); setIsExporting(false); addNotification('EXPORT CANCELLED', 'error'); return; } if (isRecording) { try { await stopRecordingAndSave(); } catch(e) { console.error("Error saving:", e); setIsRecording(false); } } const returnTime = isRecording ? recordingStartRef.current : (isLooping && loopRange ? loopRange.start : 0); setCurrentTime(returnTime); startOffsetRef.current = returnTime; };

  // --- Multi-Touch Pinch Zoom Logic ---
  const handleTouchStart = (e: React.TouchEvent) => {
      if (e.touches.length === 2) {
          const dist = Math.hypot(
              e.touches[0].clientX - e.touches[1].clientX,
              e.touches[0].clientY - e.touches[1].clientY
          );
          pinchStartRef.current = { dist, zoom };
          if (dragRef.current) {
              dragRef.current = null;
              setSnapTime(null); 
          }
      }
  };

  const handleTouchMove = (e: React.TouchEvent) => {
      if (e.touches.length === 2 && pinchStartRef.current) {
          e.preventDefault(); 
          const dist = Math.hypot(
              e.touches[0].clientX - e.touches[1].clientX,
              e.touches[0].clientY - e.touches[1].clientY
          );
          const scale = dist / pinchStartRef.current.dist;
          const newZoom = Math.max(10, Math.min(1000, pinchStartRef.current.zoom * scale));
          setZoom(newZoom);
          return; 
      }
  };

  const handleTouchEnd = () => {
      if (pinchStartRef.current) {
         pinchStartRef.current = null;
      }
  };

  // --- Clip Interaction (Move/Split/Context) ---
  const handleClipInteract = (clipId: string, action: string, data?: any) => {
    if (action === 'context') {
        const { action: ctxAction } = data;
        if (ctxAction === 'copy') { setSelectedClipId(clipId); handleCopy(); }
        if (ctxAction === 'split') { splitClip(clipId, currentTime); }
        if (ctxAction === 'delete') { setSelectedClipId(clipId); deleteSelectedClip(); }
        if (ctxAction === 'reverse') {
             const c = clips.find(x => x.id === clipId);
             if (c) {
                handleClipFXUpdate(clipId, { isReversed: !c.fx.isReversed });
                addNotification(c.fx.isReversed ? 'CLIP NORMALIZED' : 'CLIP REVERSED', 'info');
             }
        }
        return;
    }
    if (action === 'tap') {
        setSelectedClipId(clipId);
        return;
    }
    if (editMode === EditMode.MOVE && action === 'start') {
      if (pinchStartRef.current) return;

      setSelectedClipId(clipId);
      dragRef.current = { clipId, startX: data.x, originalStart: data.originalStart };

      const handleMove = (e: any) => {
        if (e.touches && e.touches.length > 1) {
            dragRef.current = null; 
            return;
        }

        if (!dragRef.current || !containerRef.current) return;
        const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
        const deltaX = clientX - dragRef.current.startX;
        const deltaTime = deltaX / zoom; 

        let newStart = Math.max(0, dragRef.current.originalStart + deltaTime);

        const snappedStart = calculateSnap(newStart, zoom);
        if (Math.abs(snappedStart - newStart) * zoom < 15) {
            setSnapTime(snappedStart);
            newStart = snappedStart;
        } else {
            setSnapTime(null);
        }

        const containerRect = containerRef.current.getBoundingClientRect();
        const scrollY = containerRef.current.scrollTop;
        const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
        const relativeY = clientY - containerRect.top + scrollY;

        let accumulatedHeight = 0;
        let targetTrackId = null;
        for (const track of tracks) {
            const h = track.isExpanded ? EXPANDED_TRACK_HEIGHT : TRACK_HEIGHT;
            if (relativeY >= accumulatedHeight && relativeY < accumulatedHeight + h) {
                targetTrackId = track.id;
                break;
            }
            accumulatedHeight += h;
        }

        setClips(prev => prev.map(c => 
          c.id === dragRef.current?.clipId ? { 
              ...c, startTime: newStart, 
              trackId: targetTrackId || c.trackId 
          } : c
        ));
      };

      const handleEnd = () => {
        dragRef.current = null;
        setSnapTime(null);
        window.removeEventListener('touchmove', handleMove); window.removeEventListener('touchend', handleEnd);
        window.removeEventListener('mousemove', handleMove); window.addEventListener('mouseup', handleEnd);
      };
      window.addEventListener('touchmove', handleMove, { passive: false }); window.addEventListener('touchend', handleEnd);
      window.addEventListener('mousemove', handleMove); window.addEventListener('mouseup', handleEnd);
    }
  };

  const handleClipFXUpdate = (clipId: string, updates: Partial<AudioClip['fx']> | { viewConfig: any }) => {
      setClips(prev => prev.map(c => c.id === clipId ? { ...c, ...('viewConfig' in updates ? { viewConfig: updates.viewConfig } : { fx: { ...c.fx, ...updates } }) } : c));
      if (!('viewConfig' in updates)) audioEngine.updateClipParams(clipId, updates as Partial<typeof DEFAULT_CLIP_FX>);
  };

  const splitClip = (clipId: string, splitTimeOverride?: number) => {
    const clip = clips.find(c => c.id === clipId);
    if (!clip) return;
    const timeToSplitAt = splitTimeOverride !== undefined ? splitTimeOverride : currentTime;

    const snappedSplit = calculateSnap(timeToSplitAt, zoom);

    const relativeSplitTime = (snappedSplit - clip.startTime); 
    if (relativeSplitTime <= 0.01 || relativeSplitTime >= clip.duration - 0.01) {
        addNotification('CANNOT SPLIT: TOO CLOSE TO EDGE', 'error');
        return;
    }

    const clip1: AudioClip = { ...clip, id: clip.id + '_1', duration: relativeSplitTime };
    const clip2: AudioClip = { ...clip, id: clip.id + '_2', startTime: snappedSplit, duration: clip.duration - relativeSplitTime, offset: clip.offset + relativeSplitTime };
    setClips(prev => prev.filter(c => c.id !== clipId).concat([clip1, clip2]));
    setSelectedClipId(clip2.id);
    addNotification('CLIP SPLIT SUCCESSFUL', 'success');
  };

  const handleSplitButton = () => { if (selectedClipId) splitClip(selectedClipId, currentTime); else addNotification('NO CLIP SELECTED', 'error'); };
  const deleteSelectedClip = () => { if (selectedClipId) { setClips(prev => prev.filter(c => c.id !== selectedClipId)); setSelectedClipId(null); addNotification('CLIP DELETED', 'info'); }};

  const handleTimelineScrub = (e: any) => {
     if (e.target.dataset.bg) setSelectedClipId(null);
     if (!containerRef.current) return;
     const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
     const containerLeft = containerRef.current.getBoundingClientRect().left;
     const scrollLeft = containerRef.current.scrollLeft;
     const relativeX = clientX - containerLeft + scrollLeft;
     const rawTime = Math.max(0, (relativeX - currentChannelWidth) / zoom);
     const snappedTime = calculateSnap(rawTime, zoom);
     setCurrentTime(snappedTime);
     startOffsetRef.current = snappedTime;
  };

  const selectedClip = clips.find(c => c.id === selectedClipId);

  return (
    <div className="flex flex-col h-screen w-screen bg-transparent text-slate-100 overflow-hidden select-none font-sans relative">
      <BackgroundInterference />

      {/* Replaced NotificationSystem with LogConsole Toggle Logic */}
      {showLogs && <LogConsole logs={notifications} onClose={() => setShowLogs(false)} />}

      <div className="flex flex-col h-full w-full z-10 relative bg-black/10 backdrop-blur-[1px]">
        <Controls 
            isPlaying={isPlaying} isRecording={isRecording} isLooping={isLooping} loopRange={loopRange}
            onPlayPause={togglePlay} onRecord={toggleRecord} onStop={stop} onBounce={() => setShowInfoPanel(true)} 
            onDelete={deleteSelectedClip} onSplit={handleSplitButton} onCopy={handleCopy} onPaste={handlePaste}
            onToggleLoop={handleToggleLoop} onSetLoopIn={handleSetLoopIn} onSetLoopOut={handleSetLoopOut}
            onOpenInfo={() => setShowInfoPanel(true)} onShowCredits={() => setShowCredits(true)}
            onToggleLogs={() => setShowLogs(!showLogs)} // Wired Up
            editMode={editMode} setEditMode={setEditMode} monitor={monitor} setMonitor={setMonitor}
            zoom={zoom} setZoom={setZoom} hasSelection={!!selectedClipId} hasClipboard={!!clipClipboard}
            viewSettings={viewSettings} setViewSettings={setViewSettings}
        />

        <div ref={containerRef} className="flex-1 overflow-y-auto overflow-x-auto relative mt-[60px] mb-[260px]" 
            onClick={() => setSelectedClipId(null)} data-bg="true"
            onTouchStart={handleTouchStart}
            onTouchMove={handleTouchMove}
            onTouchEnd={handleTouchEnd}
        >

            {/* Snap Guide Line */}
            {snapTime !== null && (
                <div className="absolute top-0 bottom-0 border-l border-yellow-400 z-50 pointer-events-none opacity-80"
                     style={{ left: `${(snapTime * zoom) + currentChannelWidth}px` }}></div>
            )}

            {/* Playhead */}
            <div className="absolute top-0 bottom-0 z-40 pointer-events-none border-r border-cyan-500 shadow-[0_0_15px_rgba(6,182,212,0.6)]"
                style={{ left: `${(currentTime * zoom) + currentChannelWidth}px`, width: '1px' }}>
                <div className="absolute -top-4 -translate-x-1/2 bg-cyan-900 text-[9px] px-1.5 py-0.5 rounded-sm text-cyan-200 font-mono shadow-md whitespace-nowrap z-50 border border-cyan-500/50">
                    {currentTime.toFixed(2)}s
                </div>
                <div className="absolute top-0 bottom-0 w-px bg-cyan-500/50"></div>
            </div>

            {/* Ruler */}
            <div className="h-8 min-w-full bg-[#030305]/90 border-b border-white/10 relative cursor-pointer shadow-lg z-30 transition-all duration-300"
                style={{ width: `${Math.max(window.innerWidth, (300 * zoom) + currentChannelWidth)}px` }}
                onClick={(e) => { e.stopPropagation(); handleTimelineScrub(e); }}>
                {loopRange && (
                    <div className="absolute top-0 bottom-0 bg-blue-500/10 border-x border-blue-500/50 z-0"
                        style={{ left: `${loopRange.start * zoom + currentChannelWidth}px`, width: `${(loopRange.end - loopRange.start) * zoom}px` }}>
                    </div>
                )}
                {/* Adaptive Ticks */}
                {Array.from({ length: Math.ceil(300 * zoom / 100) * (zoom > 150 ? 8 : 4) }).map((_, i) => {
                    const step = zoom > 150 ? 0.125 : 0.25;
                    const sec = i * step;
                    const isMajor = Math.abs(sec % 1) < 0.001;
                    const isMedium = Math.abs(sec % 0.5) < 0.001;
                    let h = 'h-1 border-slate-700';
                    if (isMajor) h = 'h-3 border-slate-500';
                    else if (isMedium) h = 'h-2 border-slate-600';
                    return (
                    <div key={i} className={`absolute bottom-0 border-l z-10 pointer-events-none ${h}`} 
                        style={{ left: (sec * zoom) + currentChannelWidth }}>
                        {isMajor && <span className="text-[8px] font-mono font-medium text-slate-500 pl-1.5 -mt-4 block">{sec}</span>}
                    </div>
                )})}
            </div>

            {/* Tracks Container */}
            <div className="min-w-full pb-20 relative bg-transparent transition-all duration-300" style={{ width: `${Math.max(window.innerWidth, (300 * zoom) + currentChannelWidth)}px` }} data-bg="true">
            {tracks.map(track => (
                <div key={track.id} className="flex border-b border-white/5 bg-black/20" style={{ height: track.isExpanded ? EXPANDED_TRACK_HEIGHT : TRACK_HEIGHT }}>
                <ChannelStrip 
                    track={track} onUpdate={handleTrackUpdate} onToggleArm={toggleTrackArm} onToggleExpand={toggleTrackExpand} onDuplicate={handleDuplicateTrack}
                    width={currentChannelWidth} viewSettings={viewSettings} isCollapsed={viewSettings.isCollapsed}
                />
                <div className="relative w-full z-10 flex-1 min-w-0">
                    <TrackLane track={track} clips={clips.filter(c => c.trackId === track.id)} editMode={editMode} selectedClipId={selectedClipId} onClipInteract={handleClipInteract} currentTime={currentTime} isPlaying={isPlaying} zoom={zoom} />
                </div>
                </div>
            ))}
            </div>
        </div>

        {selectedClip ? (
            <ClipInspector clip={selectedClip} onUpdate={handleClipFXUpdate} onClose={() => setSelectedClipId(null)} />
        ) : (
            <DSPRack dspState={dspState} onChange={(s) => { setDspState(s); audioEngine.updateMasterDSP(s); }} />
        )}

        {showInfoPanel && (
            <ProjectInfoPanel metadata={metadata} onChange={setMetadata} onClose={() => !isExporting && setShowInfoPanel(false)} onExport={handleExport} isExporting={isExporting} />
        )}
        {showCredits && (
            <CreditsModal onClose={() => setShowCredits(false)} />
        )}
      </div>
    </div>
  );
};

export default App;

import React, { useEffect, useRef } from 'react';
import { Notification } from '../types';

interface LogConsoleProps {
    logs: Notification[];
    onClose: () => void;
}

export const LogConsole: React.FC<LogConsoleProps> = ({ logs, onClose }) => {
    const scrollRef = useRef<HTMLDivElement>(null);

    // Auto-scroll to bottom
    useEffect(() => {
        if (scrollRef.current) {
            scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
        }
    }, [logs]);

    const handleCopy = () => {
        const text = logs.map(l => `[${new Date(l.timestamp).toISOString()}] [${l.type.toUpperCase()}] ${l.message}`).join('\n');
        navigator.clipboard.writeText(text);
        // We could add a self-log here but that might be recursive!
    };

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/80 backdrop-blur-sm animate-in fade-in duration-200">
            <div className="w-[800px] h-[500px] bg-[#0c0c0e] border border-slate-700 rounded-lg shadow-2xl flex flex-col font-mono overflow-hidden relative">

                {/* Header */}
                <div className="bg-[#1a1a1c] px-4 py-2 border-b border-slate-700 flex justify-between items-center select-none">
                    <div className="flex items-center space-x-2">
                        <div className="w-3 h-3 rounded-full bg-red-500/20 border border-red-500"></div>
                        <div className="w-3 h-3 rounded-full bg-yellow-500/20 border border-yellow-500"></div>
                        <div className="w-3 h-3 rounded-full bg-green-500/20 border border-green-500"></div>
                        <span className="text-xs text-slate-400 font-bold ml-2">SYSTEM.LOG // KERNEL_DUMP</span>
                    </div>
                    <div className="flex space-x-4">
                        <button onClick={handleCopy} className="text-[10px] text-cyan-500 hover:text-cyan-300 uppercase font-bold tracking-wider">
                            Copy All
                        </button>
                        <button onClick={onClose} className="text-[10px] text-slate-500 hover:text-white uppercase font-bold tracking-wider">
                            Close
                        </button>
                    </div>
                </div>

                {/* Log Output */}
                <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-1 bg-black/50">
                    <div className="text-[10px] text-slate-600 mb-4 select-none">
                        > INITIALIZING SYSTEM... OK<br/>
                        > CONNECTING TO AUDIO CONTEXT... OK<br/>
                        > LOADING DSP MODULES... OK<br/>
                        > AWAITING INPUT...
                    </div>

                    {logs.map((log) => (
                        <div key={log.id} className="flex space-x-3 text-[11px] border-b border-white/5 pb-0.5 mb-0.5 hover:bg-white/5">
                            <span className="text-slate-600 select-none">
                                {new Date(log.timestamp).toLocaleTimeString([], {hour12: false, hour:'2-digit', minute:'2-digit', second:'2-digit'})}.{new Date(log.timestamp).getMilliseconds()}
                            </span>
                            <span className={`font-bold w-16 select-none ${
                                log.type === 'error' ? 'text-red-500' : 
                                log.type === 'warning' ? 'text-yellow-500' : 
                                log.type === 'success' ? 'text-green-500' : 'text-blue-400'
                            }`}>
                                {log.type.toUpperCase()}
                            </span>
                            <span className="text-slate-300 flex-1 break-all">
                                {log.message}
                            </span>
                        </div>
                    ))}
                    {logs.length === 0 && (
                        <div className="text-slate-700 italic text-xs p-4 text-center">No active logs recorded in this session.</div>
                    )}
                </div>

                {/* Footer Status */}
                <div className="bg-[#1a1a1c] px-2 py-1 border-t border-slate-700 flex justify-between">
                    <span className="text-[9px] text-slate-500">MEM_USAGE: {(performance as any).memory?.usedJSHeapSize ? Math.round((performance as any).memory.usedJSHeapSize / 1024 / 1024) + ' MB' : 'N/A'}</span>
                    <span className="text-[9px] text-slate-500">Active Threads: 1 (Main) + AudioWorklet</span>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useRef, useEffect } from 'react';
import { Track, ViewSettings } from '../types';
import { COLORS, TRACK_HEIGHT, EXPANDED_TRACK_HEIGHT } from '../constants';
import { Knob } from './Knob';
import { Slider } from './Slider';
import { XYPad } from './XYPad';
import { audioEngine } from '../services/audioEngine';
import { DynamicsTransfer, FilterResponse, LFOOscilloscope } from './Visualizers';

interface ChannelStripProps {
  track: Track;
  onUpdate: (id: string, updates: Partial<Track>) => void;
  onToggleArm: (id: string) => void;
  onToggleExpand: (id: string) => void;
  onDuplicate: (id: string) => void;
  width: number;
  viewSettings: ViewSettings;
  isCollapsed: boolean;
}

type Tab = 'DYNAMICS' | 'EQUALIZER' | 'MODULATION' | 'SPACE';

export const ChannelStrip: React.FC<ChannelStripProps> = ({ 
    track, onUpdate, onToggleArm, onToggleExpand, onDuplicate, 
    width, viewSettings, isCollapsed 
}) => {
  const [showColors, setShowColors] = useState(false);
  const [activeTab, setActiveTab] = useState<Tab>('DYNAMICS');
  const menuRef = useRef<HTMLDivElement>(null);
  const meterCanvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) setShowColors(false);
    };
    if (showColors) document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [showColors]);

  // Meter Animation Loop
  useEffect(() => {
    if (isCollapsed) return;
    const canvas = meterCanvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animId: number;
    let peakHold = 0;
    let peakTimer = 0;

    const drawMeter = () => {
        const rms = audioEngine.getTrackRMS(track.id);
        const w = canvas.width;
        const h = canvas.height;
        ctx.clearRect(0, 0, w, h);

        ctx.fillStyle = '#111';
        ctx.fillRect(0, 0, w, h);

        const level = Math.min(1.0, rms * 2.5); 
        const activeW = level * w;

        const grad = ctx.createLinearGradient(0, 0, w, 0);
        grad.addColorStop(0, track.color + '20'); 
        grad.addColorStop(0.5, track.color);     
        grad.addColorStop(1, '#fff');            

        ctx.fillStyle = grad;
        ctx.fillRect(0, 0, activeW, h);

        if (level > peakHold) {
            peakHold = level;
            peakTimer = 60;
        } else {
            if (peakTimer > 0) peakTimer--;
            else peakHold *= 0.95;
        }

        ctx.fillStyle = '#fff';
        ctx.fillRect(peakHold * w, 0, 2, h);
        ctx.fillStyle = 'rgba(0,0,0,0.5)';
        for(let i=1; i<10; i++) ctx.fillRect(i * (w/10), 0, 1, h);

        animId = requestAnimationFrame(drawMeter);
    };

    drawMeter();
    return () => cancelAnimationFrame(animId);
  }, [track.id, track.color, isCollapsed]);

  const updateFX = (key: keyof typeof track.fx, value: any) => {
      onUpdate(track.id, {
          fx: { ...track.fx, [key]: value }
      });
  };

  const isWide = width > 200;

  return (
    <div 
        className="sticky left-0 z-20 flex flex-col transition-all duration-300 ease-out group shadow-[4px_0_20px_rgba(0,0,0,0.8)] overflow-hidden" 
        style={{ 
            width: width,
            height: track.isExpanded ? EXPANDED_TRACK_HEIGHT : TRACK_HEIGHT,
            background: '#0a0a0c',
            borderRight: `1px solid ${track.color}20`
        }}
    >
       {/* --- HEADER SECTION --- */}
       <div className="p-3 flex-shrink-0 flex flex-col relative" style={{ height: TRACK_HEIGHT }}>
            <div className={`flex items-center gap-2 relative z-30 transition-all ${isCollapsed ? 'justify-center flex-col h-full space-y-4' : 'justify-between mb-2'}`}>
                <div className="relative flex-shrink-0" ref={menuRef}>
                    <button
                        className="w-3 h-3 rounded-full transition-all duration-300 hover:scale-125"
                        style={{ backgroundColor: track.color, boxShadow: `0 0 8px ${track.color}` }}
                        onClick={() => setShowColors(!showColors)}
                    />
                    {showColors && (
                    <div className="absolute top-full left-0 mt-2 bg-black/90 backdrop-blur-xl border border-white/10 p-2 rounded-lg grid grid-cols-4 gap-2 shadow-2xl z-50 w-32 animate-in zoom-in-95 duration-100">
                        {COLORS.map(c => (
                            <button key={c} className="w-5 h-5 rounded-full border border-white/10 hover:scale-110 transition-transform" style={{ backgroundColor: c, boxShadow: `0 0 10px ${c}` }}
                            onClick={(e) => { e.stopPropagation(); onUpdate(track.id, { color: c }); setShowColors(false); }} />
                        ))}
                    </div>
                    )}
                </div>
                {!isCollapsed && (
                    <input
                        className="bg-transparent text-[13px] font-bold text-slate-200 w-full outline-none px-0.5 truncate tracking-wide focus:text-white placeholder-slate-600 font-mono transition-all"
                        value={track.name}
                        onChange={(e) => onUpdate(track.id, { name: e.target.value })}
                        style={{ opacity: width < 60 ? 0 : 1 }}
                    />
                )}
                <button 
                    onClick={() => onToggleArm(track.id)} 
                    className={`w-6 h-6 rounded-full flex-shrink-0 flex items-center justify-center transition-all ${track.armed ? 'bg-red-500/10 shadow-[0_0_15px_rgba(220,38,38,0.4)]' : 'bg-transparent hover:bg-white/5'}`}
                >
                    <div className={`w-2.5 h-2.5 rounded-full transition-all ${track.armed ? 'bg-red-500 animate-pulse' : 'bg-slate-700'}`} />
                </button>
            </div>

            {!isCollapsed && (
                <div className={`flex space-x-1 mb-3 transition-all duration-300 overflow-hidden ${viewSettings.showTransport ? 'opacity-100 max-h-10' : 'opacity-0 max-h-0'}`}>
                    <button className={`flex-1 py-1.5 text-[10px] font-bold rounded transition-all tracking-wider ${track.muted ? 'bg-orange-500 text-black' : 'bg-[#1a1a1e] text-slate-500 hover:bg-[#222]'}`} onClick={() => onUpdate(track.id, { muted: !track.muted })}>MUTE</button>
                    <button className={`flex-1 py-1.5 text-[10px] font-bold rounded transition-all tracking-wider ${track.solo ? 'bg-yellow-400 text-black' : 'bg-[#1a1a1e] text-slate-500 hover:bg-[#222]'}`} onClick={() => onUpdate(track.id, { solo: !track.solo })}>SOLO</button>
                    {viewSettings.showRack && (
                        <button className={`flex-1 py-1.5 text-[10px] font-bold rounded transition-all tracking-wider ${track.isExpanded ? 'bg-blue-600 text-white' : 'bg-[#1a1a1e] text-blue-500 hover:bg-[#222]'}`} onClick={() => onToggleExpand(track.id)}>FX</button>
                    )}
                </div>
            )}

            {!isCollapsed && width > 100 && (
                <button 
                    className="absolute right-2 top-10 text-[8px] text-slate-700 hover:text-white uppercase tracking-wider opacity-0 group-hover:opacity-100 transition-opacity"
                    onClick={() => onDuplicate(track.id)}
                >Dup</button>
             )}

            {!isCollapsed && (
                <div className={`flex flex-col space-y-3 transition-all duration-500 overflow-hidden ${viewSettings.showMix ? 'opacity-100 max-h-24' : 'opacity-0 max-h-0'}`}>
                    <div className="flex items-center space-x-2 group/vol relative">
                         {isWide && <span className="text-[8px] font-bold text-slate-600 w-8 text-right">VOL</span>}
                        <div className="flex-1 h-3 relative flex items-center bg-[#111] rounded-sm overflow-hidden border border-white/10 cursor-ew-resize">
                            <canvas ref={meterCanvasRef} width={200} height={12} className="absolute inset-0 w-full h-full opacity-60 pointer-events-none" />
                            <div className="absolute top-0 bottom-0 w-1 bg-white shadow-[0_0_10px_white] z-10 pointer-events-none" style={{ left: `${track.volume * 100}%` }}></div>
                            <input 
                                type="range" min="0" max="1" step="0.01" value={track.volume} 
                                onChange={(e) => onUpdate(track.id, { volume: parseFloat(e.target.value) })}
                                className="absolute w-full h-full opacity-0 cursor-ew-resize z-20" 
                            />
                        </div>
                        {isWide && <span className="text-[9px] font-mono text-white w-8 text-right">{(track.volume * 100).toFixed(0)}</span>}
                    </div>

                    <div className="flex items-center space-x-2 group/pan">
                         {isWide && <span className="text-[8px] font-bold text-slate-600 w-8 text-right">PAN</span>}
                        <div className="flex-1 h-1.5 relative flex items-center bg-[#111] rounded-full border border-white/5 cursor-ew-resize">
                            <div className="absolute left-1/2 w-px h-full bg-slate-600"></div>
                            <div className="absolute h-2.5 w-2.5 rounded-full shadow-[0_0_8px_white] bg-white pointer-events-none transition-transform top-1/2 -translate-y-1/2" style={{ left: `calc(${((track.pan + 1) / 2) * 100}% - 5px)` }} />
                            <input 
                                type="range" min="-1" max="1" step="0.1" value={track.pan} 
                                onChange={(e) => onUpdate(track.id, { pan: parseFloat(e.target.value) })}
                                className="absolute w-full h-full opacity-0 cursor-ew-resize" 
                            />
                        </div>
                        {isWide && <span className="text-[9px] font-mono text-slate-400 w-8 text-right">{track.pan.toFixed(1)}</span>}
                    </div>
                </div>
            )}
       </div>

       {/* --- MODULAR FX RACK --- */}
       {track.isExpanded && !isCollapsed && (
           <div className="flex-1 flex flex-col overflow-hidden relative bg-[#050505] animate-in slide-in-from-left duration-300">

               {/* TABS */}
               <div className="flex border-b border-white/5 bg-[#080808]">
                   {(['DYNAMICS', 'EQUALIZER', 'MODULATION', 'SPACE'] as Tab[]).map(tab => (
                       <button
                           key={tab}
                           onClick={() => setActiveTab(tab)}
                           className={`flex-1 py-3 text-[9px] font-black tracking-widest border-r border-white/5 transition-colors
                           ${activeTab === tab ? 'bg-[#111] text-cyan-400 border-b-2 border-b-cyan-500' : 'text-slate-600 hover:text-slate-400'}`}
                       >{tab}</button>
                   ))}
               </div>

               {/* TAB CONTENT (GRID LAYOUT) */}
               <div className="flex-1 overflow-y-auto p-0 scrollbar-hide bg-[#0b0b0d]">

                   {/* 1. DYNAMICS: GATE + COMPRESSOR */}
                   {activeTab === 'DYNAMICS' && (
                       <div className="h-full flex flex-col">
                           {/* TOP: COMPRESSOR VISUALIZER + MAIN CONTROLS */}
                           <div className="h-[200px] relative border-b border-white/5 p-4 flex items-center justify-around overflow-hidden">
                               <DynamicsTransfer threshold={track.fx.compressorThreshold} ratio={track.fx.compressorRatio} color="#eab308" />
                               <div className="relative z-10 flex space-x-6">
                                    <Knob value={track.fx.compressorThreshold} min={-60} max={0} label="THRESH" unit="dB" color="yellow" size={50} onChange={(v) => updateFX('compressorThreshold', v)} />
                                    <Knob value={track.fx.compressorRatio} min={1} max={20} label="RATIO" unit=":1" color="yellow" size={50} onChange={(v) => updateFX('compressorRatio', v)} />
                               </div>
                           </div>
                           {/* BOTTOM: ENVELOPE + GATE */}
                           <div className="flex-1 grid grid-cols-2">
                               <div className="border-r border-white/5 p-2 flex flex-col items-center justify-center space-y-2 bg-[#0e0e11]">
                                   <span className="text-[8px] font-bold text-slate-500 mb-1">ENVELOPE</span>
                                   <div className="flex space-x-2">
                                       <Knob value={(track.fx.compressorAttack || 0.003) * 1000} min={1} max={100} label="ATTACK" unit="ms" color="yellow" size={36} onChange={(v) => updateFX('compressorAttack', v/1000)} />
                                       <Knob value={(track.fx.compressorRelease || 0.25) * 1000} min={10} max={1000} label="RELEASE" unit="ms" color="yellow" size={36} onChange={(v) => updateFX('compressorRelease', v/1000)} />
                                   </div>
                               </div>
                               <div className="p-2 flex flex-col items-center justify-center space-y-2 bg-[#0e0e11]">
                                   <span className="text-[8px] font-bold text-green-500 mb-1">NOISE GATE</span>
                                   <Knob value={track.fx.gateThreshold} min={-80} max={0} label="FLOOR" unit="dB" color="green" size={40} onChange={(v) => updateFX('gateThreshold', v)} />
                               </div>
                           </div>
                       </div>
                   )}

                   {/* 2. EQUALIZER */}
                   {activeTab === 'EQUALIZER' && (
                       <div className="h-full flex flex-col relative">
                            {/* EQ VISUALIZER BACKGROUND */}
                            <div className="absolute inset-0 opacity-20 pointer-events-none">
                                <FilterResponse freq={track.fx.highPassFreq} res={0.7} type="highpass" color="#555" />
                                <FilterResponse freq={200} res={0.7} gain={track.fx.eqLow} type="lowshelf" color="#06b6d4" />
                                <FilterResponse freq={1000} res={0.7} gain={track.fx.eqMid} type="peaking" color="#06b6d4" />
                                <FilterResponse freq={4000} res={0.7} gain={track.fx.eqHigh} type="highshelf" color="#06b6d4" />
                            </div>

                            <div className="flex-1 grid grid-cols-3 gap-px bg-white/5">
                                <div className="bg-[#0b0b0d] flex flex-col items-center justify-center pt-4">
                                    <Slider value={track.fx.eqLow} min={-12} max={12} label="LOW" unit="dB" color="cyan" height={160} onChange={(v) => updateFX('eqLow', v)} />
                                    <div className="mt-2 border-t border-white/5 w-full flex justify-center py-2">
                                       <Knob value={track.fx.highPassFreq} min={20} max={500} logarithmic label="HPF" unit="Hz" color="slate" size={32} onChange={(v) => updateFX('highPassFreq', v)} />
                                    </div>
                                </div>
                                <div className="bg-[#0b0b0d] flex flex-col items-center justify-center pt-4">
                                    <Slider value={track.fx.eqMid} min={-12} max={12} label="MID" unit="dB" color="cyan" height={160} onChange={(v) => updateFX('eqMid', v)} />
                                    <div className="mt-2 border-t border-white/5 w-full flex justify-center py-2">
                                       <span className="text-[9px] text-slate-700 font-mono">1kHz</span>
                                    </div>
                                </div>
                                <div className="bg-[#0b0b0d] flex flex-col items-center justify-center pt-4">
                                    <Slider value={track.fx.eqHigh} min={-12} max={12} label="HIGH" unit="dB" color="cyan" height={160} onChange={(v) => updateFX('eqHigh', v)} />
                                    <div className="mt-2 border-t border-white/5 w-full flex justify-center py-2">
                                       <Knob value={track.fx.presence || 4000} min={1000} max={10000} logarithmic label="AIR" unit="Hz" color="cyan" size={32} onChange={(v) => updateFX('presence', v)} />
                                    </div>
                                </div>
                            </div>
                       </div>
                   )}

                   {/* 3. MODULATION (EXPANDED) */}
                   {activeTab === 'MODULATION' && (
                       <div className="grid grid-cols-1 gap-px bg-white/5 pb-20">
                           {/* CHORUS */}
                           <div className="bg-[#0e0e11] p-3 flex items-center justify-between border-b border-white/5 relative overflow-hidden">
                               <LFOOscilloscope rate={track.fx.chorusRate || 1.5} depth={track.fx.chorusDepth || 0.5} color="#a855f7" />
                               <div className="relative z-10 w-full flex justify-between items-center px-2">
                                    <span className="text-[9px] font-black text-purple-500 -rotate-90 w-4">CHORUS</span>
                                    <Knob value={track.fx.chorusMix || 0} min={0} max={1} label="MIX" unit="%" color="purple" size={36} onChange={(v) => updateFX('chorusMix', v)} />
                                    <Knob value={track.fx.chorusRate || 1.5} min={0.1} max={5} label="RATE" unit="Hz" color="purple" size={36} onChange={(v) => updateFX('chorusRate', v)} />
                                    <Knob value={(track.fx.chorusDepth || 0.002) * 1000} min={0} max={10} label="DEPTH" unit="ms" color="purple" size={36} onChange={(v) => updateFX('chorusDepth', v/1000)} />
                               </div>
                           </div>

                           {/* FLANGER */}
                           <div className="bg-[#0e0e11] p-3 flex items-center justify-between border-b border-white/5 relative overflow-hidden">
                                <LFOOscilloscope rate={track.fx.flangerRate || 0.5} depth={0.8} color="#3b82f6" />
                                <div className="relative z-10 w-full flex justify-between items-center px-2">
                                    <span className="text-[9px] font-black text-blue-500 -rotate-90 w-4">FLANGE</span>
                                    <Knob value={track.fx.flangerMix || 0} min={0} max={1} label="MIX" unit="%" color="blue" size={36} onChange={(v) => updateFX('flangerMix', v)} />
                                    <Knob value={track.fx.flangerRate || 0.5} min={0.1} max={2} label="RATE" unit="Hz" color="blue" size={36} onChange={(v) => updateFX('flangerRate', v)} />
                                    <Knob value={track.fx.flangerFeedback || 0} min={0} max={0.95} label="FDBK" unit="%" color="blue" size={36} onChange={(v) => updateFX('flangerFeedback', v)} />
                               </div>
                           </div>

                           {/* PHASER */}
                           <div className="bg-[#0e0e11] p-3 flex items-center justify-between relative overflow-hidden">
                                <LFOOscilloscope rate={track.fx.phaserRate || 1.0} depth={0.6} color="#ec4899" />
                                <div className="relative z-10 w-full flex justify-between items-center px-2">
                                    <span className="text-[9px] font-black text-pink-500 -rotate-90 w-4">PHASE</span>
                                    <Knob value={track.fx.phaserMix || 0} min={0} max={1} label="MIX" unit="%" color="pink" size={36} onChange={(v) => updateFX('phaserMix', v)} />
                                    <Knob value={track.fx.phaserRate || 1.0} min={0.1} max={5} label="RATE" unit="Hz" color="pink" size={36} onChange={(v) => updateFX('phaserRate', v)} />
                                    <div className="w-9"></div> {/* Spacer */}
                               </div>
                           </div>
                       </div>
                   )}

                   {/* 4. SPACE & COLOR */}
                   {activeTab === 'SPACE' && (
                       <div className="grid grid-cols-2 gap-px bg-white/5 h-full">
                           {/* SATURATION */}
                           <div className="col-span-2 bg-[#0e0e11] h-32 relative overflow-hidden border-b border-white/5">
                                <XYPad 
                                 x={(track.fx.saturation || 0) / 100} 
                                 y={(Math.min(20000, Math.max(1000, track.fx.distortionTone || 20000)) - 1000) / 19000}
                                 labelX="TUBE DRIVE" labelY="TONE" color="orange"
                                 onChange={(x, y) => {
                                     updateFX('saturation', x * 100);
                                     updateFX('distortionTone', 1000 + (y * 19000));
                                 }}
                               />
                           </div>

                           {/* AUTO WAH & CABINET SPLIT */}
                           <div className="col-span-2 grid grid-cols-2 border-b border-white/5">
                               {/* AUTO WAH */}
                               <div className="bg-[#0e0e11] p-2 flex flex-col items-center justify-center border-r border-white/5">
                                   <div className="flex items-center space-x-2 mb-2">
                                        <span className="text-[8px] font-black text-green-400">AUTO-WAH</span>
                                        <div className={`w-1.5 h-1.5 rounded-full ${track.fx.autoWahMix > 0 ? 'bg-green-500 shadow-[0_0_5px_lime]' : 'bg-slate-800'}`}></div>
                                   </div>
                                   <div className="flex space-x-2">
                                        <Knob value={track.fx.autoWahSens || 0} min={0} max={100} label="SENS" unit="%" color="green" size={32} onChange={(v) => updateFX('autoWahSens', v)} />
                                        <Knob value={track.fx.autoWahMix || 0} min={0} max={1} label="MIX" unit="%" color="green" size={32} onChange={(v) => updateFX('autoWahMix', v)} />
                                   </div>
                               </div>

                               {/* CABINET EMULATOR */}
                               <div className="bg-[#0e0e11] p-2 flex flex-col items-center justify-center relative overflow-hidden">
                                   <div className="flex items-center space-x-2 mb-2 z-10">
                                        <button 
                                            onClick={() => updateFX('cabinetOn', !track.fx.cabinetOn)}
                                            className={`text-[8px] font-black px-1.5 py-0.5 rounded border transition-all ${track.fx.cabinetOn ? 'bg-orange-900/40 border-orange-500 text-orange-400 shadow-[0_0_10px_rgba(249,115,22,0.3)]' : 'border-slate-700 text-slate-600 hover:text-slate-400'}`}
