import React, { useEffect, useRef } from 'react';

// --- MATH & PHYSICS KERNEL ---

const PI = Math.PI;
const TWO_PI = Math.PI * 2;

// Complex Number Structure
interface Complex { re: number; im: number; }

// Z-Transform Evaluation on Unit Circle: H(z) = (b0 + b1*z^-1 + b2*z^-2) / (1 + a1*z^-1 + a2*z^-2)
// Where z = e^(j*omega)
const evaluateBiquad = (f: number, fs: number, b: number[], a: number[]): { mag: number, phase: number } => {
    const omega = (TWO_PI * f) / fs;
    const cos1 = Math.cos(omega);
    const sin1 = Math.sin(omega);
    const cos2 = Math.cos(2 * omega);
    const sin2 = Math.sin(2 * omega);

    // Numerator
    const numRe = b[0] + b[1] * cos1 + b[2] * cos2;
    const numIm = -(b[1] * sin1 + b[2] * sin2);

    // Denominator
    const denRe = 1 + a[1] * cos1 + a[2] * cos2;
    const denIm = -(a[1] * sin1 + a[2] * sin2);

    // Magnitude Squared
    const magSq = (numRe * numRe + numIm * numIm) / (denRe * denRe + denIm * denIm);

    // Phase (optional for visualization but good for "complex" feel)
    const phase = Math.atan2(numIm, numRe) - Math.atan2(denIm, denRe);

    return { mag: Math.sqrt(magSq), phase };
};

// Coefficient Calculator (Standard Audio EQ Cookbook formulas)
const calculateBiquadCoeffs = (type: string, freq: number, fs: number, Q: number, gainDb: number = 0) => {
    const w0 = (TWO_PI * freq) / fs;
    const alpha = Math.sin(w0) / (2 * (Q || 0.707));
    const A = Math.pow(10, gainDb / 40);
    const cosW = Math.cos(w0);

    let b0=0, b1=0, b2=0, a0=1, a1=0, a2=0;

    switch (type) {
        case 'lowpass':
            b0 = (1 - cosW) / 2; b1 = 1 - cosW; b2 = (1 - cosW) / 2;
            a0 = 1 + alpha; a1 = -2 * cosW; a2 = 1 - alpha;
            break;
        case 'highpass':
            b0 = (1 + cosW) / 2; b1 = -(1 + cosW); b2 = (1 + cosW) / 2;
            a0 = 1 + alpha; a1 = -2 * cosW; a2 = 1 - alpha;
            break;
        case 'peaking':
            b0 = 1 + alpha * A; b1 = -2 * cosW; b2 = 1 - alpha * A;
            a0 = 1 + alpha / A; a1 = -2 * cosW; a2 = 1 - alpha / A;
            break;
        case 'lowshelf':
            b0 = A*((A+1) - (A-1)*cosW + 2*Math.sqrt(A)*alpha);
            b1 = 2*A*((A-1) - (A+1)*cosW);
            b2 = A*((A+1) - (A-1)*cosW - 2*Math.sqrt(A)*alpha);
            a0 = (A+1) + (A-1)*cosW + 2*Math.sqrt(A)*alpha;
            a1 = -2*((A-1) + (A+1)*cosW);
            a2 = (A+1) + (A-1)*cosW - 2*Math.sqrt(A)*alpha;
            break;
        case 'highshelf':
            b0 = A*((A+1) + (A-1)*cosW + 2*Math.sqrt(A)*alpha);
            b1 = -2*A*((A-1) + (A+1)*cosW);
            b2 = A*((A+1) + (A-1)*cosW - 2*Math.sqrt(A)*alpha);
            a0 = (A+1) - (A-1)*cosW + 2*Math.sqrt(A)*alpha;
            a1 = 2*((A-1) - (A+1)*cosW);
            a2 = (A+1) - (A-1)*cosW - 2*Math.sqrt(A)*alpha;
            break;
    }

    return {
        b: [b0/a0, b1/a0, b2/a0],
        a: [1, a1/a0, a2/a0]
    };
};

// --- VISUALIZERS ---

// 1. COMPLEX FIELD RESPONSE (Magnitude + Phase + Particle Flow)
interface FilterResponseProps {
    freq: number;
    res: number;
    gain?: number;
    type: 'lowpass' | 'highpass' | 'peaking' | 'lowshelf' | 'highshelf';
    color: string;
}

export const FilterResponse: React.FC<FilterResponseProps> = ({ freq, res, gain = 0, type, color }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let animationFrame: number;
        let time = 0;

        const render = () => {
            time += 0.02;
            // Check for valid dimensions to prevent errors
            if (canvas.offsetWidth === 0 || canvas.offsetHeight === 0) {
                 animationFrame = requestAnimationFrame(render);
                 return;
            }
            const w = canvas.width = canvas.offsetWidth;
            const h = canvas.height = canvas.offsetHeight;
            ctx.clearRect(0, 0, w, h);

            // Calculate exact Coefficients via Z-Transform
            const coeffs = calculateBiquadCoeffs(type, freq, 48000, res, gain);

            // Draw Bode Magnitude Plot
            ctx.beginPath();
            ctx.lineWidth = 2;
            ctx.strokeStyle = color;
            ctx.shadowBlur = 15;
            ctx.shadowColor = color;

            const points: {x:number, y:number, mag: number}[] = [];

            for (let i = 0; i < w; i+=2) {
                // Logarithmic frequency mapping: 20Hz to 20kHz
                const f = 20 * Math.pow(1000, i / w);
                const { mag } = evaluateBiquad(f, 48000, coeffs.b, coeffs.a);

                // Convert Magnitude to dB then to pixels
                // Range: +/- 24dB roughly
                const db = 20 * Math.log10(mag + 0.00001);
                const y = (h / 2) - (db * (h / 60)); 
                const clampedY = Math.max(0, Math.min(h, y));

                points.push({x: i, y: clampedY, mag});

                if (i === 0) ctx.moveTo(i, clampedY);
                else ctx.lineTo(i, clampedY);
            }
            ctx.stroke();

            // Quantum Field Fill (Gradient based on Magnitude)
            ctx.globalCompositeOperation = 'screen';
            const gradient = ctx.createLinearGradient(0, h, 0, 0);
            gradient.addColorStop(0, `${color}00`);
            gradient.addColorStop(1, `${color}44`);
            ctx.fillStyle = gradient;
            ctx.lineTo(w, h);
            ctx.lineTo(0, h);
            ctx.fill();

            // Particle Flow Simulation (Visualizing Phase/Flow)
            // Particles move faster where magnitude is higher (Passband)
            // Particles interact with the curve
            ctx.fillStyle = '#fff';
            const particleCount = 20;
            for(let i=0; i<particleCount; i++) {
                // Deterministic pseudo-random positions based on time
                const pOffset = (i / particleCount) * w;
                const speed = 1 + Math.sin(i * 32.1 + time);
                let px = (pOffset + time * 50 * speed) % w;

                // Find response at this X
                const idx = Math.floor(px / 2);
                if (idx < points.length) {
                    const pt = points[idx];
                    // Particles exist on the line, size modulated by magnitude
                    const size = Math.min(3, Math.max(0.5, pt.mag * 1.5));

                    // Add "Quantum Jitter"
                    const jitterX = (Math.random() - 0.5) * 2;
                    const jitterY = (Math.random() - 0.5) * 2;

                    ctx.globalAlpha = Math.min(1, pt.mag);
                    ctx.fillRect(pt.x + jitterX, pt.y + jitterY - 1, size, size);
                }
            }

            ctx.globalAlpha = 1;
            ctx.globalCompositeOperation = 'source-over';

            animationFrame = requestAnimationFrame(render);
        };
        render();
        return () => cancelAnimationFrame(animationFrame);

    }, [freq, res, gain, type, color]);

    return <canvas ref={canvasRef} className="absolute inset-0 w-full h-full opacity-60 pointer-events-none" />;
};

// 2. QUANTUM PROBABILITY DENSITY (Dynamics)
// Visualizes compression as a collapse of signal probability density
interface DynamicsProps {
    threshold: number; // dB
    ratio: number;
    color: string;
}
export const DynamicsTransfer: React.FC<DynamicsProps> = ({ threshold, ratio, color }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let frameId: number;
        let t = 0;

        const render = () => {
            t += 0.1;
            if (canvas.offsetWidth === 0 || canvas.offsetHeight === 0) {
                 frameId = requestAnimationFrame(render);
                 return;
            }
            const w = canvas.width = canvas.offsetWidth;
            const h = canvas.height = canvas.offsetHeight;
            ctx.clearRect(0,0,w,h);

            // 1. Draw The Transfer Function Line (The "Event Horizon")
            ctx.strokeStyle = '#ffffff40';
            ctx.setLineDash([2, 2]);
            ctx.beginPath();

            const kneePoints: {x:number, y:number}[] = [];

            for(let i=0; i<=w; i+=2) {
                const inDb = -60 + (i/w)*60;
                let outDb = inDb;
                if (inDb > threshold) {
                    outDb = threshold + (inDb - threshold) / ratio;
                }
                const y = h - ((outDb + 60) / 60) * h;
                kneePoints.push({x: i, y});
                if (i===0) ctx.moveTo(i, y); else ctx.lineTo(i, y);
            }
            ctx.stroke();
            ctx.setLineDash([]);

            // 2. Simulate Signal Probability Cloud
            // Generate random particles that represent signal amplitudes
            // Show them getting "squashed" by the curve
            const particles = 100;
            ctx.fillStyle = color;
            ctx.shadowColor = color;
            ctx.shadowBlur = 4;

            for(let i=0; i<particles; i++) {
                // Input Amplitude (Gaussian-ish distribution biased towards center)
                // We oscillate the input distribution to simulate music dynamics
                const signalSurge = Math.sin(t * 0.5 + i) * 20; 
                const randomDb = -30 + ((Math.random() - 0.5) * 30) + signalSurge;

                // Clamp input to visual range
                const inDb = Math.max(-60, Math.min(0, randomDb));

                // Calculate Output (Compressed)
                let outDb = inDb;
                let isCompressed = false;
                if (inDb > threshold) {
                    outDb = threshold + (inDb - threshold) / ratio;
                    isCompressed = true;
                }

                // Map to Pixels
                const x = ((inDb + 60) / 60) * w;
                const y = h - ((outDb + 60) / 60) * h;

                // Draw Particle
                // If compressed, particle glows brighter and turns white (Energy Release)
                if (isCompressed) {
                    ctx.fillStyle = '#fff';
                    ctx.globalAlpha = 0.8;
                    const size = 1.5 + (inDb - threshold) * 0.1; // Larger if heavily compressed
                    ctx.fillRect(x - size/2, y - size/2, size, size);

                    // Draw "Reduction Vector" (Ghost trail down from where it would have been)
                    const uncompressedY = h - ((inDb + 60) / 60) * h;
                    ctx.fillStyle = color;
                    ctx.globalAlpha = 0.3;
                    ctx.fillRect(x, uncompressedY, 1, y - uncompressedY);

                } else {
                    ctx.fillStyle = color;
                    ctx.globalAlpha = 0.4;
                    ctx.fillRect(x, y, 1, 1);
                }
            }

            // 3. Threshold Marker (Singularity)
            const threshX = ((threshold + 60) / 60) * w;
            const threshY = h - ((threshold + 60) / 60) * h;

            ctx.beginPath();
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 1;
            ctx.globalAlpha = 0.5;
            ctx.arc(threshX, threshY, 4 + Math.sin(t)*1, 0, TWO_PI);
            ctx.stroke();

            frameId = requestAnimationFrame(render);
        };
        render();
        return () => cancelAnimationFrame(frameId);

    }, [threshold, ratio, color]);

    return <canvas ref={canvasRef} className="absolute inset-0 w-full h-full opacity-80 pointer-events-none" />;
};

// 3. WAVEFUNCTION ENVELOPE (Fluid Bezier)
interface EnvelopeProps {
    fadeIn: number;
    fadeOut: number;
    color: string;
}
export const EnvelopeGraph: React.FC<EnvelopeProps> = ({ fadeIn, fadeOut, color }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        if (canvas.offsetWidth === 0 || canvas.offsetHeight === 0) return;
        const w = canvas.width = canvas.offsetWidth;
        const h = canvas.height = canvas.offsetHeight;
        ctx.clearRect(0,0,w,h);

        const inPx = Math.min(w * 0.4, fadeIn * 50); // Scale logic
        const outPx = Math.min(w * 0.4, fadeOut * 50);

        // Draw Fluid Spline
        ctx.beginPath();
        ctx.moveTo(0, h);

        // Attack Curve (Exponential)
        ctx.bezierCurveTo(inPx * 0.5, h, inPx * 0.5, 0, inPx, 0);

        // Sustain
        ctx.lineTo(w - outPx, 0);

        // Release Curve (Logarithmic)
        ctx.bezierCurveTo(w - outPx * 0.5, 0, w - outPx * 0.5, h, w, h);

        // Fill Gradient
        const grad = ctx.createLinearGradient(0, 0, 0, h);
        grad.addColorStop(0, color);
        grad.addColorStop(1, '#00000000');
        ctx.fillStyle = grad;
        ctx.globalAlpha = 0.3;
        ctx.fill();

        // Stroke
        ctx.lineWidth = 2;
        ctx.strokeStyle = color;
        ctx.shadowColor = color;
        ctx.shadowBlur = 10;
        ctx.globalAlpha = 1.0;
        ctx.stroke();

    }, [fadeIn, fadeOut, color]);
    return <canvas ref={canvasRef} className="absolute inset-0 w-full h-full opacity-60 pointer-events-none" />;
};

// 4. PHASOR PROJECTION SCOPE (LFO)
// Visualizes the rotating complex vector (Phasor) and its projection onto time
interface LFOProps {
    rate: number;
    depth: number;
    color: string;
}
export const LFOOscilloscope: React.FC<LFOProps> = ({ rate, depth, color }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let frameId: number;
        let time = 0;

        const render = () => {
            time += 0.016;
            if (canvas.offsetWidth === 0 || canvas.offsetHeight === 0) {
                 frameId = requestAnimationFrame(render);
                 return;
            }
            const w = canvas.width = canvas.offsetWidth;
            const h = canvas.height = canvas.offsetHeight;
            ctx.clearRect(0,0,w,h);

            const midY = h/2;
            const radius = (h/2) * 0.8 * depth;
            const phasorX = w * 0.15; // Phasor circle center X

            // 1. Draw Phasor Circle (Unit Circle)
            ctx.beginPath();
            ctx.strokeStyle = '#ffffff20';
            ctx.lineWidth = 1;
            ctx.arc(phasorX, midY, radius, 0, TWO_PI);
            ctx.stroke();

            // Calculate Phasor Position
            const angle = time * rate * TWO_PI;
            const tipX = phasorX + Math.cos(angle) * radius;
            const tipY = midY + Math.sin(angle) * radius * -1; // Canvas Y is inverted

            // 2. Draw Phasor Vector
            ctx.beginPath();
            ctx.strokeStyle = '#fff';
            ctx.moveTo(phasorX, midY);
            ctx.lineTo(tipX, tipY);
            ctx.stroke();

            // 3. Draw Projection Line (The "Collapse" to Real Domain)
            const waveStartX = w * 0.3;
            ctx.beginPath();
            ctx.strokeStyle = `${color}40`;
            ctx.setLineDash([2, 2]);
            ctx.moveTo(tipX, tipY);
            ctx.lineTo(waveStartX, tipY);
            ctx.stroke();
            ctx.setLineDash([]);

            // 4. Draw Time Domain Waveform
            ctx.beginPath();
            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.shadowColor = color;
            ctx.shadowBlur = 8;

            ctx.moveTo(waveStartX, tipY);

            // Plot history of wave
            for(let x=waveStartX; x<w; x++) {
                // Determine time at this x relative to current phasor time
                const xOffset = x - waveStartX;
                const timeDelay = xOffset * 0.01; // Scale factor
                const pastAngle = angle - (timeDelay * rate * 10); // Frequency scaling

                const y = midY + Math.sin(pastAngle) * radius * -1;
                ctx.lineTo(x, y);
            }
            ctx.stroke();

            // Phasor Tip Glow
            ctx.fillStyle = '#fff';
            ctx.shadowBlur = 10;
            ctx.shadowColor = '#fff';
            ctx.beginPath();
            ctx.arc(tipX, tipY, 3, 0, TWO_PI);
            ctx.fill();

            frameId = requestAnimationFrame(render);
        };
        render();
        return () => cancelAnimationFrame(frameId);
    }, [rate, depth, color]);
    return <canvas ref={canvasRef} className="absolute inset-0 w-full h-full opacity-60 pointer-events-none" />;
};

