import { useState, useRef, useEffect, useCallback } from 'react';

interface UseControlDragProps {
    value: number;
    min: number;
    max: number;
    onChange: (val: number) => void;
    sensitivity?: number; // Pixels to traverse full range (default 200)
    direction?: 'vertical' | 'horizontal';
    logarithmic?: boolean;
}

export const useControlDrag = ({
    value, min, max, onChange,
    sensitivity = 200,
    direction = 'vertical',
    logarithmic = false
}: UseControlDragProps) => {
    const [isDragging, setIsDragging] = useState(false);
    const startPos = useRef(0);
    const startVal = useRef(0);

    // Normalize value 0..1
    const toNormal = useCallback((v: number) => {
        const safeV = Math.max(min, Math.min(max, v));
        if (logarithmic) {
            const minLog = Math.log(min === 0 ? 0.001 : min);
            const maxLog = Math.log(max);
            return (Math.log(safeV) - minLog) / (maxLog - minLog);
        }
        return (safeV - min) / (max - min);
    }, [min, max, logarithmic]);

    // Denormalize 0..1 to value
    const fromNormal = useCallback((n: number) => {
        const clamped = Math.max(0, Math.min(1, n));
        if (logarithmic) {
            const minLog = Math.log(min === 0 ? 0.001 : min);
            const maxLog = Math.log(max);
            return Math.exp(minLog + (maxLog - minLog) * clamped);
        }
        return min + clamped * (max - min);
    }, [min, max, logarithmic]);

    const [internalNormal, setInternalNormal] = useState(toNormal(value));

    // Sync external changes when not dragging
    useEffect(() => {
        if (!isDragging) {
            setInternalNormal(toNormal(value));
        }
    }, [value, toNormal, isDragging]);

    const handleStart = (clientPos: number) => {
        setIsDragging(true);
        startPos.current = clientPos;
        startVal.current = internalNormal;
        document.body.style.cursor = direction === 'vertical' ? 'ns-resize' : 'ew-resize';
        document.body.style.userSelect = 'none';
    };

    const handleMove = useCallback((clientPos: number, isFine: boolean) => {
        if (!isDragging) return;

        const deltaPixels = startPos.current - clientPos; // Up/Left drag increases value typically

        // Direction correction: Up (lower Y) is positive. Right (higher X) is positive.
        // If vertical: startY - currentY (positive delta = moving up)
        // If horizontal: currentX - startX (positive delta = moving right)
        const adjustedDelta = direction === 'vertical' ? deltaPixels : (clientPos - startPos.current);

        const effectiveSensitivity = isFine ? sensitivity * 5 : sensitivity;
        const deltaNormal = adjustedDelta / effectiveSensitivity;

        const newNormal = Math.max(0, Math.min(1, startVal.current + deltaNormal));

        setInternalNormal(newNormal);
        onChange(fromNormal(newNormal));
    }, [isDragging, sensitivity, direction, fromNormal, onChange]);

    const handleEnd = useCallback(() => {
        setIsDragging(false);
        document.body.style.cursor = '';
        document.body.style.userSelect = '';
    }, []);

    useEffect(() => {
        if (isDragging) {
            const onMouseMove = (e: MouseEvent) => {
                e.preventDefault();
                const pos = direction === 'vertical' ? e.clientY : e.clientX;
                handleMove(pos, e.shiftKey || e.ctrlKey);
            };
            const onTouchMove = (e: TouchEvent) => {
                e.preventDefault(); 
                const pos = direction === 'vertical' ? e.touches[0].clientY : e.touches[0].clientX;
                handleMove(pos, false); // No modifier keys on touch usually
            };
            const onUp = () => handleEnd();

            window.addEventListener('mousemove', onMouseMove, { passive: false });
            window.addEventListener('touchmove', onTouchMove, { passive: false });
            window.addEventListener('mouseup', onUp);
            window.addEventListener('touchend', onUp);

            return () => {
                window.removeEventListener('mousemove', onMouseMove);
                window.removeEventListener('touchmove', onTouchMove);
                window.removeEventListener('mouseup', onUp);
                window.removeEventListener('touchend', onUp);
            };
        }
    }, [isDragging, handleMove, handleEnd, direction]);

    return {
        isDragging,
        handleStart,
        percentage: internalNormal
    };
};

import React from 'react';
import { useControlDrag } from '../hooks/useControlDrag';

interface KnobProps {
  value: number;
  min: number;
  max: number;
  onChange: (val: number) => void;
  label: string;
  color?: string;
  size?: number;
  resetValue?: number;
  logarithmic?: boolean;
  unit?: string;
  bipolar?: boolean; // Centers the arc at 12 o'clock (good for Pan/EQ)
}

export const Knob: React.FC<KnobProps> = ({ 
    value, min, max, onChange, label, 
    color = 'cyan', size = 46, resetValue, 
    logarithmic = false, unit = '', bipolar = false 
}) => {

  const { isDragging, handleStart, percentage } = useControlDrag({
      value, min, max, onChange, logarithmic, sensitivity: 250
  });

  const handleDoubleClick = (e: React.MouseEvent | React.TouchEvent) => {
      e.stopPropagation();
      const target = resetValue !== undefined ? resetValue : (bipolar ? (max+min)/2 : min);
      onChange(target);
  };

  const colorMap: Record<string, string> = {
    cyan: '#00f0ff', blue: '#2f80ed', purple: '#b721ff', green: '#0aff60',
    yellow: '#ffcc00', orange: '#ff6600', red: '#ff003c', pink: '#ff00d4', white: '#ffffff', slate: '#94a3b8'
  };
  const accentColor = colorMap[color] || colorMap['cyan'];

  // --- SVG MATH ---
  // Standard knob range: -135deg (7 o'clock) to +135deg (5 o'clock) = 270deg range
  const START_ANGLE = -135;
  const RANGE = 270;

  const radius = 44; 
  const center = 50;
  const strokeWidth = 5;

  // Calculate arc paths
  const valueAngle = START_ANGLE + (percentage * RANGE);

  // For Bipolar: Arc starts at -90 (12 o'clock visual up is -90 in SVG space? No, 0 is 3 o'clock).
  // Let's use rotation transforms. 
  // Base circle rotates -90deg so 0 is Top.
  // Standard Knob: 0% = -135deg, 100% = +135deg.
  // Bipolar Knob: Fill starts at 0deg (Top) and goes to Value Angle.

  const polarToCartesian = (centerX: number, centerY: number, radius: number, angleInDegrees: number) => {
    const angleInRadians = (angleInDegrees - 90) * Math.PI / 180.0;
    return {
      x: centerX + (radius * Math.cos(angleInRadians)),
      y: centerY + (radius * Math.sin(angleInRadians))
    };
  };

  const describeArc = (x: number, y: number, radius: number, startAngle: number, endAngle: number) => {
      const start = polarToCartesian(x, y, radius, endAngle);
      const end = polarToCartesian(x, y, radius, startAngle);
      const largeArcFlag = endAngle - startAngle <= 180 ? "0" : "1";
      return [
          "M", start.x, start.y, 
          "A", radius, radius, 0, largeArcFlag, 0, end.x, end.y
      ].join(" ");
  };

  // Background Arc (Always full 270)
  const bgArc = describeArc(center, center, radius, -135, 135);

  // Active Arc
  let activePath = "";
  if (bipolar) {
      // From 0 (Top) to current angle.
      // Normalize percentage to -1..1
      const biPerc = (percentage - 0.5) * 2; // -1 to 1
      const angle = biPerc * (RANGE / 2); // -135 to 135 relative to top
      // If biPerc is negative: arc from angle to 0. If positive: arc from 0 to angle.
      const start = Math.min(0, angle);
      const end = Math.max(0, angle);
      activePath = describeArc(center, center, radius, start, end);
  } else {
      activePath = describeArc(center, center, radius, -135, valueAngle);
  }

  // Value formatting
  let displayValue = value.toFixed(1);
  if (Math.abs(value) < 1 && value !== 0) displayValue = value.toFixed(2);
  if (Math.abs(value) >= 1000) displayValue = (value / 1000).toFixed(1) + 'k';

  // Tick Mark Rotation
  const tickRot = valueAngle; 

  return (
    <div 
      className="flex flex-col items-center justify-center select-none touch-none group relative py-2" 
      onMouseDown={(e) => handleStart(e.clientY)}
      onTouchStart={(e) => handleStart(e.touches[0].clientY)}
      onDoubleClick={handleDoubleClick}
      style={{ width: size + 10, cursor: isDragging ? 'ns-resize' : 'pointer' }}
    >
      {/* Precision Overlay */}
      <div className={`absolute -top-10 z-50 transition-all duration-200 pointer-events-none flex flex-col items-center
          ${isDragging ? 'opacity-100 translate-y-0 scale-100' : 'opacity-0 translate-y-2 scale-90'}`}
      >
          <div className="bg-[#0c0c0e] border border-white/20 px-2 py-1 rounded shadow-[0_4px_20px_rgba(0,0,0,0.8)] backdrop-blur-md">
              <span className="text-xs font-bold font-mono text-white" style={{ textShadow: `0 0 10px ${accentColor}` }}>
                  {displayValue}<span className="text-[9px] text-slate-500 ml-0.5">{unit}</span>
              </span>
          </div>
          <div className="w-0.5 h-2 bg-white/20"></div>
      </div>

      <div className="relative" style={{ width: size, height: size }}>
          <svg width="100%" height="100%" viewBox="0 0 100 100">
             {/* Backplate Glow */}
             <defs>
                 <filter id={`glow-${label}`}>
                     <feGaussianBlur stdDeviation="2.5" result="coloredBlur"/>
                     <feMerge>
                         <feMergeNode in="coloredBlur"/>
                         <feMergeNode in="SourceGraphic"/>
                     </feMerge>
                 </filter>
             </defs>

             {/* Background Track */}
             <path d={bgArc} fill="none" stroke="#1f2937" strokeWidth={strokeWidth} strokeLinecap="round" />

             {/* Active Track */}
             <path 
                d={activePath} 
                fill="none" 
                stroke={accentColor} 
                strokeWidth={strokeWidth} 
                strokeLinecap="round" 
                filter={`url(#glow-${label})`}
                opacity={0.9}
             />
          </svg>

          {/* Rotatable Cap */}
          <div 
            className="absolute top-[15%] left-[15%] w-[70%] h-[70%] rounded-full bg-[#111] shadow-[inset_0_1px_3px_rgba(255,255,255,0.1),0_5px_10px_rgba(0,0,0,0.5)] border border-white/5 flex items-center justify-center transition-transform duration-75 ease-out will-change-transform"
            style={{ transform: `rotate(${tickRot}deg)` }}
          >
              <div className="absolute top-[5%] w-[3px] h-[30%] bg-white rounded-full shadow-[0_0_5px_white]"></div>
          </div>
      </div>

      <span 
        className="mt-1.5 text-[7px] font-bold tracking-widest uppercase transition-colors duration-200 text-center truncate w-full"
        style={{ 
            color: isDragging ? accentColor : '#52525b',
            textShadow: isDragging ? `0 0 8px ${accentColor}` : 'none',
        }}
      >
        {label}
      </span>
    </div>
  );
};

import React from 'react';
import { useControlDrag } from '../hooks/useControlDrag';

interface FaderProps {
  value: number;
  min: number;
  max: number;
  onChange: (val: number) => void;
  label: string;
  color?: string;
  height?: number;
  unit?: string;
}

export const Fader: React.FC<FaderProps> = ({ 
    value, min, max, onChange, label, 
    color = 'cyan', height = 140, unit = '' 
}) => {

  const { isDragging, handleStart, percentage } = useControlDrag({
      value, min, max, onChange, direction: 'vertical', sensitivity: 200
  });

  const handleDoubleClick = (e: React.MouseEvent | React.TouchEvent) => {
    e.stopPropagation();
    // Default reset logic: 0 if min/max cross 0, else min
    const target = (min <= 0 && max >= 0) ? 0 : min;
    onChange(target);
  };

  const colorMap: Record<string, string> = {
    cyan: '#00f0ff', blue: '#2f80ed', purple: '#b721ff', green: '#0aff60',
    yellow: '#ffcc00', orange: '#ff6600', red: '#ff003c', pink: '#ff00d4', white: '#ffffff'
  };
  const accentColor = colorMap[color] || colorMap['cyan'];

  // Values for Tooltip
  const safeValue = Math.min(max, Math.max(min, Number.isFinite(value) ? value : min));

  return (
    <div className="flex flex-col items-center justify-center space-y-2 select-none touch-none group relative w-12">

      {/* Precision Overlay */}
      <div className={`absolute -top-12 z-50 transition-all duration-200 pointer-events-none flex flex-col items-center
          ${isDragging ? 'opacity-100 translate-y-0 scale-100' : 'opacity-0 translate-y-2 scale-90'}`}
      >
          <div className="bg-[#0c0c0e] border border-white/20 px-2 py-1 rounded shadow-[0_4px_20px_rgba(0,0,0,0.8)] backdrop-blur-md whitespace-nowrap">
              <span className="text-sm font-bold font-mono text-white" style={{ textShadow: `0 0 10px ${accentColor}` }}>
                  {safeValue.toFixed(2)}<span className="text-[9px] text-slate-500 ml-0.5">{unit}</span>
              </span>
          </div>
          <div className="w-0.5 h-2 bg-white/20"></div>
      </div>

      <div 
        className="relative w-full flex justify-center cursor-ns-resize"
        style={{ height: height }}
        onMouseDown={(e) => handleStart(e.clientY)}
        onTouchStart={(e) => handleStart(e.touches[0].clientY)}
        onDoubleClick={handleDoubleClick}
      >
        {/* Rail Background */}
        <div className="absolute w-1.5 h-full bg-[#050505] rounded-full shadow-[inset_0_0_4px_rgba(0,0,0,1)] border border-white/5 overflow-hidden">
             {/* LED Level Strip (behind thumb) */}
             <div 
                className="absolute bottom-0 w-full transition-all duration-75"
                style={{ 
                    height: `${percentage * 100}%`, 
                    backgroundColor: isDragging ? accentColor : `${accentColor}40`,
                    boxShadow: `0 0 10px ${accentColor}`,
                    opacity: 0.8
                }}
             />
        </div>

        {/* Scale Marks */}
        <div className="absolute left-0 top-0 bottom-0 w-full pointer-events-none flex flex-col justify-between py-1 opacity-20">
            {[...Array(9)].map((_, i) => (
                 <div key={i} className={`w-full h-px ${i % 4 === 0 ? 'bg-white w-3 mx-auto' : 'bg-slate-500 w-1.5 mx-auto'}`}></div>
            ))}
        </div>

        {/* Fader Cap (Thumb) */}
        <div 
            className="absolute w-8 h-5 flex items-center justify-center z-20 pointer-events-none will-change-transform transition-all duration-75 ease-out"
            style={{ 
                bottom: `calc(${percentage * 100}% - 10px)`,
            }}
        >
             {/* Cap Body */}
             <div className="w-full h-full bg-gradient-to-b from-[#333] to-[#111] rounded shadow-[0_2px_5px_rgba(0,0,0,0.8),inset_0_1px_1px_rgba(255,255,255,0.2)] border border-black flex flex-col items-center justify-center gap-[2px]">
                 <div className="w-[80%] h-[1px] bg-black/50"></div>
                 <div className="w-[80%] h-[1px] bg-black/50"></div>
                 <div className="w-[80%] h-[1px] bg-black/50"></div>
                 {/* Center Line */}
                 <div className="absolute w-full h-[2px] bg-white mix-blend-overlay opacity-80" style={{ backgroundColor: isDragging ? accentColor : 'white' }}></div>
             </div>
        </div>

      </div>

      <span 
        className="text-[7px] font-bold tracking-widest uppercase transition-all duration-200 truncate w-full text-center"
        style={{ 
            color: isDragging ? accentColor : '#52525b',
            textShadow: isDragging ? `0 0 8px ${accentColor}` : 'none'
        }}
      >
        {label}
      </span>
    </div>
  );
};

import React from 'react';

interface ToggleProps {
    value: boolean;
    onChange: (val: boolean) => void;
    label?: string; // Optional text inside
    color?: string;
    size?: 'sm' | 'md';
    vertical?: boolean; // Label orientation
}

export const Toggle: React.FC<ToggleProps> = ({ 
    value, onChange, label, 
    color = 'cyan', size = 'md', vertical = false 
}) => {

    const colorMap: Record<string, string> = {
        cyan: '#00f0ff', blue: '#2f80ed', purple: '#b721ff', green: '#0aff60',
        yellow: '#eab308', orange: '#f97316', red: '#ef4444', pink: '#ff00d4', white: '#ffffff', slate: '#64748b'
    };
    const accentColor = colorMap[color] || colorMap['cyan'];

    return (
        <button
            onClick={() => onChange(!value)}
            className={`
                relative flex items-center justify-center transition-all duration-100 ease-out border
                ${size === 'sm' ? 'h-5 px-1.5 text-[8px]' : 'h-6 px-3 text-[9px]'}
                ${value 
                    ? `bg-opacity-20 text-white shadow-[0_0_10px_rgba(0,0,0,0.5)]` 
                    : `bg-[#1a1a1e] text-slate-500 border-transparent hover:bg-[#222] hover:text-slate-300`}
                rounded font-bold tracking-wider uppercase overflow-hidden group
            `}
            style={{ 
                backgroundColor: value ? `${accentColor}20` : undefined,
                borderColor: value ? accentColor : 'transparent',
                color: value ? accentColor : undefined,
                boxShadow: value ? `inset 0 0 10px ${accentColor}10` : 'none'
            }}
        >
            {/* LED Indicator */}
            {value && (
                <div className="absolute inset-0 z-0 opacity-10" style={{ backgroundColor: accentColor }}></div>
            )}

            {/* Content */}
            <span className="relative z-10 flex items-center gap-1">
                {value && <div className="w-1 h-1 rounded-full animate-pulse" style={{ backgroundColor: accentColor, boxShadow: `0 0 5px ${accentColor}` }}></div>}
                {label}
            </span>
        </button>
    );
};

import React, { useState, useRef, useEffect } from 'react';
import { Track, ViewSettings } from '../types';
import { COLORS, TRACK_HEIGHT, EXPANDED_TRACK_HEIGHT, TRACK_PRESETS } from '../constants';
import { Knob } from './Knob';
import { Fader } from './Fader';
import { Toggle } from './Toggle';
import { XYPad } from './XYPad';
import { audioEngine } from '../services/audioEngine';
import { DynamicsTransfer, FilterResponse, LFOOscilloscope } from './Visualizers';

interface ChannelStripProps {
  track: Track;
  onUpdate: (id: string, updates: Partial<Track>) => void;
  onToggleArm: (id: string) => void;
  onToggleExpand: (id: string) => void;
  onDuplicate: (id: string) => void;
  width: number;
  viewSettings: ViewSettings;
  isCollapsed: boolean;
}

type Tab = 'DYNAMICS' | 'EQUALIZER' | 'MODULATION' | 'SPACE';

export const ChannelStrip: React.FC<ChannelStripProps> = ({ 
    track, onUpdate, onToggleArm, onToggleExpand, onDuplicate, 
    width, viewSettings, isCollapsed 
}) => {
  const [showColors, setShowColors] = useState(false);
  const [showPresets, setShowPresets] = useState(false);
  const [activeTab, setActiveTab] = useState<Tab>('DYNAMICS');
  const menuRef = useRef<HTMLDivElement>(null);
  const presetRef = useRef<HTMLDivElement>(null);
  const meterCanvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) setShowColors(false);
      if (presetRef.current && !presetRef.current.contains(event.target as Node)) setShowPresets(false);
    };
    if (showColors || showPresets) document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [showColors, showPresets]);

  // Meter Animation Loop
  useEffect(() => {
    if (isCollapsed) return;
    const canvas = meterCanvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animId: number;
    let peakHold = 0;
    let peakTimer = 0;

    const drawMeter = () => {
        const rms = audioEngine.getTrackRMS(track.id);
        const w = canvas.width;
        const h = canvas.height;
        ctx.clearRect(0, 0, w, h);

        ctx.fillStyle = '#111';
        ctx.fillRect(0, 0, w, h);

        const level = Math.min(1.0, rms * 2.5); 
        const activeW = level * w;

        const grad = ctx.createLinearGradient(0, 0, w, 0);
        grad.addColorStop(0, track.color + '20'); 
        grad.addColorStop(0.5, track.color);     
        grad.addColorStop(1, '#fff');            

        ctx.fillStyle = grad;
        ctx.fillRect(0, 0, activeW, h);

        if (level > peakHold) {
            peakHold = level;
            peakTimer = 60;
        } else {
            if (peakTimer > 0) peakTimer--;
            else peakHold *= 0.95;
        }

        ctx.fillStyle = '#fff';
        ctx.fillRect(peakHold * w, 0, 2, h);
        ctx.fillStyle = 'rgba(0,0,0,0.5)';
        for(let i=1; i<10; i++) ctx.fillRect(i * (w/10), 0, 1, h);

        animId = requestAnimationFrame(drawMeter);
    };

    drawMeter();
    return () => cancelAnimationFrame(animId);
  }, [track.id, track.color, isCollapsed]);

  const updateFX = (key: keyof typeof track.fx, value: any) => {
      onUpdate(track.id, {
          fx: { ...track.fx, [key]: value }
      });
  };

  const applyPreset = (presetName: string) => {
      const preset = TRACK_PRESETS[presetName];
      if (preset) {
          onUpdate(track.id, {
              fx: { ...track.fx, ...preset }
          });
          setShowPresets(false);
      }
  };

  const isWide = width > 200;

  return (
    <div 
        className="sticky left-0 z-20 flex flex-col transition-all duration-300 ease-out group shadow-[4px_0_20px_rgba(0,0,0,0.8)] overflow-hidden" 
        style={{ 
            width: width,
            height: track.isExpanded ? EXPANDED_TRACK_HEIGHT : TRACK_HEIGHT,
            background: '#0a0a0c',
            borderRight: `1px solid ${track.color}20`
        }}
    >
       {/* --- HEADER SECTION --- */}
       <div className="p-3 flex-shrink-0 flex flex-col relative" style={{ height: TRACK_HEIGHT }}>
            <div className={`flex items-center gap-2 relative z-30 transition-all ${isCollapsed ? 'justify-center flex-col h-full space-y-4' : 'justify-between mb-2'}`}>
                <div className="relative flex-shrink-0" ref={menuRef}>
                    <button
                        className="w-3 h-3 rounded-full transition-all duration-300 hover:scale-125"
                        style={{ backgroundColor: track.color, boxShadow: `0 0 8px ${track.color}` }}
                        onClick={() => setShowColors(!showColors)}
                    />
                    {showColors && (
                    <div className="absolute top-full left-0 mt-2 bg-black/90 backdrop-blur-xl border border-white/10 p-2 rounded-lg grid grid-cols-4 gap-2 shadow-2xl z-50 w-32 animate-in zoom-in-95 duration-100">
                        {COLORS.map(c => (
                            <button key={c} className="w-5 h-5 rounded-full border border-white/10 hover:scale-110 transition-transform" style={{ backgroundColor: c, boxShadow: `0 0 10px ${c}` }}
                            onClick={(e) => { e.stopPropagation(); onUpdate(track.id, { color: c }); setShowColors(false); }} />
                        ))}
                    </div>
                    )}
                </div>
                {!isCollapsed && (
                    <input
                        className="bg-transparent text-[13px] font-bold text-slate-200 w-full outline-none px-0.5 truncate tracking-wide focus:text-white placeholder-slate-600 font-mono transition-all"
                        value={track.name}
                        onChange={(e) => onUpdate(track.id, { name: e.target.value })}
                        style={{ opacity: width < 60 ? 0 : 1 }}
                    />
                )}
                <button 
                    onClick={() => onToggleArm(track.id)} 
                    className={`w-6 h-6 rounded-full flex-shrink-0 flex items-center justify-center transition-all ${track.armed ? 'bg-red-500/10 shadow-[0_0_15px_rgba(220,38,38,0.4)]' : 'bg-transparent hover:bg-white/5'}`}
                >
                    <div className={`w-2.5 h-2.5 rounded-full transition-all ${track.armed ? 'bg-red-500 animate-pulse' : 'bg-slate-700'}`} />
                </button>
            </div>

            {!isCollapsed && (
                <div className={`flex space-x-1 mb-3 transition-all duration-300 overflow-hidden ${viewSettings.showTransport ? 'opacity-100 max-h-10' : 'opacity-0 max-h-0'}`}>
                    <Toggle value={track.muted} onChange={() => onUpdate(track.id, { muted: !track.muted })} label="MUTE" color="orange" size="sm" />
                    <Toggle value={track.solo} onChange={() => onUpdate(track.id, { solo: !track.solo })} label="SOLO" color="yellow" size="sm" />
                    {viewSettings.showRack && (
                        <Toggle value={track.isExpanded} onChange={() => onToggleExpand(track.id)} label="FX" color="blue" size="sm" />
                    )}
                </div>
            )}

            {!isCollapsed && width > 100 && (
                <button 
                    className="absolute right-2 top-10 text-[8px] text-slate-700 hover:text-white uppercase tracking-wider opacity-0 group-hover:opacity-100 transition-opacity"
                    onClick={() => onDuplicate(track.id)}
                >Dup</button>
             )}

            {!isCollapsed && (
                <div className={`flex flex-col space-y-3 transition-all duration-500 overflow-hidden ${viewSettings.showMix ? 'opacity-100 max-h-24' : 'opacity-0 max-h-0'}`}>
                    {/* Volume Meter & Fader Logic (Simplified for Strip view) */}
                    <div className="flex items-center space-x-2 group/vol relative">
                         {isWide && <span className="text-[8px] font-bold text-slate-600 w-8 text-right">VOL</span>}
                        <div className="flex-1 h-3 relative flex items-center bg-[#111] rounded-sm overflow-hidden border border-white/10 cursor-ew-resize">
                            <canvas ref={meterCanvasRef} width={200} height={12} className="absolute inset-0 w-full h-full opacity-60 pointer-events-none" />
                            <div className="absolute top-0 bottom-0 w-1 bg-white shadow-[0_0_10px_white] z-10 pointer-events-none" style={{ left: `${track.volume * 100}%` }}></div>
                            <input 
                                type="range" min="0" max="1" step="0.01" value={track.volume} 
                                onChange={(e) => onUpdate(track.id, { volume: parseFloat(e.target.value) })}
                                className="absolute w-full h-full opacity-0 cursor-ew-resize z-20" 
                            />
                        </div>
                        {isWide && <span className="text-[9px] font-mono text-white w-8 text-right">{(track.volume * 100).toFixed(0)}</span>}
                    </div>

                    {/* Pan Logic */}
                    <div className="flex items-center space-x-2 group/pan">
                         {isWide && <span className="text-[8px] font-bold text-slate-600 w-8 text-right">PAN</span>}
                        <div className="flex-1 h-1.5 relative flex items-center bg-[#111] rounded-full border border-white/5 cursor-ew-resize">
                            <div className="absolute left-1/2 w-px h-full bg-slate-600"></div>
                            <div className="absolute h-2.5 w-2.5 rounded-full shadow-[0_0_8px_white] bg-white pointer-events-none transition-transform top-1/2 -translate-y-1/2" style={{ left: `calc(${((track.pan + 1) / 2) * 100}% - 5px)` }} />
                            <input 
                                type="range" min="-1" max="1" step="0.1" value={track.pan} 
                                onChange={(e) => onUpdate(track.id, { pan: parseFloat(e.target.value) })}
                                className="absolute w-full h-full opacity-0 cursor-ew-resize" 
                            />
                        </div>
                        {isWide && <span className="text-[9px] font-mono text-slate-400 w-8 text-right">{track.pan.toFixed(1)}</span>}
                    </div>
                </div>
            )}
       </div>

       {/* --- MODULAR FX RACK --- */}
       {track.isExpanded && !isCollapsed && (
           <div className="flex-1 flex flex-col overflow-hidden relative bg-[#050505] animate-in slide-in-from-left duration-300">

               {/* PRESET MENU */}
               <div className="absolute top-0 right-0 z-50 p-2" ref={presetRef}>
                  <button 
                      onClick={() => setShowPresets(!showPresets)}
                      className="px-2 py-1 bg-[#1a1a1e] border border-white/10 rounded text-[9px] font-bold text-cyan-500 hover:text-cyan-400 hover:border-cyan-500/50 uppercase tracking-widest"
                  >
                      Presets
                  </button>
                  {showPresets && (
                      <div className="absolute right-2 top-8 w-48 bg-black/95 border border-cyan-900 rounded shadow-2xl overflow-hidden flex flex-col max-h-64 overflow-y-auto z-50">
                          {Object.keys(TRACK_PRESETS).map(name => (
                              <button
                                  key={name}
                                  onClick={() => applyPreset(name)}
                                  className="text-left px-3 py-2 text-[10px] text-slate-300 hover:bg-cyan-900/30 hover:text-white border-b border-white/5 last:border-0 font-mono"
                              >
                                  {name}
                              </button>
                          ))}
                      </div>
                  )}
               </div>

               {/* TABS */}
               <div className="flex border-b border-white/5 bg-[#080808]">
                   {(['DYNAMICS', 'EQUALIZER', 'MODULATION', 'SPACE'] as Tab[]).map(tab => (
                       <button
                           key={tab}
                           onClick={() => setActiveTab(tab)}
                           className={`flex-1 py-3 text-[9px] font-black tracking-widest border-r border-white/5 transition-colors
                           ${activeTab === tab ? 'bg-[#111] text-cyan-400 border-b-2 border-b-cyan-500' : 'text-slate-600 hover:text-slate-400'}`}
                       >{tab}</button>
                   ))}
               </div>

               {/* TAB CONTENT (GRID LAYOUT) */}
               <div className="flex-1 overflow-y-auto p-0 scrollbar-hide bg-[#0b0b0d]">

                   {/* 1. DYNAMICS: GATE + COMPRESSOR */}
                   {activeTab === 'DYNAMICS' && (
                       <div className="h-full flex flex-col">
                           {/* TOP: COMPRESSOR VISUALIZER + MAIN CONTROLS */}
                           <div className="h-[200px] relative border-b border-white/5 p-4 flex items-center justify-around overflow-hidden">
                               <DynamicsTransfer threshold={track.fx.compressorThreshold} ratio={track.fx.compressorRatio} color="#eab308" />
                               <div className="relative z-10 flex space-x-6">
                                    <Knob value={track.fx.compressorThreshold} min={-60} max={0} label="THRESH" unit="dB" color="yellow" size={50} onChange={(v) => updateFX('compressorThreshold', v)} />
                                    <Knob value={track.fx.compressorRatio} min={1} max={20} label="RATIO" unit=":1" color="yellow" size={50} onChange={(v) => updateFX('compressorRatio', v)} />
                               </div>
                           </div>
                           {/* BOTTOM: ENVELOPE + GATE */}
                           <div className="flex-1 grid grid-cols-2">
                               <div className="border-r border-white/5 p-2 flex flex-col items-center justify-center space-y-2 bg-[#0e0e11]">
                                   <span className="text-[8px] font-bold text-slate-500 mb-1">ENVELOPE</span>
                                   <div className="flex space-x-2">
                                       <Knob value={(track.fx.compressorAttack || 0.003) * 1000} min={1} max={100} label="ATTACK" unit="ms" color="yellow" size={36} onChange={(v) => updateFX('compressorAttack', v/1000)} />
                                       <Knob value={(track.fx.compressorRelease || 0.25) * 1000} min={10} max={1000} label="RELEASE" unit="ms" color="yellow" size={36} onChange={(v) => updateFX('compressorRelease', v/1000)} />
                                   </div>
                               </div>
                               <div className="p-2 flex flex-col items-center justify-center space-y-2 bg-[#0e0e11]">
                                   <span className="text-[8px] font-bold text-green-500 mb-1">NOISE GATE</span>
                                   <Knob value={track.fx.gateThreshold} min={-80} max={0} label="FLOOR" unit="dB" color="green" size={40} onChange={(v) => updateFX('gateThreshold', v)} />
                               </div>
                           </div>
                       </div>
                   )}

                   {/* 2. EQUALIZER */}
                   {activeTab === 'EQUALIZER' && (
                       <div className="h-full flex flex-col relative">
                            {/* EQ VISUALIZER BACKGROUND */}
                            <div className="absolute inset-0 opacity-20 pointer-events-none">
                                <FilterResponse freq={track.fx.highPassFreq} res={0.7} type="highpass" color="#555" />
                                <FilterResponse freq={200} res={0.7} gain={track.fx.eqLow} type="lowshelf" color="#06b6d4" />
                                <FilterResponse freq={1000} res={0.7} gain={track.fx.eqMid} type="peaking" color="#06b6d4" />
                                <FilterResponse freq={4000} res={0.7} gain={track.fx.eqHigh} type="highshelf" color="#06b6d4" />
                            </div>

                            <div className="flex-1 grid grid-cols-3 gap-px bg-white/5">
                                <div className="bg-[#0b0b0d] flex flex-col items-center justify-center pt-4">
                                    <Fader value={track.fx.eqLow} min={-12} max={12} label="LOW" unit="dB" color="cyan" height={160} onChange={(v) => updateFX('eqLow', v)} />
                                    <div className="mt-2 border-t border-white/5 w-full flex justify-center py-2">
                                       <Knob value={track.fx.highPassFreq} min={20} max={500} logarithmic label="HPF" unit="Hz" color="slate" size={32} onChange={(v) => updateFX('highPassFreq', v)} />
                                    </div>
                                </div>
                                <div className="bg-[#0b0b0d] flex flex-col items-center justify-center pt-4">
                                    <Fader value={track.fx.eqMid} min={-12} max={12} label="MID" unit="dB" color="cyan" height={160} onChange={(v) => updateFX('eqMid', v)} />
                                    <div className="mt-2 border-t border-white/5 w-full flex justify-center py-2">
                                       <span className="text-[9px] text-slate-700 font-mono">1kHz</span>
                                    </div>
                                </div>
                                <div className="bg-[#0b0b0d] flex flex-col items-center justify-center pt-4">
                                    <Fader value={track.fx.eqHigh} min={-12} max={12} label="HIGH" unit="dB" color="cyan" height={160} onChange={(v) => updateFX('eqHigh', v)} />
                                    <div className="mt-2 border-t border-white/5 w-full flex justify-center py-2">
                                       <Knob value={track.fx.presence || 4000} min={1000} max={10000} logarithmic label="AIR" unit="Hz" color="cyan" size={32} onChange={(v) => updateFX('presence', v)} />
                                    </div>
                                </div>
                            </div>
                       </div>
                   )}

                   {/* 3. MODULATION (EXPANDED) */}
                   {activeTab === 'MODULATION' && (
                       <div className="grid grid-cols-1 gap-px bg-white/5 pb-20">
                           {/* CHORUS */}
                           <div className="bg-[#0e0e11] p-3 flex items-center justify-between border-b border-white/5 relative overflow-hidden">
                               <LFOOscilloscope rate={track.fx.chorusRate || 1.5} depth={track.fx.chorusDepth || 0.5} color="#a855f7" />
                               <div className="relative z-10 w-full flex justify-between items-center px-2">
                                    <span className="text-[9px] font-black text-purple-500 -rotate-90 w-4">CHORUS</span>
                                    <Knob value={track.fx.chorusMix || 0} min={0} max={1} label="MIX" unit="%" color="purple" size={36} onChange={(v) => updateFX('chorusMix', v)} />
                                    <Knob value={track.fx.chorusRate || 1.5} min={0.1} max={5} label="RATE" unit="Hz" color="purple" size={36} onChange={(v) => updateFX('chorusRate', v)} />
                                    <Knob value={(track.fx.chorusDepth || 0.002) * 1000} min={0} max={10} label="DEPTH" unit="ms" color="purple" size={36} onChange={(v) => updateFX('chorusDepth', v/1000)} />
                               </div>
                           </div>

                           {/* FLANGER */}
                           <div className="bg-[#0e0e11] p-3 flex items-center justify-between border-b border-white/5 relative overflow-hidden">
                                <LFOOscilloscope rate={track.fx.flangerRate || 0.5} depth={0.8} color="#3b82f6" />
                                <div className="relative z-10 w-full flex justify-between items-center px-2">
                                    <span className="text-[9px] font-black text-blue-500 -rotate-90 w-4">FLANGE</span>
                                    <Knob value={track.fx.flangerMix || 0} min={0} max={1} label="MIX" unit="%" color="blue" size={36} onChange={(v) => updateFX('flangerMix', v)} />
                                    <Knob value={track.fx.flangerRate || 0.5} min={0.1} max={2} label="RATE" unit="Hz" color="blue" size={36} onChange={(v) => updateFX('flangerRate', v)} />
                                    <Knob value={track.fx.flangerFeedback || 0} min={0} max={0.95} label="FDBK" unit="%" color="blue" size={36} onChange={(v) => updateFX('flangerFeedback', v)} />
                               </div>
                           </div>

                           {/* PHASER */}
                           <div className="bg-[#0e0e11] p-3 flex items-center justify-between relative overflow-hidden">
                                <LFOOscilloscope rate={track.fx.phaserRate || 1.0} depth={0.6} color="#ec4899" />
                                <div className="relative z-10 w-full flex justify-between items-center px-2">
                                    <span className="text-[9px] font-black text-pink-500 -rotate-90 w-4">PHASE</span>
                                    <Knob value={track.fx.phaserMix || 0} min={0} max={1} label="MIX" unit="%" color="pink" size={36} onChange={(v) => updateFX('phaserMix', v)} />
                                    <Knob value={track.fx.phaserRate || 1.0} min={0.1} max={5} label="RATE" unit="Hz" color="pink" size={36} onChange={(v) => updateFX('phaserRate', v)} />
                                    <div className="w-9"></div> {/* Spacer */}
                               </div>
                           </div>
                       </div>
                   )}

                   {/* 4. SPACE & COLOR */}
                   {activeTab === 'SPACE' && (
                       <div className="grid grid-cols-2 gap-px bg-white/5 h-full">
                           {/* SATURATION */}
                           <div className="col-span-2 bg-[#0e0e11] h-32 relative overflow-hidden border-b border-white/5">
                                <XYPad 
                                 x={(track.fx.saturation || 0) / 100} 
                                 y={(Math.min(20000, Math.max(1000, track.fx.distortionTone || 20000)) - 1000) / 19000}
                                 labelX="TUBE DRIVE" labelY="TONE" color="orange"
                                 onChange={(x, y) => {
                                     updateFX('saturation', x * 100);
                                     updateFX('distortionTone', 1000 + (y * 19000));
                                 }}
                               />
                           </div>

                           {/* AUTO WAH & CABINET SPLIT */}
                           <div className="col-span-2 grid grid-cols-2 border-b border-white/5">
                               {/* AUTO WAH */}
                               <div className="bg-[#0e0e11] p-2 flex flex-col items-center justify-center border-r border-white/5">
                                   <div className="flex items-center space-x-2 mb-2">
                                        <span className="text-[8px] font-black text-green-400">AUTO-WAH</span>
                                        <div className={`w-1.5 h-1.5 rounded-full ${track.fx.autoWahMix > 0 ? 'bg-green-500 shadow-[0_0_5px_lime]' : 'bg-slate-800'}`}></div>
                                   </div>
                                   <div className="flex space-x-2">
                                        <Knob value={track.fx.autoWahSens || 0} min={0} max={100} label="SENS" unit="%" color="green" size={32} onChange={(v) => updateFX('autoWahSens', v)} />
                                        <Knob value={track.fx.autoWahMix || 0} min={0} max={1} label="MIX" unit="%" color="green" size={32} onChange={(v) => updateFX('autoWahMix', v)} />
                                   </div>
                               </div>

                               {/* CABINET EMULATOR */}
                               <div className="bg-[#0e0e11] p-2 flex flex-col items-center justify-center relative overflow-hidden">
                                   <div className="flex items-center space-x-2 mb-2 z-10">
                                        <Toggle 
                                            value={track.fx.cabinetOn} 
                                            onChange={(v) => updateFX('cabinetOn', v)} 
                                            label="CABINET" 
                                            color="orange"
                                            size="sm" 
                                        />
                                   </div>
                                   {track.fx.cabinetOn && (
                                       <div className="absolute inset-0 pointer-events-none opacity-10 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-orange-500 via-transparent to-transparent"></div>
                                   )}
                                   <Knob value={track.fx.cabinetTone} min={0} max={1} label="TONE" unit="" color="orange" size={36} onChange={(v) => updateFX('cabinetTone', v)} />
                               </div>
                           </div>

                           {/* BITCRUSH */}
                           <div className="bg-[#0e0e11] flex flex-col items-center justify-center p-2 border-r border-white/5">
                                <span className="text-[8px] text-red-500 font-bold mb-1">BITCRUSH</span>
                                <Knob value={track.fx.bitCrushMix || 0} min={0} max={1} label="MIX" unit="%" color="red" size={36} onChange={(v) => updateFX('bitCrushMix', v)} />
                                <div className="h-2"></div>
                                <Fader value={track.fx.bitCrushBits || 16} min={1} max={16} label="BITS" unit="b" color="red" height={60} onChange={(v) => updateFX('bitCrushBits', Math.round(v))} />
                           </div>

                           {/* SENDS */}
                           <div className="bg-[#0e0e11] flex flex-col items-center justify-around p-2">
                                <span className="text-[8px] text-blue-500 font-bold">SENDS</span>
                                <Knob value={track.fx.sendReverb} min={0} max={1} label="VERB" unit="%" color="blue" size={36} onChange={(v) => updateFX('sendReverb', v)} />
                                <Knob value={track.fx.sendDelay} min={0} max={1} label="DELAY" unit="%" color="blue" size={36} onChange={(v) => updateFX('sendDelay', v)} />
                           </div>
                       </div>
                   )}

               </div>
           </div>
       )}
    </div>
  );
};

import React, { useEffect, useRef } from 'react';
import { DSPState } from '../types';
import { Knob } from './Knob';
import { Fader } from './Fader';
import { Toggle } from './Toggle';
import { audioEngine } from '../services/audioEngine';

interface DSPRackProps {
  dspState: DSPState;
  onChange: (newState: DSPState) => void;
}

// Helper calculation functions (Simplified for Vector Scope)
const calculateFilterPoints = (freq: number, res: number) => {
    // Return array of Y points (0-1)
    const points = [];
    for(let i=0; i<100; i++) {
        const f = 20 * Math.pow(1000, i/99);
        // LP Sim
        const ratio = f/freq;
        let mag = 1 / Math.sqrt(1 + Math.pow(ratio, 4));
        if (Math.abs(ratio - 1) < 0.2) mag += (res * 0.1); // Resonance peak
        points.push(Math.min(1.2, mag));
    }
    return points;
};

const drawVectorScope = (ctx: CanvasRenderingContext2D, width: number, height: number, points: number[], color: string, bypassed: boolean, mode: string) => {
    ctx.clearRect(0,0,width,height);
    const opacity = bypassed ? 0.2 : 1.0;

    // Grid
    ctx.strokeStyle = 'rgba(255,255,255,0.05)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    for(let i=0; i<width; i+=20) { ctx.moveTo(i,0); ctx.lineTo(i,height); }
    for(let i=0; i<height; i+=20) { ctx.moveTo(0,i); ctx.lineTo(width,i); }
    ctx.stroke();

    ctx.strokeStyle = color;
    ctx.shadowColor = color;
    ctx.shadowBlur = bypassed ? 0 : 8;
    ctx.globalAlpha = opacity;
    ctx.lineWidth = 2;
    ctx.beginPath();

    if (mode === 'dynamics') {
        // Points[0] is reduction amount (0-1)
        const red = points[0];
        const h = height;
        const w = width;
        // Draw Reduction Bar
        ctx.fillStyle = color;
        const barH = red * h;
        ctx.fillRect(w/2 - 10, h - barH, 20, barH);
        return;
    }

    if (mode === 'output') {
        // Output Spectral Display (FFT)
        // points is FFT data scaled 0-1
        const step = width / points.length;
        ctx.fillStyle = color;
        for(let i=0; i<points.length; i++) {
            const val = points[i];
            const barH = val * height;
            ctx.fillRect(i * step, height - barH, step+1, barH);
        }
        return;
    }

    // Default Line Plot
    const step = width / (points.length - 1);
    for (let i = 0; i < points.length; i++) {
        const val = points[i]; // 0-1 magnitude typically
        // Flip Y, map 1.0 to top, 0.0 to bottom? Usually 1.0 is mid or max. 
        // For filter, 1.0 is full volume.
        const y = height - (Math.min(1, Math.max(0, val)) * height * 0.8) - (height*0.1); 

        if(i===0) ctx.moveTo(0, y);
        else ctx.lineTo(i * step, y);
    }
    ctx.stroke();

    // Fill
    ctx.fillStyle = color;
    ctx.globalAlpha = opacity * 0.2;
    ctx.lineTo(width, height);
    ctx.lineTo(0, height);
    ctx.fill();

    ctx.globalAlpha = 1.0;
    ctx.shadowBlur = 0;
};

const RackModule: React.FC<{
  title: string;
  type: 'filter' | 'saturator' | 'exciter' | 'eq' | 'dynamics' | 'spatial' | 'width' | 'output';
  color: string;
  dspState: DSPState;
  children: React.ReactNode;
  isBypassed?: boolean;
  onToggleBypass?: () => void;
}> = ({ title, type, color, dspState, children, isBypassed = false, onToggleBypass }) => {

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const colorMap: Record<string, string> = {
    pink: '#ff00d4', orange: '#ff6600', blue: '#2f80ed',
    yellow: '#ffcc00', purple: '#b721ff', cyan: '#00f0ff',
    red: '#ff003c', green: '#0aff60',
  };
  const hexColor = colorMap[color] || '#3b82f6';

  useEffect(() => {
     const canvas = canvasRef.current;
     if(!canvas) return;
     const ctx = canvas.getContext('2d');
     if(!ctx) return;

     let frameId: number;
     const dataArray = new Uint8Array(audioEngine.analyser.frequencyBinCount);

     const render = () => {
         frameId = requestAnimationFrame(render);

         const w = canvas.width;
         const h = canvas.height;
         let points: number[] = [];

         if (type === 'filter') points = calculateFilterPoints(dspState.masterFilterFreq, dspState.masterFilterRes);
         else if (type === 'saturator') {
             // Drive curve visualization (Linear)
             for(let i=0; i<100; i++) {
                 const x = (i/50) - 1; // -1 to 1
                 const k = dspState.masterSaturation;
                 const y = ((Math.PI + k) * x) / (Math.PI + k * Math.abs(x));
                 points.push((y + 1) / 2); // 0-1
             }
         }
         else if (type === 'eq') {
             // EQ curve approx
             for(let i=0; i<100; i++) {
                let gain = 0;
                if (i < 33) gain = dspState.masterEqLow;
                else if (i < 66) gain = dspState.masterEqMid;
                else gain = dspState.masterEqHigh;
                // Interpolate
                points.push((gain + 12) / 24); // +/- 12db mapped to 0-1
             }
         }
         else if (type === 'dynamics') {
             const reduction = audioEngine.getMasterGainReduction(); 
             points = [Math.abs(reduction) / 20.0];
         }
         else if (type === 'spatial') {
             // Delay taps visual
             for(let i=0; i<50; i++) points.push(Math.random() * dspState.reverbMix);
         }
         else if (type === 'output') {
             audioEngine.analyser.getByteFrequencyData(dataArray);
             for(let i=0; i<50; i++) {
                 points.push(dataArray[i*2] / 255);
             }
         }
         else {
             points = new Array(100).fill(0.5);
         }

         drawVectorScope(ctx, w, h, points, hexColor, !!isBypassed, type);
     };
     render();
     return () => cancelAnimationFrame(frameId);
  }, [type, dspState, hexColor, isBypassed]);

  return (
    <div className={`flex flex-col h-full backdrop-blur-md border-r border-white/5 relative group min-w-[170px] overflow-hidden transition-colors ${isBypassed ? 'bg-black/40' : 'bg-white/5'}`}>

      {/* VFD Screen Area */}
      <div className="h-24 relative p-3 flex flex-col items-center justify-end bg-black/40 shadow-[inset_0_10px_30px_rgba(0,0,0,0.5)]">
        <div className={`w-full h-full relative rounded border overflow-hidden transition-colors ${isBypassed ? 'border-white/5 bg-black' : 'border-white/10 bg-black/80'}`}>
             <div className="absolute inset-0 z-20 pointer-events-none opacity-20" style={{ backgroundImage: 'linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.25) 50%), linear-gradient(90deg, rgba(255, 0, 0, 0.06), rgba(0, 255, 0, 0.02), rgba(0, 0, 255, 0.06))', backgroundSize: '100% 2px, 3px 100%' }}></div>
             <canvas ref={canvasRef} width={140} height={60} className="w-full h-full" />
        </div>

        {/* Module Title Badge */}
        <div className={`absolute top-3 left-3 px-1.5 py-0.5 border rounded z-30 shadow-[0_0_10px_rgba(0,0,0,1)] flex items-center gap-2 ${isBypassed ? 'border-white/5 bg-black text-slate-600' : 'border-white/10 bg-black/80'}`}>
            <span className={`text-[9px] font-black tracking-widest uppercase transition-colors ${isBypassed ? 'text-slate-600' : 'text-white/90'}`} style={{ textShadow: isBypassed ? 'none' : `0 0 5px ${hexColor}` }}>{title}</span>
        </div>

        {/* Bypass LED */}
        {onToggleBypass && (
            <button 
                onClick={onToggleBypass}
                className={`absolute top-3 right-3 w-3 h-3 rounded-full border transition-all z-40 ${isBypassed ? 'bg-slate-900 border-slate-700' : `bg-${color}-500 border-white shadow-[0_0_8px_${hexColor}]`}`}
                style={{ backgroundColor: isBypassed ? '#111' : hexColor }}
            ></button>
        )}
      </div>

      {/* Controls Area */}
      <div className={`flex-1 flex items-center justify-center space-x-4 px-3 py-2 relative transition-opacity duration-300 ${isBypassed ? 'opacity-30 pointer-events-none grayscale' : 'opacity-100'}`}>
         {children}
      </div>
      <div className="absolute top-0 bottom-0 left-0 w-px bg-white/10"></div>
    </div>
  );
};

export const DSPRack: React.FC<DSPRackProps> = ({ dspState, onChange }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    let animationId: number;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const dataArray = new Uint8Array(audioEngine.analyser.frequencyBinCount);

    const draw = () => {
      animationId = requestAnimationFrame(draw);
      audioEngine.analyser.getByteFrequencyData(dataArray);
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      const numBlocks = 64;
      const blockWidth = canvas.width / numBlocks;
      const step = Math.floor(dataArray.length / numBlocks);

      for(let i = 0; i < numBlocks; i++) {
        const val = dataArray[i * step] / 255; 
        const activeHeight = val * canvas.height;
        ctx.fillStyle = `hsl(${210 + (val * 60)}, 100%, 60%)`;
        ctx.globalAlpha = 0.8;
        ctx.fillRect(i * blockWidth, canvas.height - activeHeight, blockWidth - 1, activeHeight);

        ctx.globalAlpha = 0.2;
        ctx.fillRect(i * blockWidth, canvas.height, blockWidth - 1, activeHeight * 0.5);
      }
    };
    draw();
    return () => cancelAnimationFrame(animationId);
  }, []);

  return (
    <div className="fixed bottom-0 left-0 right-0 h-[260px] bg-[#030305]/95 backdrop-blur-xl border-t border-white/10 shadow-[0_-10px_50px_rgba(0,0,0,0.9)] z-50 flex flex-col">
