             <Fader value={dspState.masterVolume} min={0} max={1.5} label="GAIN" unit="dB" color="red" onChange={(v) => onChange({...dspState, masterVolume: v})} />
          </RackModule>
        </div>
      </div>
    </div>
  );
};

